\end{align*}

\noindent This fundamentally divergent assumption on the bit transmission rate underlies the paradoxical, and unexpected, aspects of Quantum information which can allow Alice and Bob to not sacrifice error correction, and authentication, probabilities over $A \longleftrightarrow B$, albeit the fact that $N_{A \longleftrightarrow B} > N_{B \longleftrightarrow E}$. Moreover, the underlying aspects of Quantum information which guarantee that, as proposed sources of Quantum advantage, Alice and Bob can still execute error correction, and authentication, protocols whp, is closely related to the following series of observations, and questions:


\begin{itemize}
    \item[$\bullet$] \textit{Nonlocality and contextuality}. Information processing tasks making use of entanglement are known to satisfy nonlocality properties, which ultimately stems from the fact that the universe itself is locally not real. To this end, what other strict upper bounds on the bit transmission rate across Alice and Bob's shared Quantum channel, continue permitting for them to execute error correction, and authentication, protocols whp?
    \item[$\bullet$] \textit{Eve's attempts to send corrupted messages as authenticated ones to Alice's and Bob's shared Quantum channel}. The eavesdropper, Eve, attempts to corrupt bit codewords that Alice or Bob shares with the other player. How might Eve, to increase her probability of simultaneously corrupting a message into Alice's and Bob's authenticated space, determine which letters of Alice's, or Bob's, alphabets, have already been used for transmission?
    \item[$\bullet$] \textit{Equal noise thresholds across the Quantum channels shared between Alice and Bob, and between Bob and Eve}. What proposed sources of Quantum advantage would one expect to have when $N_{A \longleftrightarrow B} \equiv N_{B\longleftrightarrow E}$, in comparison to $N_{A \longleftrightarrow B} > N_{B\longleftrightarrow E}$?
\end{itemize}




\subsection{Game-theoretic objects}

\noindent For the 2-player XOR game $G$, the set of all possible strategies $\mathcal{S}$ which players optimize over given some realization of a strategy $S$ takes the form,


\begin{align*}
      \beta \big( G , \mathcal{S}  \big)     \equiv \underset{s \in S}{\sum} \underset{t \in T}{\sum} G_{st} \bra{\psi} A_s \otimes B_t \ket{\psi}  \text{, } 
\end{align*}

\noindent as the \textit{success bias}, where the summation runs over all rows and columns $s$ and $t$ of $G$, with the observables in the tensor product taking the form,


\begin{align*}
 A_S \equiv \underset{s \in S}{\bigcup} A_s \equiv \big\{   s  \in S :  A_s \in \big\{ - 1 , + 1 \big\}    \big\}     \text{, } \\    B_T \equiv \underset{t \in T}{\bigcup} B_t \equiv \big\{ t \in T  :  B_t \in \big\{ -1 , + 1 \big\}  \big\}    \text{. }
\end{align*}

\noindent The quantity above is related to the probability of winning the XOR game given $\mathcal{S}$, denoted as $\omega \big( G , \mathcal{S} \big)$, as,

\begin{align*}
       \beta \big( G , \mathcal{S}  \big)  = 2   \omega \big( G , \mathcal{S} \big) - 1      \text{. } 
\end{align*}


\noindent As a supremum over all possible $\mathcal{S}$ for $G$, define,


\begin{align*}
 \beta \big( G \big) \equiv  \underset{\text{Strategies }\mathcal{S}}{\mathrm{sup}} \text{ } \beta \big( G , \mathcal{S} \big) \text{, } 
\end{align*}

\noindent corresponding to the optimal quantum strategy. From the optimal strategy $\beta \big( G \big)$, the notion of approximately optimal strategies can be introduced, in which for some strictly positive $\epsilon$,

\begin{align*}
\big( 1 - \epsilon \big) \beta \big( G \big)   \leq   \beta \big( G , \mathcal{S} \big)        \leq  \beta \big( G \big) \text{. }
\end{align*}



\noindent From each possible combination of questions that can be raised to Alice and then Bob, one can form orthonormal bases $\ket{i}$ and $\ket{ij}$, for the \textit{game matrix}, which are of the form,


\begin{align*}
  G =  \frac{1}{4 {n \choose 2}}   \underset{1\leq i \leq j \leq n}{\sum}   \bigg[    \ket{i}\bra{ij}  +   \ket{j} \bra{ij} + \ket{i} \bra{ji} - \ket{j} \bra{ji}             \bigg]   \text{. } 
\end{align*}

\noindent from which the \textit{optimal success bias} for $G$ takes the form, under the correspondence from the superposition of bra-ket states above,


\begin{align*}
    \ket{i}\bra{ij} \longleftrightarrow A_i B_{ij}       \text{, } \\    \ket{j} \bra{ij}  \longleftrightarrow A_j B_{ij}   \text{, } \\  \ket{i}\bra{ji}  \longleftrightarrow  A_i B_{ji}  \text{, } \\                  - \ket{j} \bra{ji}  
 \longleftrightarrow  - A_j B_{ji} \text{, }
\end{align*}


\noindent from which a summation of quantum states over $i,j$, provides,


\begin{align*}
