\end{align*}


\noindent while increasing the probability of false acceptance,


\begin{align*}
P_{\mathrm{FA}} \equiv          \underset{\mathrm{fa} \in \mathrm{FA}}{\mathrm{inf}}    p_{\mathrm{fa}} \equiv           \mathrm{inf} \big\{ \text{failure probability of a player accepting a message that} \\ \text{ should have not been accepted} \big\}              \text{, }
\end{align*}


\noindent for the set of all instances of false acceptance over a Quantum channel,


\begin{align*}
