\noindent \textbf{Lemma} \textit{1} (\textit{the first property of error correcting codes over noisy Quantum channels: inverse monotonicity of the radius of Hamming balls for codewords with respect to channel noise}). Denote, 

\begin{align*}
   \mathcal{B}_1 \big( r, \mathcal{C}_1  \big)   \equiv  \big\{ \forall r, \exists \epsilon_1 > 0 : \big| \mathcal{C}_1 - r \big| < \epsilon_1       \big\}    \text{, }  \\      \mathcal{B}_2 \big( r, \mathcal{C}_2  \big)  \equiv \big\{  \forall r, \exists \epsilon_2 > 0: \big| \mathcal{C}_2 - r \big| < \epsilon_2  \big\}     \text{, }
\end{align*}




\noindent as two Hamming balls, $   \mathcal{B}_1$ and $\mathcal{B}_2$,  centered about codewords $\mathcal{C}_1$, and $\mathcal{C}_2$, which are respectively transmitted over the two Quantum channels,

\begin{align*}
   \mathcal{N}^n_{p,q, A \longleftrightarrow B}  \text{, }  \\      \mathcal{N}^n_{p,q, B \longleftrightarrow E}     \text{, }
\end{align*}




\noindent between Alice and Bob, and between Bob and Eve, respectively. For $N_{A \longleftrightarrow B} > N_{B \longleftrightarrow E}$, the radius of the Hamming balls, $\mathcal{B}_1$ and $\mathcal{B}_2$ is inversely proportional to the presence of noise over a Quantum channel, as,



\begin{align*}
  \frac{\textbf{P} \big[ \big\{  \forall r_1 > 0, \exists n_1 > 0 :  \big|  \mathscr{C} \cap \mathcal{B}_1 \big( r_1, \mathcal{C}_1 \big)  \big| \equiv n_1      \big\}    \big| \big\{  \mathcal{C}_1 \text{ is transmitted} \cdots }{\textbf{P} \big[ \big\{ \forall r_2 > r_1 > 0, \exists n_2 > n_1  > 0 :       \big| \mathscr{C} \cap \mathcal{B}_1 \big( r_2, \mathcal{C}_2 \big) \big| \equiv n_2 \big\}    \big| \big\{ \mathcal{C}_2 \text{ is transmitted} \cdots  }    \\ \frac{\cdots \text{through }   \mathcal{N}^n_{p,q, A \longleftrightarrow B} \big\}   \big] }{\cdots \text{through }   \mathcal{N}^n_{p,q, B \longleftrightarrow E}  \big\} \big] }\equiv \frac{\mathscr{P}_1}{\mathscr{P}_2}     \gtrsim   \frac{N_{A \longleftrightarrow B}}{N_{B \longleftrightarrow E}}   \text{, }
