\begin{align*}
  \frac{\textbf{P} \big[ \big\{  \forall r_1 > 0, \exists n_1 > 0 :  \big|  \mathscr{C} \cap \mathcal{B}_1 \big( r_1, \mathcal{C}_1 \big)  \big| \equiv n_1       \big\}   \big| \big\{  \mathcal{C}_1 \text{ is transmitted through }   \dots }{\textbf{P} \big[ \big\{  \forall r_2 > r_1 > 0, \exists n_2 > n_1  > 0 :       \big| \mathscr{C} \cap \mathcal{B}_1 \big( r_2, \mathcal{C}_2 \big) \big| \equiv n_2  \big\}   \big| \big\{  \mathcal{C}_2 \text{ is transmitted through } \dots   }   \\ \frac{\dots \mathcal{N}^{+\infty}_{p,q, A \longleftrightarrow B} \big\}   \big] }{\dots   \mathcal{N}^{+\infty}_{p,q, B \longleftrightarrow E} \big\}  \big] }   \gtrsim   \frac{N^{+\infty}_{A \longleftrightarrow B}}{N^{+\infty}_{B \longleftrightarrow E}}   \text{, }
