\noindent A third favorable property of error correcting codes, stated below, quantitatively captures an iff correspondence between the decoding, and false acceptance, probabilities. Given arguments in the previous result which establish that the probability of decodings which are not good, in addition to encodings that are not good for decoding a message after a bit codeword is transmitted, can be made arbitrarily small, the probability of an encoding which belongs to the authenticated set of codewords is high iff the probability of false acceptance is low.



\bigskip

\noindent The arguments for each direction of the correspondence rely upon the fact that, over all possible realizations $\mathrm{ec}$ and $\mathrm{fa}$ of $\mathrm{EC}$, and $\mathrm{FA}$, respectively, one has the following equivalence, 

\begin{align*}
   \underset{\mathrm{ec} \in \mathrm{EC}}{\bigcup}  \big\{ p_{\mathrm{ec},+ \infty} \big\}  > \underset{\mathrm{fa} \in \mathrm{FA}}{\bigcup} \big\{ p_{\mathrm{fa},+\infty}  \big\}  \\  \Bigg\Updownarrow \\ \underset{\mathrm{ec} \in \mathrm{EC}}{\bigcup}  \bigg\{     \underset{\mathrm{bits}}{\sum}   \big\{ p_{\mathrm{ec}, \mathrm{bits}}       \big\}   \bigg\} > \underset{\mathrm{fa} \in \mathrm{FA}}{\bigcup} \bigg\{ \underset{\text{bits}}{\sum} \big\{ p_{\mathrm{fa},\text{bits}}  \big\} \bigg\} \\ \Bigg\Updownarrow \\ \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}  \bigg\{   \bigg\{    \underset{\mathrm{ec} \in \mathrm{EC}}{\bigcup}  \bigg\{     \underset{\text{bits}^{\prime}-1}{\sum}   \big\{ p_{\mathrm{ec}, \text{bits}^{\prime}-1}       \big\}   \bigg\}        > \underset{\mathrm{fa} \in \mathrm{FA}}{\bigcup}  \bigg\{ \underset{\text{bits}^{\prime}-1}{\sum} \big\{ p_{\mathrm{fa},\text{bits}^{\prime}-1}  \big\} \bigg\}   \bigg\}     \\ \Longleftrightarrow\bigg\{ \underset{\mathrm{ec} \in \mathrm{EC}}{\bigcup}  \bigg\{     \underset{\mathrm{bits}}{\sum}   \big\{ p_{\mathrm{ec}, \text{bits}^{\prime}}       \big\}   \bigg\}    >  \underset{\mathrm{fa} \in \mathrm{FA}}{\bigcup}  \bigg\{ \underset{\text{bits}^{\prime}}{\sum} \big\{ p_{\mathrm{fa},\text{bits}^{\prime}}  \big\} \bigg\}           \bigg\}   \bigg\} \\ \Bigg\Updownarrow  \\     \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \bigg\{          \textbf{P} \bigg[   \forall \epsilon > 0,  \exists \text{ codewords } \mathcal{C} \in \mathscr{C} \text{ with } \text{bits}^{\prime} \text{ bits} :   \big| \mathcal{B} \big( \mathcal{C}, r_{\mathcal{C}} \big) \big|   \approx \frac{1}{\epsilon} \big| \mathscr{C} \big|   \\ \bigg|  p_{\mathrm{EC}, \text{bits}^{\prime}-1} \approx 1      \bigg]                                   \bigg\}    \text{, } \tag{$\mathcal{C}$-Probab.}
\end{align*}





