\begin{align*}
\mathscr{C} \equiv   \underset{\mathcal{C}, \text{ bits}}{\bigcup} \big\{ \text{infinitely many bit } \mathcal{C} \text{ transmitted over }  \mathcal{N}^{\text{bits}}_{p,q, A \longleftrightarrow B}, \text{ and} \\ \text{over }   \mathcal{N}^{\text{bits}}_{p,q, B \longleftrightarrow E} \big\}   \text{.}
\end{align*}





\noindent \textbf{Lemma} \textit{3} (\textit{the third property of error correcting codes over noisy Quantum channels: error correcting codes occurring with high probability in the presence of noise are related to instances of false acceptance occurring with low probability}). One has the correspondence,


\begin{align*}
 p_{\mathrm{EC}} \approx 1 \Longleftrightarrow p_{\mathrm{FA}} \approx 0  \text{. }
\end{align*}


\bigskip


\noindent \textit{Proof of Lemma 3}. For the forward direction of the correspondence, we argue that the desired conclusion holds, namely that the false acceptance probability, approximately vanishes, with the following. We establish a collection of several equivalent conditions, which is expressed as a union over all instances of error correcting correction and false acceptance. By taking a summation over all bits in the codeword that is transmitted and then sending the number of bits to $+ \infty$, we conclude that $p_{\mathrm{FA}} \approx 0$ by . ($\Longrightarrow$) Suppose that $p_{\mathrm{EC}} \approx 1$. It suffices to prove that the stochastic domination,

\begin{align*}
    p_{\mathrm{EC},n} > p_{\mathrm{FA},n}       \text{, }
\end{align*}



\noindent holds between implementing an error correcting scheme, from the class of all suitable codes $\mathrm{EC}$, is \textit{stable} as $n \longrightarrow + \infty$. \textit{Stability} in the limit of infinitely many bits for a codeword requires,


\begin{align*}
     p_{\mathrm{EC},+ \infty} > p_{\mathrm{FA},+\infty} \Longleftrightarrow \underset{N \longrightarrow + \infty}{\mathrm{lim}} \bigg\{   \forall N   ,  \big\{    p_{\mathrm{EC}, N} > p_{\mathrm{FA}, N } \big\}          \Longleftrightarrow \big\{     p_{\mathrm{EC}, N-1}  > p_{\mathrm{FA}, N-1}  \big\}  \bigg\}                \text{. }
\end{align*}





\noindent From an application of Bayes' Rule, one can demonstrate that the first direction of the iff correspondence holds, upon manipulating the conditional probability as the number of bits $\longrightarrow + \infty$, which equals,



\begin{align*}
   (\mathcal{C}\text{-Probab.}) =     \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \big\{   \mathscr{P}_1 \mathscr{P}_2 \mathscr{P}_3     \big\}     \text{, }
\end{align*}

\noindent for,


\begin{align*}
 \mathscr{P}_1 \equiv \textbf{P} \bigg[   p_{\mathrm{EC}, \text{bits}^{\prime}-1} \approx 1    \bigg|  \forall \epsilon > 0,  \exists \text{ codewords } \mathcal{C} \in \mathscr{C} \text{ with } \text{bits}^{\prime} \text{ bits} \\ :    \big| \mathcal{B} \big( \mathcal{C}, r_{\mathcal{C}} \big) \big|   \approx \frac{1}{\epsilon} \big| \mathscr{C} \big|     \bigg]        \text{, } \\ \\ \mathscr{P}_2 \equiv    \frac{1}{\textbf{P} \big[   p_{\mathrm{EC}, \text{bits}^{\prime}-1} \approx 1  \big] }        \text{, } \\ \\ \mathscr{P}_3 \equiv     \textbf{P} \bigg[   \forall \epsilon > 0,  \exists \text{ codewords } \mathcal{C} \in \mathscr{C} \text{ with } \text{bits}^{\prime} \text{ bits}   :   \big| \mathcal{B} \big( \mathcal{C}, r_{\mathcal{C}} \big) \big|   \\  \approx \frac{1}{\epsilon} \big| \mathscr{C} \big| \bigg]       \text{. }
\end{align*}


\noindent Observe, for $\mathrm{bits}^{\prime\prime} >> \mathrm{bits}^{\prime}$, 


\begin{align*}
    \mathscr{P}_2 < \frac{1}{\textbf{P} \big[ p_{\mathrm{EC}, \mathrm{bits}^{\prime\prime}-1} \approx 1  \big]} \equiv \mathscr{P}^{\prime}_2     \Longrightarrow    \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \big\{   \mathscr{P}_1 \mathscr{P}_2 \mathscr{P}_3     \big\}   <  \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \big\{   \mathscr{P}_1 \mathscr{P}^{\prime}_2 \mathscr{P}_3     \big\}    \text{, }
\end{align*}


\noindent from the error correction probability being monotonically decreasing with respect to the number of bits in a transmitted codeword. To argue that,



\begin{align*}
           \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \big\{   \mathscr{P}_1 \mathscr{P}^{\prime}_2 \mathscr{P}_3     \big\}       \text{, }
\end{align*}


\noindent can be upper bounded by the error correction probability, observe,

\begin{align*}
     \mathscr{P}_3   \lesssim r_{\mathcal{C}} \equiv C^{\prime} \big( r_{\mathcal{C}} , \mathrm{bits}^{\prime} \big) \equiv C^{\prime}  \in \big[ 0, 1 \big]       \text{, }
\end{align*}


\noindent readily implying, 

\begin{align*}
0 \approx  p_{\mathrm{FA}} <  (\mathcal{C}\text{-Probab.})  <  \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \big\{   \mathscr{P}_1 \mathscr{P}^{\prime}_2 \mathscr{P}_3     \big\} <   \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}         \big\{   \mathscr{P}_1 \mathscr{P}^{\prime}_2 C^{\prime}   \big\}  \\ \overset{(\mathscr{P}_1 \mathscr{P}_2 \mathscr{P}_3)}{\equiv} \big\{ \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}        \mathscr{P}_1 \big\}  \big\{ \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}      \mathscr{P}^{\prime}_2  \big\} \big\{ \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}      C^{\prime} \big\}  \\ \lesssim     \big\{ \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}        \mathscr{P}_1 \big\}  \big\{ \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}      \mathscr{P}^{\prime}_2  \big\}  \\   \lesssim             \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}        \mathscr{P}_1   <   \underset{\text{bits}^{\prime} \longrightarrow + \infty}{\mathrm{lim}}   \textbf{P} \big[   p_{\mathrm{EC}, \text{bits}^{\prime}-1} \approx 1   \big] \\ <   p_{\mathrm{EC}} \approx 1          \text{, }
