\noindent Altogether,


\begin{align*}
 p_{\mathrm{FA}, \mathrm{bits}} \longrightarrow 0   \Longrightarrow p_{\mathrm{EC}, \mathrm{bits}} \longrightarrow 1 \text{, as bits} \longrightarrow + \infty \Longrightarrow        p_{\mathrm{FA}, + \infty} \approx  0  \\  \Longrightarrow p_{\mathrm{EC}, + \infty } \approx  1  \text{, }
\end{align*}



\noindent for codewords with infinitely many bits, from which we conclude the forward direction of the argument. ($\Longleftarrow$) Suppose that $p_{\mathrm{FA}} \approx 0$. To argue that the remaining direction of the correspondence holds, introduce the following expression for the false acceptance probability, as a supremeum over all instances over $A \longrightarrow B$,


\begin{align*}
p_{\mathrm{FA}} \equiv \underset{\mathrm{FA}, A \longleftrightarrow B}{\mathrm{sup}}  \textbf{P} \big[   \mathrm{FA} :  \textbf{P} \big[      \text{Alice, or Bob, accepts a message corrupted by Eve that} \\ \text{is placed into } \mathcal{A}^{rn}_{A \longleftrightarrow B}     \big] > 0  \big]  \text{, }
\end{align*}


\noindent for which Alice and Bob can mistakenly accept a message from Eve that has been corrupted. Moreover,


\begin{align*}
 p_{\mathrm{FA}} \equiv   \underset{n \longrightarrow + \infty}{\mathrm{lim}}  \bigg\{       \underset{\text{FA on } n-\text{bits}, A \longleftrightarrow B}{\mathrm{sup}}    p_{\mathrm{FA}}             \bigg\} \equiv \underset{n \longrightarrow + \infty}{\mathrm{lim}} \bigg\{ \underset{\mathrm{fa} \in \mathrm{FA}}{\bigcup} \bigg\{         \underset{\text{fa on } n-\text{bits}, A \longleftrightarrow B}{\mathrm{sup}}    p_{\mathrm{FA}}             \bigg\} \bigg\}   \\  <   \underset{n \longrightarrow + \infty}{\mathrm{lim}}  \bigg\{ \underset{\mathrm{fa} \in \mathrm{FA}}{\bigcup} p^{*}_{\mathrm{fa},n}   \bigg\}   \equiv p^{*}_{\mathrm{FA}}              \text{,}
\end{align*}


\noindent where $p^{*}_{\mathrm{FA}}     $ denotes the instance of false acceptance for which the probability of Alice, or Bob, falsely accepting a corrupted message is maximized. This probability can be lower bounded with the error correction probability, from the fact that,


\begin{align*}
  0 \approx  p_{\mathrm{FA},n} <   p^{*}_{\mathrm{FA},n}  <   \textbf{P} \big[   p_{\mathrm{EC},n} \big|   p^{*}_{\mathrm{FA},n}        \big]             \overset{(\text{Bayes' Rule})}{\equiv}   \textbf{P} \big[ p_{\mathrm{EC},n}     \big] \bigg[  \frac{\textbf{P} \big[    p^{*}_{\mathrm{FA},n}  \big| p_{\mathrm{EC},n}       \big]}{\textbf{P} \big[  p^{*}_{\mathrm{FA},n}       \big]} \bigg]    \\ <   \frac{\textbf{P} \big[    p^{*}_{\mathrm{FA},n}  \big| p_{\mathrm{EC},n}       \big]}{\textbf{P} \big[  p^{*}_{\mathrm{FA},n}       \big]}           \overset{(1)}{\approx}  \textbf{P} \big[ p_{\mathrm{EC},n} \big] \equiv  p_{\mathrm{EC},n} \overset{(2)}{<} p^{*}_{\mathrm{EC},n}  \overset{(3)}{<} p^{*}_{\mathrm{EC}}      \text{, }
\end{align*}

\noindent where, in (1), we made use of the observation that,

\begin{align*}
  \frac{\textbf{P} \big[    p^{*}_{\mathrm{FA},n}  \big| p_{\mathrm{EC},n}       \big]}{\textbf{P} \big[  p^{*}_{\mathrm{FA},n}       \big]}  \approx  \frac{\textbf{P} \big[    p^{*}_{\mathrm{FA},n}  ,  p_{\mathrm{EC},n}       \big]}{\textbf{P} \big[  p^{*}_{\mathrm{FA},n}       \big]} \equiv  \frac{\textbf{P} \big[    p^{*}_{\mathrm{FA},n}  \cap   p_{\mathrm{EC},n}       \big]}{\textbf{P} \big[  p^{*}_{\mathrm{FA},n}       \big]} \equiv \frac{\textbf{P} \big[    p^{*}_{\mathrm{FA},n} \big] \textbf{P} \big[   p_{\mathrm{EC},n}       \big]}{\textbf{P} \big[  p^{*}_{\mathrm{FA},n}       \big]} \\ =  \textbf{P} \big[   p_{\mathrm{EC},n}       \big] \text{, }
\end{align*}


\noindent while, in (2), we made use of the observation that,

\begin{align*}
 p^{*}_{\mathrm{EC},n} \equiv \bigg\{         \underset{\mathrm{EC}, A \longleftrightarrow B}{\mathrm{sup}} p_{\mathrm{EC}}            \bigg\}  \equiv \underset{\mathrm{ec} \in \mathrm{EC}}{\bigcup} \bigg\{         \underset{\mathrm{ec}, A \longleftrightarrow B}{\mathrm{sup}} p_{\mathrm{ec}}            \bigg\} <    \underset{\mathrm{ec} \in \mathrm{EC}}{\bigcup}  \big\{ p^{*}_{\mathrm{ec},n} \big\} \equiv p^*_{\mathrm{EC},n} \text{,}
\end{align*}


\noindent and finally, in (3), that,


\begin{align*}
 \underset{n \longrightarrow + \infty}{\mathrm{lim}}  p^*_{\mathrm{EC},n} \equiv p^*_{\mathrm{EC}} \longrightarrow 1 \text{. }
\end{align*}

\noindent Hence,

\begin{align*}
 0 \approx  p_{\mathrm{FA}} < p_{\mathrm{EC}} \approx 1   \text{, }
\end{align*}


\noindent from which we conclude the reverse direction of the argument. With both directions of the correspondence established, we conclude the argument. \boxed{}



