\underset{y \in \textbf{Y}, z \in \textbf{Z}}{\bigcup} \bigg\{  \textbf{P} \big[  \forall \text{ encoding} \in \mathcal{N}^{n}_{p,q,A \longleftrightarrow B}, \exists \text{ decoding}: \text{decoding} \in \mathcal{A}^{rn}_{A \longleftrightarrow B} \\ \Longleftrightarrow  \big\{  \big\{ x \big\}  \cap \big\{ y \big\} \equiv \emptyset  \big\}    \big] \bigg\} \equiv 1 \text{, }
