 \begin{align*} \frac{ \underset{\mathrm{EC}, B \longleftrightarrow E}{\mathrm{sup}} \bigg\{  \underset{y \in \textbf{Y}, z \in \textbf{Z}}{\bigcup}    \bigg\{ \textbf{P} \big[  \big\{  \forall \mathscr{C}^{*} \in \textbf{R}, \exists \text{ } \mathrm{ ec } : \mathscr{O} \big( y,z  \big)  > \mathscr{C}^{*}, p_{\mathrm{ec}} > 0   \big\}    \big| \big\{ \text{alphabets } y, z  \big\} \big]     \bigg\} \bigg\}   +     \frac{1}{CC}  }{p_{\mathrm{FA}, A \longleftrightarrow B }}     \text{. }
