\subsubsection{Argument}

\noindent \textit{Proof of Theorem 2}. To show that each desired probability can be made arbitrarily small at the same time, it suffices to argue,


\begin{align*}
 \textbf{P} \big[ p_{\mathrm{FA}} > 0 \big| p_{\mathrm{DE}} > 0  \big] > 0 \Longleftrightarrow  \textbf{P} \big[ p_{\mathrm{DE}} > 0 \big| p_{\mathrm{FA}} > 0  \big] >  0    \text{. }
