\noindent That is, conditionally upon $p_{\mathrm{DE}}$, or $p_{\mathrm{FA}}$ occurring, $p_{\mathrm{FA}}$ and $p_{\mathrm{DE}}$ can occur. If the probabilities in the conditioning above are set to be very close to $0$,

\begin{align*}
 \textbf{P} \big[ p_{\mathrm{FA}} > 0 \big| p_{\mathrm{DE}} \approx 0  \big] \approx 0 \Longleftrightarrow  \textbf{P} \big[ p_{\mathrm{DE}} > 0 \big| p_{\mathrm{FA}} \approx 0   \big] \approx 0    \text{. }
\end{align*}


\noindent Fix some constant $CC>0$. Under the assumption that $N_{A \longleftrightarrow B} > N_{B \longleftrightarrow E}$, to prove the desired result,

\begin{align*}
 p_{\mathrm{EC}, A \longleftrightarrow B} >   p_{\mathrm{EC}, B \longleftrightarrow E}  \text{, } \\ \\   p_{\mathrm{FA}, B \longleftrightarrow E}  >   p_{\mathrm{FA}, A \longleftrightarrow B}  \text{, }
\end{align*}



\noindent for,


\begin{align*}
 \underset{\mathrm{EC}, A \longleftrightarrow B}{\mathrm{sup}}  \big\{ \cdot \big\} \equiv   \underset{\mathrm{ec} \in \mathrm{EC}, A \longleftrightarrow B}{\mathrm{sup}}  \big\{ \cdot \big\} \text{, }
