Before the proof of Theorem \ref{thm1} for discrete nonlinear Schr{\"o}dinger equation with well potential and non-autonomous nonlinearities, we consider the limit functional
\[
\Phi^{\infty}(u)= \frac{1}{2}\int_{\mathbb{Z}^{d}} |\nabla u|^{2}\, dx
-\int_{\mathbb{Z}^{d}}\tilde{F}(u) \,dx.
\]
Limit functional is a special case of (5) such that $V(x)=0$ and $F(x,u)=\tilde{F}(u)$.  Set $E^{\infty}_a :=\inf\limits_{u\in S_a}\Phi^{\infty}(u)$. Then we try to find a threshold for $E_a^{\infty}$ before proving the main results for $E_a$. For our purposes, we need the following lemma.
\begin{lemma}\label{limitcomp}
   Suppose $\{u_n\}$ is a minimizing sequence of $E^{\infty}_a$ for $\Phi^{\infty}$, then one of the following holds:\\
    (i) $\lim\limits_{n\rightarrow\infty}{\Vert u_n(x)\Vert_{\infty}}=0.$\\
    (ii) There exists a family $\{y_n\}\subset\mathbb{Z}^d$ and a global minimizer $u$ such that if taking a subsequence necessarily, we have $
    u_n(\cdot-y_n)\rightarrow u$ in $l^2(\mathbb{Z}^d).$
\end{lemma}
\begin{proof}
    Suppose (i) is not true, then taking a subsequence if necessary, we have
    \[
    0\textless\lim_{n\rightarrow\infty}\sup_{x\in\mathbb{Z}^d}\vert u_n(x) \vert.
    \]
Suppose $\sup_{x\in\mathbb{Z}^d}\vert u_n(x) \vert=\vert u_n(y) \vert$, then $u_n(\cdot-y_n)$ is bounded in $l^2(\mathbb{Z}^d)$ by Lemma \ref{boundness}, therefore there exists $u\in l^2(\mathbb{Z}^d)$ such that $u_n(\cdot-y_n)\rightharpoonup u$ in $l^2(\mathbb{Z}^d)$. Set $v_n=u_n(\cdot-y_n)-u$, then by Lemma \ref{PhiBreLieb} we have 
    \[
    \Phi^{\infty}(u_n)-\Phi^{\infty}(u)-\Phi^{\infty}(v_n)=o(1).
    \]

    We claim that $\lim\limits_{n\rightarrow\infty}\Vert v_n\Vert_{\infty}=0$. Suppose it is not true, then taking a subsequence if necessary, we find $\{z_n\}\subset\mathbb{Z}^d$ and $v\in l^2(\mathbb{Z}^d)$ such that $v_n(\cdot-z_n)\rightharpoonup v$ in $l^2(\mathbb{Z}^d)$. 
    Set $\omega_n= v_n(\cdot-z_n)-v$, then by Lemma \ref{PhiBreLieb} again we have
    \[
    \Phi^{\infty}(v_n)=\Phi^{\infty}(v)+\Phi^{\infty}(\omega_n)+o(1).
    \]
    Therefore we have 
    \[
    \Phi^{\infty}(u_n)=\Phi^{\infty}(u)+\Phi^{\infty}(v)+\Phi^{\infty}(\omega_n)+o(1).
    \]
    Set $\beta = \Vert u\Vert_{2}^2$, $\gamma=\Vert v\Vert_{2}^2$, $\delta = a-\beta-\gamma$, then by Corollary \ref{NormBreLieb}, $\Vert\omega_n\Vert_2^2 = \delta+o(1)$.\\

    If $\delta\textgreater0$, then we set $\tilde{\omega}_n=\frac{\sqrt{\delta}}{\Vert \omega_n\Vert_{2}}\omega_n$. Similar to the proof of (6) in Lemma \ref{funproper}, we have $\Phi^{\infty}(\omega_n)=\Phi^{\infty}(\tilde{\omega}_n)+o(1)$. Therefore, by (4) in Lemma \ref{funproper}, we have 
    \[
    \begin{aligned}
    \Phi^{\infty}(u_n)&=\Phi^{\infty}(u)+\Phi^{\infty}(v)+\Phi^{\infty}(\omega_n)+o(1)\\
    &=\Phi^{\infty}(u)+\Phi^{\infty}(v)+\Phi^{\infty}(\tilde{\omega}_n)+o(1)\\
    &\geq \Phi^{\infty}(u)+\Phi^{\infty}(v)+E^{\infty}_{\delta}+o(1)\\
    &\geq E^{\infty}_{\beta}+E^{\infty}_{\gamma}+E^{\infty}_{\delta}+o(1)\\
    &\geq E^{\infty}_{a}+o(1).
    \end{aligned}
    \]
    Taking $n\rightarrow\infty$, we have all inequalities become equalities and $u,v$ are global minimizers of $E_{\beta}^{\infty}, E_{\gamma}^{\infty}$ respectively. But then by (5) in Lemma \ref{funproper}, $E^{\infty}_{\beta}+E^{\infty}_{\gamma}\textgreater E^{\infty}_{\beta+\gamma}$, which is a contradiction.\\

    If $\delta =0$, then $\lim\limits_{n\rightarrow\infty}\Vert\omega_n\Vert_{2}=0$, which implies $\lim\limits_{n\rightarrow\infty}\Phi^{\infty}(\omega_n)=0$ by Lemma \ref{Fvanish}. Therefore we have
    \[
    E^{\infty}_{a} = \Phi^{\infty}(u)+\Phi^{\infty}(v)\geq E^{\infty}_{\beta}+E^{\infty}_{\gamma}\geq E^{\infty}_a.
    \]
    Thus, $u,v$ are global minimizers of $E_{\beta}^{\infty}, E_{\gamma}^{\infty}$ respectively, but this is a contradiction to (5) in Lemma \ref{funproper}.\\

Hence, we prove the claim.  Therefore by Lemma \ref{vanish} we have $\lim\limits_{n\rightarrow\infty}\Vert v_n\Vert_{q+1}=0$, which implies $\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\tilde{F}(v_n)dx=0$ by Lemma \ref{Fvanish}. Now we prove that $\lim\limits_{n\rightarrow\infty}\Vert v_n\Vert_{2}=0$. Otherwise, without loss of generality, taking a subsequence if necessary, we may assume $\lim\limits_{n\rightarrow\infty}\Vert v_n\Vert_{2}\textgreater0.$ Since 
    \[
    \Phi^{\infty}(u_n)=\Phi^{\infty}(u)+\Phi^{\infty}(v_n)+o(1)
    \]
    and 
    \[
    \varliminf_{n\rightarrow\infty}\Phi^{\infty}(v_n)\geq -\lim_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\tilde{F}(v_n)dx=0,
    \]
    we have 
    \[
    E^{\infty}_{a}\geq \Phi^{\infty}(u)\geq E^{\infty}_{\beta}\geq E^{\infty}_{a}.
    \]
    Thus $u$ is a global minimizer of $E^{\infty}_{\beta}$, but then $E^{\infty}_{\beta}\textgreater E^{\infty}_{a}$, which is a contradiction. Hence, we prove the result $\lim\limits_{n\rightarrow\infty}\Vert v_n\Vert_2=0.$ By Corollary \ref{NormBreLieb}, we have $\Vert u\Vert_2^2=a$. Since $\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\tilde{F}(v_n)dx=0$,  $\lim\limits_{n\rightarrow\infty}\Phi^{\infty}(v_n)=0$. By Lemma \ref{PhiBreLieb} we have $\Phi^{\infty}(u)=\lim\limits_{n\rightarrow\infty}\Phi^{\infty}(u_n)=E^{\infty}_a$.
\end{proof}
 Using Lemma \ref{limitcomp}, we are able to find a ground state normalized solution when $E_a^{\infty}\textless0$.
\begin{theorem}\label{limitmain}
    If $E_a^{\infty}\textless0$, then there exists $u\in S_a$ such that $\Phi^{\infty}(u)=E^{\infty}_a$. Moreover, let $\alpha^{\infty}=inf\{a:E^{\infty}_a\textless 0\}$, then if $a\textgreater\alpha^{\infty}$, $E_a^{\infty}$ is attained, if $0\textless a\textless\alpha^{\infty}$, $E_a^{\infty}$ can not be attained.
\end{theorem}
\begin{proof}
    Taking a minimizing sequence $\{u_n\}$ for $E_a^{\infty}$, we exclude the case $\lim\limits_{n\rightarrow\infty}\Vert u_n\Vert_{{\infty}}=0$. Otherwise, suppose that $\lim\limits_{n\rightarrow\infty}\Vert u_n\Vert_{{\infty}}=0$, by Lemma \ref{vanish} we have $u_n\rightarrow0$ in $l^{q+1}(\mathbb{Z}^d)$, therefore by Lemma \ref{Fvanish} we have $\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\tilde{F}(u_n)dx=0.$ Thus 
    \[
    E_a^{\infty}=\lim\limits_{n\rightarrow\infty}\Phi^{\infty}(u_n)\geq-\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\tilde{F}(u_n)dx=0.
    \]
    This contradicts $E_a^{\infty}\textless 0$. Therefore, by Lemma \ref{limitcomp}, there exists a global minimizer $u$. \\

    For the rest of the proof, if $a\textgreater\alpha^{\infty},$ then $E_a^{\infty}\textless0$ and thus $E_a^{\infty}$ is attained. If $0\textless a\textless\alpha^{\infty}$, $E_a^{\infty}$ can not be attained. If not, by (5) of Lemma \ref{funproper} we have $E^{\infty}_{\alpha^{\infty}}\textless E_a^{\infty}\leq 0$, but this contradicts $E_{\alpha^{\infty}}^{\infty}=0$. This proves the result.
\end{proof}

Afterward, we give a criterion for $\alpha^{\infty}=0$, which is closely related to the discrete Gagliardo-Nirenberg-Sobolev inequality.
We first recall a partial result of discrete Gagliardo-Nirenberg-Sobolev inequality, which was proved in \citep{MR4608774}.
\begin{theorem}\label{partialGNS}
     Suppose $d\geq 1$, if $2\textless p\leq p_d$ with

    \begin{equation*}
p_d:=\left\{
\begin{aligned}
    &\infty,d=1,2\\
    &\frac{2d}{d-2},d\geq 3
\end{aligned}
\right.
\end{equation*}
    then for every $0\textless\theta\textless\min(1,d(\frac{1}{2}-\frac{1}{p}))$, there exists constant $C_{\theta,p}$ such that the following inequality holds for any function $u\in l^2(\mathbb{Z}^d)$
\begin{equation}
\Vert u\Vert_p\leq C_{\theta,p}\Vert\nabla u\Vert_2^{\theta}\Vert u\Vert_2^{1-\theta} .  
\end{equation}
For $p\textgreater p_d$, (8) holds with $\theta =1$.
\end{theorem}

However Theorem \ref{partialGNS} do not address the case $2\textless p\leq p_d$ and $\theta = \min(1,d(\frac{1}{2}-\frac{1}{p}))$. We give a supplementary proof in the case $d\geq 3$ and $d=1$. First, recall the discrete Sobolev inequality \citep{HUA20156162}; see also \citep{MR4328634}. 
\begin{theorem}\label{sobolev}
    Suppose $d\geq 2$, then for any $u\in D^{1,p}(\mathbb{Z}^d)$, we have
    \[
    \Vert u\Vert_{p^{*}}\leq C_p\Vert u\Vert_{D^{1,p}}
    \]
    where $1\leq p\textless d$, $p^{*}=\frac{dp}{d-p}$, $\Vert u\Vert_{D^{1,p}}=(\int_{\mathbb{Z}^d}\vert\nabla u\vert^pdx)^{\frac{1}{p}}$ and $D^{1,p}(\mathbb{Z}^d)$ is the completion of $C_0(\mathbb{Z}^d)$ under the $D^{1,p}$ norm.
\end{theorem}
Using Theorem 4,6, we have the following theorem.
\begin{theorem}\label{ourGNS}


      Suppose $d\geq 3$ or $d=1$, if $2\textless p\leq p_d$ with 

    \begin{equation*}
p_d:=\left\{
\begin{aligned}
    &\infty,d=1\\
    &\frac{2d}{d-2},d\geq 3
\end{aligned}
\right.
\end{equation*}
    then for every $\theta=\min(1,d(\frac{1}{2}-\frac{1}{p}))$, there exists constant $C_{d,p}$ such that the following inequality holds for any function $u\in l^2(\mathbb{Z}^d)$
\begin{equation*}
\Vert u\Vert_p\leq C_{d,p}\Vert\nabla u\Vert_2^{\theta}\Vert u\Vert_2^{1-\theta}.   
\end{equation*}
Suppose $d=2$, then there exists constant $C$ such that the following inequality holds for any function $u\in l^2(\mathbb{Z}^2)$
\[
\Vert u\Vert_4^4\leq C\Vert\nabla u\Vert_2^{2}\Vert u\Vert_2^{2}.    
\]
\end{theorem}
\begin{proof}
    If $d\geq 3$ and $2\textless p\leq p_d$, by Theorem \ref{sobolev} and H\"{o}lder's inequality, we have
    \[
        \Vert u\Vert_p\leq C\Vert u\Vert_{p_d}^{d(\frac{1}{2}-\frac{1}{p})}\Vert u\Vert_2^{1-d(\frac{1}{2}-\frac{1}{p})}\leq C\Vert \nabla u\Vert_{2}^{d(\frac{1}{2}-\frac{1}{p})}\Vert u\Vert_2^{1-d(\frac{1}{2}-\frac{1}{p})}.
    \]

    If $d=1$ and $2\textless p\leq\infty$, then for any $v\in l^1(\mathbb{Z})$, suppose $\vert v(x)\vert=\Vert v\Vert_{\infty}$ for some $x$, then we have 
    \begin{align*}
        \vert v(x)\vert&\leq\sum\limits_{i=0}^{k}\vert v(x+i)-v(x+i+1)\vert +\vert v(x+k+1)\vert\\
        &\leq C\Vert\nabla v\Vert_{1} +\vert v(x+k+1)\vert.
    \end{align*}
    Letting $k\rightarrow\infty$, we have that
    \begin{equation}
    \Vert v\Vert_{\infty}\leq C\Vert \nabla v\Vert_{1} .   
    \end{equation}

    For any $u\in l^2(\mathbb{Z})$, substituting $v = u ^2$ into (9), we have that
    \begin{align*}
        \Vert u\Vert^{2}_{\infty}&\leq C\sum\limits_{x\sim y}\vert u^{2}(x)-u^{2}(y)\vert\\
        &\leq C\sum\limits_{x\sim y}\vert u(x)-u(y)\vert(\vert u(x)\vert+\vert u(y)\vert)\\
        &\leq  C(\sum\limits_{x\sim y}\vert u(x)-u(y)\vert^{2})^{\frac{1}{2}}(\sum\limits_{x\sim y}\vert u(x)\vert^{2}+\vert u(y)\vert^{2})^{\frac{1}{2}}\\
        &\leq C\Vert \nabla u\Vert_{2}\Vert u\Vert_{2}.
    \end{align*}
    Hence we have
    \begin{align*}
        \Vert u\Vert_p^p&\leq \Vert u\Vert_2^2\Vert u\Vert_{\infty}^{p-2}\\
        &\leq C\Vert u\Vert_2^2(\Vert\nabla u\Vert_2\Vert u\Vert_{2})^{\frac{p-2}{2}}\\
        &=C\Vert \nabla u\Vert_2^{\frac{p-2}{2}}\Vert u\Vert_{2}^{\frac{p+2}{2}}.
    \end{align*}

    If $d=2$, by Theorem \ref{sobolev}, for all $v\in l^1(\mathbb{Z}^2)$, we have
    \[
    \Vert v\Vert_2\leq C\Vert \nabla v\Vert_1.
    \]
    Hence, for all $u\in l^2(\mathbb{Z}^2)$, taking $v=u^2$, we have
    \begin{align*}
        \Vert u\Vert^{2}_{4}&\leq C\sum\limits_{x\sim y}\vert u^{2}(x)-u^{2}(y)\vert\\
        &\leq C\sum\limits_{x\sim y}\vert u(x)-u(y)\vert(\vert u(x)\vert+\vert u(y)\vert)\\
        &\leq  C(\sum\limits_{x\sim y}\vert u(x)-u(y)\vert^{2})^{\frac{1}{2}}(\sum\limits_{x\sim y}\vert u(x)\vert^{2}+\vert u(y)\vert^{2})^{\frac{1}{2}}\\
        &\leq C\Vert\nabla u\Vert_{2}\Vert u\Vert_{2}.
    \end{align*}
\end{proof}
In conclusion, we have the following corollary.
\begin{corollary}\label{masscritiGNS}
    There exists constant $C_{d,2+\frac{4}{d}}$ such that for any function $u\in l^2(\mathbb{Z}^d)$, $d\geq1$, the following inequality holds
    \[
    \Vert u\Vert_{2+\frac{4}{d}}^{2+\frac{4}{d}}\leq C_{d,2+\frac{4}{d}}\Vert \nabla u\Vert^2_2\Vert u\Vert_2^{\frac{4}{d}}.
    \]
\end{corollary}
Using Corollary \ref{masscritiGNS}, we can establish Theorem \ref{thm2} in the special case that $V(x)\equiv 0$ and $f(x,s)=\tilde{f}(s)$.
\begin{theorem}\label{limitcritirion}
    (i)If $\varliminf\limits_{s\rightarrow0}\frac{\tilde{F}(s)}{\vert s\vert^{2+\frac{4}{d}}}=\infty$ , then $\alpha^{\infty}=0$.\\ 
    (ii)If $\varlimsup\limits_{s\rightarrow0}\frac{\tilde{F}(s)}{\vert s\vert^{2+\frac{4}{d}}}\textless\infty$, then $\alpha^{\infty}\textgreater0$.
\end{theorem}
\begin{proof}

(i) For arbitrary $a\textgreater0$, let
    \[
    u_{n}(x)=\left\{
    \begin{aligned}
       & c_{a,d,n}\frac{n-\vert x\vert}{n^{\frac{d}{2}+1}}, \vert x\vert\leq n\\
       & 0, \mathrm{otherwise}
    \end{aligned}
    \right.
    \]
    where $c_{a,d,n}$ is taken such that $\Vert u_n\Vert_2^2=a.$ Then we have $\Vert\nabla u_n\Vert_2^2\leq C_{a,d}^1n^{-2}$ and $\Vert u_n\Vert_p^p\leq C^2_{a,d}n^{-\frac{d(p-2)}{2}}$ for all $2\textless p\textless \infty$, therefore $\lim\limits_{n\rightarrow\infty}\Vert u_n\Vert_{\infty}=0$. Since $\varliminf_{s\rightarrow0}\frac{\tilde{F}(s)}{\vert s\vert^{2+\frac{4}{d}}}=\infty$, for any large $\delta\textgreater0$, there exists $\eta\textgreater0$ such that
    \[
    \tilde{F}(s)\geq \delta \vert s\vert^{2+\frac{4}{d}}
    \]
    holds for all $s\in[-\eta,\eta]$. We take sufficiently large $\delta$  such that $\frac{1}{2}C^1_{a,d} -C^2_{a,d}\delta\textless0 $. Choosing large $n$ such that $\Vert u_n\Vert_{\infty}\leq\eta$, we have that
     \[
    \begin{aligned}
        \Phi^{\infty}(u_n)&\leq \frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla u_n\vert^2dx-\delta\int_{\mathbb{Z}^d}\vert u_n\vert^{2+\frac{4}{d}}dx\\
        &\leq \frac{1}{2}C^1_{a,d} n^{-2}-C^2_{a,d}\delta n^{-2}.\\
    \end{aligned}
    \]
     Then $\Phi^{\infty}(u_n)\textless 0$, and we have $E_a^{\infty}\textless 0$.\\

(ii)If $\varlimsup\limits_{s\rightarrow0}\frac{\tilde{F}(s)}{\vert s\vert^{2+\frac{4}{d}}}\textless\infty$, then there exist constants $C_{F}$ and $\eta\textgreater0$ such that 
\[
\tilde{F}(s)\leq C_{F} \vert s\vert^{2+\frac{4}{d}}
\]
holds for all $s\in[-\eta,\eta].$ Hence for $a\leq \eta^2$ and any $u\in S_a$, we have $\Vert u\Vert_{\infty}\leq\Vert u\Vert_2\leq\eta$. By Corollary \ref{masscritiGNS}, we have
\[
\begin{aligned}
    \Phi^{\infty}(u)&\geq \frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx-C_{F}\int_{\mathbb{Z}^d}\vert u\vert^{2+\frac{4}{d}}dx\\
    &\geq \frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx-C_{F}C_{d,2+\frac{4}{d}}a^{\frac{2}{d}}\Vert\nabla u\Vert_2^{2}.\\
\end{aligned}
\]
Hence, for $a\leq\min(\eta^2,(\frac{1}{2C_FC_{d,2+\frac{4}{d}}})^{\frac{d}{2}})$, we have that $\Phi^{\infty}(u)\geq 0 $ holds for all $u\in S_a$. Therefore, $E_a^{\infty}=0$ and $\alpha^{\infty}\textgreater 0$.
\end{proof}
By the above results, we have prove the limit case. We now consider the general case. We assume there exists $x\in\mathbb{Z}^d$ such that $V(x)\textless V_{\infty}=0$ or $f(x,s)\textgreater\tilde{f}(s)$, otherwise it is reduced to the limit case. Then we have the following lemmas, which will be useful to prove the main result.
\begin{lemma}\label{comparelimit}
    (i) $\forall a\textgreater0$, we have $E_a\leq E_a^{\infty}$.\\
    (ii) If $E_a^{\infty}$ is attained, then we have $E_a\textless E_a^{\infty}$.
\end{lemma}
\begin{proof}

    (i) Since $V(x)\leq 0$ and $f(x,s)\geq\tilde{f}(s)$, it is obvious that we have $E_a\leq E_a^{\infty}$.\\

    (ii) Suppose $u$ is a global minimizer of $\Phi^{\infty}$ with respect to $E_a^{\infty}$, let $x_1\in\mathbb{Z}^d$ such that  $V(x_1)\textless V_{\infty}=0$ or $f(x_1,s)\textgreater\tilde{f}(s)$. Take $x_0$ such that $u(x_0)\neq 0.$ Setting $\tilde{u}(x)=u(x+x_0-x_1)$,  we have
    \[
    \begin{aligned}
        E_a&\leq \frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla\tilde{u}\vert^2+V(x)\tilde{u}^2dx-\int_{\mathbb{Z}^d}F(x,\tilde{u})dx\\
        &=\frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla\tilde{u}\vert^2dx-\int_{\mathbb{Z}^d}\tilde{F}(\tilde{u})dx+\frac{1}{2}\int_{\mathbb{Z}^d}V(x)\tilde{u}^2dx-\int_{\mathbb{Z}^d}(F(x,\tilde{u})-\tilde{F}(\tilde{u}))dx\\
        &=E^{\infty}_a+\frac{1}{2}\int_{\mathbb{Z}^d}V(x)\tilde{u}^2dx-\int_{\mathbb{Z}^d}(F(x,\tilde{u})-\tilde{F}(\tilde{u}))dx.
    \end{aligned}
    \]
    Since $\frac{1}{2}\int_{\mathbb{Z}^d}V(x)\tilde{u}^2dx\leq 0$ and $-\int_{\mathbb{Z}^d}(F(x,\tilde{u})-\tilde{F}(\tilde{u}))dx\leq0$ can not vanish simultaneously, we have
    \[
    E_a\textless E_a^{\infty}.
    \]
\end{proof}
\begin{lemma}\label{compareattained}
    If $E_a\textless E_a^{\infty}$, then $E_a$ is attained.
\end{lemma}
\begin{proof}

    Take a minimizing sequence $\{u_n\}\subset S_a$ with respect to $E_a$, then $\{u_n\}$ is bounded in $l^2(\mathbb{Z}^d)$ by Lemma \ref{boundness}, so that taking a subsequence if necessary we assume $u_n\rightharpoonup u$ in $l^2(\mathbb{Z}^d)$. Lemma \ref{PhiBreLieb} implies that
    \[
    \Phi(u)=\Phi(u_n)+\Phi(u_n-u)+o(1).
    \]
    Assume $\Vert u\Vert_{2}^2=\eta$, then $\eta\leq a$. We prove that $\eta=a$.\\

Suppose that this is not true. If $\eta=0$, then for all $x\in\mathbb{Z}^d$, we have $\lim\limits_{n\rightarrow\infty}u_n(x)=0$. Since $\lim\limits_{\vert x\vert\rightarrow\infty}V(x)=0$, 
    by Lemma \ref{Vvanish} we have $\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}V(x)u_n^2dx=0$. 
    For any $\epsilon\textgreater0$, taking $\delta\textgreater0$ and $R\textgreater0$ which will be determined later, we have following estimate
    \[
    \begin{aligned}
        \vert\int_{\mathbb{Z}^d}(F(x,u_n)-\tilde{F}(u_n))dx\vert\leq&\int_{B_R}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\&
        +\int_{x\in B_R^c,\vert u_n\vert\leq\delta}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
        &+\int_{x\in B_R^c,\delta\leq\vert u_n\vert\leq\frac{1}{\delta}}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
        &+\int_{x\in B_R^c,\frac{1}{\delta}\leq\vert u_n\vert}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
        &\triangleq I_1+I_2+I_3+I_4.
    \end{aligned}
    \]
    Now we estimate $I_1,I_2,I_3,I_4$ seperately. \\

    For $I_1$, since for any $x\in\mathbb{Z}^d$, $\lim\limits_{n\rightarrow\infty}u_n(x)=0$, we have 
    \begin{align*}
    &\int_{B_R}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
    &\leq \int_{B_R}\vert F(x,u_n)\vert dx+\int_{B_R}\vert\tilde{F}(u_n)\vert dx\\
    &\leq \epsilon    
    \end{align*}
    for sufficiently large $n.$ \\

    For $I_2$, from condition $(f1)$ we have 
    \begin{align*}
    &\int_{x\in B_R^c,\vert u_n\vert\leq\delta}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
    &\leq \sup_{x\in\mathbb{Z}^d,0\textless s\leq\delta}\frac{\vert F(x,s)-\tilde{F}(s)\vert}{s^2} \int_{x\in B_R^c}\vert u(x)\vert^2 dx\\
    &\leq a\epsilon    
    \end{align*}
for sufficiently small $\delta$.\\

    For $I_3$, from condition $(f2)$ we have
    \[
    \begin{aligned}
        &\int_{x\in B_R^c,\delta\leq\vert u_n\vert\leq\frac{1}{\delta}}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
        &\leq\int_{x\in B_R^c,\delta\leq\vert u_n\vert\leq\frac{1}{\delta}}\vert F(x,u_n)-\tilde{F}(u_n)\vert\frac{\vert u(x)\vert^2}{\delta^2} dx\\
        &\leq\frac{a\epsilon}{\delta^2}
    \end{aligned}
    \]
    for sufficiently large $R$.\\

    For $I_4$, from condition $(f1)$ we have
    \begin{align*}
            &\int_{x\in B_R^c,\frac{1}{\delta}\leq\vert u_n\vert}\vert F(x,u_n)-\tilde{F}(u_n)\vert dx\\
            &
    \leq \sup_{x\in\mathbb{Z}^d,s\geq \frac{1}{\delta}}\frac{\vert F(x,s)-\tilde{F}(s)\vert}{s^{q+1}}\int_{x\in B_R^c}\vert u_n\vert^{q+1} dx\\
    &\leq C\epsilon
    \end{align*}
    for sufficiently small $\delta$.
    In conclusion, we have 
    \[
    \lim_{n\rightarrow\infty}\int_{\mathbb{Z}^d}(F(x,u_n)-\tilde{F}(u_n))dx=0.
    \]
    Hence, we have
    \[
    \begin{aligned}
        E_a&=\Phi(u_n)+o(1)\\
        &=\frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla u_n\vert^2+V(x)u_n^2dx-\int_{\mathbb{Z}^d}F(x,u_n)dx+o(1)\\
        &=\frac{1}{2}\int_{\mathbb{Z}^d}\vert\nabla u_n\vert^2dx-\int_{\mathbb{Z}^d}\tilde{F}(u_n)dx+o(1)\\
        &\geq E_a^{\infty} + o(1).
    \end{aligned}
    \]\
    But this is a contradiction to $E_a\textless E_a^{\infty}$.\\

    If $0\textless \eta\textless a$, then by Corollary \ref{NormBreLieb} we have $\Vert v_n\Vert_{2}^2=a-\eta+o(1)$. If $E_{\eta}$ can not be attained, then we have
    \[
    \begin{aligned}
        E_{a}&=\Phi(u)+\Phi(v_n)+o(1)\\
        &\geq \Phi(u)+E_{a-\eta}+o(1)
    \end{aligned}
    \]
   Letting $n\rightarrow\infty,$ we have
    \[
    \begin{aligned}
        E_{a}&\geq \Phi(u)+E_{a-\eta}\\
        &\textgreater E_{\eta}+E_{a-\eta}\\
        &\geq E_a.
    \end{aligned}
    \]
    This is a contradiction. Hence $u$ is a global minimizer of $\Phi$ with respect to $E_{\eta}$, but then 
    \[
    E_a\geq E_{\eta}+E_{a-\eta}.
    \]
    This is a contradiction to $E_a\textless E_{\eta}+E_{a-\eta}$ since $E_{\eta}$ is attained.\\

    In conclusion, $\Vert u\Vert_2^2=a$. By Corollary \ref{NormBreLieb} we have $\lim\limits_{n\rightarrow\infty}\Vert u_n-u\Vert_2=0$, hence by Lemma \ref{Fvanish}, $\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}F(x,u_n-u)dx=0.$ Note that $$\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\vert\nabla(u_n-u)\vert^2dx\leq C\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z}^d}\vert u_n-u\vert^2dx=0.$$ Using $\lim\limits_{n\rightarrow\infty}\Vert u_n-u\Vert_{\infty}\leq \lim\limits_{n\rightarrow\infty}\Vert u_n-u\Vert_2=0,$ by Lemma \ref{Vvanish} we have $\lim\limits_{n\rightarrow\infty}\int_{\mathbb{Z^d}}V(x)\vert u_n-u\vert^2dx=0$. In conclusion $\lim\limits_{n\rightarrow\infty}\Phi(u_n-u)=0$, which implies $\Phi(u)=\lim\limits_{n\rightarrow\infty}\Phi(u_n)=E_a$ by Lemma \ref{PhiBreLieb}, therefore $u$ is a global minimizer of $\Phi$ with respect to $E_a$.
\end{proof}
At the end, we are ready to prove Theorem \ref{thm1}
\begin{proof}[{Proof of  Theorem \ref{thm1}}]
    Take $\alpha=\inf\{a\enspace|E_a\textless0\}.$ If $a\textgreater\alpha$ and $E_a^{\infty}=0$, then $E_a\textless 0=E_a^{\infty}.$ By Lemma \ref{compareattained} $E_a$ is attained. If $a\textgreater\alpha$ and $E_a^{\infty}\textless0$, then by Theorem \ref{limitmain}, $E_a^{\infty}$ can be attained. Hence $E_a\textless E_a^{\infty}$ by (ii) in Lemma \ref{comparelimit}, and $E_a$ can be attained by Lemma \ref{compareattained}. If $0\textless a\textless\alpha$, the proof is similar to the proof of Theorem \ref{limitmain}.
\end{proof}

Before the proof of Theorem \ref{thm2}, we recall the Hardy inequality on the lattice $\mathbb{Z}^d$, $d\geq 3$; see \citep{MR2544038, MR3774437}.

\begin{theorem}\label{hardy}
    If $d\geq 3$, there exists constant $C_d$ such that
    \[
    C_d\int_{\mathbb{Z}^d}\frac{u^2}{1+\vert x\vert^2}dx\leq \int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx,u\in C_c(\mathbb{Z}^d).
    \]
\end{theorem}
Using Theorem \ref{hardy}, we can prove Theorem \ref{thm2}

\begin{proof}[{Proof of  Theorem \ref{thm2}}]
    Without loss of generality, we can assume $V_{\infty}=0$.\\

    (i) Considering the function $u_R$ in the proof of Lemma \ref{funproper}, we have 
    \[
    \Phi(u_R)\leq d\xi^2(2R+1)^{d-1}-\tilde{F}(\xi)(2R+1)^d.
    \]
    Take $R=\frac{1}{2}[\frac{d\xi^2}{\tilde{F}(\xi)}]$, then $\Phi(u_R)\textless0$, and $\Vert u_R\Vert_2^2=\xi^2([\frac{d\xi^2}{\tilde{F}(\xi)}]+1)^{d}$. Hence, $\alpha\textless\xi^2([\frac{d\xi^2}{\tilde{F}(\xi)}]+1)^{d}$.\\

    (ii) This is a direct consequence of Theorem \ref{limitcritirion} and Lemma \ref{comparelimit}.\\

    (iii) By Theorem \ref{hardy}, we have 
    \[
    \frac{1}{2}\int_{\mathbb{Z}^d}V(x)u^2dx\geq - \frac{C_d}{2}(1-\epsilon)\int_{\mathbb{Z}^d}\frac{1}{1+\vert x\vert^2}u^2dx\geq -(\frac{1-\epsilon}{2})\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx.
    \]
    Then the proof for $\alpha\textgreater0$ is similar to the proof of Theorem \ref{limitcritirion}. For the lower bound, suppose $u\in l^2(\mathbb{Z}^d)$ such that $\Vert u\Vert_2^2\leq \delta^2$, then $\Vert u\Vert_{\infty}\leq \delta$. We have
    \begin{align*}
    \Phi(u)&\geq\frac{\epsilon}{2}\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx-\int_{\mathbb{Z}^d}F(x,u)dx  \\
    &\geq\frac{\epsilon}{2}\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx- C_F\int_{\mathbb{Z}^d}\vert u\vert^{2+\frac{4}{d}}dx\\
    &\geq\frac{\epsilon}{2}\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx- C_FC_{d,2+\frac{4}{d}}a^{\frac{2}{d}}\int_{\mathbb{Z}^d}\vert\nabla u\vert^2dx.
    \end{align*}
    Hence, for $a\leq\min((\frac{\epsilon}{2C_{F}C_{d,2+\frac{4}{d}}})^{\frac{d}{2}},\delta^2)$, $\Phi(u)\geq 0 $.\\
    This proves the theorem.

\end{proof}

