		&R'_k(\lambda;q) 
		\\
		&= \sum_{\substack{\nu \vdash n-1 \\ \nu_1 = n-k-1}} q^{\nu_1 - (n-1-\lambda_1)} \sum_{T \in \SYT^{\pi'}_\nu} \wt(T;q) + \sum_{\substack{\nu \vdash n-1 \\ \nu_1 = n-k}} [\lambda_1-n+\nu_1+1]_q \sum_{T \in \SYT^{\pi'}_\nu} \wt(T:q)
		\\
