\section*{Semiclassical Approximation} \label{SA}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection*{Infinite time limit} \label{SA_INF}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Using only the $z$ component of the hyperfine interactions, 

\begin{equation} \label{eq20}
    A_{zz} = -  \frac{\mathcal{G}}{r^3} (3 \cos^2(\theta) - 1) 
\end{equation}

we can predict correlations in the infinite limit as:

\begin{equation} \label{eq21}
    C(\infty ) = \langle A_{zz} \rangle \langle A_{zz} \rangle
\end{equation}    

where the average $\langle A_{zz} \rangle$ is given by

\begin{equation} \label{eq22}
    \langle A_{zz} \rangle = - \mathcal{G} \langle\frac{1}{r^3}(3\cos^2(\theta) - 1)\rangle 
\end{equation}

\begin{equation} \label{eq23}
    \langle \frac{1}{r^{3}} (3 \cos^2(\theta) - 1) \rangle =  \frac{\int_{\frac{-L_{x}}{2}}^{\frac{L_{x}}{2}}  \,dx \int_{\frac{-L_{y}}{2}}^{\frac{L_{y}}{2}}  \,dy  \int_{0}^{L_{z}}  \,dz \frac{1}{r^{3}} (3 \cos^2(\theta) - 1) }{\int_{\frac{-L_{x}}{2}}^{\frac{L_{x}}{2}}  \,dx \int_{\frac{-L_{y}}{2}}^{\frac{L_{y}}{2}}  \,dy  \int_{0}^{L_{z}}  \,dz}
    %\rho (x, y, z) = \int_{x_{min}}^{x_{max}}  \,dx \int_{y_{min}}^{y_{max}}  \,dy  \int_{z_{min}}^{z_{max}}  \,dz \frac{1}{r^{3}}
\end{equation}

and $\mathcal{G}$ = $\frac{\hbar \mu_0 \gamma_{e} \gamma_{proton}}{4\pi}$ = -79064.3 \AA$^3$ kHz. The distance $r$ in Cartesian coordinates and considering the qubit at the origin is:

\begin{equation} \label{eq24}
    r = \sqrt{x^2 + y^2 + z^2} 
\end{equation}

The angle $\theta$ is given by

\begin{equation} \label{eq25}
    \cos^2(\theta) = \left( \frac{\vec{B} \cdot \vec{r}}{|\vec{B}| |\vec{r}|} \right)^{2}
\end{equation}

where the quantization axis of the qubit, $\vec{B}$, is:

\begin{equation} \label{eq26}
    \vec{B} = (0, 0, L_z)
\end{equation}

The limits of integration allow us to consider the average distance between a fixed point (qubit at the origin) and a random point inside the simulation box (dimensions $L_{x}$, $L_{y}$, and $L_{z}$) with angle $\theta$ with respect to the $z$-axis. In order to consider a more realistic geometry, we subtracted the exclusion region ($\sim$2.5 \AA) in both limits of integration in the $z$ axis, since in this region there are no molecules of water due to the chosen solid-liquid interaction in the LJ potential.


