\section{Определения, обозначения и предварительные сведения}
\label{sec:defs}
%%% begin file('ru//sec/defs.tex') %%%


Натуральные числа обозначаются как $\N$, $\om=\sset 0 \cup \N$ --- первый счетный ординал, $\om_1$ --- первый несчетный ординал. Под пространством мы подразумеваем тихоновское пространство. 
Пусть $X$ пространство.

Семейство $\cN$ подмножеств пространства $X$  называется \term{сетью} пространства $X$ если для любого открытого множества $U\subset X$ существует подсемейство $\cM\subset \cN$, такое что $U=\bigcup\cM$. Семейство $\cN$ называется \term{базой} пространства $X$ если $\cN$ состоит из открытых множеств и является сетью пространства $X$. 

Подмножество $S\subset X$ называется \term{секвенциально плотным} в $X$, если для любого $x\in X$ существует последовательность $(x_n)_n\subset S$, сходящаяся к точке $x$.

Пространство $X$ называется пространством \term{Фреше--Урысона}, если для каждого $A\subset X$ и $x\in \cl X$ существует последовательность $(x_n)_n\subset A$, сходящаяся к $x$.

Пусть $f\: X\to Y$ отображение пространств. Отображение $f$ называется \term{уплотнением}, если $f$ непрерывная биекция. Отображение $f$ называется \term{совершенным}, если $f$ непрерывное замкнутое отображение, такое что $f^{-1}(x)$ компактно для всех $x\in Y$.


Определим некоторые кардинальнве инварианты:
\begin{align*}
iw(X) &= \min \{\ \tau: X \text{ уплотняется на пространство с весом не более } \tau \} + \om,
\\
w(X) &= \min \{\ |\cB|: \cB \text{ является базой пространства } X \} + \om,
\\
nw(X) &= \min \{\ |\cN|: \cN \text{ является сетью пространства } X \}  + \om,
\\
d(X) &= \min \{\ |M|: M\subset X = \cl M \}  + \om,
\\
hd(X) &= \sup \{\ d(M): M\subset X\},
\\
l(X) &= \min \{\ \tau: \text{ для любого открытого покрытия }\ga\text{ пространства }X
\\
&\qquad\qquad\quad
\text{ существует }\la\subset\ga,\text{ такое что }|\la|\leq\tau\text{ и }\bigcup\la=X\ \},
\\
hl(X) &= \sup \{\ l(M): M\subset X\},
\\
hl^*(X) &= \sup \{\ hl(X^n): n\in\om\},
\\
wl(X) &= \min \{\ \tau: \text{ для любого открытого покрытия }\ga\text{ пространства }X
\\
&\qquad\qquad\quad
\text{ существует }\la\subset\ga,\text{ такое что }|\la|\leq\tau\text{ и }\cl{\bigcup\la}=X\ \}.
\end{align*}
Тогда 
$iw(X)$ --- \term{$i$-вес},
$w(X)$ --- \term{вес},
$nw(X)$ --- \term{сетевой вес},
$d(X)$ --- \term{плотность},
$hd(X)$ --- \term{наследственная плотность},
$l(X)$ --- \term{число Линделефа},
$hl(X)$ --- \term{наследственное число Линделефа},
$wl(X)$ --- \term{слабое число Линделефа}
пространства $X$. 

Пространства со счетной сетью (т.е.\ пространства со счетным сетевым весом) так же называются \term{космическими пространствами} (cosmic space). Пространства со счетной плотностью называются \term{сепарабельными} пространствами.


Пространство $X$ называется \term{линделефовым пространством}, если $l(X)\leq\om$. 
Пространство $X$ является \term{линделефовым $p$-пространством}, если $X$ можно совершенно отобразить на пространство со счетной базой. Непрерывные образы линделефовых $p$-пространств называют \term{линделефовыми $\Si$-пространствами}.

Линделефовы $\Si$-пространства также называют \term{счетно определяемыми} (countably determined) или \term{$K$-счетно определяемыми} ($K$-countably determined).

Множество $F\subset X$ называется \term{нуль} множеством пространства $X$, если $F=f^{-1}(0)$  для некоторой непрерывной функции на $X$. Дополнения до нуль множеств называется \term{ко-нуль} множествами.

Пространство $X$  называется \term{совершенно $\ka$-нормальным}, если для любого открытого $U\subset X$ замыкание $\cl U$ является нуль множеством.


Множество $Y\subset X$ \term{$z$-вложено} в $X$, если для любого нуль множества $Q$ множества $Y$ существует  нуль множество $F$ пространства $X$, такое что $Q=F\cap Y$.


Непрерывные функции на $X$ обозначим $C(X)$. Пусть $B\subset X$. Обозначим 
\[
C(X|B) = \set{ \pi_B(f) : f\in C(X) } \subset C(B),
\]
где $\pi_B(f)=\restr fB$.
Семейство функций вида 
\[
\de_x\: C(X) \to \R,\ f\mapsto f(x)
\]
для $x\in B$ определяют топологию $\tau_p(B)$ множества $C(X)$ с топологией поточечной сходимости на множестве $B$.
Если $M\subset C(X)$, то будем обозначать через $(M,\tau_p(B))$  подпространство $M$  топологического пространства $(C(X),\tau_p(B))$.
В общем случае пространство $(M,\tau_p(B))$ неотделимо, но мы будем рассматривать такие $M$ и $B$, что пространство $(M,\tau_p(B))$ отделимо.
Пространство $(C(X),\tau_p(X))$ с топологией поточечной сходимости  на всем множестве $X$ обозначим $C_p(X)$. 
Обозначим $C_p(X|B)$ множество $C(X|B)$ с топологией, наследуемой из пространства $C_p(X)$.
Если пространство $(M,\tau_p(B))$ отделимо, то отображение $\pi_B$ гомеоморфно отображает $(M,\tau_p(B))$ на $\pi_B(M)\subset C_p(X|B) \subset C_p(B)$.

Если $S\subset \R^X$, то $S$ \term{разделяет точки} $X$, если для различных $x,y\in X$ существует $f\in S$, такое что $f(x)\neq f(y)$.


\begin{proposition}[\cite{Arhangelskii1989CpBook}]\label{p:defs:1}
Пусть $X$ пространство.
\begin{enumerate}
\item
$d(X)\leq nw(X) \leq w(X)$ и $iw(X)\leq nw(X)$;
\item
если $X$ метризуемое пространство, то $d(X)=nw(X)=w(X)$;
\item
если $Y$ пространство и $X$ непрерывный образ $Y$, то $nw(X)\leq nw(Y)$;
\item
$nw(X)=nw(C_p(X))$;
\item
$d(X)=iw(C_p(X))$, 
$iw(X)=d(C_p(X))$;
\item
$nw(X)=iw(X)$ если $X$ линделефово $\Si$-пространство;
\item
$w(X)=nw(X)=iw(X)$ если $X$ линделефово $p$-пространство, в частности, если $X$ компактно;
\item
$hd(C_p(X))=hl^*(X)$.
\end{enumerate}
\end{proposition}

Счетно-аддитивная мера $\mu$ на $\si$-алгебре $\cB(X)$ борелевских множеств пространства $X$ называется \term{борелевской} мерой.
Обозначим
\begin{align*}
\mu^*(A)  &= \inf\set{\mu(B): A\subset B\in \cB(X)},
&
\mu_*(A)  &= \sup\set{\mu(B): A\supset B\in \cB(X)}
\end{align*}
\term{внешнюю} и \term{внутреннюю} меру множества $A\subset X$.
Множество вероятностных борелевских мер на пространстве $X$ обозначим через $P_b(X)$.
Пусть $\mu\in P_b(X)$.
Вероятностная мера $\mu$ называется \term{радоновской}, если для всякого борелевского множества $B\subset X$ и для всякого $\ep>0$ существует компактное $K\subset B$, такое что $\mu(B\setminus K)<\ep$. 
Множество вероятностных радоновских мер на пространстве $X$ обозначим через $P(X)$.
Мера $\mu$ называется \term{$\tau$-аддитивной}, если
\[
\mu(\bigcup\cU) = \sup \set{ \mu(\bigcup\cV) : \cV\subset \cU,\ |\cV|<\om }
\]
для любого семейства $\cU$ открытых подмножеств пространства $X$. 
Множество вероятностных $\tau$-аддитивных мер на пространстве $X$ обозначим через $P_\tau(X)$. Отметим, что $P(X)\subset P_\tau(X)$. 

Пусть $Y$ пространство и $X\subset Y$.  Множество $P_b(X)$ естественным образом вложено в $P_b(Y)$, мере $\mu\in P_b(X)$ соответствует мера $\tilde\mu\in P_b(Y)$, такая что $\tilde\mu(B)=\mu(B\cap Y)$ для $B\in\cB(Y)$.  Будем считать, что $P_b(X)\subset P_b(Y)$. Если $Y$ компактно, то $P(X)\subset P_\tau(X)\subset P(Y)$. 
Положим $P_\si(X)=\{\mu\in P(\bt X): \mu(C)=0$ для любого компактного множества $C\subset \bt X\setminus X$ типа $G_\de\}$. Меры из $P_\si(X)$ соответствуют вероятностным $\si$-аддитивным мерам на $\si$-алгебре бэровских множеств пространства $X$.

Обозначим через $C^*(X)$ множество непрерывных ограниченных функций на $X$.
Семейство функции вида 
\[
\ph_f\: P_\tau(X) \to \R,\ \mu \mapsto \mu(f) = \int_X f \mathrm{d}\,\mu
\]
для $f\in C^*(X)$ определяют слабую топология пространства $P_\tau(X)$.

\begin{proposition}[\cite{Banakh1995ru}]\label{p:defs:2}
Пусть $Y$ компактное пространство и $X\subset Y$.
Тогда $w(X)=w(P(X))=w(P_\tau(X))$ и 
\begin{align*}
P(X)  &= \set{\mu \in P(Y): \mu_*(X)=1},
&
P_\tau(X)  &= \set{\mu \in P(Y): \mu^*(X)=1}.
\end{align*}
Вложение $P(X)$ и $P_\tau(X)$ в $P(Y)$ является топологическим вложением.
\end{proposition}

Компактные выпуклые подмножества линейных локально выпуклых пространств будем называть \term{выпуклыми компактами}.
Пусть $K$ выпуклый компакт. 

Точка $x\in K$ называется \term{крайней точкой}, если из того, что $y,z\in K$ и $x=\frac{y+z}2$ вытекает, что $x=y=z$.
Множество крайних точек выпуклого компакта $K$ обозначим как $\ext X$. Множество непрерывных аффинных функций на $K$ обозначим как $\af K$.
Пусть $\nmc$ есть $\sup$-норма на $\af K$, $\nm f=\sup_{x\in K} |f(x)|$ и $\afb K=\set{f\in \af K: \nm f \leq 1}$ --- единичный шар в $(\af K,\nmc)$. 
Для $M\subset \af K$ будем обозначать через $(M,\nmc)$ множество $M$ с метрикой (и, соответственно, с топологией), наследуемой из $(\af K,\nmc)$.

Множество $B\subset K$ называется \term{границей}, если максимум любой аффинной непрерывной функции $f\in \af K$ достигается в некоторой точке $b\in B$,  то есть $f(b)=\max_{x\in K}f(x)$.
Множество крайних точек $\ext K$ является границей в $K$.
Так как выпуклая оболочка границы $B$ плотна в $K$, то $(\af K,\tau_p(B))$ отделимое пространство и $(\af K,\tau_p(B))$ вкладывается в $C_p(K|B)\subset C_p(B)$ \cite{MoorsReznichenko2008}.

\begin{proposition}\label{p:defs:3}
Пусть $K$ выпуклый компакт и $B\subset K$ некоторая граница $K$.
% и $(f_n)_n\subset \afb K$.
\begin{enumerate}
%\item
%(лемма Симонс \cite[теорема 3]{Simons1972}, \cite[Следствие 3.75]{LukesMalyNetukaSpurny2010}) Тогда
%\[ \sup_{b\in B} \limsup_{n\to\infty} f_n(b) = \sup_{x\in K} \limsup_{n\to\infty} f_n(x). \]
\item
(теорема Рейнуотер--Симонс, \cite{Simons1972}) Если $(f_n)_n\subset \afb K$ сходится к $f\in \afb K$ в $(\af K,\tau_p(B))$, то $(f_n)_n$ сходится к $f$ в $(\af K,\tau_p(K))$.
Другими словами, сходящиеся последовательности в  $(\afb K,\tau_p(B))$ и $(\afb K,\tau_p(K))$  совпадают.
\item
(теорема Пфицнер, \cite{Pfitzner2010}) Если $Y\subset \afb K$ и $(Y,\tau_p(B))$ компактно, то $(Y,\tau_p(K))$ компактно. 
Другими словами, компактные подмножества в $(\afb K,\tau_p(B))$ и $(\afb K,\tau_p(K))$  совпадают.
\end{enumerate}
\end{proposition}


Пусть $\mu\in P(K)$. Точка $x\in K$ называется \term{барицентром} меры $\mu$, если $f(x)=\int_X f \mathrm{d}\,\mu$ для любого $f\in \af K$. Обозначим через $r_K(\mu)$ барицентр меры $\mu$ в выпуклом компакте $K$.
Обозначим через $P_{\max}(K)$ множество \term{максимальных} мер на выпуклом компакте $K$ (см.\ определение и свойства максимальных мер в главе 1, \$4 \cite{Alfsen1971}).


\begin{proposition}\label{p:defs:4}
Пусть $K$ выпуклый компакт.
\begin{enumerate}
\item
(теорема Мильмана, \cite[теорема 1.12.6]{BogachevSmolyanovSobolev2012})
если $C\subset K$ замкнуто и выпуклая оболочка $C$ плотна в $K$, то $\ext K\subset C$;
\item
(теорема Шоке--Бишоп--де Леу, \cite[теорема I.4.8]{Alfsen1971}) $p_K(P_{\max}(K))=K$;
\item
(теорема Бишопа--де Леу, \cite[следствие I.4.12.]{Alfsen1971})
если $\mu\in P_{\max}(K)$ и $F\subset K\setminus \ext K$ компакт типа $G_\de$, то $\mu(F)=0$;
\item
(\cite[предложение 2.38]{LukesMalyNetukaSpurny2010})
отображение $r_K\: P(K) \to K$ является непрерывным аффинным отображением;
\item
(\cite[следствие 3.60]{LukesMalyNetukaSpurny2010}) $P_\tau(\ext X)\subset P_{\max}(K)$.
\end{enumerate}
\end{proposition}





















