\section{Cеквенциально плотные подмножества функциональных пространств}
\label{sec:asd}
%%% begin file('ru//sec/asd.tex') %%%


Пусть $X$ пространство. Семейство подмножеств $\cN$ пространства $X$ назовем \term{\cz-сетью}, если для любого ко-нуль множества $U\subset X$ существует не более чем счетное $\cM\subset \cN$, такое что $\bigcup\cM=U$.
Ясно, любая \cz-сеть является сетью.
Положим
\begin{align*}
\nwcz(X) &= \min \{\ |\cN| : \cN \text{является \cz-сетью пространства }X \}+\omega,
\\
\ds(X) &= \min \{\ |S| : S \text{ является секвенциально плотным в }X \}+\omega,
\\
\hds(X) &= \sup \{\ \ds(M): M\subset X  \}.
\end{align*}

В пространстве Фреше--Урысона плотное подмножество секвенциально плотно, поэтому верно следующие утверждение.

\begin{proposition}\label{p:asd:fu}
Если $X$ пространство Фреше--Урысона, то $\ds(X)=d(X)$ и $\hds(X)=hd(X)$.
\end{proposition}

\begin{lemma}\label{l:asd:1}
Пусть $X$ линделефово $\Si$-пространство. Существует линделефово $p$-пространство $Y$, такое что $X$ является непрерывным образом пространства $Y$ и $w(Y)=nw(X)$.
\end{lemma}
\begin{proof}
Существует линделефово $p$-пространство $Z$ и непрерывное сюрьективное отображение $f \: Z\to X$. Существует сепарабельное метризуемое пространство $M$ и непрерывное сюрьективное совершенное отображение $g\: Z\to M$. 
Положим
\[
h= f \diag g\: Z\to X\times M,\ x\mapsto (f(x),g(x)),
\]
$\pi$ проекция $Y=h(Z)\subset X\times M$ на $X$ и $p$ проекция $Y$ на $M$. Так как отображение $g$ совершенно, то отображение $h= f \diag g$ совершенно \cite[теорема 3.7.11]{EngelkingBookRu}. 
Так как $g=p\circ h$ и отображения $g$ и $h$ совершенны, то отображение $p\: Y\to M$ совершенно. Следовательно, пространство $Y$ является линделефовым $p$-пространством. 
Так как $Y\subset X\times M$, то $iw(Y)\leq iw(X\times M)= iw(X)$. 
Так как $X$ линделефово $\Si$-пространство, $Y$ линделефово $p$-пространство и $X$ непрерывный образ $Y$, то 
\[
w(Y)=iw(Y)\leq iw(X)=nw(X)\leq nw(Y)\leq w(Y)
\]
(см.\ предложение \ref{p:defs:1}). Следовательно, $w(Y)=nw(X)$.
\end{proof}

\begin{theorem}\label{t:asd:1}
Пусть $X$ пространство. Тогда
\begin{enumerate}
\item
$nw(X)\leq \nwcz(X)\leq 2^{nw(X)}$;
\item
если $X$ компактно, то $\nwcz(X)=nw(X)=w(X)$;
\item
если $Y$ пространство и $X\subset Y$ $z$-вложено в $Y$, то $\nwcz(X)\leq \nwcz(Y)$;
\item
если $Y$ пространство и $f\: Y\to X$ непрерывное сюрьективное отображение, то $\nwcz(X)\leq \nwcz(Y)$;
\item
если $X$ линделефово, то $\nwcz(X)\leq w(X)$;
\item
если $X$ линделефово $\Si$-пространство, то $\nwcz(X)= nw(X)$;
\item
если $nw(X)=\om$, то $\nwcz(X)=\omega$;
\item
если $X$ плотно в произведении $\prod_{\al\in A}X_\al$  сепарабельных метризуемых не однототочечных пространств и множество $A$ бесконечно, то $\nwcz(X)\leq w(X)=|A|$.
\end{enumerate}
\end{theorem}
\begin{proof}
(1) Так как \cz-сеть является сетью, то $nw(X)\leq \nwcz(X)$. Так как мощность топологии $X$ не превосходит $2^{nw(X)}$, то $\nwcz(X)\leq 2^{nw(X)}$.

(2) 
Так как любое ко-нуль множество в компакте линделефово, то любая база является \cz-сетью. Следовательно, $\nwcz(X)\leq w(X)$.
Так как $X$ компактно, то $w(X)=nw(X)$ \cite{Hodel1984handbook}. Так как $w(X)=nw(X)\leq \nwcz(X)\leq w(X)$, то $\nwcz(X)=nw(X)=w(X)$.

(3) Пусть $\cN$ \cz-сеть в $Y$. Положим $\cL=\set{M\cap X: M\in\cN}$. Достаточно показать, что $\cL$ \cz-сеть в $X$. Пусть $U$ ко-нуль множество в $X$. Так как $X$ $z$-вложено в $Y$, то $U=W\cap X$ для некоторого ко-нуль множества $W$ в $Y$. Так как $\cN$ \cz-сеть в $Y$, то $W=\bigcup \cN'$ для некоторого счетного $\cN'\subset \cN$. Тогда $\cL'=\set{M\cap X: M\in\cN'}\subset \cL$, то $U=\bigcup\cL'$.

(4) Пусть $\cN$ \cz-сеть в $Y$. Тогда  $\cL=\set{f(M): M\in\cN}$ \cz-сеть в $X$. 

(5) Так как любое ко-нуль множество в линделефовым пространстве линделефово, то любая база является \cz-сетью. Следовательно, $\nwcz(X)\leq w(X)$.

(6) Из леммы \ref{l:asd:1} вытекает, что существует линделефово $p$-пространство $Y$, такое что $X$ является непрерывным образом пространства $Y$ и $w(Y)=nw(X)$.
Из пунктов (4) и (5) вытекает, что $\nwcz(X)\leq \nwcz(Y)\leq w(Y)$. Так как $w(Y)=nw(X)$, то $\nwcz(X)\leq nw(X)$.

(7) Счетная сеть является \cz-сетью.

(8) Пусть $K_\al$ компактное метризуемое расширение пространства $X_\al$ для $\al\in K$. Тогда $X$ плотное подмножество $K=\prod_{\al\in A}K_\al$ и $w(K)=|A|$. 
Произведение  метризуемых  пространств является  совершенно $\ka$-нормальным пространством \cite{Shepin1976}, поэтому $K$ совершенно $\ka$-нормально.
Плотные подмножества совершенно $\ka$-нормальных пространств $z$-вложено в них \cite[Lemma 8.4.5]{at2009}, поэтому $X$ $z$-вложено в компакт $K$. Из  (2) и (3) вытекает, что $\nwcz(X)\leq w(K)=|A|$.
\end{proof}

\begin{proposition}\label{p:asd:1}
Пусть $X$ пространство и $\cN$ семейство подмножеств $X$. Следующие условия эквивалентны:
\begin{enumerate}
\item
семейство $\cN$ является \cz-сетью пространства $X$;
\item
для любого $f\in C(X)$ существует $\cP\subset \cN$, $|\cP|\leq\om$, такое что выполняется условие
\begin{enumerate}
\item[$(F_{cz})$]
для каждого $x\in X$ и $\ep>0$ существует $P\in\cP$, для которого $x\in P$ и
\[
\Om(f,P) = \sup_{x_1,x_2\in P} |f(x_1) - f(x_2)| < \ep.
\]
\end{enumerate}
\end{enumerate}
\end{proposition}
\begin{proof}
$(1)\rarr(2)$ Пусть $\cB$ есть счетная база $\R$. Для $U\in\cB$ существует $\cP_U\subset \cN$, $|\cP_U|\leq\om$, такое что $\bigcup\cP_U=U$. Положим $\cP=\bigcup_{U\in\cB}$. Тогда для $\cP$ выполняется условие $(F_{cz})$.

$(2)\rarr(1)$ Пусть $W=f^{-1}(\R\setminus\sset 0)$ ко-нуль множество и $f\in C(X)$. Возьмем $\cP\subset \cN$, $|\cP|\leq\om$, для которого выполняется условие $(F_{cz})$. Положим $\cM=\set{P\in\cP: P\subset W}$. Тогда $W=\bigcup\cM$.
\end{proof}


\begin{theorem}\label{t:asd:2}
Пусть $X$ пространство. Тогда $\hds(C_p(X))\leq \nwcz(X)$.
\end{theorem}
\begin{proof}
Пусть $M\subset C_p(X)$. Надо найти $S\subset M$, такое что $S$ секвенциально плотно в $M$ и $|S|\leq \nwcz(X)$.
Пространство $C_p(X)$ гомеоморфно пространству $C_p(X,(-1,1))$, так что будем считать, что $M\subset C_p(X,(-1,1))$. 

Пусть $\tau=\nwcz(X)$ и $\cN$ есть \cz-сеть пространства $X$, мощность которой не превосходит $\tau$.
%Обозначим $B=C(X,(-1,1))$.
Для $P\in\cP$ положим 
\begin{align*}
\F^+_P &\: M\to \R,\ f\mapsto \sup \set{ f(x)): x\in P },
\\
\F^-_P &\: M\to \R,\ f\mapsto \inf \set{ f(x)): x\in P }.
\end{align*}
Пусть $\tp$ есть топология на $M$, порожденная семейством функций $\set{\F^+_P,\F^-_P: \al<\tau}$.
Тогда вес пространства $(M,\tp)$ не превосходит $\tau$. Возьмем $S\subset M$ таким образом, что $|S|\leq\tau$ и $S$ плотно в $M$ относительно топологии $\tp$.

Покажем, что множество $S$ секвенциально плотно в $M$ относительно топологии $C_p(X)$. Пусть $f\in M$. Из предложения \ref{p:asd:1} вытекает, что существует $\cP=\set{P_n:n<\om}\subset \cN$, для которого выполняется условие $(F_{cz})$. Для $n,m\in\om$ положим
\[
W_{n,m} = \set{g\in M:  -\tfrac{1}{2^m}+\F^-_{P_n}(f) < \F^-_{P_n}(g) \leq \F^+_{P_n}(g) <  \tfrac{1}{2^m}+\F^+_{P_n}(f) }.
\]
Множество $W_{n,m}$ является открытой в $(M,\tp)$ окрестностью точки $f$. Пусть $(n_k,m_k)_{k<\om}$ есть нумерация множества $\om\times \om$. Положим $U_k=\bigcap_{i\leq k}W_{n_i,m_i}$ и выберем $f_k\in U_k\cap S$ для $k<\om$. 

Докажем, что последовательность $(f_k)_k$ поточечно сходится к $f$. Пусть $x\in X$ и $\ep>0$. Возьмем $m<\om$, такое что $\frac{1}{2^m}<\frac \ep 2 $. Из $(F_{cz})$ вытекает, что существует $n\in \om$, такое что $x\in P_n$ и $\Om(f,P_n)<\frac \ep 2$. Тогда $|f(x)-g(x)|<\ep$ для любого $g\in W_{n,m}$. Для некоторого $N<\om$, $n=n_N$ и $m=m_N$. Тогда $f_k\in W_{n,m}$ и $|f(x)-f_k(x)|<\ep$ для $k\geq N$.
\end{proof}

\begin{proposition}[Теорема Комфорда--Хагера {\cite{ComfortHager1970}}]\label{p:asd:ch}
Пусть $X$ пространство. Тогда
\[
w(\bt X)^\om = |C(X)|^\om = |C(X)| \leq w(X)^{wl(X)}.
\]
\end{proposition}

\begin{theorem}\label{t:asd:3}
Пусть $X$ пространство. Тогда 
\[
\nwcz(X)\leq w(\bt X)\leq w(\bt X)^\om = \ds(C_p(X))^\om = \nwcz(X)^\om.
\]
\end{theorem}
\begin{proof}
Из теоремы \ref{t:asd:2} вытекает, что $\ds(C_p(X))\leq \nwcz(X)$.
Cуществует $S\subset C_p(X)$, такое что $S$ секвенциально плотно в $C_p(X)$ и $|S|\leq \ds(C_p(X))$.
Так как $S$ секвенциально плотно в $C_p(X)$, то $|C(X)|\leq |S|^\om=\ds(C_p(X))^\om$.
Так как $X$ $C^*$-вложено в $\bt X$, то $X$ $z$-вложено в $\bt X$. Из теоремы \ref{t:asd:1}(2) и (3) вытекает $\nwcz(X)\leq w(\bt X)$. Следовательно, $\nwcz(X)^\om\leq w(\bt X)^\om$.
Теоремы Комфорда--Хагера влечет, что $\leq w(\bt X)^\om=|C(X)|^\om\leq \nwcz(X)^\om$. Получаем $\nwcz(X)\leq w(\bt X)$ и $w(\bt X)^\om = \ds(C_p(X))^\om = \nwcz(X)^\om$.
\end{proof}

Из теорем  \ref{t:asd:1}(5), \ref{t:asd:2} и \ref{t:asd:3} и теоремы Комфорда--Хагера (предложение \ref{p:asd:ch}) вытекают следующие утверждение.

\begin{cor}\label{c:asd:1}
Пусть $X$ линделефово пространство. Тогда $\hds(C_p(X))\leq w(X)$ и 
\[
w(X) \leq w(\bt X) \leq w(\bt X)^\om = w(X)^\om.
\]
\end{cor}

В \cite{Hager1969} было доказано, что $\ds(C_p(X))\leq w(X)$ и $|C(X)|= w(X)^\om$ для линделефово пространства $X$.

Из теорем  \ref{t:asd:1}(6), \ref{t:asd:2} и \ref{t:asd:3}  следующие утверждение.
%
\begin{cor}\label{c:asd:2}
Пусть $X$ линделефово $\Si$-пространство. Тогда $\hds(C_p(X))\leq nw(X)$ и 
\[
nw(X) \leq w(\bt X) \leq w(\bt X)^\om = nw(X)^\om.
\]
\end{cor}

В \cite{Tkachenko2017weight} было доказано, что $w(\bt X)\leq |C(X)|\leq nw(X)^\om$ для линделефово $\Si$-пространства $X$.




