\section{Вес выпуклых компактов и пространство вероятностных мер}
\label{sec:wcps}
%%% begin file('ru//sec/wcps.tex') %%%

\begin{proposition}\label{p:wcps:1}
Пусть $K$ выпуклый компакт. Тогда $w(K)= nw(P_{\max}(K))$.
\end{proposition}
\begin{proof}
Отображение $p_K\: P(K)\to K$ взятия барицентра меры непрерывно (предложение \ref{p:defs:4}(4)).
Из теоремы Шоке--Бишоп--де Леу (предложение \ref{p:defs:4}(2)) вытекает, что $p_K(P_{\max}(K))=K$. 
Следовательно, $w(K)=nw(K)\leq nw(P_{\max}(K))$. Ясно, $nw(P_{\max}(K))\leq w(P(K))=w(K)$.
\end{proof}

\begin{proposition}\label{p:wcps:2}
Пусть $K$ выпуклый компакт. Если $p_K(P_\tau(\ext K))=K$, то $w(K)=w(\ext K)$.
\end{proposition}
\begin{proof}
Отображение $p_K\: P(K)\to K$ взятия барицентра меры непрерывно (предложение \ref{p:defs:4}(4)).
Из теоремы Т.Банаха (предложение \ref{p:defs:2}) вытекает, что $w(P_\tau(\ext K))=w(\ext K)$.
Следовательно, $w(K)=nw(K)\leq w(P_\tau(\ext K))$.
\end{proof}

Отметим, $P_\tau(\ext X)\subset P_{\max}(K)$ для выпуклого компакта $K$.
%
\begin{theorem}\label{t:wcps:1}
Пусть $K$ выпуклый компакт.
Если $P_{\max}(K)=P_\tau(\ext K)$, то $w(K)=w(\ext K)=nw(\ext K)$.
\end{theorem}
\begin{proof}
Равенство $w(\ext K)=nw(\ext K)$ было доказано в \cite[теорема 3.2]{Reznichenko1990}.
Осталось применить предложения \ref{p:wcps:2} и \ref{p:defs:4}(5).
\end{proof}

Теорема \ref{t:wcps:1} является усилением теоремы 1.2 из \cite{Spurny2010}.

\begin{proposition}\label{p:wcps:3}
Пусть $K$ выпуклый компакт. Если $\ext K\subset B\subset K$ и $B$ линделефово, то $P_{\max}(K)\subset P_\tau(B)$.
\end{proposition}
\begin{proof}
Пусть $\mu\in P_{\max}(K)$. Для доказательства $\mu\in P_\tau(B)$ нужно проверить, что если $C\subset K\setminus B$ компактно, то $\mu(C)=0$. Пусть $\ga=\{ U\subset K\setminus C: U$ ко-нуль множество в $K\}$. Тогда $\bigcup\ga=K\setminus C$. Так как $B$ линделефово, то существует $(U_n)_n\subset\ga$, такое что $B\subset U=\bigcup_n U_n$. Тогда $B\subset U \subset K\setminus C$ и $C\subset G=K\setminus U\subset K\setminus B$. Множество $G$ является нуль множеством. Из теоремы Бишопа--де Леу (предложение \ref{p:defs:4}) вытекает, что $\mu(G)=0$. Следовательно, $\mu(C)=0$.
\end{proof}

Из теоремы \ref{t:wcps:1} и предложения \ref{t:wcps:1} вытекает следующие утверждение.

\begin{theorem}[{\cite[теорема 3.3]{Reznichenko1990}}]\label{t:wcps:2}
Пусть $K$ выпуклый компакт. Если $\ext K$ линделефово, то и $w(K)=w(\ext K)=nw(\ext K)$.
\end{theorem}

Из предложений \ref{p:wcps:1} и \ref{p:wcps:3}  вытекает следующие утверждение.

\begin{theorem}\label{t:wcps:3}
Пусть $K$ выпуклый компакт. Если $\ext K\subset B\subset K$ и $B$ линделефово, то $w(K)=nw(P_\tau(B))$.
\end{theorem}

Пусть $X$ пространство. Положим
\[
zw(X) = \min\{ w(K) : X \text{ $z$-владывается в компакт }K\}.
\]
Кардинал $zw(X)$ называется \term{$z$-весом} пространства $X$. Тогда $w(P_\si(X))\leq zw(X)$ (\cite[теорема 2.4]{BanakhChigogidzeFedorchuk2003}). Из предложения \ref{t:asd:1} (2) и (3) вытекает, что $\nwcz(X)\leq zw(X)$.


\begin{proposition}\label{p:wcps:4}
Пусть $X$ пространство. Тогда $nw(P_\si(X))\leq \nwcz(X)$.
\end{proposition}
\begin{proof}
Пусть $\cN$ есть \cz-сеть пространства $X$ и $|\cN|\leq \nwcz(X)$. Можно считать, что $\cN$ состоит из замкнутых множеств и семейство $\cN$ замкнуто относительно конечных пересечений, то есть $\bigcup\cL\in \cN$ для конечного $\cL\subset\cN$. 
Положим $\cR=\{ W(F,\ep) : F\in \cN,\ \ep\in (0,1)\cap \Q  \}$, где
\[
W(F,\ep) = \{ \mu \in P_\si(X) : \mu(F)>\ep \}.
\]
Предбазу топологии $P_\si(X)$ образуют множества вида $W(U,\ep)$ для ко-нуль множества $U\subset X$ и $\ep>0$ \cite[4.3]{Bogachev2016book}. Покажем, что $\cR$ есть сеть пространства $P_\si(X)$. 
Пусть $\mu\in W(F,\ep)$. 
Пусть $c\in \Q\cap(\ep,\mu(U))$.
Так как $\cN$ \cz-сеть $X$, то существует последовательность $(F_n)_n\subset \cN$, такая что $\bigcup_n F_n=U$. Положим $P_n=\bigcup_{i\leq n} F_i$. Тогда $\mu(U)=\lim_{n\to\infty}\mu(P_n)$ и, следовательно, $\mu(P_m)>c$ для некоторого $m$. Получаем, $\mu\in W(P_m,c)\subset W(U,\ep)$ и $W(P_m,c)\in\cR$.
\end{proof}

Из теоремы \ref{p:wccs:1}(7) и предложения \ref{p:wcps:4} вытекает следующие утверждение.

\begin{cor}\label{c:wcps:1}
Пусть $X$ пространство. 
Если $X$ со счетной сетью, то $P_\si(X)$ со счетной сетью.
\end{cor}

Из теоремы \ref{t:wcps:3} и предложения \ref{p:wcps:4} вытекает следующие утверждение.

\begin{cor}\label{c:wcps:2}
Пусть $K$ выпуклый компакт. Если $\ext K\subset B\subset K$ и $B$ линделефово, то $w(K)\leq \nwcz(B)$.
\end{cor}

В следующем разделе это следствие будет значительно усилено (теорема \ref{t:wccs:2}).


