\section{Вес выпуклых компактов и пространство аффинных функций}
\label{sec:wccs}
%%% begin file('ru//sec/wccs.tex') %%%

Пространство $X$ называется \term{$k$-пространством} если для $F\subset X$, $F$ замкнуто в $X$ если и только если $F\cap K$ замкнуто в $X$ для каждого компакта $K\subset X$. Любое метризуемое пространство является $k$-пространством. Пространство $X$ называется \term{$k_\R$-пространством} если для  $f\: X\to \R$,  функция $f$ непрерывна если и только если для каждого компакта $K\subset X$ ограничение $\restr fK$ функции $f$ на $K$ непрерывно. Любое $k$-пространство является $k_\R$-пространством.

Непосредственно проверяется следующие утверждение.
\begin{lemma}\label{l:wccs:1}
Пусть $X$ $k_\R$-пространство. Отображение пространств $f\:X\to Y$ непрерывно если и только если для каждого компакта $K\subset X$ ограничение $\restr fK$ отображения $f$ на $K$ непрерывно.
\end{lemma}

\begin{lemma}\label{l:wccs:2}
Пусть $X$ пространство и $S\subset C_p(X)$ разделяет точки $X$. Тогда $iw(X)\leq|S|$.
Если $X$ компактно, то $w(X)\leq|S|$. Если $Q\subset S$ плотно в $S$, то $Q$ разделяет точки $X$.
\end{lemma}
\begin{proof}
Так как $S$ разделяет точки $X$, то $X$ непрерывно и иньективно отображается в $\R^S$
\cite[Предложение 0.5.4]{Arhangelskii1989CpBook}. Если $X$ компактно, то $w(X)=iw(X)$ (предложение \ref{p:defs:1}). Покажем, что $Q$ разделяет точки $X$. Пусть $x,y\in X$ и $x\neq y$. Тогда $f(x)\neq f(y)$ для некоторого $f\in S$. Пусть $\ep=\frac{|f(x)-f(y)|}2$. Множество $U=\{g\in C_p(X): |f(x)-g(x)|<\ep$ и $|f(y)-g(y)|<\ep\}$ является открытой окрестностью функции $f$ в $C_p(X)$. Пусть $g\in U\cap Q$. Тогда $g(x)\neq g(y)$.
\end{proof}


\begin{proposition}\label{p:wccs:1}
Пусть $K$ выпуклый компакт, $B\subset K$ граница $K$, $A_1=(\afb K,\tau_p(B))$, $A_1'=(\afb K,\tau_p(K))$  и $\tau$ кардинал.
Следующие условия эквивалентны:
\begin{enumerate}
\item
$w(K)\leq \tau$;
\item
$d(A_1')\leq \tau$;
\item
$\ds(A_1)\leq \tau$;
\item
$A_1$ является непрерывным образом метризуемого пространства $X$, для которого $d(X)\leq\tau$;
\item
$A_1$ является непрерывным образом $k_\R$-пространства $X$, для которого $d(X)\leq\tau$.
\end{enumerate}
\end{proposition}
\begin{proof}
$(1)\rarr(2)$ Пространство $A_1'$ является подпространством пространства $C_p(K)$.
Тогда $nw(C_p(K))=nw(K)=w(K)\leq\tau$ (Предложение \ref{p:defs:1}). Следовательно, $d(A_1')\leq nw(A_1')\leq\tau$.

$(2)\rarr(1)$ Пусть $S\subset A_1'=\cl S$ и $|S|\leq\tau$. 
Так как $\af K$ разделяет точки $K$, то $\afb K$ тоже разделяет точки $K$. Из леммы \ref{l:wccs:2} вытекает $w(K)\leq |S|\leq\tau$.

$(1)\rarr(4)$ Из (1) вытекает, что $d((\af K,\nmc))=w((\af K,\nmc))\leq\tau$. Следовательно,
$d(X)\leq\tau$, где $X=(\afb K,\nmc)$. Пространство $X$ метризуемо и непрерывно отображается на $A_1$.

$(4)\rarr(3)$ Пусть $f\: X\to A_1$ непрерывное сюрьективное отображение. Пусть $S\subset X=\cl S$ и $|S|\leq\tau$. Тогда $S$ секвенциально плотно в $X$ и, следовательно, $f(S)$ секвенциально плотно в $A_1$. Кроме того, $|f(S)|\leq|S|\leq\tau$.

$(3)\rarr(2)$ Пусть $S\subset \af K$ секвенциально плотно в $A_1$ и $|S|\leq\tau$. Из теоремы Рейнуотер--Симонс (предложение \ref{p:defs:3}(1)) вытекает, что $S$ секвенциально плотно в $A_1'$.

$(4)\rarr(5)$ Метризуемое пространство является $k_\R$-пространством.

$(5)\rarr(2)$ Пусть $f\: X\to A_1$ непрерывное сюрьюктивное отображение. Пусть $C\subset X$ компактно. Тогда $f(C)$ компактно. Из теоремы Пфицнера (предложение \ref{p:defs:3}(2)) вытекает, что $f(C)$ компактно в топологии $A_1'$ и имеет ту же топологию, что $f(C)$ в топологии $A_1$. Следовательно, $\restr fC\: C\to A_1'$ непрерывно. Из леммы \ref{l:wccs:1} вытекает, что $f\: X\to A_1'$ непрерывно. Тогда $d(A_1')\leq d(X)\leq\tau$.
\end{proof}

Отметим, что в пункте (3) нельзя заменить $\ds(A_1)\leq \tau$ на $d(A_1)\leq \tau$. Существует выпуклый неметризуемый компакт $K$, для которого $(\af K,\tau_p(\ext K))$ сепарабельно \cite[Example 4.6]{MoorsReznichenko2008}.

Из предложения \ref{p:wccs:1} вытекает следующие утверждение.

\begin{theorem}\label{t:wccs:1}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Тогда $w(K)=\ds((\afb K,\tau_p(B)))$.
\end{theorem}

\begin{theorem}\label{t:wccs:1+1}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Тогда $w(K)\leq\hds(C_p(B))$.
\end{theorem}
\begin{proof}
Пространство $A_1=(\afb K,\tau_p(B))$ является подпространством пространства $C_p(B)$.
Тогда из теоремы \ref{t:wccs:1} вытекает $w(K)= \ds(A_1)\leq \hds(C_p(B))$.
\end{proof}



\begin{theorem}\label{t:wccs:fu}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Если $C_p(B)$ пространство Фреше--Урысона, то $w(K)\leq hl^*(X)$.
\end{theorem}
\begin{proof}
Так как $hd(C_p(X))=hl^*(X)$ (предложение \ref{p:defs:1}), то из предложения \ref{p:asd:fu} вытекает $\hds(C_p(X))\leq hl^*(X)$. Из  теоремы \ref{t:wccs:1+1} вытекает $w(K)\leq hl^*(X)$.
\end{proof}


\begin{theorem}\label{t:wccs:2}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Тогда $w(K)\leq \nwcz(B)$.
\end{theorem}
\begin{proof}
Так как $\hds(C_p(B))\leq \nwcz(B)$ (теорема \ref{t:asd:2}), то из теоремы \ref{t:wccs:1+1} вытекает, что $w(K)\leq \nwcz(B)$.
\end{proof}

Из теорем \ref{t:asd:1}(7) и \ref{t:wccs:2} вытекает следующие утверждение.
%
\begin{theorem}\label{t:wccs:2+1}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Если $B$ со счетной сетью, то $K$ метризуемо.
\end{theorem}

Из теорем \ref{t:asd:1}(6) и \ref{t:wccs:2} вытекает следующие утверждение.
%
\begin{theorem}\label{t:wccs:3}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Если $B$ линделефово $\Si$-пространство, то $w(K)\leq nw(B)$.
\end{theorem}

Из теорем \ref{t:asd:1}(5) и \ref{t:wccs:2} вытекает следующие утверждение.
\begin{theorem}[{И.Спурны \cite[Corollary 1.4]{Spurny2010}}]\label{t:wccs:4}
Пусть $K$ выпуклый компакт и $B\subset K$ граница $K$.
Если $B$ линделефово, то $w(K)\leq w(B)$.
\end{theorem}



\begin{theorem}\label{t:wccs:5}
Пусть $K$ выпуклый компакт, $B\subset K$ и выпуклая оболочка $B$ плотна в $K$.
Тогда $w(K)\leq w(\bt B)$.
\end{theorem}
\begin{proof}
Пусть $C=\cl B$. Тогда $w(C)\leq w(\bt B)$ и выпуклая оболочка $C$ плотна в $K$. Из теоремы Мильмана (предложение \ref{p:defs:4}) вытекает $\ext K\subset C$. Следовательно, $C$ граница $K$. Из теоремы Спурны (теорема \ref{t:wccs:4})  вытекает, что $w(K)\leq w(C)\leq w(\bt B)$.
\end{proof}

Из теоремы \ref{t:wccs:5}, теоремы Комфорда--Хагера (предложение \ref{p:asd:ch}), теоремы \ref{t:asd:3} и
следствий \ref{c:asd:1} и \ref{c:asd:2} вытекает следующие утверждение.
%
\begin{theorem}\label{t:wccs:6}
Пусть $K$ выпуклый компакт, $B\subset K$ и выпуклая оболочка $B$ плотна в $K$.
Тогда
\begin{enumerate}
\item
$w(B) \leq w(K)\leq w(B)^{wl(B)}$;
\item
$\nwcz(B) \leq w(K) \leq \nwcz(B)^\om$;
\item
$w(B) \leq w(K) \leq w(B)^\om$ если $B$ линделефово;
\item
$nw(B)  \leq w(K) \leq  nw(B)^\om$ если $B$ линделефово $\Si$-пространство.
\end{enumerate}
\end{theorem}







