\begin{equation*}
 E_{r, \mu}(u_{n,r,j}) \rightarrow c_{r,j} \quad \text{and} \quad E_{r, \mu}^{\prime}(u_{n,r,j}) \rightarrow 0 \quad\text{as }n \to +\infty.
