\section{Introduction}


For any positive integer \( n \in \mathbb{N} \) and any integer \( k \) with \( 1 \le k \le n \), a \emph{partition} of \([n] \equiv \{1, 2, \dots, n\}\) into \( k \) blocks is an unordered collection of nonempty, pairwise disjoint subsets whose union is \([n]\). Let \(\mathcal{P}_n^k\) denote the set of all such partitions of \([n]\) into \( k \) blocks, and define \(\mathcal{P}_n \equiv \bigcup_{k=1}^n \mathcal{P}_n^k\) to be the set of all partitions of \([n]\). For instance, when $n=3$, we have $\mathcal{P}_3 = \mathcal{P}_3^{1} \cup \mathcal{P}_3^{2} \cup \mathcal{P}_3^{3}$ with 
\begin{align*}
  \mathcal{P}_3^{1} = \bigl\{\{1, 2, 3\}\bigr\}, \quad \mathcal{P}_3^{2} = \Bigl\{\bigl\{\{1, 2\},  \{3\}\bigr\}, \  \bigl\{\{1\}, \{2, 3\}\bigr\}, \ \bigl\{ \{1,3\}, \{2\}\bigr\}\Bigr\}, \quad \mathcal{P}_{3}^3 = \bigl\{\{1\},\{2\},\{3\}\bigr\}. 
\end{align*}
An \emph{exchangeable Gibbs partition} is a stochastic process taking values in \(\{\mathcal{P}_n\}_{n=1}^\infty\) defined as follows:

\begin{algorithm}[H]
  \caption{Sequential definition of the Exchangeable Gibbs partition}
  \KwIn{$\alpha \in (-\infty, 1)$ and a non-negative triangular array $(v_{n,k})$ satisfying the backward recursion}
  \begin{equation}\label{eq:recursion}
     v_{1,1} = 1 \quad \text{and} \quad 
  v_{n,k} = (n - \alpha k)\, v_{n+1, k} + v_{n+1, k+1} \ \  \text{for all} \ \ 1\le k \le n, \ n\in \mathbb{N}
  \end{equation}
  Initialize with $\Pi_1 = \big\{\{1\}\big\}$\;
  \For{$n = 1, 2, \dots$}{
    Given $\Pi_n = \{U_1, \dots, U_{\mathsf{k}_n}\} \in \mathcal{P}_n$, where $\mathsf{k}_n$ is the current number of blocks, define the probability simplex $\bm{\simp}_n \in \Delta^{\mathsf{k}_n + 1}$ by
    \begin{equation}\label{eq:intro_simplex}
      \bm{\simp}_n = (\simp_{n,0}, \simp_{n,1}, \dots, \simp_{n,\mathsf{k}_n}), \quad 
      \simp_{n,i} \equiv
      \begin{cases}
        \frac{v_{n+1, \mathsf{k}_n + 1}}{v_{n,\mathsf{k}_n}} & i = 0, \\[5pt]
        \frac{v_{n+1, \mathsf{k}_n}}{v_{n,\mathsf{k}_n}} \big( |U_i| - \alpha \big) & i \in \{1, \dots, \mathsf{k}_n\}.
      \end{cases}
    \end{equation}
    Generate $\Pi_{n+1} \in \mathcal{P}_{n+1}$ by assigning the $(n+1)$-th element according to
    \begin{equation}\label{eq:rule}
      (n+1) \in 
      \begin{cases}
        \text{a new block} & \text{with probability } \simp_{n,0}, \\
        U_i & \text{with probability } \simp_{n,i}, \quad i \in \{1, \dots, \mathsf{k}_n\}.
      \end{cases}
    \end{equation}
  }
\end{algorithm}

Here, the parameter \(\alpha\) and the triangular array \((v_{n,k})\) satisfy \(\alpha \in (-\infty, 1)\) and the backward recursion \eqref{eq:recursion}
so that \(\bm{\simp}_n\) defined in \eqref{eq:intro_simplex} is indeed a valid probability simplex, i.e., \(\sum_{i} \simp_{n,i} = 1\) and $\simp_{n,i}\ge 0$.   
An example of an array \((v_{n,k})\) satisfying \eqref{eq:recursion} is given by the well-known two-parameter family:
\begin{align}\label{eq:v_nk_ewens}
  v_{n,k}(\alpha, \theta) 
  \;=\; \frac{\prod_{i=1}^{k-1} (\theta + i \alpha)}{\prod_{i=1}^{n-1} (\theta + i)}, 
  \quad \text{with} \quad
  \begin{cases}
    \theta > -\alpha, & \text{if } 0 \le \alpha < 1, \\
    \theta = -k \alpha \text{ for some } k \in \mathbb{N}, & \text{if } \alpha < 0.
  \end{cases}
\end{align}
The corresponding random partition is known as the \emph{Ewens--Pitman partition $(\alpha,\theta)$}.

Notably, the marginal distribution of 
\(\Pi_n = \{ U_1, \dots, U_{\mathsf{k}_n} \} \in \mathcal{P}_n\) under the Gibbs partition model is given by
\begin{align}\label{eq:intro_marginal_likelihood}
  \PP\bigl( \Pi_n = \{ U_1, \dots, U_{\mathsf{k}_n} \} \bigr)
  = v_{n, \mathsf{k}_n}
  \prod_{i=1}^{\mathsf{k}_n} \prod_{j=1}^{|U_i|-1} (j - \alpha)
  = v_{n, \mathsf{k}_n}
    \prod_{j=2}^{n} 
    \left( \prod_{i=1}^{j-1} (i - \alpha) \right)^{\mathsf{k}_{n,j}},
\end{align}
where 
\(\mathsf{k}_{n,j} = \sum_{i=1}^{\mathsf{k}_n} \mathbbm{1}\big\{ |U_i| = j \big\}\) 
denotes the number of blocks of size \(j\). 
Since \(\sum_{j=1}^{n} \mathsf{k}_{n,j} = \mathsf{k}_n\), equation \eqref{eq:intro_marginal_likelihood} shows that the block sizes \((\mathsf{k}_{n,j})_{j=1}^n\) are sufficient statistics for the Gibbs partition model.  
In particular, the marginal likelihood \eqref{eq:intro_marginal_likelihood} is invariant under any permutation of the labels in \([n] = \{1, \dots, n\}\).  
In general, random partitions with this property are called \emph{exchangeable random partitions}, and a large class of such exchangeable partitions can be represented by the Gibbs partition model.  
Indeed, \cite{gnedin2006exchangeable} shows that for any exchangeable partition model whose marginal likelihood $\PP(\Pi_n = \{ U_1, \dots, U_{\mathsf{k}_n} \})$ are consistent as \(n\) varies and take the product form 
\( V_{n, \mathsf{k}_n} \prod_{i=1}^{\mathsf{k}_n} W_{|U_i|} \)
for some non-negative triangular array \((V_{n,k})\) and weight \((W_\ell)\), then $W_\ell$ must take the form $\prod_{j=1}^{\ell-1} (j - \alpha)$ for some $\alpha\in(-\infty,1)$ and the array \((V_{n,k})\)  must satisfy the backward recursion \eqref{eq:recursion}.



\paragraph{Asymptotics of the Gibbs partition}
By the definition \eqref{eq:intro_simplex}--\eqref{eq:rule}, the probability that the next item belongs to a current block $U_i$ is proportional to $(|U_i|-\alpha)$, which implies that the Gibbs partition exhibits a \emph{rich-get-richer} dynamics: blocks with larger sizes are more likely to attract new elements, while the discount parameter \(\alpha\) counteracts this tendency. Therefore, intuitively, the smaller the value of \(\alpha\), the smaller the expected number of non-empty blocks \(\mathsf{k}_n\). This intuition is reflected in the asymptotic behavior of \(\mathsf{k}_n\): \cite{gnedin2006exchangeable} shows that for any Gibbs partition model with a parameter $\alpha\in (-\infty, 1)$ and an array $(v_{n,k})$ satisfying \eqref{eq:recursion}, there exists a positive random variable \(\mathsf{S}_\alpha\), whose law depends on \(\alpha\) and \((v_{n,k})\), such that
\begin{align}\label{eq:intro_sparse}
  \frac{\mathsf{k}_n}{c_n(\alpha)} \; \xrightarrow{\text{a.s.}} \; \mathsf{S}_\alpha
  \quad \text{where} \quad 
  c_n(\alpha) \equiv 
  \begin{cases}
    n^\alpha, & 0 < \alpha < 1, \\
    \log n, & \alpha = 0, \\
    1, & \alpha < 0,
  \end{cases}
\end{align}
When \(\alpha \in (0,1)\), the limit \(\mathsf{S}_\alpha\) is referred to as the \emph{$\alpha$-diversity}.  
Furthermore, for \(\alpha \in (0,1)\), the block size distribution $(\mathsf{k}_{n,j}/\mathsf{k}_n)_{j=1}^n$ converges to a discrete distribution:
\begin{align}\label{eq:intro_powerlaw}
  \forall j \in \mathbb{N}, \quad 
  \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \; \xrightarrow{\text{a.s.}} \; 
  \mathfrak{p}_\alpha(j) 
  \equiv \frac{\alpha \prod_{i=1}^{j-1} (i - \alpha)}{j!},
\end{align}
where \(\mathsf{k}_{n,j} / \mathsf{k}_n\) denotes the proportion of blocks of size \(j\) among the current partition of $[n]$; see \cite[Lemma 3.11]{pitman2006combinatorial} and \cite{gnedin2007notes}. The limit $\mathfrak{p}_\alpha(j)$ defines a valid probability mass function on $\mathbb{N}$, known as the \emph{Sibuya distribution} in the literature \cite{sibuya1979generalized}. It has been studied in connection with the stable distribution and Mittag-Leffler distribution \cite{christoph1998discrete, devroye1993triptych, pillai1995discrete, pakes1995characterization}; see also \cite{resnick2007heavy} for its relevance in extreme value theory.
By Stirling's approximation, the tail of the discrete distribution behaves as
$$
\mathfrak{p}_\alpha(j) \sim \frac{\alpha}{\Gamma(1-\alpha)} \cdot j^{-(1 + \alpha)} \quad \text{as $j\to+\infty$}.
$$
Combined with \eqref{eq:intro_powerlaw}, this means that the block size distribution $(\mathsf{k}_{n,j}/\mathsf{k}_n)_{j=1}^n$ converges asymptotically to a power law with exponent $(\alpha+1)$. 

\paragraph{Related Literature}  
The asymptotic properties of the block sizes $(\mathsf{k}_{n,j})_{j=1}^n$, as characterized in \eqref{eq:intro_sparse}–\eqref{eq:intro_powerlaw} above, make the Gibbs partition a versatile and powerful statistical model across a wide range of domains. Notable applications include species sampling problems \cite{balocchi2022bayesian, favaro2021near, favaro2009bayesian, sibuya2014prediction, battiston2018multi}, nonparametric Bayesian inference \cite{caron2017generalized, dahl2017random, ayed2019beyond, rigon2025enriched}, disclosure risk assessment \cite{favaro2021bayesian, hoshino2001applying}, network analysis \cite{crane2016edge, naulet2021asymptotic}, natural language processing \cite{teh2006hierarchical, sato2010topic}, and forensic science \cite{cereda2022learning}. While this list is not exhaustive, it highlights the broad applicability of Gibbs-type partitions, particularly their ability to capture power-law cluster size distributions that arise naturally in many real-world settings.


In this literature, considerable attention has been devoted to estimating the discount parameter $\alpha \in (0,1)$. A natural estimator, $\hat{\alpha}_n^{\text{naive}} \equiv \log \mathsf{k}_n / \log n$, is consistent by virtue of \eqref{eq:intro_sparse}, but converges at the slow rate of $1/\log n$. This suboptimal rate results from the fact that $\hat{\alpha}_n^{\text{naive}}$ depends only on the summary statistic $\mathsf{k}_n = \sum_{j=1}^n \mathsf{k}_{n,j}$, without leveraging the full sufficient statistic $(\mathsf{k}_{n,j})_{j=1}^n$ for the likelihood \eqref{eq:intro_marginal_likelihood}. 

More refined estimators that utilize the full sufficient statistic $(\mathsf{k}_{n,j})_{j=1}^n$ have been recently studied. Let us define $\hat{\alpha}_n$ as the maximizer of the likelihood \eqref{eq:intro_marginal_likelihood} with the weight $v_{n,k}$ replaced by the Ewens--Pitman weight \eqref{eq:v_nk_ewens} with $\theta = 0$:
\begin{align*}
\hat{\alpha}_n \in \argmax_{\alpha\in (0,1)} \ \alpha^{\mathsf{k}_n} \prod_{j=2}^{n} 
    \left( \prod_{i=1}^{j-1} (i - \alpha) \right)^{\mathsf{k}_{n,j}}.
\end{align*}
We refer to this estimator as the quasi-maximum likelihood estimator (QMLE). The QMLE attains the convergence rate of $n^{-\alpha/2}$, as established in \cite{favaro2021bayesian,balocchi2022bayesian, franssen2022bernstein}. The analysis in these works builds on Kingman's representation theorem \cite{kingman1978representation, kingman1982coalescent}, which serves as the analogue of de Finetti's theorem for exchangeable random partitions. 

However, the precise asymptotic distribution of the QMLE has thus far been established only for the Ewens--Pitman model. In particular, \cite{koriyama2022asymptotic} derives the following limit distribution for the QMLE:
\begin{align}\label{eq:intro_qmle_limit_dist}
\sqrt{\mathsf{k}_n \mathfrak{i}(\alpha)} \cdot (\hat{\alpha}_n - \alpha) \xrightarrow{\mathrm{d}} \mathcal{N}(0,1),
\end{align}
where $\mathfrak{i}(\alpha)$ denotes the Fisher information of the discrete distribution with pmf $\mathfrak{p}_\alpha(j)$:
\[
\mathfrak{i}(\alpha) = \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) \left( \frac{\partial}{\partial \alpha} \log \mathfrak{p}_\alpha(j) \right)^2.
\]
This result provides an asymptotic confidence interval for $\alpha$. Then, a natural question is whether the convergence in \eqref{eq:intro_qmle_limit_dist} also holds under Gibbs partition models with general weight $(v_{n,k})$.

In addition to parameter estimation, statisticians are also interested in \textit{prediction}—a practical task often more relevant in applications. Specifically, we aim to estimate the random simplex $\bm{\simp}_n \in \Delta^{\mathsf{k}_n + 1}$ defined in \eqref{eq:intro_simplex}, which describes the probability of assigning the $(n+1)$-st element to each block. This prediction problem is more challenging, as it requires simultaneous estimation of both $\alpha$ and the triangular array $(v_{n,k})$, and the length of the simplex $\bm{\simp}_n$ grows in the rate $n^\alpha$. 

\paragraph{Contribution}  
In this paper, we address the two aforementioned questions under the assumption that $v_{n,k}$ admits a mixture representation of the Ewens--Pitman weights $v_{n,k}(\alpha, \theta)$, where $\theta$ is integrated with respect to a mixing measure $\mu$ (see \Cref{assumption}). Under this setting, we show that the QMLE $\hat{\alpha}_n$ retains the asymptotic mixed normality given by \eqref{eq:intro_qmle_limit_dist}. In addition, we construct a fully data-driven estimator \(\bm{\hat\simp}_n\) for the simplex \(\bm{\simp}_n\) and establish a limit distribution for the $f$-divergence $\mathsf{D}_f(\bm{\hat{\simp}}_n \| \bm{\simp}_n)$, covering both the total variation distance and the Kullback--Leibler divergence. In particular, we show
\[
n \sqrt{\frac{\mathfrak{i}(\alpha)}{\mathsf{k}_n}} \cdot \tv(\bm{\hat\simp}_n, \bm{\simp}_n) \xrightarrow{\mathrm{d}} |\mathcal{N}(0,1)|,
\]
which enables predictive inference for the assignment of the $(n+1)$-th element, equipped with a confidence interval.

\paragraph{Organization}
\Cref{sec:alpha_diversity} introduces the working assumptions and establishes key asymptotic properties of $\mathsf{k}_n$. \Cref{sec:parameter_estimate} focuses on the estimation of $\alpha$, presenting the QMLE and deriving its asymptotic distribution. \Cref{sec:prediction} develops an estimator $\hat{\bm{\simp}}_n$ for the simplex $\bm{\simp}_n$ and derives the asymptotic distribution of the $f$-divergence $\mathsf{D}_f(\bm{\hat{\simp}}_n \| \bm{\simp}_n)$. Finally, \Cref{sec:simulation} provides numerical experiments that illustrate and validate the theoretical findings.

