It is worth discussing, among all solutions \(v_{n,k}\) to the recursion \eqref{eq:recursion}, what subset is captured by \Cref{assumption}. In this regard, \cite{gnedin2006exchangeable} shows that any Gibbs partition can be realized via conditional iid sampling from a random discrete measure known as a \emph{Poisson--Kingman process}, parameterized by \(\alpha\) and a probability measure \(\gamma\) on \((0, \infty)\). With this representation theorem, the corresponding weight $v_{n,k}$ can be written explicitly as 
\begin{align*}
  v_{n,k} = v_{n,k}(\alpha; \gamma) \equiv \int_0^\infty \frac{\alpha^k t^{-n}}{\Gamma(n - k\alpha) f_\alpha(t)} \left( \int_0^t s^{n - k\alpha -1} f_\alpha(t - s) \, \dd s \right) \dd \gamma(t),
\end{align*}
where \(f_\alpha\) is the density whose Laplace transform satisfies $\int_0^\infty e^{-\lambda x} f_\alpha(x) \, \dd x = e^{-\lambda^\alpha}$ (see  \cite{lijoi2008investigating}). Moreover, the law \(\gamma\) can be estimated by the asymptotic law of the number of blocks \(\mathsf{k}_n\) via the following transformation:
\[
\gamma =^d \mathsf{S}_\alpha^{-1/\alpha} \quad \text{where} \quad \mathsf{S}_\alpha = \lim_{n\to+\infty} n^{-\alpha} \mathsf{k}_n \text{ (a.s.)}. 
\]
Consequently, the class of solutions covered by \Cref{assumption} corresponds to the range of distributions of \(\mathsf{S}_\alpha^{-1/\alpha}\) that can be generated by mixtures over the Ewens--Pitman family via \(\mu\). In the next theorem, we briefly examine the law of \(\mathsf{S}_\alpha\); however, a comprehensive characterization remains open and is left for future work.

\begin{theorem}[$\alpha$-diversity]\label{theorem:Lp_converge}
  Let \Cref{assumption} be satisfied. Then, there exists a positive random variable $\diversity$ with bounded second moment such that 
  \begin{align*}
    n^{-\alpha} \mathsf{k}_n \to \diversity \quad \text{almost surely and in $L_2$}.
  \end{align*}
  Furthermore, the first moment of the almost sure limit $\diversity$ is bounded as 
  \begin{align}\label{eq:alpha_diversity_moment_ineq}
          \frac{1}{\alpha} \frac{\Gamma(\underline\theta+1)}{\Gamma(\underline\theta + \alpha)} \le \E[\diversity] \le \frac{1}{\alpha} \frac{\Gamma(\bar\theta+1)}{\Gamma(\bar\theta + \alpha)}. 
  \end{align}
\end{theorem}
This theorem establishes not only the almost sure convergence but also the $L_2$ convergence, which does not directly follow from the results of \cite{gnedin2006exchangeable}. Our proof leverages a basic martingale convergence argument, inspired by the approach in \cite{bercu2024martingale}. 

\begin{remark}
When $\mu=\delta_\theta$, the convergence $n^{-\alpha}\mathsf{k}_n\to \diversity$ is well studied in literatures. In this case, the law of $\diversity$ is referred to as generalized Mittag-Leffler distribution, which has finite $p$-th moments for any $p>-(1+\theta/\alpha)$, with the following closed-form expression:
$$
\E\bigl[(\mathsf{S}_{\alpha,\delta_\theta})^p\bigr] = \frac{\Gamma(\theta+1)}{\Gamma(\theta/\alpha + 1)} \frac{\Gamma(\theta/\alpha + p+1)}{\Gamma(\theta + p\alpha + 1)}. 
$$
This is consistent with the moment bound in \eqref{eq:alpha_diversity_moment_ineq} by taking $\mu=\delta_\theta$. 
Moreover, several works have extended the convergence $n^{-\alpha}\mathsf{k}_n\to \diversity$ for $\mu=\delta_\theta$: 
\cite{dolera2020berry} proves a Berry-Esseen-type theorem, showing that the Kolmogorov distance between $n^{-\alpha}\mathsf{k}_n$ and $\diversity$ decays at the rate $n^{-\alpha}$.  \cite{bercu2024martingale} shows the CLT of the form $n^{\alpha/2} (n^{-\alpha} \mathsf{k}_n-\mathsf{S}_{\alpha, \mu}) \to^d N \sqrt{\mathsf{S}_{\alpha,\mu}'}$ for $N\sim N(0,1)\indep \diversity' =^d \diversity$, and the law of the iterated logarithm for $\mathsf{k}_n$. 
\end{remark}

Let $\ell_n(\alpha, \mu)$ be the log-likelihood of the Gibbs partition where the parameters  $(\alpha, \{v_{n,k}\})$ satisfy \Cref{assumption} for some mixture $\mu$. 
From the marginal likelihood formula \eqref{eq:intro_marginal_likelihood},  $\ell_n(\alpha, \mu)$ can be expressed as 
\begin{align}\label{eq:loglikelihood}
\ell_n(\alpha; \mu) \equiv 
 \log \Bigl(\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)} \Bigr) + \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \log(i-\alpha).   
\end{align}
As an application of the $L_2$ convergence result in \Cref{theorem:Lp_converge}, we now investigate the asymptotic behavior of the Fisher information with respect to the discount parameter $\alpha\in (0,1)$. Specially, we analyze the leading term of the variance $\E[(\partial_\alpha \ell_n(\alpha; \mu))^2]$, which characterizes the Fisher information for the parameter $\alpha$ in the Gibbs partition model. 

\begin{theorem}\label{theorem:fisher}
The Fisher Information for the discount parameter $\alpha\in(0,1)$ in the Gibbs partition model behaves asymptotically as 
  $$
  \E\Bigl[\bigl(\partial_\alpha \ell_n(\alpha; \mu)\bigr)^2\Bigr] \sim n^\alpha \E[\diversity] \mathfrak{i}(\alpha), 
  $$
  where $\diversity=\lim_{n\to+\infty}n^{-\alpha} \mathsf{k}_n$ denotes the $\alpha$-diversity, and 
  $\mathfrak{i}(\alpha)$ is the Fisher Information for $\alpha$ in the discrete distribution with pmf $\mathfrak{p}_\alpha(j)$, defined as 
  \begin{align}\label{eq:fisher_sibuya}
    \mathfrak{i}(\alpha) \equiv \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) \Bigl(\frac{\partial}{\partial \alpha}\log \mathfrak{p}_\alpha(j)\Bigr)^2  \quad \text{with} \quad \mathfrak{p}_\alpha(j) 
= \frac{\alpha \prod_{i=1}^{j-1} (i - \alpha)}{j!}.
  \end{align}
\end{theorem}
With $\alpha\in(0,1)$, \Cref{theorem:fisher} implies  that the Fisher Information grows sub-linearly in $n$. When the mixing distribution $\mu$ is a Dirac measure $\mu=\delta_{\theta}$, this result recovers the result in \cite{koriyama2022asymptotic}. 

The Fisher information $\mathfrak{i}(\alpha)$ of the discrete distribution with pmf $\mathfrak{p}_\alpha(j)$ will also play a central role in constructing confidence intervals for both $\alpha$ and the predictive simplex $\bm{\simp}_n$ (see \Cref{cor:ci_alpha}, \Cref{cor:CI_additive}, and \Cref{theorem:ratio_consistency}). We introduce the following closed-form expression:
\begin{proposition}[{\cite[Proposition 3.1]{koriyama2022asymptotic}}]\label{prop:fisher_info_sibuya}
  Let $\mathfrak{i}(\alpha)$ be the Fisher Information of the discrete distribution $\mathfrak{p}_\alpha(j)$ as \eqref{eq:fisher_sibuya}. Then, $\mathfrak{i}(\alpha)$ admits the following expression:
  \begin{align*}
    \forall \alpha\in (0,1), \quad 
    \mathfrak{i}(\alpha) = \frac{1}{\alpha^2} + \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2} =  \frac{1}{\alpha^2} + \sum_{j=1}^\infty \frac{\mathfrak{p}_\alpha(j)}{\alpha(j-\alpha)}, 
  \end{align*}
  and the map $\alpha\mapsto \mathfrak{i}(\alpha)$ is continuous in $\alpha\in (0,1)$.
\end{proposition}

