In this section, we consider the estimation of the discount parameter $\alpha\in (0,1)$ in the Gibbs partition model under \Cref{assumption}, where the mixing distribution $\mu$ is unknown. We introduce the \emph{Quasi-Maximum Likelihood Estimator} (QMLE).

\begin{definition}[Quasi-Maximum Likelihood Estimator]\label{df:qmle}
The QMLE, denoted by $\hat{\alpha}_n$, is defined as
\[
\hat{\alpha}_n \in \underset{\alpha \in (0,1)}{\operatorname{argsup}} \ \ell_n(\alpha; \delta_0) = \underset{\alpha \in (0,1)}{\operatorname{argsup}} \ \left\{ (\mathsf{k}_n - 1)\log \alpha + \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \log(i - \alpha) \right\},
\]
where $\ell_n(\alpha; \delta_0)$ is the log-likelihood \eqref{eq:loglikelihood} with the mixing distribution $\mu$ set to the Dirac measure at 0.
\end{definition}

The QMLE corresponds to the MLE under a simplified Gibbs model with $\mu = \delta_0$. Notably, its computation depends only on the block size statistics $(\mathsf{k}_{n,j})_{j=1}^n$, which, as previously noted, serve as the sufficient statistics for the Gibbs models. 
Following algebraic simplifications (see, e.g., \cite{favaro2021near, koriyama2022asymptotic, carlton1999applications}), the QMLE $\hat{\alpha}_n$ is characterized as:
\begin{align}\label{eq:qmle_cases}
\hat{\alpha}_n =
\begin{cases}
0 & \text{if } \mathsf{k}_n = 1, \\
1 & \text{if } \mathsf{k}_n = n, \\
\text{the unique solution } \alpha \in (0,1) \text{ to } \partial_\alpha \ell_n(\alpha; \delta_0) = 0 & \text{if } 1 < \mathsf{k}_n < n,
\end{cases}
\end{align}
where the stationary condition $\partial_\alpha \ell_n(\alpha; \delta_0) = 0$ is explicitly given by:
\begin{align}\label{eq:stationary_condition}
0 = \partial_\alpha \ell_n(\alpha; \delta_0) = \frac{\mathsf{k}_n - 1}{\alpha} - \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{i - \alpha}, \quad \alpha \in (0,1).
\end{align}
The following proposition shows that the boundary cases $\mathsf{k}_n \in \{1, n\}$ occur with exponentially small probability, ensuring that the QMLE typically lies in the open interval $(0,1)$ satisfies the stationary condition. 

\begin{proposition}\label{prop:mle_existence}
Under \Cref{assumption}, it holds that 
\begin{align*}
\PP(\mathsf{k}_n = 1) &\lesssim n^{-(\alpha + \underline\theta)} = o(1), \\
\PP(\mathsf{k}_n = n) &\lesssim n^{\bar{\theta}(\alpha^{-1} - 1)} \alpha^n = o(1)
\end{align*}
\end{proposition}

Combining \eqref{eq:qmle_cases} and \Cref{prop:mle_existence}, we conclude that with high probability, the QMLE $\hat{\alpha}_n$ lies in the open interval $(0,1)$ and is the unique solution to the equation \eqref{eq:stationary_condition}.\\

% \subsection{Asymptotic Mixed Normality}\label{subsec:stable}
% Next, we will derive the limit distribution of the QMLE $\hat\alpha_n$, showing that the QMLE is \emph{asymptotically mixed normal}. The rigorous statements require a refined notion of stochastic convergence, \textit{the stable convergence}. Below, we introduce this concept in a general setting. 
We now turn to the asymptotic distribution of the QMLE $\hat{\alpha}_n$, and show that it is \emph{asymptotically mixed normal}. To formulate this result rigorously, we introduce a notion of stochastic convergence known as \emph{stable convergence}. We begin by defining this concept in a general setting.


\begin{definition}[{\cite[Definition 3.15]{hausler2015stable}}]
  Let $(\Omega, \mathcal{F}, P)$ be a probability space, and let $\mathcal{X}$ be a separable metrizable topological space equipped with its Borel $\sigma$-field $\mathcal{B}(\mathcal{X})$. 
% We define $\mathcal{L}^1(\Omega, \mathcal{F}, P) = \mathcal{L}^1$ as the space of $\mathcal{F}$-measurable functions satisfying $\int |f| dP < +\infty$, and let $C_b(\mathcal{X})$ denote the space of continuous bounded functions on $\mathcal{X}$. 
For a sub-$\sigma$-field $\mathcal{G} \subset \mathcal{F}$, a sequence of $(\mathcal{X}, \mathcal{B}(\mathcal{X}))$-valued random variables $(X_n)_{n\geq 1}$ is said to converge $\mathcal{G}\operatorname{-stably}$ to $X$, denoted by $X_n \rightarrow X$ $\mathcal{G}\operatorname{-stably}$, if 
 \begin{align}\label{eq:stable_convergence_rv}
    % \forall f \in \mathcal{L}^1,\quad  \forall h \in C_b(\mathcal{X}), \quad 
    \lim_{n\rightarrow\infty} \E\Bigl[f\E\bigl[h(X_n)\mid\mathcal{G}\bigr]\Bigr]
     = \E\Bigl[f\E\bigl[h(X)\mid\mathcal{G}\bigr]\Bigr]
\end{align}
for any $\mathcal{F}$-measurable and integrable function $f$, and any bounded continuous function $h$ on $\mathcal{X}$. 
%  If $X$ is independent of $\mathcal{G}$, then $(X_n)_{n\geq 1}$ is said to converge $\mathcal{G}\operatorname{-mixing}$, denoted by $X_n \rightarrow X$ $\mathcal{G}\operatorname{-mixing}$
\end{definition}
Taking $f \equiv 1$ in \eqref{eq:stable_convergence_rv}, we see that the stable convergence is stronger than the usual weak convergence. When $\mathcal{G}$ is the trivial $\sigma$-field $\{\emptyset, \Omega\}$, the $\mathcal{G}$-stable convergence reduces to the weak convergence. Indeed, in this case we have 
$\E[f\E[h(X_n)|\mathcal{G}]] = (\int f \diff P) \cdot \E[h(X_n)]$ so that \eqref{eq:stable_convergence_rv} becomes $\E[h(X_n)]\to \E[h(X)]$ for any bounded continuous function $h$, which is the definition of weak convergence. 

% \cite[Theorem 3.18]{hausler2015stable} extends 
% known theorems for the week convergence to the stable convergence. Below we provide the continuous mapping theorem and Slutsky’s lemma for the stable convergence, which will be used throughout of this paper. 

\cite[Theorem 3.18]{hausler2015stable} extends several known results for weak convergence to the setting of stable convergence. Below, we present the continuous mapping theorem and Slutsky’s lemma for stable convergence, both of which will be used throughout this paper.

\begin{lemma}[{\cite[Theorem 3.18]{hausler2015stable}}]\label{th:CS_stable}
Let $(\mathcal{X}, \mathcal{B}(\mathcal{X}))$ and $(\mathcal{Y}, \mathcal{B}(\mathcal{Y}))$ be separable metrizable spaces with a metric $d$. Suppose $(X_n)_{n\geq 1}$ is a sequence of $(\mathcal{X}, \mathcal{B}(\mathcal{X}))$-valued random variables satisfying $X_n \rightarrow X$ $\mathcal{G}\operatorname{-stably}$. Then, the following hold:
\begin{itemize}
    \item If $\mathcal{X} = \mathcal{Y}$ and $d (X_n, Y_n) \rightarrow 0$ in probability, then $Y_n \rightarrow X$ $\mathcal{G}\operatorname{-stably}$.
    \item If $Y_n \to Y$ in probability and $Y$ is $\mathcal{G}$-measurable, then $(X_n, Y_n) \rightarrow (X, Y)$ $\mathcal{G}\operatorname{-stably}$.
    \item  If $g: \mathcal{X} \rightarrow \mathcal{Y}$ is $(\mathcal{B}(\mathcal{X}), \mathcal{B}(\mathcal{Y}))$-measurable and continuous $P^{X}$-a.s., then $g(X_n) \rightarrow g(X)$ $\mathcal{G}\operatorname{-stably}$.
\end{itemize}
\end{lemma}
% If the sub $\sigma$-filed $\mathcal{G}$ is the trivial $\sigma$-field $\{\emptyset, \Omega\}$, then the above assertions reduce to the well-known results for weak convergence. 
It is important to emphasize that the second statement allows the random variable $Y$ to be $\mathcal{G}$-measurable, rather than merely a deterministic constant. This highlights that Slutsky’s lemma holds in a stronger form under stable convergence. \\

We are now ready to state the limit distribution of the QMLE. In what follows, we take the sub $\sigma$-filed $\mathcal{G}$ to the limiting $\sigma$-field $\mathcal{F}_\infty = \sigma(\cup_{n=1}^\infty \mathcal{F}_n)$, where $\mathcal{F}_n=\sigma(\Pi_n)$ is the $\sigma$-field generated by the random partition $\Pi_n\in \mathcal{P}_n$ of $[n]$. With this notation, we will show that the QMLE $\hat{\alpha}_n$, scaled by $n^{\alpha/2}$, converges $\mathcal{F}_\infty$-stably to a variance mixture of centered normal distributions.

\begin{theorem}[Asymptotic Mixed Normality]\label{thm:mle_clt}
  % Let $\mathcal{F}_n=\sigma(\Pi_n)$  and let $\mathcal{F}_\infty = \sigma(\cup_{n=1}^\infty \mathcal{F}_n)$ be the limiting $\sigma$-field. 
  Let $\mathcal{F}_\infty = \sigma(\cup_{n=1}^\infty \mathcal{F}_n)$ with $\mathcal{F}_n=\sigma(\Pi_n)$. 
  Then, we have 
  $$
  \sqrt{n^\alpha \mathfrak{i}(\alpha)} \cdot (\hat{\alpha}_n-\alpha) \to  N/\sqrt{\diversity} \quad \stable
  $$
  where $N\sim \mathcal{N}(0,1)$ is independent of $\mathcal{F}_\infty$, and $\diversity=\lim_{n\to+\infty} n^{-\alpha} \mathsf{k}_n$ is the $\alpha$-diversity, which is $\mathcal{F}_\infty$-measurable. 
\end{theorem} 

\Cref{thm:mle_clt} was established for the Ewens--Pitman model by \cite{koriyama2022asymptotic}. Here we extend the result to the general Gibbs partition under \Cref{assumption}. 
\Cref{thm:mle_clt} implies that the QMLE converges at rate $n^{-\alpha/2}$, which is slower than the standard iid parametric rate due to the fact that $\alpha\in(0,1)$. More significantly, the limiting distribution is not a fixed normal but a variance mixture of centered normals, where the randomness in the variance arises from the $\alpha$-diversity $\diversity$. 

In conjunction with the asymptotic behavior of the Fisher Information in \Cref{theorem:fisher}, we obtain:
$$
\underbrace{\sqrt{\E\Bigl[\bigl(\partial_\alpha \ell_n(\alpha; \mu)\bigr)^2\Bigr]}}_{\text{Fisher Information}} \cdot (\hat\alpha_n -\alpha) \to  \underbrace{N\cdot \sqrt{\frac{\E[\diversity]}{\diversity}}}_{\text{variance $\ge 1$}} \quad \stable. 
$$
By Jensen's inequality and the independence of $N\sim \mathcal{N}(0,1)$ and $\diversity$, it follows that the variance of the limit distribution exceeds $1$. This contrasts with the standard parametric iid setting, where the MLE achieves the Cramér–-Rao lower bound. 

As a direct consequence of  \Cref{thm:mle_clt}, we obtain an asymptotic confidence interval for $\alpha$ using the almost sure convergence  $n^{-\alpha} \mathsf{k}_n \to \diversity$ and 
Slutsky's lemma for stable convergence (see
\Cref{th:CS_stable}). 
\begin{corollary}[Confidence interval of $\alpha$]\label{cor:ci_alpha}
  Let $\mathsf{k}_n$ be the number of non-empty blocks and $\mathfrak{i}(\alpha)$ be the Fisher Information of the discrete distribution $\mathfrak{p}_\alpha(j)$ (see \Cref{prop:fisher_info_sibuya}). Then, we have 
  \begin{align*}
    \sqrt{\mathsf{k}_n \mathfrak{i}(\alpha)} (\hat{\alpha}_n-\alpha) \to N \quad  \stable
  \end{align*}
  where $N\sim \mathcal{N}(0,1)$ is independent of $\mathcal{F}_\infty$. Consequently, for any $\epsilon\in (0,1)$, letting $\tau_{1-\epsilon/2}$ be the $(1-\epsilon/2)$-quantile of $\mathcal{N}(0,1)$, we have 
  $$
  \lim_{n\to+\infty} \PP\left(\alpha \in \Bigl[\hat\alpha_n \pm \frac{\tau_{1-\epsilon/2}}{\sqrt{\mathsf{k}_n  \mathfrak{i}(\hat{\alpha}_n) }}\Bigr]\right) = 1-\epsilon. 
  $$
\end{corollary}

\section{Estimation of probability simplex $\simp_n$}\label{sec:prediction}
In this section, we study the estimation of the probability simplex $\bm{\simp}_n$, defined as:
\begin{align*}
  \bm\simp_n = (\simp_{n,0}, \dots, \simp_{n, \mathsf{k}_n})  \equiv \Bigl(\frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}} , 
  \frac{v_{n+1, \mathsf{k}_n}}{v_{n,\mathsf{k}_n}}(|U_1|-\alpha), \cdots,   \frac{v_{n+1, \mathsf{k}_n}}{v_{n,\mathsf{k}_n}}(|U_{\mathsf{k}_n}|-\alpha)
  \Bigr).
\end{align*}
Recall from \eqref{eq:rule} that, under the Gibbs partition model, given a partition $(U_1, U_2, \dots, U_{\mathsf{k}_n})$ of $[n]$, the next $(n+1)$-th item is assigned according to 
\begin{align*}
  (n+1) \in \begin{cases}
    \text{a new block} & \text{with probability } \simp_{n,0} \\
    \text{$U_i$} & \text{with probability } \simp_{n,i}, \quad i \in \{1, 2, \dots \mathsf{k}_n\}
  \end{cases}.
\end{align*}
We aim to estimate this
random simplex $\bm{\simp}_n$. Define the estimator $\bm{\hat\simp}_n$ as 
\begin{align*}
\bm{\hat\simp}_n = (\hat\simp_{n,0}, \hat\simp_{n,1}, \dots, \hat\simp_{n,\mathsf{k}_n}) \equiv \Bigl(
  \frac{\mathsf{k}_n}{n}\hat{\alpha}_n,  
\frac{|U_1|-\hat{\alpha}_n}{n}, \dots, \frac{|U_{\mathsf{k}_n}|-\hat{\alpha}_n}{n}
  \Bigr), 
\end{align*}
where $\hat{\alpha}_n$ is the QMLE. This estimator is derived from the true simplex $\bm{\simp}_{n}$ by taking \( \mu = \delta_0 \) and replacing \( \alpha \) with \( \hat{\alpha}_n \).
We investigate the asymptotic behavior of the $f$-divergence between \( \bm{\hat{\simp}}_n \) and \( \bm{\simp}_n \):
\begin{align*}
  \mathsf{D}_f(\bm{\hat{\simp}}_n \| \bm{\simp}_n) \equiv \sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \cdot f\left(\frac{\hat{\simp}_{n,i}}{\simp_{n,i}}\right),
\end{align*}
where \( f: [0, \infty) \to \mathbb{R} \) is a convex function with \( f(1) = 0 \). Notable examples include:
\begin{itemize}
  \item KL divergence: \( f(x) = x \log x \), giving
  \[ \mathsf{KL}(\bm{\hat{\simp}}_n \| \bm{\simp}_n) = \sum_{i=0}^{\mathsf{k}_n} \hat{\simp}_{n,i} \cdot \log\left(\frac{\hat{\simp}_{n,i}}{\simp_{n,i}}\right). \]
  \item Total Variation (TV) distance: \( f(x) = |x - 1| / 2 \), yielding
  \[ \mathsf{TV}(\bm{\hat{\simp}}_n, \bm{\simp}_n) = \frac{1}{2} \sum_{i=0}^{\mathsf{k}_n} |\hat{\simp}_{n,i} - \simp_{n,i}| = \sup_{I \subset \{0, \dots, \mathsf{k}_n\}} \left|\sum_{i \in I}(\hat{\simp}_{n,i} - \simp_{n,i})\right|. \]
\end{itemize}
We first consider the case where $f$ is locally twice differentiable and its second derivative is Hölder continuous at $1$. That is, there exists $\delta > 0, C > 0$, and $\beta > 0$ such that $f$ is twice differentiable on $(1 - \delta, 1 + \delta)$, and
$|f''(1 + x) - f''(1)| \le C |x|^\beta$ for all $|x| < \delta$. 
\begin{theorem}\label{thm:f_div}
  Suppose $f$ is locally twice differentiable and its second derivative is Hölder continuous at $1$. Then, we have 
  \begin{align*}
     n\cdot \mathsf{D}_f(\bm{\hat\simp}_n|| \bm{\simp}_n ) \to \frac{\alpha f''(1)}{2} |N|^2 \quad \stable
  \end{align*}
  where $N\sim \mathcal{N}(0,1)\indep \mathcal{F}_\infty$. 
\end{theorem}
For \( f(x) = x \log x \), this gives \( n \cdot \mathsf{KL}(\bm{\hat{\simp}}_n \| \bm{\simp}_n) \to \frac{\alpha}{2}|N|^2 \). Thus, KL divergence decays at the rate \( n^{-1} \), matching the typical parametric iid cases. By Pinsker's inequality ($\tv \le \sqrt{2^{-1}\mathsf{KL}}$), this implies \(\mathsf{TV}(\bm{\hat\simp}_n, \bm{\simp}_n)  = O_p(n^{-1/2}) \). However, a sharper analysis reveals $\E[\mathsf{TV}(\bm{\hat\simp}_n, \bm{\simp}_n)^2]^{1/2} \lesssim n^{-1+\frac{\alpha}{2}}$ (note $n^{-1+\frac{\alpha}{2}} \ll  n^{-1/2}$ by $\alpha\in(0,1)$).
% With $f(x)=x\log x$ in the above theorem, we have 
% $n \mathsf{KL}(\bm{\hat\simp}_n|| \bm{\simp}_n) \to \frac{\alpha}{2} |N|^2$. 
% This implies that the KL divergence decays in the $n^{-1}$ rate, which coincides with the typical parametric iid cases. 

% Now, combined with Pinsker's inequality $\tv \le \sqrt{2^{-1} \mathsf{KL}}$, it immediately follows that $\tv=O_p(n^{-1/2})$. In the next theorem we will provide a sharper result, showing that $\tv=O_p(n^{-1+\alpha/2})$ (note $n^{-1+\alpha/2}\ll n^{-1/2}$ by $\alpha\in(0,1)$). 

% The key difference from the TV distance is that the rate of convergence is $n^{-1}$, independent of $\alpha$, while the TV distance decays with $n^{-1+\alpha/2}$. As a sanity check, with $\alpha\in (0,1)$, these rates are consistent with the Pinsker's inequality: $\tv \le \sqrt{2^{-1} \mathsf{KL}}$. 

