\begin{theorem}\label{theorem:tv}
  Let $\mathsf{TV}(\bm{\hat\simp}_n, \bm{\simp}_n) = \frac{1}{2}\sum_{i=0}^{\mathsf{k}_n} |\hat\simp_{n,i}-\simp_{n,i}|$. Then:
  \begin{itemize}
    \item $n^{1-\frac{\alpha}{2}} \cdot  \tv(\bm{\hat\simp}_n, \bm{\simp}_n)$ is bounded in $\mathcal{L}_2$, i.e., $\E[\tv(\bm{\hat\simp}_n, \bm\simp_n)^2]^{1/2} \lesssim n^{-1+\frac{\alpha}{2}}$. 
    \item The limit distribution is given by
    $$
      n^{1-\frac{\alpha}{2}} \cdot  \tv(\bm{\hat\simp}_n,  \bm\simp_n)  \to \sqrt{\frac{\diversity}{\mathfrak{i}(\alpha)}} |N| \quad \stable
    $$
  where $\diversity=\lim_{n\to+\infty} \mathsf{k}_n/n^\alpha$ and $N\sim \mathcal{N}(0,1) \indep \mathcal{F}_\infty$. 
  \end{itemize}
\end{theorem}
  Combining the second claim and Slutsky's lemma in \Cref{th:CS_stable},  using the identity $\mathsf{TV}(\bm{\hat\simp}_n, \bm{\simp}_n) = \sup_{I\subset \{0, \dots \mathsf{k}_n\}} |\sum_{i\in I} (\hat\simp_{n,i}-\simp_{n,i})|$, we obtain the following corollary:
\begin{corollary}[Additive confidence interval]\label{cor:CI_additive} 
    Let $\mathsf{k}_n$ be the number of non-empty blocks and $\mathfrak{i}(\alpha)$ be the Fisher Information of the discrete distribution $\mathfrak{p}_\alpha(j)$ (see \Cref{prop:fisher_info_sibuya}). Then, we have 
  $$
  n \sqrt{\frac{\mathfrak{i}(\alpha)}{\mathsf{k}_n}}\cdot 
   \tv(\bm{\hat\simp}_n, \bm\simp_n) \to  |N|  \quad \stable. 
  $$
  Thus, for any \( \epsilon \in (0,1) \), letting \( \tau_{1 - \epsilon/2} \) denote the \((1 - \epsilon/2)\)-quantile of $\mathcal{N}(0,1)$, we have 
  \begin{align}\label{eq:additive_CI}
  \lim_{n\to+\infty}\PP\left(
  \forall I\subset \{0, 1, \dots \mathsf{k}_n\}, \quad 
  \sum_{i\in I}\simp_{n, i} \in  \Bigl[
  \sum_{i\in I}{\hat\simp}_{n,i} \pm
    \frac{\sqrt{\mathsf{k}_n}}{n} \frac{\tau_{1-\epsilon/2}}{\sqrt{\mathfrak{i}(\hat{\alpha}_n)}} 
  \Bigr]\right) = 1-\epsilon. 
  \end{align}
\end{corollary}


The confidence band in \eqref{eq:additive_CI} is additive, with width decaying at rate \( \sqrt{\mathsf{k}_n}/n \). As a consequence, the interval may become vacuous for subsets \( I \subset \{0, \dots, \mathsf{k}_n\} \) of small mass, i.e., when
\[
  \sum_{i \in I} \hat{\simp}_{n,i} \ll \frac{\sqrt{\mathsf{k}_n}}{n}.
\]
To characterize this situation more precisely, note that
\( \hat{\simp}_{n,0} = \mathsf{k}_n \hat{\alpha}_n / n \gg \sqrt{\mathsf{k}_n}/n \)
and
\( \hat{\simp}_{n,i} = (|U_i| - \hat{\alpha}_n)/n \) for \( i \geq 1 \). Thus, the interval in \eqref{eq:additive_CI} is vacuous for a subset \( I \) if and only if
\begin{align}
\label{eq:I_vacuous}
  0 \notin I \quad \text{and} \quad \sum_{i \in I} (|U_i| - \hat{\alpha}_n) \ll \sqrt{\mathsf{k}_n}.
\end{align}
We now present an alternative, ratio-type confidence interval that remains valid even when the additive band fails:
% In the next theorem, we provide an alternative confidence interval, providing a valid confidence interval for $I$ that falls in \eqref{eq:I_vacuous}. 
\begin{theorem}\label{theorem:ratio_consistency}
  For any random integer $N_n$ such that $N_n=o_p(n^{1-\alpha/2})$ (e.g. $N_n= \lfloor \sqrt{n} \rfloor$ or $\lfloor n/\mathsf{k}_n^{0.5+\delta}\rfloor$ for any $\delta>0$), define the random subset $\mathcal{I}_n$ of $2^{[\mathsf{k}_n]}$ as 
  $$
  \mathcal{I}_n = \Bigl\{
    I\subset \{1, \dots \mathsf{k}_n\}: \frac{1}{|I|}\sum_{i\in I} |U_i| \le N_n
  \Bigr\}. 
  $$
  Then, for any $\epsilon\in (0,1)$, we have 
  \begin{align*}
    \lim_{n\to+\infty}\PP\left(
      \forall I\in\mathcal{I}_n, \quad 
    \frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat{\simp}_{n,i}} \in \left[1 \pm \frac{\tau_{1-\epsilon/2}}{\sqrt{\mathsf{k}_n \mathfrak{i}(\hat{\alpha}_n)} \cdot (\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n)}\right]
    \right) = 1-\epsilon. 
  \end{align*}
\end{theorem}
% Note that the new confidence interval in \Cref{theorem:ratio_consistency} takes the ratio form, and for any $I \in \mathcal{I}_n$, the denominator $(\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n)$ is lower bounded by $(1-\hat\alpha_n) (=(1-\alpha)+o_p(1))$, so 
%  the length of the confidence interval decays in the rate of $n^{-\alpha/2}$ at the slowest for all $I\in \mathcal{I}_n$. 

 In this ratio-form interval, the denominator \( \frac{1}{|I|} \sum_{i \in I} |U_i| - \hat{\alpha}_n \) is uniformly bounded away from the positive constant $(1-\alpha)/2$ for any subset \( I \in 2^{[\mathsf{k}_n]}\) with high probability, since \( \hat{\alpha}_n \to^p \alpha \in (0,1) \) and $\frac{1}{|I|} \sum_{i \in I} |U_i|\ge 1$. As a result, the interval length decays at worst at rate \(1/\sqrt{\mathsf{k}_n} = O_p(n^{-\alpha/2})\), which vanishes as $n\to+\infty$. 


To see how this result complements the additive interval of \Cref{theorem:tv}, note that a set \( I \subset \{0, \dots, \mathsf{k}_n\} \) falls into the vacuous regime of \eqref{eq:additive_CI} precisely when it satisfies \eqref{eq:I_vacuous}. Rewriting that condition,
\[
  I \subset \{1, \dots, \mathsf{k}_n\} \quad \text{and} \quad \frac{1}{|I|} \sum_{i \in I} |U_i| \ll \frac{\sqrt{\mathsf{k}_n}}{|I|} + \hat{\alpha}_n,
\]
noting that the right-hand side is bounded by \( 2\sqrt{\mathsf{k}_n} = O_p(n^{\alpha/2}) \). Since \(n^{\alpha/2} \ll n^{1-\alpha/2}\), any such \( I \) belongs to \( \mathcal{I}_n \), and is thus covered by \Cref{theorem:ratio_consistency}.


