\section{Basic lemma}
\subsection{Definition of tilted measure}
Let $\mu$ be the mixing distribution appearing in \Cref{assumption}. For any $1\le k\le n$, define the tilted measure $\dd \mu_{n,k}$ as 
\begin{align}\label{eq:tilted_measure}. 
 1\le \forall k\le \forall n, \quad 
    \dd \mu_{n,k}(\theta) \equiv \frac{\dd \mu(\theta) v_{n,k}(\alpha, \theta)}{\int \dd\mu(\theta') v_{n,k}(\alpha,\theta')} \quad \text{with} \quad v_{n,k}(\alpha;\theta) = \frac{\prod_{i=1}^{k-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}.
\end{align}
Since the weight $v_{n,k}(\alpha;\theta)$ is strictly positive for all $\theta \in (-\alpha, +\infty)$, the support of the tilted probability measure $\mu_{n,k}$ is equal to the support of $\mu$. Combined with the condition on the support of $\mu$ from \Cref{assumption}, we have 
\begin{align}\label{eq:supp_v_nk}
1\le \forall k \le \forall n, \quad 
\operatorname{supp}(\mu_{n,k}) = \operatorname{supp} (\mu) \subset [\underline{\theta}, \bar\theta] \quad \text{with} -\alpha < \underline{\theta}\le 0 \le \bar\theta <+\infty.  
\end{align}
As we will see in later, we will handle integrals of this form $\int \dd\mu_{n,k} (\theta) h(\theta)$ for some function $h:(-\alpha, \infty) \to \mathbb{R}$ many times. By \eqref{eq:supp_v_nk}, these integrals can be estimated as 
\begin{align}\label{eq:integral_controll}
\inf_{\theta\in [\underline{\theta}, \bar\theta]} h(\theta) \le \int \dd\mu_{n,k}(\theta) h(\theta) \le \sup_{\theta\in [\underline{\theta}, \bar\theta]} h(\theta) \quad \text{and} \quad \Bigl|\int \dd\mu_{n,k}(\theta) h(\theta)\Bigr|\le \sup_{\theta\in [\underline{\theta}, \bar\theta]} |h(\theta)|
\end{align}
We will frequently use this property.
\begin{lemma}[Concentration of triangular array $v_{n,k}$]\label{lm:concentrate_v_nk}
  Suppose the triangular array $v_{n,k}$ satisfies 
  \Cref{assumption}. Then, for any $n\in \mathbb{N}$ and  $1\le k\le n$, we have 
  \begin{align*}
    \Bigl|n \frac{v_{n+1, k}}{v_{n, k}} - 1\Bigr| \vee  \Bigl|\frac{v_{n+1, k+1}}{v_{n, k}} - \frac{k}{n}\alpha\Bigr|  \le \frac{\bar{\theta}-\underline{\theta}}{n+\underline\theta}. 
  \end{align*}
\end{lemma}
\begin{proof}
  By \Cref{assumption} and the definition of tilted probability measure \eqref{eq:tilted_measure}, we have 
  \begin{align*}
    \frac{v_{n+1, k}}{v_{n, k}} &= \frac{\int \dd\mu(\theta) \frac{\prod_{i=1}^{k-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}\frac{1}{n+\theta}}{\int\dd\mu(\theta)  \frac{\prod_{i=1}^{k-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}} =  \int \dd \mu_{n,k}(\theta) \frac{1}{\theta+n}= \frac{1}{n} + {\int \dd\mu_{n, k}(\theta) \bigl(\frac{1}{\theta+n}-\frac{1}{n}\bigr)}, \\
    \frac{v_{n+1, k+1}}{v_{n, k}} &= \frac{\int \dd\mu(\theta) \frac{\prod_{i=1}^{k-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}\frac{\theta+k\alpha}{n+\theta}}{\int\dd\mu(\theta)  \frac{\prod_{i=1}^{k-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}  =  \int \dd\mu_{n,k}(\theta) \frac{\theta+k\alpha}{\theta + n} = \frac{k}{n}\alpha + {\int \dd\mu_{n, k} \bigl(\frac{\theta+k \alpha}{\theta+n}-\frac{k \alpha}{n}\bigr)}.
  \end{align*}
  By the property in \eqref{eq:integral_controll}, it holds that
  \begin{align*}
    \Bigl|\frac{v_{n+1, k}}{v_{n, k}} - \frac{1}{n}\Bigr| &\le 
  \sup_{\theta\in [\underline{\theta}, \bar{\theta}]} |\frac{1}{\theta+n}-\frac{1}{n}| =   \sup_{\theta\in [\underline{\theta}, \bar{\theta}]}  \Bigl|\frac{\theta}{n(n+\theta)}\Bigr|\le 
   \frac{1}{n} 
  %  \frac{\bar\theta-\underline\theta}{n+\underline{\theta}}
   \sup_{\theta\in [\underline{\theta}, \bar{\theta}]} \frac{|\theta|}{\theta+n}
   \\
  \Bigl|\frac{v_{n+1, k+1}}{v_{n, k}}-\frac{k}{n}\alpha\Bigr| &\le   
  \sup_{\theta\in [\underline{\theta}, \bar{\theta}]} \Bigl|\frac{\theta+k \alpha}{\theta+n}-\frac{k\alpha}{n}\Bigr| = 
    \sup_{\theta\in [\underline{\theta}, \bar{\theta}]} \Bigl|
      \frac{(n- k \alpha)\theta}{n(\theta+n)} 
    \Bigr|
    \le \sup_{\theta\in [\underline{\theta}, \bar{\theta}]} \frac{|\theta|}{\theta+n}
      %  \le \frac{\bar{\theta}+\alpha}{n(n-\alpha)},
  \end{align*}
With $\sup_{\theta\in [\underline{\theta}, \bar{\theta}]} \frac{|\theta|}{\theta+n} \le 
  \frac{\bar\theta-\underline\theta}{n+\underline{\theta}}$, we complete the proof.  
\end{proof}


\subsection{Dominated convergence theorem for empirical measure $\sum_{j=1}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \delta_j$}

Given a partition $(U_1, U_2, \dots )$ of $[n]$, let $\mathsf{k}_{n,j}$ be the number of blocks of size $j$ and let $\mathsf{k}_n = \sum_{j=1}^n \mathsf{k}_{n,j}$ be the number of non-empty blocks.
Since $\mathsf{k}_{n,j}=0$ for any $j\ge n+1$, this induces the following empirical measure over $\mathbb{N}$:
$$
   \sum_{j=1}^\infty  \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \delta_j.
$$
By equation \eqref{eq:intro_powerlaw}, this empirical measure converges to the discrete distribution $\mathfrak{p}_\alpha(j)$ pointwisely, i.e.,
$$
\frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \asconv \mathfrak{p}_\alpha(j) = \frac{\alpha\prod_{i=1}^{j-1}(i-\alpha)}{j!}.
$$
During proofs in later section, we will see many terms of the integral $\sum_{j=1}^\infty \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} f(j)$ for some function $f:\mathbb{N}\to\mathbb{R}$. The next lemma claims a dominated convergence-type theorem, i.e., if the test function $f$ is bounded, then the integral also converges almost surely. 
\begin{lemma}[Dominated convergence theorem]\label{lm:bounded_conv}
  As $n\to+\infty$, it holds that 
  $$\sum_{j=1}^\infty \Bigl|\frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} - \mathfrak{p}_\alpha(j)\Bigr|\asconv 0$$
  Therefore, for any bounded function $f:\mathbb{N}\to\mathbb{R}$, we have
  $$
  \sum_{j=1}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} f(j) \asconv \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) f(j). 
  $$
\end{lemma}

\begin{proof}
This result follows from Scheff\'e's Lemma applied with 
 the point-wise convergence $\mathsf{k}_{n,j}/\mathsf{k}_n \asconv \mathfrak{p}_\alpha(j)$ (a.s.) and the fact that $(\mathsf{k}_{n,j}/\mathsf{k}_n)_{j=1}^\infty$ and $(\mathfrak{p}_\alpha(j))_{j=1}^\infty$ are probability measures on $\mathbb{N}$. 
\end{proof}


\section{$\alpha$-diversity and Fisher Information}

\subsection{Proof of \Cref{theorem:Lp_converge}}
The proof in this section is inspired by \cite{bercu2024martingale}, which focuses on the case $\mu=\delta_\theta$, 
 and we borrow several notations from the paper. 
Let $\mathcal{F}_n$ be the $\sigma$-filed generated by the random partition of $[n]$, i.e., $(U_1, \dots \cdots U_{\mathsf{k}_n})\in \mathcal{P}_n$. 
By the definition, the number of nonempty blocks $\mathsf{k}_n$ can be written as a summation of Bernoulli random variables as follows:
\begin{align*}
  \mathsf{k}_{n+1} = \mathsf{k}_n + \xi_{n+1}, \quad \xi_{n+1}|\mathcal{F}_n\sim \Bernoulli(p_n), \quad   p_n\equiv \frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}}.
\end{align*}
By \Cref{assumption}, the success probability $p_n$ can be expressed as an integral of tilted measure:
\begin{align*}
   p_n = \frac{\int\dd \mu(\theta) v_{n,\mathsf{k}_n}(\alpha, \theta) \frac{\theta+\mathsf{k}_n\alpha}{\theta + n}}{\int \dd \mu(\theta) v_{n, \mathsf{k}_n}(\alpha,\theta)} =\int \dd \mu_{n, \mathsf{k}_n}(\theta) \frac{\theta+\mathsf{k}_n\alpha}{\theta + n}. 
\end{align*}
Here $\dd \mu_{n,\mathsf{k}_n}$ is the tilted probability measure \eqref{eq:tilted_measure} with $k=\mathsf{k}_n$.  
Here, the integrand $(\theta+\mathsf{k}_n\alpha)/(\theta+n)$ is increasing in $\theta\in (-\alpha, +\infty)$ by $\alpha \mathsf{k}_n < 1 \cdot n$. Thus, using the property of \eqref{eq:integral_controll}, we get 
\begin{align}\label{eq:p_n_inequality}
 \underline{p}_n \equiv \frac{\underline\theta + \alpha \mathsf{k}_n}{\underline\theta + n}  \le p_n \le  \frac{\bar\theta + \alpha \mathsf{k}_n}{\bar\theta + n} =: \bar{p}_n
\end{align}
Then, using the estimate $p_n\le \bar{p}_n$, 
the conditional expectation $  \E[\mathsf{k}_{n+1}|\mathcal{F}_n]$ is bounded from above as 
\begin{align*}
  \E[\mathsf{k}_{n+1}|\mathcal{F}_n] 
  &=\mathsf{k}_n + p_n &&\mathsf{k}_{n+1}=\mathsf{k}_n + \xi_{n+1}, \ \xi_{n+1}|\mathcal{F}_n\sim \Bernoulli(p_n)\\
  &\le  \mathsf{k}_n + \frac{\bar{\theta}+\mathsf{k}_n\alpha}{\bar{\theta}+n} && p_n \le \bar{p}_n=\frac{\bar\theta + \alpha \mathsf{k}_n}{\bar\theta + n}. 
  % &= \mathsf{k}_n \Bigl(
  %   1+ \frac{\alpha}{\bar{\theta}+n} 
  % \Bigr) + \frac{\bar{\theta}}{\bar{\theta}+n}
\end{align*}
Rearranging the above display, we get 
\begin{align*}
  \E\Bigl[\mathsf{k}_{n+1} + \frac{\bar{\theta}}{\alpha}\mid \mathcal{F}_n\Bigr] &\le\Bigl(\mathsf{k}_n + \frac{\bar{\theta}}{\alpha}\Bigr) \Bigl(
    1 + \frac{\alpha}{\bar{\theta}+n}
  \Bigr). 
\end{align*}
This means that $\bar M_n$ defined by 
\begin{align}\label{eq:M_n_upper}
  \bar M_n  \equiv \bar b_n(\mathsf{k}_n+\frac{\bar\theta}\alpha) \quad \text{with} \quad \bar b_n \equiv \prod_{k=1}^{n-1} \Bigl(
      1 + \frac{\alpha}{\bar{\theta}+k} 
    \Bigr)^{-1} = \prod_{k=1}^{n-1} \Bigl(
  \frac{\bar{\theta}+k}{\bar{\theta}+k + \alpha}
    \Bigr)
\end{align}
is a non-negative super martingale, i.e., 
% $\bar M_{n} \ge 0$ and $\E[\bar M_{n+1} |\mathcal{F}_n] \le \bar{M}_n$ for all $n\in \mathbb{N}$. 
$$
\bar M_{n} \ge 0, \quad 
\E[\bar M_{n+1} |\mathcal{F}_n] \le \bar{M}_n.
$$ 
Then, by Doob's martingale convergence theorem (cf. \cite[Theorem 4.2.12]{DU19}), there exists a positive random variable $\bar M_\infty$ such that 
$$
\bar M_n \asconv \bar M_\infty, \quad  \bar M_\infty\in L_1. 
$$
With $\Gamma(n+\alpha)/\Gamma(n)\sim n^\alpha$ for any $\alpha\in \mathbb{R}$, the coefficient $\bar{b}_n$ appearing in \eqref{eq:M_n_upper} behave asymptotically as 
\begin{align}\label{eq:b_upper_asym}
\bar{b}_n = \frac{\Gamma(\bar\theta+\alpha+1)}{\Gamma(\bar\theta+1)} \frac{\Gamma(\bar\theta+n)}{\Gamma(\bar\theta+\alpha+n)}  \sim n^{-\alpha} \frac{\Gamma(\bar\theta + \alpha+1)}{\Gamma(\bar\theta+1)}.   
\end{align}
Combined with the definition $\bar{M}_n = \bar b_n (\mathsf{k}_n + \bar\theta/\alpha)$ and $\bar{M}_n \asconv\bar{M}_\infty\in L_1$, we get 
\begin{align}\label{eq:Kn_as_conv}
n^{-\alpha} \mathsf{k}_n  \asconv \diversity \equiv \frac{\Gamma(\bar{\theta}+1)}{\Gamma(\bar{\theta}+\alpha+1)} \bar M_\infty\in L_1. 
\end{align}
Furthermore, since $\bar M_n$ is a super martingale with $\bar M_1 = 1+\frac{\bar\theta}{\alpha}$, it holds that 
\begin{align*}
  b_n \E[\mathsf{k}_n+\frac{\bar\theta}{\alpha}] = \E[\bar M_{n}] \le \E[\bar M_1] = 1+\frac{\bar\theta}{\alpha}. 
\end{align*}
Combined with \eqref{eq:b_upper_asym}, we obtain 
the upper bound of $\E[\mathsf{k}_n]$:
\begin{align}\label{eq:Kn_moment_upper_bound}
\E[\mathsf{k}_n] &\le \bar{b}_n^{-1} \Bigl(1+\frac{\bar\theta}{\alpha}\Bigr) - \frac{\bar\theta}{\alpha} \sim n^\alpha \frac{\Gamma(\bar\theta+1)} {\Gamma(\bar\theta+\alpha+1)}\Bigl(1+\frac{\bar\theta}{\alpha}\Bigr)  = n^\alpha \frac{\Gamma(\bar\theta+1)}{\alpha \Gamma(\bar\theta+\alpha)}.
\end{align}

Next, we will show $n^{-\alpha} \mathsf{k}_n\to\diversity $ in $L^2$ (stronger than \eqref{eq:Kn_as_conv}) by constructing a sub-martingale and applying Doob's maximum $L_p$ inequality. Now, similarly to \eqref{eq:M_n_upper}, we define $\underline{M}_n$ as 
$$
\underline{M}_n = \underline b_n(\mathsf{k}_n+\frac{\underline\theta}\alpha),  \quad  \underline b_n \equiv  \prod_{k=1}^{n-1} \Bigl(
\frac{\underline{\theta}+k}{\underline{\theta}+k + \alpha}
  \Bigr) = \frac{\Gamma(\underline\theta+\alpha+1)}{\Gamma(\underline\theta+1)} \frac{\Gamma(\underline\theta+n)}{\Gamma(\underline\theta+\alpha+n)}
$$
Then, by the same argument for $\bar{M}_n$, now using the lower estimate $\underline{p}_n\le p_n$ in \eqref{eq:p_n_inequality}, 
 one can show that  $\underline{M}_n$ is non-negative sub martingale, i.e., 
$$
\underline{M}_n\ge 0, \quad 
\E[\underline{M}_{n+1}|\mathcal{F}_n] \ge \underline M_n. 
$$
Furthermore, by the same argument for $\bar{b}_n$ in \eqref{eq:b_upper_asym}, the leading term of $\underbar{b}_n$ is given by 
\begin{align}\label{eq:b_lower_asym}
\underline{b}_n \sim 
n^{-\alpha} \frac{\Gamma(\underline\theta + \alpha+1)}{\Gamma(\underline \theta+1)}. 
\end{align}
By the same argument in \eqref{eq:Kn_moment_upper_bound}, now using the sub-martingale property of $\bar{M}_n$, we also get the lower bound of $\E[\mathsf{k}_n]$:
\begin{align}\label{eq:Kn_moment_lower_bound}
\E[\mathsf{k}_n] &\gtrsim n^\alpha \frac{\Gamma(\underline\theta+1)}{\alpha \Gamma(\underline\theta+\alpha)}.
\end{align}
Combining  \eqref{eq:Kn_as_conv},  \eqref{eq:b_lower_asym}, and $\underline{M}_n = \underline b_n(\mathsf{k}_n+\frac{\underline\theta}\alpha)$, we obtain
\begin{align*}
  \underline{M}_n \sim  \frac{\Gamma(\underline\theta + \alpha+1)}{\Gamma(\underline \theta+1)}  n^{-\alpha} \Bigl(\mathsf{k}_n + \frac{\underline{\theta}}{\alpha}\Bigr)  \asconv \underline{M}_\infty \equiv \frac{\Gamma(\underline\theta + \alpha+1)}{\Gamma(\underline \theta+1)} \diversity \in L_1. 
\end{align*}
Next, we will show that the non-negative sub martingale $\underline{M}_n$ is bounded in $L_2$, i.e., $\sup_{n\ge 1} \|\underline{M}_n\|_2 < +\infty$.  Note that the increment of $\bar{M}_n$ can be written as 
\begin{align*}
  \underline{M}_{n+1} - \underline{M}_n &= \underline{b}_{n+1} (\mathsf{k}_{n+1} + \frac{\underline \theta}{\alpha}) - \underline{b}_{n} (K_{n} + \frac{\underline \theta}{\alpha})\\
  &= \underline{b}_{n+1} (K_{n} + \xi_{n+1} + \frac{\underline \theta}{\alpha}) - \underline{b}_{n} (K_{n} + \frac{\underline \theta}{\alpha})\\
  % &= \underline{b}_{n+1} \xi_{n+1} - (\underline{b}_{n}-\underline{b}_{n+1}) (K_{n} + \frac{\underline \theta}{\alpha})\\
  &= \underline{b}_{n+1} \Bigl(
  \xi_{n+1} - (\frac{\underline{b}_n}{\underline{b}_{n+1}}-1) (\mathsf{k}_n + \frac{\underline{\theta}}{\alpha}) 
  \Bigr)\\
  &= \underline{b}_{n+1} \Bigl(
  \xi_{n+1} - \frac{\alpha}{n+\underline{\theta}} (\mathsf{k}_n + \frac{\underline{\theta}}{\alpha}) 
  \Bigr) && \underline b_n = \prod_{k=1}^{n-1} \Bigl(
\frac{\underline{\theta}+k}{\underline{\theta}+k + \alpha}
  \Bigr)  \\
  &= \underline{b}_{n+1} \Bigl(
  \xi_{n+1} - \underline{p}_{n}
  \Bigr) && \underline{p} = \frac{\alpha \mathsf{k}_n + \underline{\theta}}{n+\underline{\theta}}. 
\end{align*}
Then, we have 
\begin{align}
  \E[(\underline M_{n}-\underline M_1)^2] &= \E\Bigl[\Bigl(\sum_{i=1}^{n-1}(\underline M_{i+1}-\underline M_{i})\Bigr)^2\Bigr]\nonumber \\
  &= \sum_{k=1}^{n-1} \underline{b}_{k+1}^2 \E[(
  \xi_{k+1} - \underline{p}_{k}
)^2]  +  2 \sum_{1\le k<\ell\le n-1} \underline{b}_{k+1} \underline{b}_{\ell+1} \E\bigl[(
  \xi_{k+1} - \underline{p}_{k}
  )  (
  \xi_{\ell+1} - \underline{p}_{\ell}
  )  \bigr]\label{eq:quadratic_variation_Mn}
\end{align}
Now we claim $\sup_{n\ge 1}\E[(M_{n}-M_1)^2] <+\infty$. First, let us derive an upper bound of the first term. By the tower property, as $k\to+\infty$, 
\begin{align*}
  \E[(\xi_{k+1}-\underline{p}_k)^2] &=   \E[\E[(\xi_{k+1}-\underline{p}_k)^2|\mathcal{F}_k]]\\
  &= \E[p_k(1-\underline{p}_k)^2 + (1-p_k)\underline{p}_k^2] && \xi_{k+1}|\mathcal{F}_k \sim \Bernoulli(p_k)\\
  % &= \E[p_k(1-2\underline{p}_k + \underline{p}_k^2)  + \underline{p}_k^2 - p_k \underline{p}_k^2]\\
  % &= \E[p_k - 2p_k \underline{p}_k + \underline{p}_k^2]\\
  % &= \E[\underline{p}_k(1-\underline{p}_k)] + 2\E[\underline{p}_k (p_k - \underline{p}_k)]\\
  % &\le \E[\underline{p}_k(1-\underline{p}_k)] + 2\E[\underline{p}_k (\bar p_k  - \underline{p}_k)]\\
  % &\le \E[\underline{p}_k] + 2\E[\underline{p}_k]\\
  &\le 2 \E[\bar p_k]  && 0\le \underline{p}_k \le p_k \le \bar{p}_k \le 1  \\
  &= 2 \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta}\\
  &\lesssim k^{-1+\alpha} && \text{$\E[\mathsf{k}_n]\lesssim n^\alpha$ from \eqref{eq:Kn_moment_upper_bound}}
\end{align*}
Combined with $\underline{b}_n \asymp n^{-\alpha}$ from \eqref{eq:b_lower_asym}, we have that, as $n\to+\infty$, 
\begin{align}
  \sum_{k=1}^{n-1} \underline{b}_{k+1}^2 \E\bigl[(
  \xi_{k+1} - \underline{p}_{k}
)^2 \bigr] \lesssim \sum_{k=1}^{n-1} k^{-2\alpha} k^{-1+\alpha} = \sum_{k=1}^{n-1} k^{-(1+\alpha)} = O(1). \label{eq:first_O1}
\end{align}
Next, let us bound the cross term $\underline{b}_{k+1} \underline{b}_{\ell+1} \E[(
  \xi_{k+1} - \underline{p}_{k}
)(
  \xi_{\ell+1} - \underline{p}_{\ell}
)]$. By $\underline p_n \le p_n \le \bar p_n$ and $\E[\xi_{n+1}|\mathcal{F}_n]=p_n$, 
  \begin{align*}
    \E[\xi_{n+1}-\underline{p}_n|\mathcal{F}_n] = \E[p_n - \underline{p}_n] \ge 0
  \end{align*}
  and
  \begin{align*}
p_n - \underline{p}_n 
&\le \bar p_n - \underline{p}_n \\
&= \frac{\bar\theta + \alpha \mathsf{k}_n}{\bar\theta + n} - \frac{\underline\theta + \alpha \mathsf{k}_n}{\underline \theta + n}\\
&= \frac{\bar\theta-\underline\theta}{(\bar\theta + n)(\underline{\theta}+n)}(n-\alpha \mathsf{k}_n)\\
&\le \frac{\bar\theta-\underline\theta}{(\underline{\theta}+n)} && 0\le \alpha \mathsf{k}_n < n,\  \bar\theta\ge 0
\end{align*}
for all $n$. 
Let us fix $k < \ell$. With $k+1\le \ell$, using the tower property, 
\begin{align*}
\E\bigl[(
  \xi_{k+1} - \underline{p}_{k}
  )(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )|\mathcal{F}_{k+1}\bigr]
  &= (
  \xi_{k+1} - \underline{p}_{k}
  )\E\Bigl[(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )|\mathcal{F}_{k+1}\Bigr] \\
  &= (
  \xi_{k+1} - \underline{p}_{k}
  )\E\Bigl[\E\bigl[(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )|\mathcal{F}_{\ell}\bigr]|\mathcal{F}_{k+1}\Bigr]  \\
  &=  (
  \xi_{k+1} - \underline{p}_{k}
  )\E\bigl[(p_{\ell} - \underline{p}_{\ell}
  )|\mathcal{F}_{k+1}\bigr]   
\end{align*}
so 
\begin{align*}
  \Bigl|\E\bigl[(
  \xi_{k+1} - \underline{p}_{k}
  )(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )|\mathcal{F}_{k+1}\bigr] \Bigr|
  &\le  \bigl|
  \xi_{k+1} - \underline{p}_{k}
  \bigr|\E\bigl[|p_{\ell} - \underline{p}_{\ell}
  | \mid \mathcal{F}_{k+1}\bigr] \le  \bigl|
  \xi_{k+1} - \underline{p}_{k}
  \bigr| \frac{\bar\theta-\underline\theta}{\underline{\theta}+\ell}
\end{align*}
This gives 
\begin{align*}
  \left|\E\bigl[(
  \xi_{k+1} - \underline{p}_{k}
  )(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )\bigr]\right| &= \left|\E\Bigl[\E\bigl[(
  \xi_{k+1} - \underline{p}_{k}
  )(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )|\mathcal{F}_{k+1}\bigr]\Bigr]\right|\\
  &\le  \E\Bigl[\Bigl|\E[(
  \xi_{k+1} - \underline{p}_{k}
  )(
  \xi_{\ell+1} - \underline{p}_{\ell}
  )|\mathcal{F}_{k+1}]\Bigr|\Bigr]\\
  &\le \E[|
  \xi_{k+1} - \underline{p}_{k}
  |] \cdot \frac{\bar\theta-\underline\theta}{\underline{\theta}+\ell}
  % \\
  % &=  \frac{\bar\theta-\underline\theta}{\underline{\theta}+\ell}  \E[|
  % \xi_{k+1} - \underline{p}_{k}
  % |],
\end{align*}
where 
\begin{align*}
   \E[|
  \xi_{k+1} - \underline{p}_{k}
  |] &=  \E[\E[|
  \xi_{k+1} - \underline{p}_{k}
  |\mid \mathcal{F}_k]]\\
  &=\E[p_k (1-\underline{p}_k) + (1-p_k) \underline{p}_k]\\
  &\le 2 \E[\underline{p}_k]\\
  &= 2 \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta}.
\end{align*}
Therefore, the cross term is upper bounded as 
\begin{align*}
  \left|\sum_{1\le k<\ell\le n-1}\underline{b}_{k+1} \underline{b}_{\ell+1} \E[(
  \xi_{k+1} - \underline{p}_{k})(
  \xi_{\ell+1} - \underline{p}_{\ell}
 )]\right|
 &\le   \sum_{1\le k<\ell\le n-1}\underline{b}_{k+1} \underline{b}_{\ell+1} \Bigl|\E[(
  \xi_{k+1} - \underline{p}_{k})(
  \xi_{\ell+1} - \underline{p}_{\ell}
 )]\Bigr| \\
 &\le \sum_{1\le k<\ell\le n-1}\underline{b}_{k+1} \underline{b}_{\ell+1}  \frac{\bar\theta-\underline\theta}{\underline{\theta}+\ell} \cdot 2 \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta}\\
 &=\sum_{\ell=2}^{n-1} \underline{b}_{\ell+1} \frac{\bar\theta-\underline{\theta}}{\ell+\underline{\theta}} \cdot \sum_{k=1}^{\ell-1} 2 \underline{b}_{k+1}  \cdot \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta}
\end{align*}
Here, as $k\to+\infty$, using $\underline{b}_k\asymp k^{-\alpha}$ and $\E[\mathsf{k}_k]\lesssim k^\alpha$
$$
\underline{b}_{k+1}  \cdot \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta} \lesssim k^{-\alpha} \frac{k^\alpha}{k}  = \frac{1}{k}, 
$$
so that  as $\ell\to+\infty$, 
$$
\sum_{k=1}^{\ell-1} 2 \underline{b}_{k+1}  \cdot \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta} \lesssim \log \ell. 
$$
This in turn gives 
$$
\underline{b}_{\ell+1} \frac{\bar\theta-\underline{\theta}}{\ell+\underline{\theta}} \cdot \sum_{k=1}^{\ell-1} 2 \underline{b}_{k+1}  \cdot \frac{\bar\theta  + \alpha \E[\mathsf{k}_k]}{k+\bar \theta} \lesssim \ell^{-\alpha} \frac{1}{\ell} \log \ell = \frac{\log \ell}{\ell^{\alpha+1}}
$$
as $\ell\to+\infty$. Therefore, we have that, as $n\to+\infty$, 
\begin{align}
 \Bigl|\sum_{1\le k<\ell\le n-1}\underline{b}_{k+1} \underline{b}_{\ell+1} \E[(
  \xi_{k+1} - \underline{p}_{k})(
  \xi_{\ell+1} - \underline{p}_{\ell}
 )]\Bigr| 
 \lesssim \sum_{\ell=2}^{n-1}  \frac{\log \ell}{\ell^{\alpha+1}} = O(1) \label{eq:second_O1}
\end{align}
where we have used the fact that $\int_1^\infty x^{-(\alpha+1)} \log x$ is finite. 

Putting \eqref{eq:quadratic_variation_Mn}, \eqref{eq:first_O1}, and \eqref{eq:second_O1} together, we obtain 
$$
\sup_{n\ge 1}  \E[(\underline M_{n}-\underline M_1)^2] <+\infty. 
$$
With $\underline M_1=1+\frac{\underline\theta}{\alpha}$, which is a deterministic constant, we conclude that $\underline M_n$ is bounded in $L_2$. Since $\underline{M}_n$ is non-negative sub martingale, Doob's maximum $L_p$ inequality with $p=2$ (cf. \cite[Theorem 4.4.4]{DU19}) yields
\begin{align*}
  \E\Bigl[\bigl(\sup_{n\ge 1} |\underline{M}_n|\bigr)^2\Bigr] \le \Bigl(\frac{2}{2-1}\Bigr)^{2} \sup_{n\ge 1} \E[|\underline{M}_n|^2] < +\infty 
\end{align*}
On the other hand, since $\underline{M}_n$ converges to $\underline{M}_\infty$ almost surely as $n\to+\infty$, we have 
\begin{align*}
  \sup_{n\ge 1} |\underline{M}_n - \underline{M}_\infty|^2  \le \bigl(2 \sup_{n\ge 1} |\underline{M}_n|\bigr)^2.
\end{align*}
% Furthermore, since $\underline{M}_n$ is non-negative sub martingale, Doob's maximum $L_p$ inequality with $p=2$ (cf. \cite[Theorem 4.4.4]{DU19}) implies 
% \begin{align*}
%   \E\Bigl[\bigl(\sup_{n\ge 1} |\underline{M}_n|\bigr)^2\Bigr] \le \Bigl(\frac{2}{2-1}\Bigr)^{2} \sup_{n\ge 1} \E[|\underline{M}_n|^2] < +\infty 
% \end{align*}
Therefore, the dominated convergence theorem gives 
$$
 \lim_{n\to+\infty} \E[|\underline{M}_n - \underline{M}_\infty|^2] =  \E[\lim_{n\to+\infty}|\underline{M}_n - \underline{M}_\infty|^2] = 0. 
$$
This concludes that $\underline{M}_n$ converges to $\underline{M}_\infty$ in $L_2$.
Moreover, since $\underline{M}_n$ is bounded in $L_2$, we also get $\underline{M}_\infty \in L_2$. 
Finally, combining 
$$
\underline{M}_n = \underline{b}_n (\mathsf{k}_n + \frac{\underline{\theta}}{\alpha}), \quad \underline{b}_n \sim n^{-\alpha} \frac{\Gamma(\underline\theta + \alpha+1)}{\Gamma(\underline \theta+1)}, \quad \underline{M}_\infty = \frac{\Gamma(\underline\theta + \alpha+1)}{\Gamma(\underline \theta+1)} \diversity, 
$$
and noting that $\underline{b}_n$ is deterministic, we conclude that $\diversity\in L_2$ and 
$n^{-\alpha} \mathsf{k}_n \to^{L^2} \diversity$.


The inequality \eqref{eq:alpha_diversity_moment_ineq} of $\E[\diversity]$  immediately follows 
from \eqref{eq:Kn_moment_upper_bound}, \eqref{eq:Kn_moment_lower_bound}, and the $L_1$ convergence $n^{-\alpha} \mathsf{k}_n \to^{L^1}\diversity$.

\subsection{Proof of \Cref{theorem:fisher}}\label{sec:proof_fisher}
Let $\ell_n(\alpha;\mu)$ be the log-likelihood given by \eqref{eq:loglikelihood}. Since the marginal distribution of the Gibbs partition is a discrete distribution over $\mathcal{P}_n$, the expectation $\E$ over the law and derivative with respect to $\alpha$ is interchangeable. As a result, it holds that 
 \begin{align*}
  \E[(\partial_\alpha \ell_n(\alpha;\mu)^2)] =
   - \E[\partial_\alpha^2 \ell_n(\alpha;\mu)],
\end{align*}
and hence it suffices to show $n^{-\alpha} \E[\partial_\alpha^2 \ell_n(\alpha;\mu)] \to -\E[\diversity]\mathfrak{i}(\alpha)$. 

Here, the first and the second derivative of the log-likelihood function are given by 
\begin{align*}
  \partial_\alpha \ell_n(\alpha;\mu) &= \frac{\partial}{\partial \alpha} \left(\log \Bigl(\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)} \Bigr)+ \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \log(i-\alpha)\right)\\
  &=  \frac{\frac{\partial}{\partial\alpha} \int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}{\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}} - \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha}, \\
  \partial_\alpha^2 \ell_n(\alpha;\mu)
  &=  \frac{\frac{\partial^2}{\partial\alpha^2} \int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}{\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}} - \left(\frac{\frac{\partial}{\partial\alpha} \int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}{\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}\right)^2 - \sum_{j=1}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2}, 
\end{align*}
% \begin{align*}
%   \partial_\alpha^2 \ell_n(\alpha;\mu) &= \partial_\alpha^2 \left(\log \Bigl(\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)} \Bigr)+ \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \log(i-\alpha)\right)\\
%   &=  \frac{\frac{\partial^2}{\partial\alpha^2} \int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}{\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}} - \left(\frac{\frac{\partial}{\partial\alpha} \int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}{\int \dd \mu(\theta) \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}}\right)^2 - \sum_{j=1}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2}, 
% \end{align*}
Now we claim that the derivative $\partial_\alpha, \partial_\alpha^2$ and the integration $\int\dd\mu$ appearing above are interchangeable. This is because the first and second derivative of the integrand $\frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}$ with respect to $\alpha$ are given by 
  \begin{align*}
    \frac{\partial}{\partial \alpha} \Bigl(\frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}\Bigr) &= \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)} \sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha}\\
    \frac{\partial^2}{\partial \alpha^2} \Bigl(\frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}\Bigr) &= \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)} \Bigl(\sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha}\Bigr)^2  - \frac{\prod_{i=1}^{\mathsf{k}_n-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)} \sum_{i=1}^{\mathsf{k}_n-1} \frac{i^2}{(\theta+i\alpha)^2}.
  \end{align*}
By \Cref{assumption} 
the support of $\mu$ is contained in $[\underline{\theta}, \bar{\theta}]$ with $-\alpha< \underline{\theta} <\bar{\theta} <+\infty$, while the second derivative above is continuous in $\theta$ over the support $[\underline{\theta}, \bar\theta]$.  
Therefore, the derivative $\partial_\alpha, \partial_\alpha^2$ and the integration $\int\dd\mu$ are interchangeable. 

% Now, we write the tilted measure $\dd\mu_{n, \mathsf{k}_n}$ as $\dd \mu_{n,\mathsf{k}_n}$ for simplicity, and write the integral operator $\mathcal{E}$ and variance operator $\mathcal{V}$ under $\mu_{n,\mathsf{k}_n}$ as follows:
%   $$
%   \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}} [f(\theta)] \equiv \int \dd\mu_{n}(\theta) f(\theta), \quad 
%   \mathcal{V}_{\theta\sim \mu_{n,\mathsf{k}_n}} [f(\theta)] \equiv \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}[f(\theta)^2] - \Bigl(\mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}[f(\theta)] \Bigr)^2, 
%   $$
Substituting the derivative formula of $ \partial_\alpha^2$ to the previous display of $\partial_\alpha^2 \ell_n(\alpha; \mu)$, changing the order of $\partial_\alpha^2$ and $\int \dd\mu$, using the definition of tilted measure $\dd\mu_{n,\mathsf{k}_n}$, we get 
    \begin{align*}
    &\partial_\alpha^2 \ell_n(\alpha; \mu)\\
    &= \int \dd \mu_{n,\mathsf{k}_n}(\theta) \Bigl(\sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha}\Bigr)^2 - \int \dd\mu_{n,\mathsf{k}_n}(\theta) \sum_{i=1}^{\mathsf{k}_n-1} \frac{i^2}{(\theta+i\alpha)^2}
  - \Bigl(\int \dd\mu_{n,\mathsf{k}_n}(\theta) \sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha}\Bigr)^2
   -  \sum_{j=1}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{(i-\alpha)^2}\\
   &= \mathcal{V}_{\theta\sim \mu_{n,\mathsf{k}_n}}\Bigl[\sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta + i\alpha}\Bigr] - \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}\Bigl[ \sum_{i=1}^{\mathsf{k}_n-1}\frac{i^2}{(\theta+i\alpha)^2} \Bigr] -  \sum_{j=1}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{(i-\alpha)^2},
  \end{align*}
  where we have defined the integral operator $\mathcal{E}$ and variance operator $\mathcal{V}$ under $\mu_{n, \mathsf{k}_n}$ as follows:
  $$
  \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}} [f(\theta)] \equiv \int \dd\mu_{n}(\theta) f(\theta), \quad 
  \mathcal{V}_{\theta\sim \mu_{n,\mathsf{k}_n}} [f(\theta)] \equiv \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}[f(\theta)^2] - \Bigl(\mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}[f(\theta)] \Bigr)^2. 
  $$
  In particular, if we take the Dirac measure $\mu=\delta_0$, noting that $\mu_{n,\mathsf{k}_n}=\delta_0$, we get 
\begin{align}\label{eq:ell_n_0_second}
    \partial_\alpha^2 \ell_n(\alpha; \delta_0) = 0  -\frac{\mathsf{k}_n-1}{\alpha^2} - \sum_{j=1}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{(i-\alpha)^2}. 
\end{align}
  Taking the difference between $\partial_\alpha^2 \ell_n(\alpha; \delta_0)$ and $\partial_\alpha^2 \ell_n(\alpha; \mu)$,  we have 
  \begin{align*}
    -\partial_\alpha^2 \ell_n(\alpha;\mu) + \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0) = -\mathcal{V}_{\theta\sim \mu_{n,\mathsf{k}_n}}\Bigl[\sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta + i\alpha}\Bigr] + \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}\Bigl[ \sum_{i=1}^{\mathsf{k}_n-1}\Bigl(\frac{i^2}{(\theta+i\alpha)^2}-\frac{1}{\alpha^2}\Bigr)\Bigr]. 
  \end{align*}
  Let us bound the variance term. Since the integrand can be decomposed as 
  $$
  \sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha} = \frac{1}{\alpha} - \sum_{i=1}^{\mathsf{k}_n-1} \frac{\theta}{\alpha(\theta+i\alpha)},
  $$
  where $1/\alpha$ is constant (with respect to $\theta\sim\mu_{n,\mathsf{k}_n}$), we have
  \begin{align*}
  0\le \mathcal{V}_{\theta}\Bigl(
    \sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha}
    \Bigr) &=  \mathcal{V}_{\theta}\Bigl(
      \sum_{i=1}^{\mathsf{k}_n-1} \frac{\theta}{\alpha(\theta+i\alpha)}
      \Bigr) \le \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}} \Bigl[\Bigl(
        \sum_{i=1}^{\mathsf{k}_n-1} \frac{\theta}{\alpha(\theta+i\alpha)}
      \Bigr)^2 \Bigr]
      % \\
      % &\le \Bigl(\sum_{i=1}^{n-1} \frac{\bar\theta}{\alpha(\bar\theta + i\alpha )}\Bigr)^2. 
  \end{align*}
  This leads to 
  \begin{align*}
    \bigl|\partial_\alpha^2 \ell_n(\alpha;\mu) - \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)\bigr| \le \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}} \Bigl[\Bigl(
      \sum_{i=1}^{\mathsf{k}_n-1} \frac{\theta}{\alpha(\theta+i\alpha)}
    \Bigr)^2 \Bigr] + \mathcal{E}_{\theta\sim \mu_{n,\mathsf{k}_n}}\Bigl[\Bigl|\sum_{i=1}^{\mathsf{k}_n-1} \Bigl(\frac{i^2}{(\theta+i\alpha)^2}-\frac{1}{\alpha^2}\Bigr)\Bigr|\Bigr] 
  \end{align*}
  Since $\operatorname{supp}(\mu_{n,\mathsf{k}_n})\in [\underline{\theta}, \bar\theta]$, there exists a deterministic constant $C(\alpha,\bar\theta, \underline{\theta})$ such that the integrands appearing in the above display are uniformly bounded as 
  \begin{align*}
    \sup_{\theta\in\operatorname{supp}(\mu_{n,\mathsf{k}_n})}
\Bigl(
      \sum_{i=1}^{\mathsf{k}_n-1} \frac{\theta}{\alpha(\theta+i\alpha)}
    \Bigr)^2 \le \Bigl(\sum_{i=1}^{\mathsf{k}_n-1} \frac{\bar\theta- \underline{\theta}}{\alpha(\underline{\theta}+i\alpha)}\Bigr)^2 \le C(\alpha,\bar\theta, \underline{\theta}) (\log n)^2
  \end{align*}
and 
\begin{align*}
   \sup_{\theta\in \operatorname{supp}(\mu_{n,\mathsf{k}_n})}  \Bigl|\sum_{i=1}^{\mathsf{k}_n-1} \Bigl(\frac{i^2}{(\theta+i\alpha)^2}-\frac{1}{\alpha^2}\Bigr)\Bigr| &=   \sup_{\theta\in \operatorname{supp}(\mu_{n,\mathsf{k}_n})}  \Bigl|\sum_{i=1}^{\mathsf{k}_n-1} \frac{-\theta^2 - 2i\alpha\theta}{\alpha^2(\theta+i\alpha)^2}\Bigr| \\
  &\le \sum_{i=1}^{\mathsf{k}_n-1} \frac{
   (\bar\theta-\underline{\theta})^2 + 2i \alpha (\bar\theta-\underline{\theta}) 
  }{\alpha^2 (\underline{\theta}+i\alpha)^2}\\
  & \le C(\alpha,\bar\theta, \underline{\theta}) \log n. 
\end{align*}
Therefore, the difference $\partial_\alpha^2 \ell_n(\alpha;\mu) - \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)$ is bounded as 
\begin{align*}
  |\partial_\alpha^2 \ell_n(\alpha;\mu) - \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)|
  &\le C(\alpha,\bar\theta, \underline{\theta})  \Bigl((\log n)^2 + \log n \Bigr)
\end{align*}
Since $(\log n)^2\ll n^\alpha$, in order to prove $n^{-\alpha} \E[\partial_{\alpha}^2 \ell_{n}(\alpha; \mu)] \to - \E[\diversity ]\mathfrak{i}(\alpha)$, 
it suffices to show 
$$
  n^{-\alpha} \E[\partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)] \to - \E[\diversity ]\mathfrak{i}(\alpha). 
$$
By the expression of $\partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)$ in \eqref{eq:ell_n_0_second}, 
$$
\frac{1}{n^\alpha} \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0) 
  = \frac{\mathsf{k}_n}{n^\alpha}\Bigl(
    - \frac{1-\mathsf{k}_n^{-1}}{\alpha^2} - \sum_{j=1}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2}
  \Bigr).
$$
Now, combining $n^{-\alpha}\mathsf{k}_n\asconv \diversity$ and the dominated convergence theorem (\Cref{lm:bounded_conv}), noting that $j\mapsto \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2}$ is bounded,  we have 
\begin{align*}
  \frac{1}{n^\alpha} \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0) 
  & \asconv \diversity \Bigl(-\frac{1}{\alpha^2} - \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2}  \Bigr) = -\diversity \mathfrak{i}(\alpha)
\end{align*}
where the last equality follows from the formula of $\mathfrak{i}(\alpha)$ in \Cref{prop:fisher_info_sibuya}. Furthermore, with $\sum_{j=1}^n \mathsf{k}_{n,j}=\mathsf{k}_n$, $- \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)$ is dominated by $\mathsf{k}_n$ up to a constant:
$$
0 \le - \partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0) = \frac{\mathsf{k}_n-1}{\alpha^2}  + \sum_{j=1}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1}\frac{1}{(i-\alpha)^2} \le \mathsf{k}_n C,  \quad C = \frac{1}{\alpha^2} + \sum_{i=1}^\infty \frac{1}{(i-\alpha)^2}<+\infty
$$
Since $n^{-\alpha} \mathsf{k}_n$ is bounded in $L_2$ by \Cref{theorem:Lp_converge}, $n^{-\alpha} \partial_\alpha^2 \ell_n(\alpha;\delta_0)$ is also bounded in $L_2$ and hence uniformly integrable. Thus, the almost sure convergence $n^{-\alpha} \partial_\alpha \ell_n(\alpha;\delta_0)\asconv -\diversity \mathfrak{i}(\alpha)$ implies the convergence in mean:
$
n^{-\alpha} \E[\partial_{\alpha}^2 \ell_{n}(\alpha; \delta_0)] \to - \E[\diversity] \mathfrak{i}(\alpha), 
$
which completes the proof. 



\section{Asymptotic analysis of QMLE}
\subsection{Proof of \Cref{prop:mle_existence}} 
Recall the expression: 
$$\mathsf{k}_{n+1} = \mathsf{k}_n + \xi_{n+1}, \quad \xi_{n+1}|\mathcal{F}_n\sim \Bernoulli(p_n)$$ 
where 
$$
p_n = \frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}}, \quad 1-p_n = 1-\frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}} \overset{(*)}{=} (n-\mathsf{k}_n\alpha) \frac{v_{n+1, \mathsf{k}_n}}{v_{n,\mathsf{k}_n}}
$$
where we have used the recursion \eqref{eq:recursion} for $(*)$. 
Then:
  \begin{align*}
      \PP(\mathsf{k}_n=1) &= \prod_{m=1}^{n-1} (m-\alpha) \frac{v_{m+1,1}}{v_{m,1}} = \prod_{m=1}^{n-1} \int \diff \mu_{m,1}(\theta) \frac{m-\alpha}{\theta+m}\\
      \PP(\mathsf{k}_n=n) &=  \prod_{m=1}^{n-1} \frac{v_{m+1,m+1}}{v_{m,m}} = \prod_{m=1}^{n-1} \int \diff \mu_{m,m}(\theta) \frac{\theta+\alpha m}{\theta+m}
  \end{align*}
  where $\mu_{m,1}$ and $\mu_{m, m}$ are the tilted probability measure defined in \eqref{eq:tilted_measure}. Using $\operatorname{supp}(\mu_{n,k})\subset [\underline\theta, \bar\theta]$ for any $1\le k\le n$ and the fact that $\theta\mapsto \frac{m-\alpha}{\theta+m}$ is decreasing and $\theta\mapsto  \frac{\theta+\alpha m}{\theta+m}$ is increasing, we get 
  \begin{align*}
      \PP(\mathsf{k}_n=1) &\le \prod_{m=1}^{n-1} \frac{m-\alpha}{m+\underline\theta} = \frac{\Gamma(n-\alpha)}{\Gamma(1-\alpha)} \frac{\Gamma(1+\underline\theta)}{\Gamma(n+\underline{\theta})}\\
     \PP(\mathsf{k}_n=n) &\le \prod_{m=1}^{n-1}\frac{\bar\theta+m\alpha}{\bar\theta+m} = \alpha^{n-1} \frac{\Gamma(\bar\theta+1)}{\Gamma(\bar\theta+n)} \frac{\Gamma(\bar\theta/\alpha +n)}{\Gamma(\bar\theta/\alpha+1)}
  \end{align*}
  With $\Gamma(n+c)/\Gamma(n)\sim n^c$ for any $c>0$, we have
  \begin{align*}
   \frac{\Gamma(n-\alpha)}{\Gamma(n+\underline{\theta})} \sim n^{-(\alpha +\underline{\theta})}, \quad 
    \frac{\Gamma(\bar\theta/\alpha +n)}{\Gamma(\bar\theta+n)} \sim n^{\bar\theta(\alpha^{-1}-1)}. 
  \end{align*}
  Putting them all together, we obtain the desired upper bound of $\PP(\mathsf{k}_n=1)$ and $\PP(\mathsf{k}_n=n)$. 

\subsection{Consistency of QMLE}
In this section, we prove the consistency of QMLE. The proof strategy is similar to  \cite[Section C]{koriyama2022asymptotic}, which studies the QMLE for the Ewens--Pitman partition $(\mu=\delta_\theta)$. Throughout of this section, we fix $\alpha\in (0,1)$.

Let us define the deterministic function $\Psi:(0,1)\to\mathbb{R}$ as  
  \begin{align}\label{eq:psi_def}
    \Psi(x) \equiv \frac{1}{x} - \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) \sum_{i=1}^{j-1} \frac{1}{i-x}, \quad \text{where} \quad \mathfrak{p}_\alpha(j) = \frac{\alpha\prod_{i=1}^{j-1} (i-\alpha)}{j!}
  \end{align}
  \begin{lemma}[{\cite[Lemma B.3]{koriyama2022asymptotic}}]\label{lm:psi_property}
    The map 
    $\Psi:(0,1)\to\mathbb{R}$  defined in \eqref{eq:psi_def} has the following properties.  
    \begin{itemize}
      \item $\Psi:(0,1)\to\mathbb{R}$ is $C^1$. 
      \item $\Psi$ is strictly decreasing and 
      $$   
      \forall x\in (0,1), \quad 
      \Psi'(x)=-\frac{1}{x^2} - \sum_{j=2}^\infty \mathfrak{p}_\alpha(j) \sum_{i=1}^{j-1}\frac{1}{(i-x)^2}<0
      $$
      Furthermore, it holds that $\Psi'(\alpha)=-\mathfrak{i}(\alpha) < 0$, where $\mathfrak{i}(\alpha)$ is the Fisher Information of the discrete distribution $\mathfrak{p}_\alpha(j)$ defined as \eqref{eq:fisher_sibuya}. 
      \item $\Psi$ has its unique root at $x=\alpha$, i.e., $\Psi(\alpha)=0$
    \end{itemize}
  \end{lemma}

  Given a random partition $\Pi_n = (U_1, U_2, \dots U_{\mathsf{k}_n})\in \mathcal{P}_n$, define the random function $\Psi_n:(0,1)\to\mathbb{R}$ as 
  \begin{align}\label{eq:psi_n_def}
    \Psi_n(x) \equiv \frac{\mathsf{k}_n-1}{ x \mathsf{k}_n} - \sum_{j=2}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n}\sum_{i=1}^{j-1}\frac{1}{i-x}    
  \end{align}
  where $\mathsf{k}_n$ is the number of nonempty blocks and $\mathsf{k}_{n,j}=\sum_{i=1}^{\mathsf{k}_n}\mathbbm{1}\{|U_i|=j\}$ is the number of blocks of size $j$. The next lemma claims that $\Psi_n$ is strictly decreasing and converges to the deterministic map $\Psi$ in a suitable sense. 
  \begin{lemma}\label{lm:psi_n_property}
    The random function $\Psi_n$ in \eqref{eq:psi_n_def} and the deterministic function $\Psi$ \eqref{eq:psi_def} satisfy the following:
    \begin{itemize}
      \item If $n\ge 2$, with probability $1$, 
      $-\Psi_n'(x) \ge 2^{-1}$ for all $x\in (0,1)$. 
      \item $\Psi_n(x) \to^p \Psi(x)$ for each $x\in (0,1)$. 
      \item For any fixed closed interval $I\subset (0,1)$, the uniform convergence
      $\sup_{x\in I} |\Psi_n'(x) - \Psi'(x)|=o_p(1)$ holds. 
    \end{itemize}
  \end{lemma}
  \begin{proof}

  Let us show the lower bound of $\Psi_n'$. Note
  $$
     -\Psi_n'(x) = \frac{\mathsf{k}_n-1}{ x^2 \mathsf{k}_n} + \sum_{j=2}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n}\sum_{i=1}^{j-1}\frac{1}{(i-x)^2} 
  $$
  Suppose $n\ge 2$.  If $\mathsf{k}_n=1$, then we must have $\mathsf{k}_{n,j}=0$ for $j<n$ and $\mathsf{k}_{n,n}=1$. Thus, if $\mathsf{k}_n=1$, 
    $$
    \forall x\in (0,1), \quad 
      -\Psi_n'(x) = \sum_{i=1}^{n-1} \frac{1}{(i-x)^2} \ge \sum_{i=1}^{n-1} \frac{1}{i^2} \ge \frac{1}{1^2}=1
    $$
    On the other hand, if $\mathsf{k}_n\ge 2$,
    $$
    \forall x\in (0,1), \quad 
    -\Psi_n'(x) \ge \frac{\mathsf{k}_n-1}{\mathsf{k}_n} \frac{1}{x^2} \ge \frac{1}{2}\frac{1}{x^2} \ge \frac{1}{2}. 
    $$
    This completes the proof of $-\Psi_n'(x) \ge 2^{-1}$ for all $x\in(0,1)$. \\

    Next, we prove the pointwise convergence $\Psi_n(x) \to^p \Psi(x)$ for each $x\in (0,1)$. 
    Let us show for $x=\alpha$ first. By $\Psi(\alpha)=0$, it suffices to show $\Psi_n(\alpha) = o_p(1)$. By the formula of log-likelihood, 
    \begin{align*}
      \Psi_n(\alpha) = \frac{\partial_\alpha\ell_n(\alpha;\delta_0)}{\mathsf{k}_n} = \frac{\partial_\alpha \ell_n(\alpha;\mu)}{\mathsf{k}_n}  +  \frac{1}{\mathsf{k}_n}\int \dd \mu_{n,\mathsf{k}_n}(\theta)  \sum_{i=1}^{\mathsf{k}_n-1}\frac{\theta}{\alpha(\theta+i\alpha)},  
    \end{align*}
    Since the support of $\mu_{n, \mathsf{k}_n}$ is bounded, the second term is $O(\log \mathsf{k}_n/\mathsf{k}_n)$ as $\mathsf{k}_n\to+\infty$, which is $o_p(1)$ since $\mathsf{k}_n\to \infty$ (a.s.).  For the first term, the variance of $\partial_\alpha\ell_n(\alpha;\mu)$ is $O(n^\alpha)$, thereby $\partial_\alpha\ell_n(\alpha;\delta_0)=O_p(n^{\alpha/2})$. Combined with $n^{-\alpha} \mathsf{k}_n\to\diversity >0$ (a.s.), the first term is $O_p(n^{-\alpha/2})=o_p(1)$. This finishes the proof of $\Psi_n(\alpha)\to^p  \Psi(\alpha)$. For $x\ne \alpha$, by the triangle inequality, 
    \begin{align*}
      |\Psi_n(x)-\Psi(x)| \le |\Psi_n(x)-\Psi_n(\alpha)- (\Psi(x)-\Psi(\alpha))| + (\Psi_n(\alpha)-\Psi(\alpha))
    \end{align*}
    where the last term is $o_p(1)$. Note 
    \begin{align*}
      \Psi_n(x)-\Psi_n(\alpha) &= \frac{\mathsf{k}_n-1}{\mathsf{k}_n} \Bigl(\frac{1}{x}-\frac{1}{\alpha}\Bigr) - \sum_{j=2}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \sum_{i=1}^{j-1} \frac{\alpha-x}{(i-x)(i-\alpha)}\\
      \Psi(x)-\Psi(\alpha) &= \Bigl(\frac{1}{x}-\frac{1}{\alpha}\Bigr) - \sum_{j=2}^\infty \mathfrak{p}_\alpha(j) \sum_{i=1}^{j-1} \frac{\alpha-x}{(i-x)(i-\alpha)}
    \end{align*}
    and hence 
    \begin{align*}
      \Psi_n(x)-\Psi_n(\alpha)- (\Psi(x)-\Psi(\alpha)) = -\frac{1}{\mathsf{k}_n} \Bigl(\frac{1}{x}-\frac{1}{\alpha}\Bigr) + \sum_{j=2}^\infty \Bigl(\mathfrak{p}_\alpha(j)-\frac{\mathsf{k}_{n,j}}{\mathsf{k}_n}\Bigr)  \sum_{i=1}^{j-1} \frac{|\alpha-x|}{(i-x)(i-\alpha)}. 
    \end{align*}
    The first term is $o_p(1)$ by $\mathsf{k}_n\to+\infty$ and the second term is $o_p(1)$ by \Cref{lm:bounded_conv} and the fact that $j\mapsto \sum_{i=1}^{j-1} \frac{|\alpha-x|}{(i-x)(i-\alpha)}$ is bounded. 
    This completes the proof of $\Psi_n(x) \to^p \Psi(x)$ for each $x\in (0,1)$.\\

    Finally, we prove the uniform convergence $\sup_{x\in I} |\Psi_n'(x) - \Psi'(x)| =o_p(1)$. Note
    \begin{align*}
      \Psi_n'(x) = - \frac{\mathsf{k}_n-1}{ x^2 \mathsf{k}_n} - \sum_{j=2}^n \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n}\sum_{i=1}^{j-1}\frac{1}{(i-x)^2}, \quad 
      \Psi'(x) = -\frac{1}{x^2} - \sum_{j=2}^\infty \mathfrak{p}_\alpha(j) \sum_{i=1}^{j-1}\frac{1}{(i-x)^2},  
    \end{align*}
    so that 
    $$
    |\Psi_n'(x) - \Psi'(x)|\le \frac{1}{\mathsf{k}_n x^2}+ \sum_{j=2}^\infty |\frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} - \mathfrak{p}_\alpha(j)| \cdot  \sum_{i=1}^{\infty}\frac{1}{(i-x)^2}.
    $$
    Let us write $I=[a, b]$ with $0<a<b<1$. Then, we have 
    $$
    \sup_{x\in I} |\Psi_n'(x) - \Psi'(x)| \le \frac{1}{\mathsf{k}_n a^2} + \sum_{j=2}^\infty |\frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} - \mathfrak{p}_\alpha(j)| \cdot \sum_{i=1}^{\infty}\frac{1}{(i-b)^2},
    $$
    where the first term is $o_p(1)$ by $\mathsf{k}_n\to+\infty$ and the second term is $o_p(1)$ by \Cref{lm:bounded_conv}. This completes the proof of $ \sup_{x\in I} |\Psi_n'(x) - \Psi'(x)| =o_p(1)$.
  \end{proof}

  Combining \Cref{lm:psi_property} and \Cref{lm:psi_n_property}, using the standard argument (see \cite[Lemma C.3]{koriyama2022asymptotic}), we obtain the following corollary. 
  \begin{corollary}\label{cor:consistency_and_uniform_conv} 
    The QMLE and $\Psi_n$ satisfy the following:
    \begin{itemize}
      \item The QMLE is consistent, i.e., $\hat\alpha_n\to^p \alpha$
      \item For any $\mathcal{F}_n$-measurable random variable $\tilde{\alpha}_n$ satisfying  $\tilde{\alpha}_n\to^p\alpha$, we have  $\Psi_n'(\tilde{\alpha}_n)\to^p -\mathfrak{i}(\alpha)$. 
    \end{itemize}
  \end{corollary}

\subsection{Stable Martingale CLT}
Let $\ell_n(\alpha;\mu)$ be the log-likelihood of the Gibbs-partition under \Cref{assumption}, i.e, 
$$
\ell_n(\alpha; \mu) \equiv \log \Bigl(\int \dd \mu(\theta) v_{n, \mathsf{k}_n}(\alpha, \theta) \Bigr) + \sum_{j=2}^{n} \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \log(i-\alpha), \quad n\ge 1. 
$$
Notice that $\ell_{1}(\alpha;\mu)=0$ with probability $1$ since $\mathsf{k}_1 = 1$ (w.p.1) and $v_{1,1}=0$. 
Here we recall $\operatorname{supp}(\mu)\subset [\underline{\theta}, \bar{\theta}]$ with $-\alpha < \underline{\theta}\le 0 \le \bar{\theta} <+\infty$ by \Cref{assumption}. In \Cref{sec:proof_fisher}, we proved that  the derivative $\partial_\alpha$ and the integration $\int\dd \mu$ is interchangeable. Using the notation of the tilted probability measure $\mu_{n,k}$ in \eqref{eq:tilted_measure}, the score function can be written as 
\begin{align}\label{eq:score}
  \partial_\alpha \ell_n(\alpha;\mu) &= \int \dd \mu_{n, \mathsf{k}_n} (\theta) \sum_{i=1}^{\mathsf{k}_n-1} \frac{i}{\theta+i\alpha} - \sum_{j=2}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha}\nonumber \\
  & = \frac{\mathsf{k}_n-1}{\alpha}  - \int \dd \mu_{n,\mathsf{k}_n}(\theta)  \sum_{i=1}^{\mathsf{k}_n-1}\frac{\theta}{\alpha(\theta+i\alpha)}  - \sum_{j=2}^n \mathsf{k}_{n,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha}
\end{align}
where the second equality follows from $\frac{i}{\theta+i\alpha} = \frac{1}{\alpha}  - \frac{\theta}{\alpha(\theta+i\alpha)}$. The goal of this section is to show the asymptotic mixed normality of the score function:
  \begin{align*}
    \frac{\partial_\alpha \ell_n(\alpha;\mu)}{\sqrt{n^\alpha \mathfrak{i}(\alpha)}} \to \diversity^{1/2} N,  \quad \stable,
  \end{align*}
  where $\mathcal{F}_\infty = \sigma(\cup_{n=1}^\infty \mathcal{F}_n)$ and $\mathcal{F}_n=\sigma(\Pi_n)$ is the $\sigma$-field generated by the random partition $\Pi_n\in \mathcal{P}_n$ of $[n]$.
  We will prove this result by the stable Martingale CLT \cite{hausler2015stable}. 

\begin{lemma}\label{lm:martingale_diff}
   Let $\{X_{n}\}_{n=1}^\infty$ be the martingale difference of the score function, i.e., 
 $$
 X_1 \equiv \partial_{\alpha} \ell_{1} (\alpha;\mu) = 0, \quad 
  X_{m+1} \equiv \partial_{\alpha} \ell_{m+1}(\alpha; \mu) - \partial_{\alpha} \ell_{m}(\alpha; \mu), \quad m\ge 1. 
 $$
% Let $\mathcal{F}_m = \sigma(X_1, X_2, \dots, X_m)$ be the Filtration generated by $(X_m)$ and let $\mathcal{F}_\infty = \sigma(\cup_{n=1}^\infty \mathcal{F}_n)$. 
Now, we define the $\mathcal{F}_{m+1}$-measurable event $\Omega_{m+1, j}, 0\le j\le m$ as
\begin{align*}
  \forall j\in \{1, \dots m\}, \quad \Omega_{m+1,j} &= \{\text{$m+1$-th ball belongs to an existing set of size $j$}\}\\
  \Omega_{m+1, 0} &= \{\text{$m+1$-th ball belongs to a new set}\}
\end{align*}
Then, the increment $X_{m+1}$ is given by 
\begin{align*}
  X_{m+1} =\begin{cases}
    \res_{m}  -\frac{1}{j-\alpha} & \text{under $\Omega_{m+1, j}$ for $j\in \{1, \dots m\}$}\\ 
    \res'_{m} + \frac{1}{\alpha} & \text{under $\Omega_{m+1, 0}$}
  \end{cases} 
\end{align*}
where $\res_m$ and $\res_m'$ are $\mathcal{F}_m$-measurable random variable, whose absolute values are uniformly controlled as 
$$
|\res_m| + |\res_m'| \le C(\alpha,\underline\theta, \bar\theta) (\mathsf{k}_m^{-1} \log \mathsf{k}_m + m^{-1} \log m)
$$
where $C(\alpha,\underline\theta, \bar\theta)$ is a deterministic constant depending on $\alpha,\underline\theta, \bar\theta$ only.
\end{lemma}

\begin{proof}
The claim for $m=0$ is obvious so let us show for $m\ge 1$. Recall the definition of $\mathsf{k}_{m, j}$; $\mathsf{k}_{m,j}$ is the number of blocks of size $j$ given the given partition $(U_1, \dots U_{\mathsf{k}_m})$ of $[m]$, and $\mathsf{k}_m=\sum_{j=1}^m\mathsf{k}_{m,j}$ is the number of non-empty sets. Then, under $\Omega_{m+1, j}$ for $j\in\{1, \dots m\}$, $\{\mathsf{k}_{m+1,\ell}\}_{\ell=1}^{m+1}$ and $\mathsf{k}_{m+1}$ are updated as 
$$
\mathsf{k}_{m+1,\ell} = \begin{cases}
  \mathsf{k}_{m, \ell} - 1& \ell =j\\
  \mathsf{k}_{m, \ell} + 1 & \ell = j+1\\
  \mathsf{k}_{m, \ell} & \text{else}
\end{cases}, \quad \mathsf{k}_{m+1} = \mathsf{k}_m.
$$
Note $\mathsf{k}_{m, m+1}=0$ by the definition of $\mathsf{k}_{n,j}$.
Using the expression of the score function \eqref{eq:score}, the score $\partial_{\alpha}\ell_{m+1}(\alpha;\mu)$ under $\Omega_{m+1, j}$ is given by
\begin{align*}
  \partial_{\alpha} \ell_{m+1}(\alpha;\mu) &=  \frac{\mathsf{k}_{m+1}-1}{\alpha}  - \int \dd \mu_{m+1,\mathsf{k}_{m+1}}(\theta)  \sum_{i=1}^{\mathsf{k}_{m+1}-1}\frac{\theta}{\alpha(\theta+i\alpha)} - \sum_{\ell=2}^{m+1} \mathsf{k}_{m+1,\ell} \sum_{i=1}^{\ell-1} \frac{1}{i-\alpha}\\
  &= \frac{\mathsf{k}_{m}-1}{\alpha}  - \int \dd \mu_{m+1,\mathsf{k}_{m}}(\theta)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)} - \sum_{\ell=2}^{m} \mathsf{k}_{m,\ell} \sum_{i=1}^{\ell-1} \frac{1}{i-\alpha} + \sum_{i=1}^{j-1} \frac{1}{i-\alpha} -  \sum_{i=1}^{j} \frac{1}{i-\alpha} \\
  &= \frac{\mathsf{k}_{m}-1}{\alpha}  - \int \dd \mu_{m+1,\mathsf{k}_{m}}(\theta)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)}  - \sum_{\ell=2}^{m} \mathsf{k}_{m,\ell} \sum_{i=1}^{\ell-1} \frac{1}{i-\alpha} - \frac{1}{j-\alpha}\\
  &= \partial_{\alpha}\ell_m(\alpha;\mu) + \int \Bigl(\dd \mu_{m+1, \mathsf{k}_{m}} (\theta) - \dd \mu_{m, \mathsf{k}_{m}} (\theta) \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}  - \frac{1}{j-\alpha}
\end{align*}
% so that 
% $$
% X_{m+1} = - \frac{1}{j-\alpha} + \res_{1,n} 
% $$
% \begin{align*}
%   X_{m+1} &= \Bigl(\int \dd \mu_{m+1, \mathsf{k}_{m+1}} (\theta) \sum_{i=1}^{\mathsf{k}_{m+1}-1} \frac{i}{\theta+i\alpha} - \sum_{j=2}^{m+1} \mathsf{k}_{m+1,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha} \Bigr)  -  \Bigl(\int \dd \mu_{m, \mathsf{k}_m} (\theta) \sum_{i=1}^{\mathsf{k}_m-1} \frac{i}{\theta+i\alpha} - \sum_{j=2}^m \mathsf{k}_{m,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha} \Bigr) \\
%   &=  \Bigl(\int \dd \mu_{m+1, \mathsf{k}_{m}} (\theta) \sum_{i=1}^{\mathsf{k}_{m}-1} \frac{i}{\theta+i\alpha} - \sum_{j=2}^{m+1} \mathsf{k}_{m+1,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha} \Bigr)  -  \Bigl(\int \dd \mu_{m, \mathsf{k}_m} (\theta) \sum_{i=1}^{\mathsf{k}_m-1} \frac{i}{\theta+i\alpha} - \sum_{j=2}^m \mathsf{k}_{m,j} \sum_{i=1}^{j-1} \frac{1}{i-\alpha} \Bigr)
