On the other hand, under the event $\Omega_{m+1,0}$, we have 
$$
\mathsf{k}_{m+1,\ell} = \begin{cases}
  \mathsf{k}_{m, \ell} + 1 & \ell = 1\\
  \mathsf{k}_{m, \ell} & \text{else}
\end{cases}, \quad \mathsf{k}_{m+1} = \mathsf{k}_m+1.
$$
Then, the score under this event is updated as 
\begin{align*}
  \partial_{\alpha} \ell_{m+1}(\alpha;\mu)&= \frac{\mathsf{k}_{m}+1-1}{\alpha}  - \int \dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta)  \sum_{i=1}^{\mathsf{k}_{m}+1-1}\frac{\theta}{\alpha(\theta+i\alpha)} - \sum_{\ell=2}^{m} \mathsf{k}_{m,\ell} \sum_{i=1}^{\ell-1} \frac{1}{i-\alpha} \\
  &= \frac{\mathsf{k}_n}{\alpha}  - \int \dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)} - \int\dd\mu_{m+1, \mathsf{k}_m+1} (\theta) \frac{\theta}{\alpha(\theta+\mathsf{k}_m \alpha)}  - \sum_{\ell=2}^{m} \mathsf{k}_{m,\ell} \sum_{i=1}^{\ell-1} \frac{1}{i-\alpha}\\
  % &= \int \dd \mu_{m+1, \mathsf{k}_m+1} (\theta) \frac{\mathsf{k}_m}{\theta + \mathsf{k}_m \alpha} + \int \dd \mu_{m+1, \mathsf{k}_{m}+1} (\theta) \sum_{i=1}^{\mathsf{k}_{m}-1} \frac{i}{\theta+i\alpha} - \sum_{\ell=2}^{m} \mathsf{k}_{m,\ell} \sum_{i=1}^{\ell-1} \frac{1}{i-\alpha}\\
  &= \partial_{\alpha} \ell_{m} (\alpha,\mu) + \frac{1}{\alpha} - \int\dd\mu_{m+1, \mathsf{k}_m+1} (\theta) \frac{\theta}{\alpha(\theta+\mathsf{k}_m \alpha)}  - \int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m, \mathsf{k}_m} \Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)}. 
