\end{align*}
where $\res_m$ and $\res_m'$ are $\mathcal{F}_m$-measurable random variable defined as 
\begin{align*}
  \res_m &\equiv \int \Bigl(\dd \mu_{m+1, \mathsf{k}_{m}} (\theta) - \dd \mu_{m, \mathsf{k}_{m}} (\theta) \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}\\
  \res_m' &\equiv - \int\dd\mu_{m+1, \mathsf{k}_m+1} (\theta) \frac{\theta}{\alpha(\theta+\mathsf{k}_m \alpha)}  - \int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m, \mathsf{k}_m} \Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)} 
\end{align*}
