Let us derive upper bounds of $\res_m$ first. Recall the definition of the tilted measure $d\mu_{n,k}(\theta)$ for $1\le k\le n$:
\begin{align*}
    d\mu_{n,k}(\theta) \equiv \frac{\dd \mu(\theta) v_{n,k}(\alpha, \theta)}{\int \dd\mu(\theta') v_{n,k}(\alpha,\theta')} \quad \text{with} \quad v_{n,k}(\alpha;\theta) = \frac{\prod_{i=1}^{k-1} (\theta + i\alpha)}{\prod_{i=1}^{n-1}(\theta + i)}.
\end{align*}
By $v_{m+1, \mathsf{k}_m} = v_{m, \mathsf{k}_m} \frac{1}{\theta+m}$, $\res_{m}$ can be written as  
\begin{align*}
  \res_{m} &= \int \Bigl(\dd \mu_{m+1, \mathsf{k}_{m}} (\theta) - \dd \mu_{m, \mathsf{k}_{m}} (\theta) \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)} \\
  % &=  \int \Bigl( \frac{\dd \mu(\theta) v_{m+1, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m+1, \mathsf{k}_m}(\theta') } -  \frac{\dd \mu(\theta) v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta') }   \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}\\
  &= \int\dd \mu(\theta)   \Bigl( \frac{v_{m, \mathsf{k}_m}(\theta) \frac{1}{\theta+m}}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')  \frac{1}{\theta'+m}} -  \frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta') }   \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}
  % &= \int \dd \mu(\theta) \Bigl( \frac{v_{m, \mathsf{k}_m}(\theta) \frac{m}{\theta+m}}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')  \frac{m}{\theta'+m}} -  \frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta') }   \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}
  % \\
  % &= \int \dd \mu(\theta) \Bigl( \frac{v_{m, \mathsf{k}_m}(\theta) -  v_{m, \mathsf{k}_m}(\theta) \frac{\theta}{\theta+m}}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')- \int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta') \frac{\theta'}{\theta'+m} } -  \frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta') }   \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}
\end{align*}
Since $\operatorname{supp}(\mu) \subset [\underline\theta, \bar\theta]$, the following inequality holds for all $\theta\in \operatorname{supp}(\mu)$:
$$
\frac{\frac{1}{\bar\theta+m}}{\frac{1}{\underline{\theta}+m}} \cdot 
\frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')} \le 
\frac{v_{m, \mathsf{k}_m}(\theta) \frac{1}{\theta+m}}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')  \frac{1}{\theta'+m}} \le \frac{\frac{1}{\underline{\theta}+m}} {\frac{1}{\bar\theta+m}}\cdot 
\frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')}. 
$$
Using $\frac{\underline{\theta}+m}{\bar\theta+m}-1  = \frac{\underline{\theta}-\bar\theta}{\bar\theta+m}$ and 
$\frac{\bar\theta+m}{\underline{\theta}+m}-1  = \frac{\bar\theta-\underline{\theta}}{\underline\theta+m}$, 
noting that $|\frac{\bar\theta-\underline{\theta}}{\underline\theta+m}|>|\frac{\underline{\theta}-\bar\theta}{\bar\theta+m}|$ by $\bar\theta>\underline{\theta}$, we have 
\begin{align*}
  \forall \theta\in \operatorname{supp}(\mu), \quad 
  \left|\frac{v_{m, \mathsf{k}_m}(\theta) \frac{1}{\theta+m}}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')  \frac{1}{\theta'+m}}  - \frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')}\right|\le  \frac{\bar\theta-\underline{\theta}}{\underline\theta+m}\cdot 
\frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')}. 
\end{align*}
Putting them all together, we get 
\begin{align}
  \Bigl| \int \Bigl(\dd \mu_{m+1, \mathsf{k}_{m}} (\theta) - \dd \mu_{m, \mathsf{k}_{m}} (\theta) \Bigr) \sum_{i=1}^{\mathsf{k}_m-1} \frac{\theta}{\alpha(\theta+i\alpha)}\Bigr| &\le \frac{\bar\theta-\underline{\theta}}{\underline\theta+m} \int \dd\mu(\theta)
\frac{v_{m, \mathsf{k}_m}(\theta)}{\int \dd \mu (\theta') v_{m, \mathsf{k}_m}(\theta')} \Bigl|\sum_{i=1}^{\mathsf{k}_m-1}\frac{\theta}{\theta+i\alpha}\Bigr|\nonumber \\
&= \frac{\bar\theta-\underline{\theta}}{\underline\theta+m} \int \dd \mu_{m, \mathsf{k}_m}(\theta) \Bigl|\sum_{i=1}^{\mathsf{k}_m-1}\frac{\theta}{\theta+i\alpha}\Bigr|\nonumber\\
&\le \frac{\bar\theta-\underline{\theta}}{\underline\theta+m} \int \dd \mu_{m, \mathsf{k}_m}(\theta) \sum_{i=1}^{\mathsf{k}_m-1}\Bigl|\frac{\theta}{\theta+i\alpha}\Bigr|\nonumber \\
&\le \frac{\bar\theta-\underline{\theta}}{\underline\theta+m} \sum_{i=1}^{\mathsf{k}_m-1} \frac{\bar\theta-\underline{\theta}}{\alpha(\underline{\theta}+i\alpha)}\label{eq:res_m_bound}
\end{align}
where we have used $\operatorname{supp}(\mu_{m, \mathsf{k}_m}) \subset [\underline{\theta}, \bar\theta]$ for the last inequality. Thus, there exists a positive constant $C=C(\alpha,\underline\theta, \bar\theta)$ such that 
$$
|\res_{m}|\le C m^{-1} \log m.
$$
Next, we derive an upper bound of $\res_m'$. Using the tilted measure again, we can write it as 
$$
\res_{m}' = - \int\dd\mu_{m+1, \mathsf{k}_m+1} (\theta) \frac{\theta}{\alpha(\theta+\mathsf{k}_m \alpha)}  - \int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m, \mathsf{k}_m}(\theta) \Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)}. 
$$
The first term is easy to control; using $\operatorname{supp}(\mu_{m+1, \mathsf{k}_{m+1}})\subset [\underline{\theta}, \bar\theta]$, 
$$
\Bigl|\int\dd\mu_{m+1, \mathsf{k}_m+1} (\theta) \frac{\theta}{\alpha(\theta+\mathsf{k}_m \alpha)}\Bigr| \le \frac{\bar\theta-\underline{\theta}}{\alpha(\underline\theta+\mathsf{k}_m\alpha)} \le C(\alpha,\underline\theta, \bar\theta)\cdot \mathsf{k}_m^{-1}
$$
As for the second term, we decompose it into two terms:
\begin{align*}
  &\int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m, \mathsf{k}_m} (\theta)\Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)} \\
  &= \int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m+1, \mathsf{k}_m}(\theta) \Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)} + \int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}}(\theta) - \dd \mu_{m, \mathsf{k}_m}(\theta) \Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)}, 
\end{align*}
where the absolute value of the second term is bounded by $m^{-1} \log m$ up to a deterministic constant by \eqref{eq:res_m_bound}. Let us bound the first term using the same argument as \eqref{eq:res_m_bound}. By the definition of the tilted measure, using $v_{m+1, \mathsf{k}_m+1} = v_{m+1, \mathsf{k}_m} (\theta + \mathsf{k}_m\alpha)$, we have 
\begin{align*}
  &\int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m+1, \mathsf{k}_m} (\theta)\Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)} \\
  &= \int \dd\mu(\theta) \Bigl(\frac{v_{m+1, \mathsf{k}_m} (\theta) \cdot (\theta + \mathsf{k}_m\alpha ) }{\int \dd\mu(\theta') v_{m+1, \mathsf{k}_m}(\theta') \cdot (\theta' + \mathsf{k}_m\alpha ) } - \frac{v_{m+1, \mathsf{k}_m} (\theta)}{\int \dd\mu(\theta') v_{m+1, \mathsf{k}_m}(\theta') } \Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)},
\end{align*}
and for all $\theta\in \operatorname{supp}(\mu)\subset [\underline{\theta}, \bar\theta]$, 
\begin{align*}
  \frac{\underline\theta + \mathsf{k}_m\alpha }{\bar\theta + \mathsf{k}_m\alpha } \cdot \frac{v_{m+1, \mathsf{k}_m} (\theta)}{\int \dd\mu(\theta') v_{m+1, \mathsf{k}_m}(\theta')}\le  \frac{v_{m+1, \mathsf{k}_m} (\theta) \cdot (\theta + \mathsf{k}_m\alpha ) }{\int \dd\mu(\theta') v_{m+1, \mathsf{k}_m}(\theta') \cdot (\theta' + \mathsf{k}_m\alpha ) }  \le \frac{\bar\theta + \mathsf{k}_m\alpha }{\underline\theta + \mathsf{k}_m\alpha } \cdot  \frac{v_{m+1, \mathsf{k}_m} (\theta)}{\int \dd\mu(\theta') v_{m+1, \mathsf{k}_m}(\theta')}.
\end{align*}
Using $\frac{\underline\theta + \mathsf{k}_m\alpha }{\bar\theta + \mathsf{k}_m\alpha } -1 = \frac{\underline\theta-\bar\theta}{\bar\theta+\mathsf{k}_m\alpha}$ and $\frac{\bar\theta + \mathsf{k}_m\alpha }{\underline\theta + \mathsf{k}_m\alpha } -1 = \frac{\bar\theta-\underline\theta}{\underline\theta+\mathsf{k}_m\alpha}$, with $|\frac{\bar\theta-\underline\theta}{\underline\theta+\mathsf{k}_m\alpha}| > |\frac{\underline\theta-\bar\theta}{\bar\theta+\mathsf{k}_m\alpha}|$ by $\bar\theta>\underline{\theta}$, 
we have 
\begin{align*}
  \Bigl|\int \Bigl(\dd \mu_{m+1,\mathsf{k}_{m}+1}(\theta) - \dd \mu_{m+1, \mathsf{k}_m} (\theta)\Bigr)  \sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)}\Bigr| &\le \frac{\bar\theta-\underline\theta}{\underline\theta + \mathsf{k}_m\alpha }\int \dd \mu_{m+1, \mathsf{k}_m}(\theta) \Bigl|\sum_{i=1}^{\mathsf{k}_{m}-1}\frac{\theta}{\alpha(\theta+i\alpha)}\Bigr|\\
  &\le \frac{\bar\theta-\underline\theta}{\underline\theta + \mathsf{k}_m\alpha } \sum_{i=1}^{\mathsf{k}_m-1} \frac{\bar\theta-\underline{\theta}}{\alpha(\underline{\theta}+i\alpha)}
  % \\
  % &\lesssim \mathsf{k}_m^{-1} \log \mathsf{k}_m.
\end{align*}
Therefore, there exists a deterministic constant $C=C(\alpha, \underline{\theta}, \bar\theta)$ such that 
\begin{align*}
  |\res_{m}'| \le C(\alpha, \underline{\theta}, \bar\theta) (
    \mathsf{k}_m^{-1} + \mathsf{k}_m^{-1}\log \mathsf{k}_m + m^{-1}\log m)
\end{align*}
This completes the proof. 
\end{proof}
Now we derive the almost sure limit of the quadratic variation of the martingale difference $X_{m+1}$. 
\begin{lemma}\label{lm:quadratic_variation}
Let $X_{m+1}$ be the martingale difference defined in \Cref{lm:martingale_diff}.  Then, we have
  $$
  n^{-\alpha} \sum_{m=0}^{n-1} \E[X_{m+1}^2|\mathcal{F}_{m}] \to^p \mathfrak{i}(\alpha) \diversity,
  $$
  where $\diversity = \lim_{n\to+\infty} n^{-\alpha} K_n$ (a.s.) and $\mathfrak{i}(\alpha)$ is the Fisher Information of the discrete distribution $p_\alpha(j)$ given by \Cref{prop:fisher_info_sibuya}. 
\end{lemma}

