\end{align*}
where the second term is $o_{a.s.}(1)$:
\begin{align*}
\left|\bigl(\frac{1}{\alpha} + \res_{m}'\bigr)^2 \frac{m}{\mathsf{k}_m} \Bigl(\frac{v_{m+1, \mathsf{k}_{m}+1}} {v_{m, \mathsf{k}_m}} - \frac{\mathsf{k}_m}{m}\alpha \Bigr)\right| &\lesssim \bigl(\frac{1}{\alpha} + \res_{m}'\bigr)^2 \frac{m}{\mathsf{k}_m} \cdot \frac{1}{m} && \Bigl|\frac{v_{m+1, \mathsf{k}_{m}+1}} {v_{m, \mathsf{k}_m}} - \frac{\mathsf{k}_m}{m}\alpha \Bigr|\lesssim \frac{1}{m}. \\
&\asconv 0 && |\res_m'| \asconv 0, \quad \mathsf{k}_m\asconv +\infty. 
\end{align*}
Therefore, we obtain
$$
 \frac{m}{\mathsf{k}_m} \E[X_{m+1}^2|\mathcal{F}_m]  = \sum_{j=1}^{m}\Bigl(\frac{1}{(j-\alpha)}+\res_m\Bigr)^2 (j-\alpha) \frac{\mathsf{k}_{m,j}}{\mathsf{k}_m}  + \Bigl(\frac{1}{\alpha} + \res_{m}'\Bigr)^2 \alpha + o_{a.s.} (1). 
