\frac{1}{n^\alpha} \sum_{m=1}^{n-1} \alpha m^{\alpha-1}\Bigl|
  \frac{\E[X_{m+1}^2|\mathcal{F}_m]}{\alpha m^{\alpha-1}} - \mathfrak{i}(\alpha) \diversity 
\Bigr| \le \epsilon + (1+1)\epsilon = 3\epsilon
$$
Since $\epsilon$ is taken arbitrary, we get 
$$
\frac{1}{n^\alpha} \sum_{m=1}^{n-1} \alpha m^{\alpha-1}\Bigl|
  \frac{\E[X_{m+1}^2|\mathcal{F}_m]}{\alpha m^{\alpha-1}} - \mathfrak{i}(\alpha) \diversity 
\Bigr|  \asconv 0
$$
This finishes the proof.
\end{proof}


\begin{theorem}\label{thm:score_clt}
The score function has the asymptotic mixed normality:
  \begin{align*}
    \frac{\partial_\alpha \ell_n(\alpha;\mu)}{\sqrt{n^\alpha \mathfrak{i}(\alpha)}} \to \diversity^{1/2} N,  \quad \stable
  \end{align*}
\end{theorem}
\begin{proof}
  By \Cref{lm:martingale_diff} and \Cref{lm:quadratic_variation}, the martingale difference of the score function is bounded, and the limit of the quadratic variation is given by $n^{-\alpha} \sum_{m=0}^{n-1} \E[X_{m+1}^2|\mathcal{F}_{m}] \to^p \mathfrak{i}(\alpha) \diversity$. Then the claim follows from \cite[Theorem 6.23]{hausler2015stable}. 
\end{proof}


\subsection{Proof of \Cref{thm:mle_clt}}
Recall $\Psi_n(\alpha)=\mathsf{k}_n^{-1} \cdot \partial_\alpha \ell_n(\alpha;\delta_0)$.
Let us consider the event $\{1<\mathsf{k}_n<n\}$, which holds with high probability by \Cref{prop:mle_existence}. Under this event, $\hat{\alpha}_n$ satisfies 
$$
{\Psi}_n(\hat{\alpha}_n) = 0. 
$$
Furthermore, by the consistency $\hat\alpha_n\to^p\alpha$ from \Cref{cor:consistency_and_uniform_conv}, we have $\hat{\alpha}_n \in I$ for $I=[\alpha/2,  (1+\alpha)/2] \subset (0,1)$ with high probability. Then, by Taylor's expansion,  there exists a random sequence $\tilde{\alpha}_n \to^p \alpha$ such that 
\begin{align*}
  \Psi_n(\alpha) = \Psi_n(\alpha) - \Psi_n(\hat\alpha_n) = -\Psi_{n}'(\tilde{\alpha}_n) (\alpha-\hat{\alpha}_n), 
\end{align*}
and  $ -\Psi_{n}'(\tilde\alpha_n)\to^p \mathfrak{i}(\alpha)$ by \Cref{cor:consistency_and_uniform_conv}. On the other hand, by \eqref{eq:psi_n_def} and \eqref{eq:score}, the LHS can be written as 
\begin{align*}
  \Psi_n(\alpha) = \frac{1}{\mathsf{k}_n} \Bigl(\frac{\mathsf{k}_n-1}{ \alpha} - \sum_{j=2}^n {\mathsf{k}_{n,j}}\sum_{i=1}^{j-1}\frac{1}{i-\alpha}\Bigr) = \frac{1}{\mathsf{k}_n} \Bigl({\partial_\alpha \ell_n(\alpha; \mu)} + \int \dd \mu_{n,\mathsf{k}_n}(\theta)  \sum_{i=1}^{\mathsf{k}_n-1}\frac{\theta}{\alpha(\theta+i\alpha)}\Bigr), 
\end{align*}
where $\int \dd \mu_{n,\mathsf{k}_n}(\theta)  \sum_{i=1}^{\mathsf{k}_n-1}\frac{\theta}{\alpha(\theta+i\alpha)} = O(\log \mathsf{k}_n)$ by $\operatorname{supp}(\mu_{n,\mathsf{k}_n})\subset [\underline\theta, \bar\theta]$. Putting the above displays together, we obtain
\begin{align*}
  n^{\alpha/2} (-\Psi'_n(\tilde{\alpha}_n)) (\alpha-\tilde{\alpha}_n) &= n^{\alpha/2} \Psi_n(\alpha)\\
  &= \frac{n^{\alpha}}{\mathsf{k}_n} \frac{\partial_\alpha \ell_n(\alpha;\mu)}{n^{\alpha/2}} + \frac{n^{\alpha/2}}{\mathsf{k}_n} \int \dd \mu_{n,\mathsf{k}_n}(\theta)  \sum_{i=1}^{\mathsf{k}_n-1}\frac{\theta}{\alpha(\theta+i\alpha)}\\
  &= \frac{n^{\alpha}}{\mathsf{k}_n} \frac{\partial_\alpha \ell_n(\alpha;\mu)}{n^{\alpha/2}} + O(n^{\alpha/2} \mathsf{k}_n^{-1}\log \mathsf{k}_n),
\end{align*}
where $O(n^{\alpha/2} \mathsf{k}_n^{-1}\log \mathsf{k}_n)\asconv 0$ by $\mathsf{k}_n/n^\alpha \asconv \diversity>0$. Now, \Cref{theorem:Lp_converge} implies 
\begin{align*}
  \frac{\partial_\alpha \ell_n(\alpha;\mu)}{\sqrt{n^\alpha \mathfrak{i}(\alpha)}} \to \diversity^{1/2} N \quad \stable.
\end{align*}
Combined with $\mathsf{k}_n/n^\alpha \asconv \diversity$ and Slutsky's lemma for the stable convergence (see \Cref{th:CS_stable}), we obtain 
\begin{align*}
  n^{\alpha/2} (-\Psi'_n(\tilde{\alpha}_n)) (\alpha-\tilde{\alpha}_n) \to \frac{1}{\diversity} \sqrt{\diversity \cdot \mathfrak{i}(\alpha)} N =  \sqrt{\frac{\mathfrak{i}(\alpha)}{\diversity}} N \quad  \stable.
\end{align*}
Combined with $ -\Psi_{n}'(\tilde\alpha_n)\to^p \mathfrak{i}(\alpha)$, we complete the proof. 

\begin{lemma}\label{lemma:qmle_bounded_l2}
  $n^{-\alpha/2}\mathsf{k}_n|\hat\alpha_n-\alpha|$ is bounded in $\mathcal{L}_2$. 
\end{lemma}
\begin{proof}
\eqref{eq:qmle_cases} implies $\hat{\alpha}_n=0$ if $\mathsf{k}_n=1$ and $\hat{\alpha}_n=1$ if $\mathsf{k}_n=n$. Then, we can decompose the second moment $\E\bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2\bigr]$ into three terms:
  \begin{align*}
      n^{-\alpha} \E\bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2\bigr] &= n^{-\alpha}\E\Bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2 (\mathbbm{1}\{\mathsf{k}_n=1\} + \mathbbm{1}\{\mathsf{k}_n=n\}+  \mathbbm{1}\{1<\mathsf{k}_n<n\})\Bigr]\\
      &= n^{-\alpha} \alpha^2 \PP(\mathsf{k}_n=1) + 
      n^{2-\alpha} (1-\alpha)^2 \PP(\mathsf{k}_n=n) + n^{-\alpha} \E\bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2 \mathbbm{1}\{1<\mathsf{k}_n<n\}\bigr]
  \end{align*}
Here, \Cref{prop:mle_existence} implies 
\begin{align*}
\PP(\mathsf{k}_n = 1) = o(1), \quad 
\PP(\mathsf{k}_n = n) \lesssim n^{\bar{\theta}(\alpha^{-1} - 1)} \alpha^n = o(n^{\alpha-2})
\end{align*}
so that 
$$
 n^{-\alpha} \E\bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2\bigr] = n^{-\alpha} \E\bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2 \mathbbm{1}\{1<\mathsf{k}_n<n\}\bigr] + o(1). 
$$
Under the event $\{1<\mathsf{k}_n<n\}$, by the calculation right before \Cref{lemma:qmle_bounded_l2},  there exists a random sequence $\tilde{\alpha}_n\in(0,1)$ such that 
  $$
  \mathsf{k}_n (-\Psi_n'(\tilde\alpha_n)) (\alpha-\hat\alpha_n) = \partial_\alpha\ell_n(\alpha;\mu) + \int \dd \mu_{n,\mathsf{k}_n}(\theta)  \sum_{i=1}^{\mathsf{k}_n-1}\frac{\theta}{\alpha(\theta+i\alpha)}. 
  $$ 
  Here, the absolute value of the second term is bounded by $C \log n$ up to some constant $C=C(\alpha, \underline\theta, \bar\theta)$. Using the uniform lower bound $\inf_{x\in (0,1)} (-\Psi_n'(x))\ge 1/2$ from \Cref{lm:psi_n_property}, we get 
  $$
  \mathbbm{1}\{1<\mathsf{k}_n<n\} \mathsf{k}_n|\alpha-\hat\alpha_n| \le 2\bigl(|\partial_\alpha\ell_n(\alpha;\mu)| + C \log n\bigr).
  $$
  Thus, combined with $\E[\partial_\alpha\ell_n(\alpha;\mu)^2]\asymp n^{\alpha}$ from \Cref{theorem:fisher}, we obtain
  $$
  n^{-\alpha}
\E\bigl[\mathsf{k}_n^2|\hat\alpha_n-\alpha|^2 \mathbbm{1}\{1<\mathsf{k}_n<n\}\bigr] \le 8 n^{-\alpha} \Bigl(\E\bigl[
  |\partial_\alpha\ell_n(\alpha;\mu)|^2 \bigr]+ C^2 (\log n)^2\Bigr)
 = O(1). 
  $$
  This completes the proof. 
\end{proof}


\section{Limit distribution of f-Divergence}

\subsection{Proof of \Cref{theorem:tv}}
\Cref{theorem:tv} immediately follows from \Cref{thm:mle_clt}, \Cref{lemma:qmle_bounded_l2}, and the following lemma:
  \begin{lemma}\label{prop:tv_decompose}
  \begin{align*}
    \Bigl|\tv(\bm\simp_n, \bm{\hat\simp}_n) - \frac{\mathsf{k}_n}{n}|\hat\alpha_n - \alpha|\Bigr|\le  \frac{\bar{\theta}-\underline{\theta}}{n+\underline{\theta}} 
  \end{align*}
\end{lemma}
\begin{proof}[Proof of \Cref{prop:tv_decompose}]
  The TV distance can be decomposed into two terms:
$$
\tv(\bm{\hat\simp}_n, \bm\simp_n)  = \frac{1}{2}|\hat\simp_{n,0}-\simp_{n,0}| + \frac{1}{2}\sum_{i=1}^{\mathsf{k}_n} |\hat\simp_{n,i}-\simp_{n,i}|, 
$$
where
\begin{align*}
  |\simp_{n,0} - \hat\simp_{n,0}| &= \Bigl|\frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}}-\frac{\mathsf{k}_n}{n}\hat\alpha_n\Bigr| =  \Bigl|\frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}} - \frac{\mathsf{k}_n}{n}\alpha  + \frac{\mathsf{k}_n}{n}(\alpha -\hat\alpha_n)\Bigr|
\end{align*}
Combined with $|\frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}} - \frac{\mathsf{k}_n}{n}\alpha| \le \frac{\bar{\theta}-\underline\theta}{n+\underline{\theta}}$ from \Cref{lm:concentrate_v_nk}, we have 
\begin{align}\label{eq:delta_0_bound}
  \Bigl|  |\simp_{n,0} - \hat\simp_{n,0}| - \frac{\mathsf{k}_n}{n} |\alpha-\hat\alpha_n| \Bigr|\le \Bigl|\frac{v_{n+1, \mathsf{k}_{n}+1}}{v_{n, \mathsf{k}_n}} - \frac{\mathsf{k}_n}{n}\alpha\Bigr| \le \frac{\bar{\theta}-\underline\theta}{n+\underline{\theta}}. 
\end{align}
As for the second term$\sum_{i=1}^{\mathsf{k}_n} |\simp_{n,i} - \hat\simp_{n,i}|$. Note
\begin{align*}
  |\simp_{n,i} - \hat\simp_{n,i}| &=  \Bigl|
    \frac{v_{n+1, \mathsf{k}_n}}{v_{n,\mathsf{k}_n}}(|U_i|-\alpha) - \frac{|U_i|-\hat{\alpha}_n}{n}
  \Bigr| = \Bigl|\Bigl(\frac{v_{n+1, \mathsf{k}_n}}{v_{n, \mathsf{k}_n}} -\frac{1}{n}\Bigr) (|U_i|-\alpha) + \frac{\hat\alpha_n-\alpha}{n}\Bigr|.
\end{align*}
Using $|\frac{v_{n+1, K_{n}}}{v_{n, \mathsf{k}_n}} -\frac{1}{n}\alpha| \le \frac{\bar{\theta}-\underline{\theta}}{n(n+\underline{\theta})}$ from \Cref{lm:concentrate_v_nk}
\begin{align}
  \Bigl| |\simp_{n,i} - \hat\simp_{n,i}| - \frac{|\hat\alpha_n-\alpha|}{n} \Bigr|
  \le \Bigl|\frac{v_{n+1, \mathsf{k}_n}}{v_{n, \mathsf{k}_n}} -\frac{1}{n}\Bigr|(|U_i|-\alpha) \le \frac{\bar{\theta}-\underline{\theta}}{n(n+\underline{\theta})} \cdot (|U_i|-\alpha)\label{eq:delta_i_bound}
\end{align}
Therefore, we get 
\begin{align*}
  \Bigl|\sum_{i=1}^{\mathsf{k}_n} |\simp_{n,i} - \hat\simp_{n,i}| - \frac{\mathsf{k}_n}{n}|\hat\alpha_n-\alpha|\Bigr| &\le \sum_{i=1}^{\mathsf{k}_n}   \Bigl| |\simp_{n,i} - \hat\simp_{n,i}| - \frac{|\hat\alpha_n-\alpha|}{n} \Bigr|\\
  &\le \sum_{i=1}^{\mathsf{k}_n}  \frac{\bar{\theta}-\underline{\theta}}{n(n+\underline{\theta})} \cdot (|U_i|-\alpha)\\
  &= \frac{\bar{\theta}-\underline{\theta}}{n(n+\underline{\theta})} (n-\alpha \mathsf{k}_n)\\
  &\le \frac{\bar{\theta}-\underline{\theta}}{n+\underline{\theta}} 
\end{align*}
This completes the proof. 
\end{proof}


\subsection{Proof of \Cref{theorem:ratio_consistency}}
Let $C_n \equiv n \frac{v_{n+1, \mathsf{k}_n}}{v_{n, \mathsf{k}_n}}  - 1$. Note $|C_n|\le \frac{\bar{\theta}+\alpha}{n+\underline\theta}$ by \Cref{lm:concentrate_v_nk}. The ratio $\frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat \simp_{n,i}}$ can be expressed as 
\begin{align*}
  \frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat \simp_{n,i}} = n \frac{v_{n+1, \mathsf{k}_n}}{v_{n, \mathsf{k}_n}} \frac{\sum_{i\in I} (|U_i|-\alpha)}{\sum_{i\in I} (|U_i|-\hat{\alpha}_n)} = (1+C_n) \frac{\frac{1}{|I|}\sum_{i\in I}|U_i|-\alpha}{\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n}.
\end{align*}
Rearranging the above display, we get 
\begin{align*}
\Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n\Bigr)\Bigl(1-   \frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat \simp_{n,i}} \Bigr) - (\alpha-\hat{\alpha}_n)  &= \Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n\Bigr)-(1+C_n)\Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\alpha\Bigr) - (\alpha-\hat{\alpha}_n) \\
    &= - C_n\Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\alpha\Bigr)
\end{align*}
for all $I\subset \{1, \dots, \mathsf{k}_n\}$. 
Now we define the random subset $\mathcal{I}_n\subset \{1, \dots, \mathsf{k}_n\}$ as 
$$
\mathcal{I}_n = \Bigl\{I \subset  \{1, \dots \mathsf{k}_n\}, \quad \frac{1}{|I|}\sum_{i\in I}|U_i| \le N_n\Bigr\} \quad \text{with} \quad N_n=o_p(n^{1-\alpha/2}).
$$
With $|C_n|\le \frac{\bar{\theta}+\alpha}{n+\underline\theta}$,  the absolute value of the previous display is uniformly bounded as follows:
\begin{align*}
 \sup_{I\in \mathcal{I}_n} \left|\Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n\Bigr)\Bigl(1-   \frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat \simp_{n,i}} \Bigr) - (\alpha-\hat{\alpha}_n) \right| \le |C_n|  \sup_{I\in \mathcal{I}_n}  \Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\alpha\Bigr) \le \frac{\bar\theta}{\bar\theta+n} N_n
\end{align*}
Multiplying the both sides by $\sqrt{\mathsf{k}_n \mathfrak{i}(\hat{\alpha}_n)} =O_p(n^{\alpha/2})$, with  $N_n=o_p(n^{1-\alpha/2})$, we get
\begin{align*}
  \sqrt{\mathsf{k}_n \mathfrak{i}(\hat{\alpha}_n)} \cdot \sup_{I\in \mathcal{I}_n} \left|\Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n\Bigr)\Bigl(1-   \frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat \simp_{n,i}} \Bigr) - (\alpha-\hat{\alpha}_n) \right| = O_p(n^{\alpha/2}) n^{-1} o_p(n^{1-\alpha/2})=o_p(1), 
\end{align*}
and hence 
\begin{align*}
  \left| \sup_{I\in \mathcal{I}_n}\sqrt{\mathsf{k}_n \mathfrak{i}(\hat{\alpha}_n)} \Bigl(\frac{1}{|I|}\sum_{i\in I}|U_i|-\hat{\alpha}_n\Bigr)\Bigl(1-   \frac{\sum_{i\in I}\simp_{n,i}}{\sum_{i\in I}\hat \simp_{n,i}} \Bigr) -  \sqrt{\mathsf{k}_n \mathfrak{i}(\hat{\alpha}_n)} (\alpha-\hat{\alpha}_n) \right| = o_p(1).
\end{align*}
Combined with $ \sqrt{\mathsf{k}_n \mathfrak{i}(\hat{\alpha}_n)} (\alpha-\hat{\alpha}_n) \to N$ $\stable$ by \Cref{thm:mle_clt}, we complete the proof. 


\subsection{Proof of \Cref{thm:f_div}}
Let $f$ be a convex function such that it is locally twice differentiable and its second derivative is Hölder continuous at $1$. That is, there exists $\delta > 0, C > 0$, and $\beta > 0$ such that $f$ is twice differentiable on $(1 - \delta, 1 + \delta)$, and
$|f''(1 + x) - f''(1)| \le C |x|^\beta$ for all $|x| < \delta$. Now we consider the following event 
$$
\Omega_{n} \equiv \Bigl\{(2\alpha-1)\vee \frac{\alpha}{2} \le \hat\alpha_n \le \frac{\alpha+1}{2} \wedge 2\alpha \Bigr\}
$$
By the consistency $\hat\alpha_n\to^p\alpha$ and $\alpha\in (0,1)$, the event $\Omega_n$ holds with high probability. Furthermore, under $\Omega_{n}$, it can be easily checked that 
\begin{align*}
  \frac{1}{2} \le  \frac{\hat\alpha_n}{\alpha} \le 2, \quad \frac{1}{2}\le \frac{|U_i|-\hat\alpha_n}{|U_i|-\alpha} \le 2 \quad \text{for all $i\in [\mathsf{k}_n]$}. 
\end{align*}
Throughout this proof, we denote $A_n \lesssim B_n$ whenever there exists a deterministic constant $C=C(\alpha, \underline\theta, \bar\theta, f)$ such that $A_n\le C \cdot B_n$. 
Note 
\begin{align*}
  \frac{1}{\simp_{n,0}} = \frac{v_{n,\mathsf{k}_n}}{v_{n+1, \mathsf{k}_n+1}} =
   \int \diff \mu_{n+1, \mathsf{k}_n+1} (\theta)  \frac{\theta+ n}{\theta+\mathsf{k}_n\alpha}.
\end{align*}
Using $\operatorname{supp}(\mu_{n+1, \mathsf{k}_n+1})\subset [\underline{\theta}, \bar\theta]$ with $-\alpha < \underline{\theta} < \bar\theta < +\infty$, we have 
\begin{align}
  \Bigl|\frac{1}{\simp_{n,0}} - \frac{n}{\mathsf{k}_n\alpha}\Bigr| &\le \sup_{\theta\in [\underline{\theta}, \bar\theta]}\Bigl|\frac{\theta+ n}{\theta+\mathsf{k}_n\alpha} - \frac{n}{\mathsf{k}_n\alpha}\Bigr|  \lesssim \frac{n}{\mathsf{k}_n^2} 
  \label{eq:p0_1}\\
  \Bigl|\frac{\hat\simp_{n,0}}{\simp_{n,0}} - \frac{\hat\alpha_n}{\alpha}\Bigr| &\lesssim \frac{1}{\mathsf{k}_n} && \text{by $\hat\simp_{n,0}=\frac{\mathsf{k}_n\hat\alpha_n}{n}$ and \eqref{eq:p0_1}}\label{eq:p0_2}
  \\
  \Bigl|\frac{\hat\simp_{n,0}}{\simp_{n,0}} - 1\Bigr| &\lesssim \frac{1}{\mathsf{k}_n} + |\hat\alpha_n-\alpha| && \text{by \eqref{eq:p0_2}}. \label{eq:p0_3}
\end{align}
By the same argument, we have 
\begin{align*}
  \frac{1}{\simp_{n,i}} = \frac{v_{n,\mathsf{k}_n}}{v_{n+1, \mathsf{k}_n}} \frac{1}{|U_i|-\alpha} =\frac{1}{|U_i|-\alpha} \int \diff \mu_{n+1, \mathsf{k}_n}(\theta) (\theta + n),
\end{align*}
which leads to % Combined with $\operatorname{supp}(\mu_{n+1, \mathsf{k}_n+1})\subset [\underline{\theta}, \bar\theta]$ with $-\alpha < \underline{\theta} < \bar\theta < +\infty$, we have 
\begin{align}
  \Bigl|
  \frac{1}{\simp_{n,i}} - \frac{n}{|U_i|-\alpha} 
\Bigr| &\lesssim \frac{1}{|U_i|-\alpha} \label{eq:pi_1}\\
\sup_{i\in[\mathsf{k}_n]}\Bigl|\frac{\hat\simp_{n,i}}{\simp_{n,i}} -  \frac{|U_i|-\hat\alpha_n}{|U_i|-\alpha}\Bigr| &\lesssim \frac{1}{n} && \text{by \eqref{eq:pi_1}, $\hat\simp_{n,i} = \frac{|U_i|-\hat\alpha_n}{n}$, and $\frac{|U_i|-\hat\alpha_n}{|U_i|-\alpha}\le 2$ under $\Omega_{n}$}
\label{eq:pi_2}\\
  \sup_{i\in[\mathsf{k}_n]}\Bigl|\frac{\hat\simp_{n,i}}{\simp_{n,i}} - 1\Bigr| &\lesssim \frac{1}{n} + |\hat\alpha_n - \alpha| && \text{by \eqref{eq:pi_2} and $|U_i| \ge 1$} \label{eq:pi_3}
\end{align}
Combining \eqref{eq:p0_3} and \eqref{eq:pi_3}, noting $\mathsf{k}_n^{-1}=O_p(n^{-\alpha})$ and $(\hat\alpha_n-\alpha)=O_p(n^{-\alpha/2})$, we obtain
\begin{align}
\sup_{i=\in\{0, 1, \dots, \mathsf{k}_n\}}  \Bigl|\frac{\hat\simp_{n,i}}{\simp_{n,i}} - 1\Bigr| \lesssim \frac{1}{\mathsf{k}_n} + \frac{1}{n} + |\hat\alpha_n-\alpha| = O_p(n^{-\alpha/2}).\label{eq:pi_3_uniform_bound}   
\end{align}
By Taylor's theorem of $f(x)$ around $x=1$ up to the second order term, we have 
\begin{align*}
    \mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n) = \sum_{i=1}^{\mathsf{k}_n}\simp_{n,i} f(\hat\simp_{n,i}/{\simp}_{n,i}) = \sum_{i=1}^{\mathsf{k}_n}\simp_{n,i} f(1) + \simp_{n,i} f'(1)\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr) + \simp_{n,i} \frac{f''(1+c_{n,i})}{2}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2.
\end{align*}
Here $c_{n,i}$ is a random variable between $1$ and $\hat\simp_{n,i}/\simp_{n,i}$. By \eqref{eq:pi_3_uniform_bound},  $|c_{n,i}|$ is uniformly bounded as 
\begin{align}\label{eq:c_n_uniform_bound}
\sup_{i=\in\{0, 1, \dots, \mathsf{k}_n\}}  |c_{n,i}|\le \sup_{i=\in\{0, 1, \dots, \mathsf{k}_n\}}   \Bigl|\frac{\hat\simp_{n,i}}{\simp_{n,i}} - 1\Bigr| = O_p(n^{-\alpha/2})  
\end{align}
Substituting $f(1)=0$ and $\sum_{i=0}^{\mathsf{k}_n} \simp_{n,i}=\sum_{i=0}^{\mathsf{k}_n} \hat\simp_{n,i}=1$ to the previous display of $\mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n)$, we are left with
$$
\mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n) = \sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \frac{f''(1+c_{n,i})}{2}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2.
% = \frac{f''(1)}{2} \sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2  + \res_n
$$
% where $\res_n =\sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \frac{f''(1+c_{n,i})}{2}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2  -\frac{f''(1)}{2} \sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2$.
By the local Hölder continuity of $f''$ around $1$, we have $|f''(1 + x) - f''(1)| \le C |x|^\beta$ for all $|x| < \delta$ where $\delta, \beta, C$ are fixed positive constant. Then, under the event $\{\sup_{i}|c_{n,i}| \le \delta\}$, which holds with high probability by
\eqref{eq:c_n_uniform_bound}, it holds that 
\begin{align*}
\Bigl|
  \mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n) - \frac{f''(1)}{2} \sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2
\Bigr| &\le  \frac{1}{2} \sup_{i\in\{0,\dots \mathsf{k}_n\}} |f''(1+c_{n,i})-f''(1)| \cdot 
\sum_{i=0}^{\mathsf{k}_n} \simp_{n,i} \Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2\\
&\lesssim \Bigl(\sup_{i\in \{0\dots, \mathsf{k}_n\}
} |c_{n,i}|\Bigr)^\beta \sum_{i=0}^{\mathsf{k}_n}\simp_{n,i}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2\\
&= O_p(n^{-\alpha\beta/2}) \sum_{i=0}^{\mathsf{k}_n}\simp_{n,i}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2 && \text{by \eqref{eq:c_n_uniform_bound}}. 
\end{align*}
Rearranging the above display, we are left with 
$$
\mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n) = \Bigl(
\frac{f''(1)}{2} + O_p(n^{-\alpha\beta/2})
\Bigr) \sum_{i=0}^{\mathsf{k}_n}\simp_{n,i} \Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2
$$
Next, let us derive the limit of $\sum_{i=0}^{\mathsf{k}_n}\simp_{n,i}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2$. Note 
\begin{align*}
  \sum_{i=0}^{\mathsf{k}_n}\simp_{n,i}\Bigl(\frac{\hat\simp_{n,i}}{{\simp}_{n,i}}-1\Bigr)^2 = \frac{(\hat\simp_{n,0}-\simp_{n,0})^2}{\simp_{n,0}} + \sum_{i=1}^{\mathsf{k}_n}\frac{(\hat\simp_{n,i}-\simp_{n,i})^2}{\simp_{n,i}}
\end{align*}
Now we define $\Delta_{n,0}$ and $\delta_{n,0}$ as 
$$
\Delta_{n,0}\equiv \frac{\mathsf{k}_n^2}{n}\Bigl(\frac{1}{\simp_{n,0}} - \frac{n}{\mathsf{k}_n\alpha}\Bigr), \quad \delta_{n,0}\equiv n\Bigl(|\simp_{n,0} - \hat\simp_{n,0}| - \frac{\mathsf{k}_n}{n} |\alpha-\hat\alpha_n|\Bigr)
$$
so that 
$$
  \frac{(\hat\simp_{n,0}-\simp_{n,0})^2}{\simp_{n,0}} = \Bigl(\frac{n}{\mathsf{k}_n\alpha} + \frac{n}{\mathsf{k}_n^2}\Delta_{n,0}\Bigr) \cdot \Bigl(
\frac{\mathsf{k}_n}{n} |\alpha-\hat\alpha_n| + \frac{\delta_{n,0}}{n}
  \Bigr)^2
$$
Here, 
\eqref{eq:p0_1} and \eqref{eq:delta_0_bound} yield  
$|\Delta_{n,0}|  \lesssim 1$ and $|\delta_{n,0}|\lesssim 1$, and hence 
$$
\frac{(\hat\simp_{n,0}-\simp_{n,0})^2}{\simp_{n,0}}
= \Bigl(\frac{n}{\mathsf{k}_n\alpha} + O_p(n^{1-2\alpha})\Bigr) \cdot \Bigl(
\frac{\mathsf{k}_n}{n} |\alpha-\hat\alpha_n| + O_p(n^{-1})\Bigr)^2. 
$$
Expanding the square, using
$n/\mathsf{k}_n = O_p(n^{1-\alpha})$ and $\mathsf{k}_n |\alpha-\hat\alpha_n|/n = O_p(n^{\alpha-\alpha/2 - 1})= O_p(n^{\alpha/2 - 1})$, we get 
\begin{align*}
  \frac{(\hat\simp_{n,0}-\simp_{n,0})^2}{\simp_{n,0}}
&= \Bigl(\frac{n}{\mathsf{k}_n\alpha} + O_p(n^{1-2\alpha})\Bigr) \cdot \Bigl(
\frac{\mathsf{k}_n^2}{n^2} |\alpha-\hat\alpha_n|^2 + O_p(n^{\alpha/2-2})
  \Bigr)\\
    &= \frac{\mathsf{k}_n}{n\alpha} |\alpha-\hat\alpha_n|^2 + O_p(n^{1-\alpha})O_p(n^{\alpha/2-2}) + O_p(n^{1-2\alpha}) O_p(n^{\alpha-2}) + O_p(n^{1-2\alpha + \alpha/2 -2})\\
  &= \frac{\mathsf{k}_n}{n\alpha} |\alpha-\hat\alpha_n|^2 + O_p(n^{-1-\alpha/2}). 
% &= \Bigl(\frac{n}{\mathsf{k}_n\alpha} + O_p(n^{1-2\alpha})\Bigr) \cdot \Bigl(
% \frac{\mathsf{k}_n^2}{n^2} |\alpha-\hat\alpha_n|^2 + O_p(n^{-1})
%   \Bigr)  
\end{align*}

Now define $\Delta_{n,i}$ and $\delta_{n,i}$ for each $i\in [\mathsf{k}_n]$ as
\begin{align*}
  \Delta_{n,i} \equiv \frac{1}{\simp_{n,i}} - \frac{n}{|U_i|-\alpha}, \quad 
  \delta_{n,i} \equiv \frac{n^2}{|U_i|-\alpha}\Bigl(|\hat\simp_{n,i}-\simp_{n,i}| - \frac{|\hat\alpha_n-\alpha|}{n}\Bigr)
\end{align*}
so that 
\begin{align*}
\frac{(\hat\simp_{n,i}-\simp_{n,i})^2}{\simp_{n,i}} &= \Bigl(\frac{n}{|U_i|-\alpha} + \Delta_{n,i}\Bigr) \Bigl(
  \frac{|\hat\alpha_n-\alpha|}{n} + \frac{|U_i|-\alpha}{n^2}\delta_{n,i}
  \Bigr)^2\\
  &= \frac{|\hat\alpha_n-\alpha|^2}{n\alpha(|U_i|-\alpha)} + \frac{|U_i|-\alpha}{n^3}\delta_{n,i}^2 +  2  \frac{|\hat\alpha_n-\alpha|}{n^2} \delta_{n,i} + \Delta_{n,i}\Bigl(
  \frac{|\hat\alpha_n-\alpha|}{n} + \frac{|U_i|-\alpha}{n^2}\delta_{n,i}
  \Bigr)^2
\end{align*}
By \eqref{eq:pi_1} and \eqref{eq:delta_i_bound}, it holds that $\sup_{i\in [\mathsf{k}_n]}|\Delta_{n,i}|\lesssim 1$ and $\sup_{i\in [\mathsf{k}_n]}|\delta_{n,i}|\lesssim 1$. Therefore, we get 
\begin{align*}
  &\sum_{i\in [\mathsf{k}_n]} \Bigl|\frac{(\hat\simp_{n,i}-\simp_{n,i})^2}{\simp_{n,i}} - \frac{|\hat\alpha_n-\alpha|^2}{n\alpha(|U_i|-\alpha)} \Bigr| \\
  &\lesssim \sum_{i\in [\mathsf{k}_n]} \Bigl(\frac{|U_i|}{n^3} + \frac{|\hat\alpha_n-\alpha|}{n^2} + \frac{|\hat\alpha_n-\alpha|^2}{n^2} + \frac{|U_i|^2}{n^4}\Bigr)\\
  & \lesssim \sum_{i\in [\mathsf{k}_n]}  \Bigl( \frac{|U_i|}{n^3} + \frac{|\hat\alpha_n-\alpha|}{n^2}\Bigr) && \text{by $|U_i|\le n$. }\\
  &=\frac{1}{n^2} + \frac{|\hat\alpha_n-\alpha|\mathsf{k}_n}{n^2} && \text{by $\sum_i |U_i|=n$}\\
  &= O_p(n^{-2}) + O_p(n^{\alpha/2-2}) && \text{by $(\hat\alpha_n-\alpha)=O_p(n^{-\alpha/2})$ and $\mathsf{k}_n=O_p(n^\alpha)$}. 
\end{align*}
Thus, 
\begin{align*}
  \sum_{i=1}^{\mathsf{k}_n}\frac{(\hat\simp_{n,i}-\simp_{n,i})^2}{\simp_{n,i}} &= \sum_{i=1}^{\mathsf{k}_n} \frac{|\hat\alpha_n-\alpha|^2}{n\alpha(|U_i|-\alpha)} + O_p(n^{\alpha/2-2}) = \sum_{j=1}^n \mathsf{k}_{n,j} \frac{|\hat\alpha_n-\alpha|^2}{n\alpha(j-\alpha)} +  O_p(n^{\alpha/2-2})
\end{align*}
% with 
% $$
%  |\sum_{i=1}^{\mathsf{k}_n} \text{Res}_{n,i}|\le C \sum_{i=1}^{\mathsf{k}_n}  \Bigl(\frac{|U_i|}{n^3} + \frac{|\hat\alpha_n-\alpha|}{n^2}
%   \Bigr) \le C\Bigl(\frac{1}{n^2} + \frac{\mathsf{k}_n}{n^2}|\hat\alpha_n-\alpha|\Bigr) = O_p(n^{-2}) + O_p(n^{-2 + \alpha/2}). 
% $$
Combining them all together, 
\begin{align*}
\sum_{i=0}^{\mathsf{k}_n}\frac{(\hat\simp_{n,i}-\simp_{n,i})^2}{\simp_{n,i}} &= \frac{\mathsf{k}_n}{n\alpha} |\alpha-\hat\alpha_n|^2  + \sum_{j=1}^n \mathsf{k}_{n,j} \frac{|\hat\alpha_n-\alpha|^2}{n \alpha(j-\alpha)} + O_p(n^{-1-\alpha/2}) + O_p(n^{-2+\alpha/2})  \\
&= \frac{\alpha \mathsf{k}_n}{n}|\hat\alpha_n-\alpha|^2 \Bigl(
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)}
\Bigr) + O_p(n^{-1-\alpha/2}) && \text{by $\alpha\in(0,1)$}
\end{align*}
and hence 
$$
\mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n) = \Bigl(
\frac{f''(1)}{2} + O_p(n^{-\alpha\beta/2})
\Bigr) \Bigl(\frac{\alpha \mathsf{k}_n}{n}|\hat\alpha_n-\alpha|^2 \Bigl(
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)}
\Bigr) + O_p(n^{-1-\alpha/2})\Bigr)
$$
By \Cref{lm:bounded_conv} and \Cref{prop:fisher_info_sibuya}, 
$$
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)} \to^p \frac{1}{\alpha^2} + \sum_{j=1}^\infty \mathfrak{p}_\alpha(j) \frac{1}{\alpha^2(j-\alpha)} = \mathfrak{i}(\alpha)
$$
while $\sqrt{\mathsf{k}_n \mathfrak{i}(\alpha)} (\hat\alpha_n-\alpha) \to N$ $\stable$ by \Cref{thm:mle_clt}. By the continuous mapping theorem and Slutsky's lemma from \Cref{th:CS_stable}, we have 
$$
 \mathsf{k}_n|\hat\alpha_n-\alpha|^2 \Bigl(
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)}
\Bigr) \to |N|^2 \mathfrak{i}(\alpha)^{-1}  \mathfrak{i}(\alpha) = |N|^2 \quad \stable
$$
where $N\sim \mathcal{N}(0,1) \indep \mathcal{F}_\infty$.  
This in particular means that the LHS is $O_p(1)$. 
Putting the above displays together, we obtain 
\begin{align*}
n \cdot \mathsf{D}_f(\bm{\hat\simp}_n || \bm{\simp}_n) &= n\cdot \Bigl(
\frac{f''(1)}{2} + O_p(n^{-\alpha\beta/2})
\Bigr) \Bigl(\frac{\alpha \mathsf{k}_n}{n}|\hat\alpha_n-\alpha|^2 \Bigl(
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)}
\Bigr) + O_p(n^{-1-\alpha/2})\Bigr)  \\
&= \Bigl(
\frac{f''(1)}{2} + O_p(n^{-\alpha\beta/2})
\Bigr) \Bigl({\alpha \mathsf{k}_n}|\hat\alpha_n-\alpha|^2 \Bigl(
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)}
\Bigr) + O_p(n^{-\alpha/2})\Bigr) \\
&= \frac{f''(1)}{2} {\alpha \mathsf{k}_n} |\hat\alpha_n-\alpha|^2 \Bigl(
  \frac{1}{\alpha^2} + \sum_{j=1}^{n} \frac{\mathsf{k}_{n,j}}{\mathsf{k}_n} \frac{1}{\alpha^2(j-\alpha)}
\Bigr)  + O_p(n^{- \alpha\beta/2}) + O_p(n^{-\alpha/2})\\
&\to \frac{f''(1)}{2}\alpha N^2  \quad \stable,  
\end{align*}
which completes the proof. 


