\section{Spatial distribution of brightest emission lines}
\label{app:flux}
\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{test_flux_maps.pdf}
    \caption{ Maps of the flux from the four brightest emission lines in the optical measured from the MaNGA observations. From top to bottom, left to right, the \ha, \hb, \hii, and \oiii\ emission lines, respectively. The flux units are the same for all the lines: \fluxunits .}
