\section{Main Statistical Guarantees}
\label{s:Main_Results}
\vspace{-.5em}
\paragraph{Setup}
% \label{s:Main_Results__ss:Setup}
We consider the generalization capacity of foundation models with low-rank randomized factors.  We consider the (random) class $\mathcal{F}$ of functions $f:\mathbb{R}^d\to \mathbb{R}^D$ admitting the representation:
\begin{equation}
\label{eq:LoRA_intro}
\setlength{\jot}{2pt} % tighter line spacing
\begin{aligned}
        f(x)
    & \eqdef 
        (W^{(T+1)}+
        \underbrace{
            B^{(T+1)}A^{(T+1)}
        }_{\Delta W^{(T+1)}: \text{ LoRA Perturbation}}
        )x^{(T+1)} + b^{(T+1)}
\\
        x^{(t+1)}
    & \eqdef 
        \sigma\bullet 
        \big(
            (W^{(t)}+
            \underbrace{
                B^{(t)}A^{(t)}
            }_{\Delta W^{(t)}: \text{ LoRA Perturbation}}
            )x^{(t)} + b^{(t)}
        \big)
\\
    x^{(1)} & \eqdef x \in\R^d
\end{aligned}
\end{equation}
where $W^{(1)},\dots,W^{(T+1)}$ are pre-trained $d_{t+1}\times d_t$-dimensional weight matrices and $b^{(1)},\dots,b^{(T+1)}$ are pre-trained biases $d_{t+1}$-dimensional, $B^{(1)},\dots,B^{(T+1)}$ are $d_{t+1}\times r$ dimensional random (non-trainable) random LoRA factors, and $A^{(1)},\dots,A^{(T+1)}$ are $r\times d_t$ dimensions \textit{trainable LoRA factors}; here $d_1=d$, $d_2=d_3=\cdots=d_{T}=W$, and $d_{T+1}=D$ and $t=1,\dots,T$.
\vspace{-.3em}
\begin{remark}[Symmetry in Upper-Bound]
Our main upper-bound (Theorem~\ref{thrm:Main_UB}) remains valid if the $B$ factors are trainable and the $A$ factors are instead randomized, as in~\cite{zhu2024asymmetry}.  
\end{remark}
\vspace{-.3em}
We consider a $1$-Lipschitz loss function $\ell:\mathbb{R}^D\times \mathbb{R}^D\to [0,1]$ and i.i.d.\ training data $\{(X_n,Y_n)\}_{n=1}^N$ (independent of the \textit{random} LoRA factors $\{B^{(t)}\}_{t=1}^{(T+1)}$) drawn from a data-generating distribution $\mathbb{P}$ on $\mathbb{R}^d\times \mathbb{R}$.
Our objective is to compute a uniform generalization bound between the empirical risk $\mathcal{R}^N(f)$ and the true risk $\mathcal{R}(f)$ for any (random) learner $f$ in the (random) class $\mathcal{F}$; defined by
\[
        \mathcal{R}^N(f) \eqdef \frac1{N}\,\sum_{n=1}^N\, \ell(f(X_n),Y_n)
    \mbox{ and }
        \mathcal{R}(f) \eqdef \mathbb{E}_{(X,Y)\sim \mathbb{P}}\big[ \ell(f(X),Y)\big]
.
\]
We emphasize that, unlike classical learning theoretic results, our function class $\mathcal{F}$ is random.
We want to derive a high probability bound on the worst-case, uniformly over all data-generating distributions and all training algorithms mapping training data to a learner.  This randomized generalization gap is
\begin{equation}
\label{eq:rand_gen}
\smash{
        \mathbf{G}
    \eqdef
        \operatorname{sup}_{f\in \mathcal{F}}\,
            \big|
                \mathcal{R}(f)
                -
                \mathcal{R}^N(f)
            \big|
.
}
\end{equation}
We highlight that, unlike classical PAC-learning guarantees, the true risk is a random object, as it depends on the randomness in the LoRA factors, rather than being deterministic.


\vspace{-1em}
\paragraph{Preliminaries and Notation}
% \label{s:Prelims}
Before stating our main results, we must first rigorously define our randomized learners with random LoRA factors expressed in~\eqref{eq:LoRA_intro} at a high level.  
\paragraph{Parametric Perturbations of Multi-Layer Perceptrons}
Fix dimensions $d,D\in \mathbb{N}_+$, depth and a width parameters $T,W\in \mathbb{N}_+$, respectively, and an MLP $\hat{f}:\mathbb{R}^d\to \mathbb{R}^D$ with representation
\begin{equation}
\label{eq:MLP_Representation}
\begin{aligned}
        \hat{f}(x|\theta)
    & \eqdef 
        W^{(T+1)}x^{(T+1)} + b^{(T+1)}
\\
        x^{(t+1)}
    & \eqdef 
        \sigma\bullet (W^{(t)}x^{(t)} + b^{(t)}) \qquad \mbox{for } t=1,\dots,T
\\
    & x^{(1)}\eqdef x
\end{aligned}
\end{equation}
% \vspace{-.5em}
where $\theta = ((W^{(t)},b^{(t)}))_{t=1}^{(T+1)}\in \mathbb{R}^p$ where $p=(T-1)\, W(W+1) + (d+1)W + (D+1)W$, $W^{(t)}\in \mathbb{R}^{d_{t+1}\times d_t}$ and $b^{(t)}\in \mathbb{R}^{d_t}$ where $d_t=W$ if $t\in \{2,\dots,T\}$, $d_1=d$, and $d_{T+1}=D$.  
\hfill\\
\noindent 
We fix a parameter $\theta_{pre}\eqdef (W^{(t)},b^{(t)})_{t=1}^{(T+1)} \in \mathbb{R}^p$.  
We defined the \textit{perturbed representation map}
\begin{equation}
\label{eq:Perturbation_Map}
\begin{aligned}
     P_{T,W}^{\theta_{pre}}:\mathbb{R}^p& \rightarrow C([0,1]^d,\mathbb{R}^D)\\
     %%%
        \theta
    & \mapsto 
        \hat{f}(\cdot|\theta+\theta_{pre})
.
\end{aligned}
\end{equation}
\vspace{-.5em}
\paragraph{LoRAs with Random Factors}
Fix a probability space $(\Omega,\mathcal{A},\mathbb{P})$; all random quantities will be defined thereon.
Fix random matrices $A_1,\dots,A_{T+1}$ of dimensions $W\times r$ for $l\le T$ and $D\times r$ for $l=T+1$.  
% 
We fix maximum admissible LoRA weight sizes $M\ge 0$.
We then define the (random) \textbf{parameter-to-LoRA map}, which maps low-rank matrices $C_1,\dots,C_{T+1}$ and an event $\omega\in \Omega$ (random initialization of non-trainable LoRA parameters $A^{t}$) to the sequences of matrices:
\begin{equation}
\label{eq:LoRA}
\begin{aligned}
    \operatorname{LoRA}: 
        \Omega \times [-M,M]^{q} 
    & \rightarrow
        C([0,1]^d,\mathbb{R}^D)
    \\
        \big(\omega,(A^{(t)})_t\big)
    & \mapsto
        P_{T,W}^{\theta_{pre}}\big(
            (B^{(t)}(\omega)A^{(t)})_{t=1}^{(T+1)}
        \big)
    \\
    & =
        \hat{f}(\cdot| (B^{(t)}(\omega)A^{(t)})_{t=1}^{(T+1)} + \vartheta_{pre})
\end{aligned}
\end{equation}
where the effective number of trainable LoRA parameters is defined to be
\begin{equation}
\label{eq:effective_dimension_LoRA}
    q\eqdef r(W(T-1)+d+D)
    \in 
    \mathcal{O}(r)
.
\end{equation}

