            +
                \|\theta_{pre}\|_{\infty}
            \big)^{c_2T}
    \biggr\}
\end{equation}
Throughout this paper, the normed space under consideration is typically the parameter space $\R^p$, where the finite collection of model parameters is flattened and concatenated into a single vector. Unless otherwise stated, the norm used is the $\infty$-norm.
We begin with a minor extension—requiring only a brief comment—of a classical covering estimate for balls in normed spaces; see, for instance, \cite[Proposition 15.1.3]{lorentz1996constructive}. The integer $p$ denotes the total number of parameters defining the LoRA mapping.
\begin{lemma}[Covering Number Estimates - Parameter Space]
For each $\varepsilon,\rho>0$, the $\varepsilon$-covering number $\mathcal{N}(\varepsilon,\rho)$ of the closed ball $B(\rho)\subseteq (\R^p,\|\cdot\|_\infty)$ satisfies
\[
    \mathcal{N}(\varepsilon,\rho) \leq \big(\rho \, 2^{-\lfloor \log_2(\varepsilon)\rfloor}\big)^{p}.
\]
\end{lemma}
\begin{proof}
The number of cubes of side-length $2^{-\lfloor \log_2(\varepsilon/L)\rfloor}$ in $[0,\rho]^d$ is precisely $\big(\rho 2^{-\lfloor \log_2(\varepsilon/L)\rfloor}\big)^p$.
\end{proof}


\begin{lemma}[Covering Number Estimates - Function Space]
\label{lem:Mapping_Bound}
Fix $r>0$ and $p\in \mathbb{N}_+$.
% \\
Let $(\mathcal{F},\mu)$ be a metric space of functions and $P:(\mathbb{R}^p,\|\cdot\|_\infty)\to
(\mathcal{F},\mu)$ be a ``parameterization map'' with Lipschitz constant at most $L$. Let $K=P(B(\rho))\subseteq (\mathcal{F},\mu)$ be the image of the ball $B(\rho)\subset (\mathbb{R}^p,\|\cdot\|_\infty)$. Then, for every $\varepsilon>0$ the $\varepsilon$-covering number $\mathcal{N}(\varepsilon,K)$ of $K\subseteq (\mathcal{F},\mu)$ is bounded above by
\[
\mathcal{N}(\varepsilon,K)
\le 
\big(\rho\, 2^{-\lfloor \log_2(\varepsilon/L)\rfloor}\big)^{p}
\]
\end{lemma}
\begin{proof}
Let $\{v_i\}_{i=1}^N$ be an $\varepsilon/L$-covering of $B(\rho)\subset(\R^p,\|\cdot\|_\infty)$; where $N\eqdef \mathcal{N}(\varepsilon/L, \rho)$.  
For each $i=1,\dots,N$ define $f_i = P(v_i)$.
Hence for $i,j\in\{1,...,N\}$, 
\begin{equation}
\label{eq:covering_bound}
        \mu(f_i,f_j)
    \le 
        \mu(P(v_i),P(v_j))
    \le 
        L\|x_i - x_j\|_\infty
    \le 
            L\varepsilon/L
        = \varepsilon.
\end{equation}
Hence $\{f_1,...,f_N\}$ is an $\varepsilon$-covering of $K$. By Eq. ~\eqref{eq:covering_bound}, we have
\[
\mathcal{N}(\varepsilon,K) \leq N = \mathcal{N}(\varepsilon/L,\rho) \leq \big(\rho\, 2^{-\lfloor \log_2(\varepsilon/L)\rfloor}\big)^{p}.
\qedhere
\]
\end{proof}


