In what follows, we use $1_{\mathbb{R}^D}$ to denote the identity map on $\mathbb{R}^D$.
\begin{lemma}[Lipschitz Stability of Currying]
\label{lem:Lip_Loss}
Let $L_{\ell}\ge 0$ and $\ell:\mathbb{R}^D\times \mathbb{R}^D$.  Then the map 
\begin{align*}
\Lambda:
\big(C(\mathbb{R}^d,\mathbb{R}^D),\|\cdot\|_{\infty}\big)
& \rightarrow
\big(C(\mathbb{R}^d\times \mathbb{R}^D,[0,1]),\|\cdot\|_{\infty}\big)
\\
f &  \mapsto \ell\circ (f\times 1_{\mathbb{R}^D})
\end{align*}
is $L_{\ell}$-Lipschitz.
\end{lemma}
\begin{proof}
Let $x\in \mathbb{R}^d$, $y\in \mathbb{R}^D$, and $f,\tilde{f}\in C(\mathbb{R}^d,\mathbb{R}^D)$.  Then,
\allowdisplaybreaks
\begin{align*}
    \big|
            \ell\big(f(x),y\big)
        -
            \ell\big(\tilde{f}(x),y\big)
    \big|
\le &
    L_{\ell}
    \,
    \big\|
            \big(f(x),y\big)
        -
            \big(\tilde{f}(x),y\big)
    \big\|_2
\\
= &
    L_{\ell}
    \,
        \big\|(f(x)-\tilde{f}(x),y-y)\big\|_2
\\
= &
    L_{\ell}
    \,
        \sqrt{\big\|f(x)-\tilde{f}(x)\big\|^2+\|y-y\big\|_2^2}
\\
= &
    L_{\ell}
    \,
    \big\|f(x)-\tilde{f}(x)\big\|
\\
\le &
    L_{\ell}
    \,
    \sup_{x\in \mathbb{R}^d}\,
    \big\|f(x)-\tilde{f}(x)\big\|
\\
= &
    L_{\ell}
    \,
    \|f-\tilde{f}\|_{\infty}
.
\end{align*}    
Thus, for any $f,\tilde{f}\in C(\mathbb{R}^d,\mathbb{R}^D)$ we have
\[
        \big|
                \Lambda(f)
            -
                \Lambda(\tilde{f})
        \big|_{\infty}
    =
    \sup_{(x,y)\in \mathbb{R}^d\times \mathbb{R}^D}
        \big|
                \ell\big(f(x),y\big)
            -
                \ell\big(\tilde{f}(x),y\big)
        \big|
    \le
        L_{\ell}
        \,
        \|f-\tilde{f}\|_{\infty}
.
\]
Consequentially, $\Lambda$ is $L_{\ell}$-Lipschitz.
\end{proof}



\begin{lemma}[Covering Number Bounds: Random LoRA Class]
\label{lem:Covering_FunctionSpace}
Consider the setting of Lemma~\ref{lem:Lipschitz_bound_LoRA}. 
For each random initialization $\omega\in\Omega$ on the non-trainable parameters $(B^{(t)})_{t=1}^{T+1}$, define the LoRA function space $\mathcal{F}$ 
equipped with the metric induced by the uniform norm $\|\cdot\|_{\infty}$:
\[
    \mathcal{F} \eqdef \mathcal{F}(\omega,M)
    =
    \{ \text{LoRA}(\omega,(A^{(t)})_{t=1}^{T+1})\in C([0,1]^d,\R^D) : |A^{(t)}_{ij}| \leq M,\ \forall t,i,j \}.
\]
Then, for every $\epsilon,
\varepsilon>0$ the $\varepsilon$-covering number $\mathcal{N}(\varepsilon,\mathcal{F})$ of $\mathcal{F}$
satisfies
\begin{equation}
\label{eq:Prob_of_Covering}
        \mathbb{P}\Big(
            \mathcal{N}(\varepsilon,\mathcal{F})
            \leq
            \left((2R+2R_0)^{cT+1} / \varepsilon \right)^q
        \Big)
    \ge 
        \mathbb{P}(\mathcal{B}_{\epsilon})
    \ge 
        1-\epsilon
\end{equation}
where $c=c_2$, $R=M\nu\sqrt{2r\log(2W/\epsilon)}$ and $R_0=\|\theta_\text{pre}\|_\infty$ as in Lemma~\ref{lem:Bound_t:CondLipschitz}.
\hfill\\
\noindent
Moreover, when the loss function $\ell$ is $1$-Lipschitz, composing $\mathcal{F}$ with $\Lambda$ in Lemma \ref{lem:Lip_Loss} yields
\begin{equation}
\label{eq:Prob_of_Covering__fullrefined}
        \mathbb{P}\Big(
                \mathcal{N}(\varepsilon,\Lambda(\mathcal{F}))
            \leq
                \left((2R+2R_0)^{cT+1} / \varepsilon \right)^q
        \Big)
    \ge 
        \mathbb{P}(\mathcal{B}_{\epsilon})
    \ge 
        1-\epsilon
\end{equation}
\end{lemma}
\begin{proof}
This is a direct consequence of Lemmata Lemmata~\ref{lem:Lipschitz_bound_LoRA} and~\ref{lem:Mapping_Bound}: with probability at least $1-\epsilon$, we have
\begin{align*}
    \mathcal{N}(\varepsilon,\mathcal{F})
    &\leq
    \left(R\cdot 2^{-\lfloor \log_2(\varepsilon/L_\text{LoRA}^{\theta_\text{pre}}) \rfloor}\right)^q\\
    &\leq
    \left(2R\cdot L_\text{LoRA}^{\theta_\text{pre}} / \varepsilon \right)^q\\
    &\leq 
    \left(2R\cdot (2R+2R_0)^{cT} / \varepsilon \right)^q\\
    &\leq 
    \left((2R+2R_0)^{cT+1} / \varepsilon \right)^q
.
\qedhere
\end{align*}
\end{proof}


\subsubsection{Step 3 - Generalization Bounds Conditioned on Covering Number Bounds}
%\label{s:Proof_Main_UB__ss:Proof___sss:CoveringNumberBound}

Next, we control the randomized generalization gap $\mathbf{G}$, as defined in~\eqref{eq:rand_gen}, conditioned on the event $\mathcal{B}_{\epsilon}$, as defined in~\eqref{eq:conditional_control__LipschitzConstant}.  Upon conditioning on the right realizations, which happen with high probability, our covering number bounds give us access to the Dudley's integral estimate; see e.g.~\citep[Corollary 2.2.8]{varderVaartWellner_EmpiricalProcessesBook_1996}.


\begin{lemma}[Conditional Generalization Bounds for ``Derandomized'' LoRAs]
\label{lem:Bound_t:CondLipschitz}
Consider the setting of Lemma~\ref{lem:Lipschitz_bound_LoRA}.  Let  $G
    \eqdef
    \sup_{f\in \mathcal{F}}\,
        \big|
            \mathcal{R}(f)
            -
            \mathcal{R}^N(f)
        \big|$
be the generalization error. The following holds
\begin{equation}
\label{eq:generalization_conditional__GoodCovering}
    \mathbb{P}\biggl(
                \mathbf{G} 
            \leq 
                4\min \left\{  1, 
            \sqrt{\rho}
            \frac{6\sqrt{A}}{\sqrt{N}}  \right\} + \sqrt{\frac{8\log (2/\epsilon)}{N}}
    \Big|
        \,
        \mathcal{B}_{\epsilon}
    \biggr)
\ge 
    1-\epsilon
\end{equation}
where $A=(cT+1)\log(2R+2R_0)$, $R=M\nu\sqrt{2r\log(2W/\epsilon)}$ and $R_0=\|\theta_\text{pre}\|_\infty$ and $\rho\eqdef \rho(q,N)\eqdef q$.
\end{lemma}
\begin{proof}

Let $\hat{\mathrm{R}}(\Lambda\circ \mathcal{F})$ denote the \textit{empirical Rademacher complexity}, computed from the $N$ samples $\{(X_n,Y_n)\}_{n=1}^N$ for the class $\Lambda\circ \mathcal{F}\eqdef \{\ell\circ (f\times 1_{\mathbb{R}^D}:\, f\in \mathcal{F}\}$.
%%
By~\cite[Theorem 8]{bartlett2002rademacher}, for every $\epsilon\in (0,1]$, the following holds with probability at-least $1-\epsilon$
\begin{equation}
\label{eq:Rademacher_Bound}
    \mathbf{G}
\le 
    \underbrace{
        2\,\hat{\mathrm{R}}(\Lambda\circ \mathcal{F})
    }_{\term{t:ERC}}
    +
    \sqrt{\frac{
        8\log(2/\epsilon)
    }{
        N
    }}.
\end{equation}

