\]
where $c^{\star}:=\sup_{f\in \mathcal{F}}\, \frac1{m}\,(\sum_{i=1}^m\,(\Lambda\circ f)^2(z_i))^{1/2}$. Note that the loss $\ell$ takes value between $[0,1]$, hence $c^*\leq 1$ and we have:
\begin{equation} \label{eq:rademacher}
    \hat{\mathrm{R}}(\Lambda\circ \mathcal{F})
     \le        
    \inf_{t\in [0,1/2]}\, 
        4t
        \,
    + 
        \frac{12}{\sqrt{N}}
            \int_t^{1/2} 
                \sqrt{\log\mathcal{N}(\varepsilon,\Lambda\circ\mathcal{F})}
                \,
            d\varepsilon.
\end{equation}
Conditioned on the event $\mathcal{B}_{\epsilon}$, we have
% Note that with probability at least $1-\epsilon$,
\[
    \sqrt{\log\mathcal{N}(\varepsilon,\Lambda\circ\mathcal{F})}
    \leq 
    \sqrt{\log\left((2R+2R_0)^{cT+1} / \varepsilon \right)^q}
    \leq 
    \sqrt{q(A+\log\varepsilon^{-1})}.
\]
where we denote $A = {(cT+1)\log(2R+2R_0)}$.
To bound the RHS of Eq. (\ref{eq:rademacher}), We will find the optimum $t^*\in[0,1/2]$ of the function $g(t)= 4t + \frac{12}{\sqrt{N}} \int_t^{1/2} \sqrt{q(A+\log\varepsilon^{-1})} \,d\varepsilon.$ By first order optimality condition:
\begin{align*}
    g'(t) &= 0\\
    4 - \frac{12}{\sqrt{N}}\sqrt{q(A+\log t^{-1})} &= 0\\
    t &= \exp \left( A - \frac{N}{9q} \right)
\end{align*}
If $N^2\gg q$, then $t^*\approx 0$. In such case, we have
\begin{align*}
    \hat{\mathrm{R}}(\Lambda\circ \mathcal{F})
    &\leq
    \frac{12}{\sqrt{N}} \int_0^{1/2} \sqrt{q(A+\log\varepsilon^{-1})}\, d\varepsilon\\
    &\leq
    \frac{12}{\sqrt{N}} \sqrt{\int_0^{1/2} q(A+\log\varepsilon^{-1})\, d\varepsilon}\\
    &=
    \frac{12}{\sqrt{N}} \sqrt{\frac{q}{2}(A+\log 2 +1)}\\
    &\leq
    \frac{12}{\sqrt{N}} \sqrt{qA}.
\end{align*}
If $N^2\ll q$, then $t^*\approx 1/2$. In such case, we have $\hat{\mathrm{R}}(\Lambda\circ \mathcal{F}) \leq 2$.
In any case, we have 
\[
\hat{\mathrm{R}}(\Lambda\circ \mathcal{F}) \leq \min \left\{  2, \frac{12\sqrt{qA}}{\sqrt{N}}  \right\}.
\]
Plug in the above result to Eq. (\ref{eq:Rademacher_Bound}) the following holds with conditional probability, conditioned on $\mathcal{B}_{\epsilon}$, at least $1-2\epsilon$, over the random draw of $\{(X_n,Y_n)\}_{n=1}^N$ the randomized generalization error is bounded by:
\[
        \mathbf{G} 
    \leq
        4\min \left\{  1, \frac{6\sqrt{qA}}{\sqrt{N}}  \right\} + \sqrt{\frac{8\log (2/\epsilon)}{N}}
    =
        4\min \left\{  1, 
    \sqrt{\rho}
    \frac{6\sqrt{A}}{\sqrt{N}}  \right\} + \sqrt{\frac{8\log (2/\epsilon)}{N}}
\]
where $A=(cT+1)\log(2R+2R_0)$, $R=M\nu\sqrt{2r\log(2W/\epsilon)}$, $R_0=\|\theta_\text{pre}\|_\infty$, and we recall that $\rho\eqdef q$.
\end{proof}

\subsubsection{Step 4 - Generalization Bounds Conditioned on Covering Number Bounds}
\label{s:Proof_Main_UB__ss:Proof___sss:PuttingTogether}

We are now ready to deduce our main theorem.

\begin{proof}[{Proof of Theorem~\ref{thrm:Main_UB}}]
Let $\epsilon\in (0,1]$ be given; to be determined retroactively.  
