.
\]  Then, the following holds
\allowdisplaybreaks
\begin{align*}
     \mathbb{P}\big(
            \mathbf{G}
        \le 
            G^{\star}
     \big)
= &  
    \mathbb{P}\big(
            \mathbf{G}
        \le 
            G^{\star}
        \big|
            \mathcal{B}_{\epsilon}
