Suppose also that $\sigma=\operatorname{ReLU}$, (for simplicity) $b^{(1)}=0$ for each $t=1,\dots,T+1$ (where we write $0$ for the appropriate-dimensional zero vector), and let $\ell(\hat{y},y)\eqdef |\hat{y}-y|$.
\hfill\\
\noindent\textbf{Step 1 - The MLP Construction:}
\hfill\\
For each $t=1,\dots,T+1$ suppose that $d_{t+1} \ge d_t$ let $\bar{I}_{d_{t+1},d_t}\eqdef I_{d_t}\oplus \mathbf{0}_{d_{t+1}-d_t}$ denote the direct-sum of the $d_t\times d_t$ identity matrix $I_{d+t}$ and the $(d_{t+1}-d_t)\times (d_{t+1}-d_t)$ zero matrix $\mathbf{0}_{d_{t+1}-d_t}$ if $d_{t+1}>d_t$ and $\bar{I}_{d_{t+1},d_t}\eqdef I_{d_t}$ if $d_{t+1}=d_t$.  
% 
For each $t=1,\dots,T+1$ define $A^{(t)}$ 
% ``$\omega$-wise'' as
\begin{equation}
\label{eq:lower_bound_weighting}
