        ((W^{(1)}+B^{(1)}A^{(1)})x^{(1)} + b^{(0)}) 
\\
    & =
        (W^{(1)}+B^{(1)}A^{(1)})x^{(1)} 
\\
    & = 
        \big(W^{(1)} + 
        B^{(1)}
        {B^{(1)}}^{\dagger}\,(\bar{I}_{d_{t+1},d_t} - W^{(1)})\big) x^{(1)}
