\section{Standard Rademacher Bounds}
\label{a:Rademchar}
This appendix presents a specific formulation of standard generalization bounds based on the empirical \textit{Rademacher} complexity of a hypothesis class, which, despite being folklore, we were (surprisingly) unable to locate in the literature. 
Given $S = \{x_1, \ldots, x_m\}$, we consider the metric space $(\mathcal{R}_S, L_S^2)$, where the metric $L_S^2$ is defined as
\[
L_S^2(f, g) := \sqrt{\frac{1}{m} \sum_{i=1}^m (f(x_i) - g(x_i))^2}
\]
for all $f, g \in \mathcal{R}_S$.

\begin{theorem}
Consider any function class $\mathcal{F}$ containing functions $f : \R^n \to \R$. 
Let $h$ be the zero function such that $h(x) = 0$ for all $x \in S$. Suppose $B := \sup_{f \in C} L_S^2(f, h)$.
Let $\hat{R}_n(\mathcal{F})$ be the empirical Rademacher complexity of function class $\mathcal{F}$. Then
\begin{equation}
\hat{R}_n(\mathcal{F}) \leq \inf_{\epsilon \geq 0} \left \{ 4 \epsilon + 12 \int_\epsilon^{B} \sqrt{\frac{\log \cN(\tau)}{n}} d\tau \right \}
\end{equation}

Alternatively,
\[
\hat{R}_n(\mathcal{F}) \leq 12 \int_0^B \sqrt{\frac{\log \cN(C, L_S^2, \epsilon)}{n}} \, d\varepsilon.
\]

\end{theorem}
\begin{proof}

Let $k$ be a positive integer. For all $0 \leq j \leq k$, define $\epsilon_j := B \cdot 2^{-j}$ and let $T_j$ be a minimum $\epsilon_j$-cover of $(\cF, L_S^2)$. It follows that $|T_j| = \cN(\cF, L_S^2, \epsilon_j)$. We let $T_0 := \{h\}$ since $L_S^2(f, h) \leq B = \epsilon_0$ for all $f \in \cF$. Note that $\cN(\cF, L_S^2, \epsilon)$ is non-increasing with respect to $\epsilon$, hence $|T_{j-1}| = \cN(\cF, L_S^2,\epsilon_{j-1}) \leq \cN(\cF, L_S^2,\epsilon_j) = |T_j|$ for $0 < j \leq k$. Without loss of generality, we assume $T_k$ is a finite set (and hence all $T_j$'s are finite sets), since otherwise $\cN(\cF, L_S^2,\epsilon)$ is unbounded for $0 \leq \epsilon \leq \epsilon_k$, in which case the integral is also unbounded and the inequality is trivially true.

For each $f \in \cF$ and $0 \leq j \leq k$, let $f_j \in T_j$ be a function such that $f_j$ covers $f$ in $T_j$, that is, $L_S^2(f, f_j) \leq \epsilon_j$. Then we can represent each $f$ by
\[
f = f - f_k + \sum_{j=1}^k (f_j - f_{j-1}),
\]
where $f_0 = h$. Then we have
\[
\hat{R}_S(\cF) = \E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sum_{i=1}^m \sigma_i \left( f(x_i) - f_k(x_i) + \sum_{j=1}^k (f_j(x_i) - f_{j-1}(x_i)) \right) \right].
\]
Applying the triangle inequality, we obtain
\[
\hat{R}_S(\cF) \leq \E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sum_{i=1}^m \sigma_i (f(x_i) - f_k(x_i)) \right] + \sum_{j=1}^k \E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sum_{i=1}^m \sigma_i (f_j(x_i) - f_{j-1}(x_i)) \right].
\]
We consider the first and second terms in the last expression separately. For the first term, recall that the $\sigma_i$’s are random variables taken from $\{-1, +1\}$. Applying the Cauchy-Schwarz inequality, we obtain
\[
\E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sum_{i=1}^m \sigma_i (f(x_i) - f_k(x_i)) \right] \leq \E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sqrt{\sum_{i=1}^m \sigma_i^2 \sum_{i=1}^m (f(x_i) - f_k(x_i))^2} \right].
\]
Since $\sigma_i$ are independent random variables with variance 1, we can simplify this to
\[
\leq \E_\sigma \left[ \sup_{f \in \cF} \sqrt{\frac{1}{m} \sum_{i=1}^m (f(x_i) - f_k(x_i))^2} \right] = \E_\sigma \left[ \sup_{f \in \cF} L_S^2(f, f_k) \right] \leq \epsilon_k.
\]

Now, we consider the second term $\sum_{j=1}^k \E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sum_{i=1}^m \sigma_i (f_j(x_i) - f_{j-1}(x_i)) \right]$. We fix $j$, and define $g_f := f_j - f_{j-1}$. That is, we define a new function $g_f$ for each $f \in \cF$. Let $G \eqdef \{g_f : f \in \cF\}$ be the collection of $g$ functions. It follows that
\[
\E_\sigma \left[ \sup_{f \in \cF} \frac{1}{m} \sum_{i=1}^m \sigma_i (f_j(x_i) - f_{j-1}(x_i)) \right] = \E_\sigma \left[ \sup_{g \in G} \frac{1}{m} \sum_{i=1}^m \sigma_i g(x_i) \right].
\]
Since $f_j \in T_j$ and $f_{j-1} \in T_{j-1}$, we have $|G| \leq |T_j| |T_{j-1}| \leq |T_j|^2$. Since $T_j$ is finite, the set $G$ is also finite. Also, for each $g = g_f \in G$, we have
\[
\sqrt{\sum_{i=1}^m g_f(x_i)^2} = L_S^2(f_j, f_{j-1}) \sqrt{m} \leq (L_S^2(f, f_j) + L_S^2(f, f_{j-1})) \sqrt{m} \leq (3 \epsilon_j) \sqrt{m}.
\]
Thus, $\sup_{g \in G} \sqrt{\sum_{i=1}^m g(x_i)^2} \leq 3 \epsilon_j \sqrt{m}$. Applying Massart’s Lemma to the functions $G$, we obtain
\[
\E_\sigma \left[ \sup_{g \in G} \frac{1}{m} \sum_{i=1}^m \sigma_i g(x_i) \right] \leq 3 \epsilon_j \sqrt{\frac{2 \ln |G|}{m}} \leq 6 \epsilon_j \sqrt{\frac{\ln |T_j|}{m}}.
\]

Combining all inequalities, we get
\[
\hat{R}_S(\cF) \leq \epsilon_k + 6 \sum_{j=1}^k \epsilon_j \sqrt{\frac{\ln |T_j|}{m}}.
\]
Taking the limit as $k \to \infty$, and using the fact that $\cN(\cF, L_S^2,\epsilon) \geq \cN(\cF, L_S^2,\epsilon_j)$ for all $\epsilon_{j+1} \leq \epsilon \leq \epsilon_j$, we arrive at
\[
\hat{R}_S(\cF) \leq 12 \int_0^B \sqrt{\frac{\ln \cN(\cF, L_S^2,\epsilon)}{m}} \, d\epsilon.
\]
\end{proof}

