\title{The Overview of Segmental Durations Modification Algorithms on Speech Signal Characteristics}

\author{
    \IEEEauthorblockN{Kyeomeun Jang, Jiaying Li, Yinuo Wang}
\thanks{All the authors are co-authors of this work with School of Electrical and Computer Engineering, Georgia Institute of Technology, Atlanta, GA 30332, USA.}.% <-this % stops a space
