We begin the classification by studying ideals of {\em toric type}, denoted by $\cI_{g}$, which are generated by relations of the form
\bea
\label{toric_ideal}
g_{ij} = s_j s_i - \omega_{ij} s_i s_j, \quad \omega_{ji} = \omega_{ij}^{-1},
\eea
and are {\em  $\Phi$-stable}, that is, invariant under the automorphisms $\Phi_{i,j,k}$ for all $(i,j,k) \in S$.

Note that $\cI_{g}$ automatically satisfies the PBW condition; thus, we only need to verify its stability.
Theorem~\ref{thm-2-1} implies that several of the parameters must coincide:
\begin{equation}
\label{toric_cond}
 \begin{array}{ll}
\Phi_{132}:\ \ \omega_1 := \omega_{12} = \omega_{13} = \omega_{32}, \qquad & \Phi_{165}:\ \ \omega_2 := \omega_{15} = \omega_{16} = \omega_{65},\\
\Phi_{364}:\ \  \omega_3 := \omega_{34} = \omega_{36} = \omega_{64}, \qquad & \Phi_{254}:\ \ \omega_4 := \omega_{24} = \omega_{25} = \omega_{54}.
 \end{array}
\end{equation}
We introduce the shorthand notation $\omega_1, \ldots, \omega_4$ for simplicity. These parameters correspond to the automorphisms $\Phi_{i,j,k},\ (i,j,k) \in S$. The remaining parameters $\omega_{14}, \omega_{26}, \omega_{35}$ correspond to index pairs that do not simultaneously appear in any triple from $S$.

\begin{lemma}
\label{lem_toric_ideal}
A  $\Phi$-stable ideal of the form \eqref{toric_ideal} is uniquely determined by four parameters $\omega_1, \omega_2, \omega_3, \omega_4$ satisfying the relation
\bea\label{om14}
\omega_1 \omega_3 = \omega_2 \omega_4.
\eea
In this case, the parameters associated with the triplets in the tetrahedron equation are determined by the values of $\omega_i$ as specified in   \eqref{toric_cond}, while the remaining parameters are given by:
\bea\label{toric_cond2}
\omega_{14} = \omega_2 / \omega_1, \qquad \omega_{26} = \omega_3 / \omega_2, \qquad \omega_{35} = \omega_2 \omega_4.
\eea
\end{lemma}
\begin{proof}
Let $(i,j,k) \in S$ be any admissible triple, and let $r\notin \{i,j,k\}.$
%Введем также обозначения для генераторов идеала
%\bea
%g_{ij}=s_j s_i-\omega_{ij} s_i s_j.\nn
%\eea
We apply $\Phi_{ijk}$ to the generators of the ideal \eqref{toric_ideal}:
\bea
\Phi_{ijk}(g_{jr})&=&(\omega_{ir}\omega_{kr}-\omega_{jr})s_i s_k s_r{\color{blue}+g_{jr}+g_{ir}s_k+\omega_{ir}s_i g_{kr};}\nn\\
\Phi_{ijk}(g_{ij})&=&(\omega_{ik}-\omega_{ij})s_i^2 s_k{\color{blue}+g_{ij}+s_i g_{ik};}\nn\\
\Phi_{ijk}(g_{kj})&=&s_i s_k^2(1-\omega_{kj} \omega_{ik}){\color{blue}+g_{kj}-\omega_{kj} g_{ik} s_k;}
\label{phi_toric}
\eea
(the terms from the ideal are marked in blue).
Using the PBW property of this ideal, we obtain, in addition to the conditions formulated in Theorem \ref{thm-2-1}, the following set of equations:
\[
\begin{array}{llll}
\omega _{12} \omega _{14}=\omega _{15}, &\omega _{13} \omega _{14}=\omega _{16}, & \omega _{24}=\omega _{26}\omega _{32},&
\omega _{25}=\omega _{12} \omega _{26},\\
\omega _{14} \omega _{24}=\omega _{34},&
\omega _{15} \omega _{25}=\omega _{35}, &\omega _{34}\omega _{32}= \omega _{35}, &
\omega _{16} \omega _{26}=\omega _{36}, \\
\omega _{35}=\omega _{13} \omega _{36}, &\omega _{64}=\omega _{1,4} \omega _{54},&
\omega _{26} \omega _{65}=\omega _{64}, &\omega _{54} \omega _{65}=\omega _{35} .
\end{array}
\]
These 12 equations can be written uniformly as
\[
 \omega_{ni}\omega_{nk}=\omega_{nj},\qquad (i,j,k)\in S,\ \ n\not \in (i,j,k),
\]
and represented by the diagram in the figure


