\bea
\omega_1 \omega_3=\omega_2 \omega_4.\nn
\eea
\end{proof}
Further on we will refer to invariant toric ideal as $I_0$ given by parameters $\omega_1, \omega_2, \omega_3, \omega_4$ subject to the relation $\omega_1 \omega_3 = \omega_2 \omega_4$.

We call a homogeneous quadratic ideal $\cI \subset \cA$ triangular if it is generated by polynomials of the form
\begin{equation}\label{ideal_type} 
f_{ij} := g_{ij} - d_{ij}; 1 \leqslant i < j \leqslant 6,
\end{equation}
where
\[
g_{ij}  = s_j s_i - \omega_{ij} s_i s_j, \qquad  
d_{ij}  = \sum\limits_{(k, l) < (i, j),\, k\leqslant l} \delta_{ijkl} s_k s_l.
\]
Here, $(k, l) < (i, j)$ denotes comparison in the right lexicographic order. This means that all monomials appearing in the quadratic polynomial $d_{ij}$ are standard, and that $\lm(d_{ij}) \prec s_i s_j$.

The toric component of an arbitrary triangular $\Phi$-stable ideal satisfy the same equations as listed in Lemma \ref{lem_toric_ideal}.
\begin{lemma}\label{lem_triangle}
Let a triangular ideal $\cI$ be $\Phi$-stable and  PBW, then parameters $\omega_{ij}$ satisfy the relations (\ref{toric_cond}), (\ref{toric_cond2}) and (\ref{om14}).
\end{lemma}

\begin{proof}
