\mathcal{P}_3(\Phi_{ijk}(g_{ij}))\in\C\pi_0(s_i^2 s_k);\qquad \mathcal{P}_3(\Phi_{ijk}(g_{jr}))\in\C\pi_0(s_i s_k s_r);\qquad \mathcal{P}_3(\Phi_{ijk}(g_{kj}))\in\C\pi_0(s_i s_k^2).\nn
