\subsection{Notations}
%
Let \( M \) denote the number of participants and \( K \) the total number of cyber attack classes.
%
Each participant $i$ owns data $D_i$; $d_i\subseteq D_i$ is a batch. For any class $j$, $N_{i,j}$ designates the number of samples of that class on participant $i$, and $N_i = \sum_{j=1}^{K}N_{i,j}$ the total number of samples on that participant.  %
%
Let $f_{\omega}(x)\rightarrow{y}$ be the locally trained detection model with $\omega$ the parameters of $f$. 
We denote $x$ and $y$ as the features of a cyber attack and the corresponding predicted attack type, respectively. 
To clarify, we further decompose the detection model as $y = f_{\omega}(x) = c(\phi(x))$, 
where $c$ and $\phi$ are the classification head and embedding layers of the detection model, respectively. 
For instance, for a ten-layered convolutional neural network (CNN), we use the first eight layers as the embedding function and the remaining two layers as the classification head. 
An input $x$ is first fed into the embedding function, then the classification head $c$ is applied to the generated embedding $\phi(x)$ to produce the attack type prediction. 
At round $t$, the model parameters trained by participant $i$ are denoted as $\omega^{t}_i$.
The logit output on $x_i$ from the locally trained detection model with respect to class $j$ is denoted as $p_{i,j} = f(\omega^{t}_i; x_i)$. 
Each participant also builds a local prototype $C_{i,j}^{t}$ for every class $j$ by averaging the embeddings of its class $j$ samples; the server aggregates those local prototypes into the global prototype $\bar{C}_j^{t}$. The dimensionality of a prototype is denoted as \( d \), and the number of model parameters as \( m \).
Let $L_S$ denote the cross-entropy loss, $L_R$ the prototype alignment loss. $\lambda$ and $\mu$ are hyperparameter scalars to balance the loss terms in the optimization objective.


\subsection{Description of PROTEAN} 
The workflow of PROTEAN is outlined in Algorithm \ref{alg: fedproto_modified} and illustrated in Figure~\ref{fig:fedproto}. 
Its training process is established based on the FL protocol. 
Each participant trains the parameters $\omega$ of the detection model locally using privately owned training samples. 
Simultaneously, each participant $i$ also generates the class prototype vector $C_{i,j}$, 
%
as given in Equation~\ref{eq:protovec}: %
\begin{equation}\label{eq:protovec}
\small
C_{i,j} = \frac{1}{N_{i,j}} \sum_{x_{i,j} \in \text{class}\,\,\,{j}}\phi(x_{i,j})
\end{equation}
%
These locally computed class prototypes encapsulate the essential characteristics of each attack type observed by the participant, with one prototype vector per attack type. 
At each federated training round, each participant transmits the locally generated class prototypes $\{C_{i,j}\}$, as well as the parameters $\omega$ of the local detection model, to a central server. 


\begin{algorithm}[t]
\caption{PROTEAN}
\small
    \label{alg: fedproto_modified}
\begin{algorithmic}[1]
        \State \textbf{Input:} $D_i, \omega_i, i = 1, \dots, M$
        \State Initialize the global prototypes $\{ \bar{C}^{0}_{j} \}, j = 1, \dots, K$ for all $K$ classes
        \State \textbf{Server executes:}
        \For{each round $t = 1, 2, \dots$}
            \For{each participant $i$ in parallel}
                \State $\{C^{t}_{i,j}\}, \omega^{t}_i \leftarrow \text{LocalUpdate}(i, \bar{C}^{t-1}_{j}, \omega^{t-1})$
            \EndFor
            \State Aggregate the local model parameters $\omega^{t}$ on the central server (Equation~\ref{eq: proto_agreg})
            \State Update the global prototypes by aggregating the local prototypes $\{C^{t}_{i,j}\}$ (Equation~\ref{eq: proto_agreg})
            \State Share back the global prototypes $\{ \bar{C}^{t}_{j} \}$ and the global model parameters $\omega^{t}$ to local clients
        \EndFor
        %
        \State \textbf{Function LocalUpdate($i, \bar{C}^{t-1}_i, \omega^{t-1}$)}
        \For{each local epoch}
            \For{each batch $(x_i, y_i) \in d_i$}
                \State Compute local prototypes using the embedding layers of the detection model
                \State Optimize the learning objective in Equation~\ref{eq:optimization_objective} to update local model parameters $\omega^{t}_i$
            \EndFor
        \EndFor
        \State \textbf{return} $\{C^{t}_{i,j}\}$, $\omega^{t}_i$


