\section{Convergence Analysis of PROTEAN}\label{app:proof}
We first provide the Lipschitz continuity and smoothness assumptions posed to the model trained in PROTEAN. 
Note that Lipschitz continuity and smoothness hold for most deep neural network models, as the learning objective function and non-linear transform encoded by deep neural networks inherently limit the rate of change and ensure smooth behavior. 


\begin{assumption}
\textbf{Lipchitz Smoothness.} For each participant, the learning objective $\mathcal{L}$ of \textit{PROTEAN}, as given in Eq.\ref{eq:optimization_objective} is $L_{1}$-Lipschitz smooth, which means, 
\begin{equation}
\begin{split}
\small
&\|\nabla_{\omega}{\mathcal{L}} - \nabla_{\omega'}{\mathcal{L}}\|_{2} \leq L_{1}\|\omega - \omega'\|_{2} s.t. \,\,\,\,\forall{\omega,\omega'}\in{\Omega}
\end{split}
\end{equation}
where $\omega$ and $\omega'$ denote two parameter values of the detection model in the parameter value space $\Omega$. $\|\|_{2}$ denotes the Euclidean distance. With $L_1$-Lipschitz smoothness, we can derive the quadratic bound of $\mathcal{L}(\omega')$ as:
\begin{equation}
\mathcal{L}(\omega') \leq \mathcal{L}(\omega) + \langle\nabla_{\omega}\mathcal{L},(\omega'-\omega)\rangle + \frac{L_1}{2}\|\omega' - \omega\|^2_2
\end{equation}
\end{assumption}

\begin{assumption}
\textbf{Lipschitz Continuity of the embedding function.} The embedding vectors produced by the embedding function $\phi$ has the $L_{\phi}$-Lipschitz continuity. For any input $x$, we give
\begin{equation}
%
\small
\|\phi'(x) - \phi(x)\|_{2} \leq L_{\phi} \|\omega_{\phi} - \omega'_{\phi}\|_{2}
%
\end{equation}
where $\omega_{\phi}$ and $\omega'_{\phi}$ are the parameters of two embedding functions $\phi$ and $\phi'$.  
\end{assumption}

\begin{assumption}
\textbf{Lipschitz Continuity of the objective function with respect to the embedding.} For each participant, the learning objective $\mathcal{L}$ of PROTEAN is $L_{2}$-Lipschitz continuous with respect to the embeddings. It gives for any training sample $(x,y)$:
\begin{equation}
\small
|\mathcal{L}(\phi') - \mathcal{L}(\phi)| \leq L_{2}\|\omega'_{\phi} - \omega_{\phi}\|_{2}
\end{equation}
where $\omega_{\phi}$ and $\omega'_{\phi}$ are the parameters of the two different embedding functions $\phi'$ and $\phi$.   
\end{assumption}



\begin{theorem}
\textbf{The upper bound of the learning objective descent at one federated training round.} For each participant $i$, we use $\mathcal{L}^{i}_{t+1}$ and $\mathcal{L}^{i}_{t}$ to denote the learning objective values of a participant of PROTEAN, which are derived at the successive federated training rounds $t+1$ and $t$. We assume the local learning rate as $\eta$ and locally the model is trained with $T$ steps of stochastic gradient descent. Given that Assumptions 1, 2, and 3 hold, we can bound the expectation of the learning objective at the communication round $t+1$, $\mathcal{L}^{i}_{t+1}$, as given in Equation~\ref{eq:upperbound_argos}.
\begin{equation}\label{eq:upperbound_argos}
\small
\begin{split}
\mathbb{E}[\mathcal{L}^{i}_{t+1}] \leq & \mathcal{L}^{i}_{t} - (\eta - \frac{L_{1}\eta^2}{2}) \cdot \sum_{k=1}^{T}\|\nabla_{\omega^{t}_{i,k}}\mathcal{L}^{i}\|^2_2 +\\
& +  \frac{{L_1}T\eta^2}{2}\sigma^2 + (L_2 + 2\lambda{L_{\phi}})\eta{L_2}T\\
\end{split}
\end{equation}
where $\sigma$ is the upper bound of the variance of the stochastic gradient in the local training of the participant. Between the federated training rounds $t$ and $t+1$, each participant conducts local training of the detection model. 
$\omega^{t}_{i,k}$ are the locally tuned detection model parameters of the participant $i$ derived at the local training step $k$. $\nabla_{\omega^{t}_{i,k}}\mathcal{L}^{i}$ is the gradient of the learning objective of the local training process of participant $i$ with respect to the model parameters $\omega^{t}_{i,k}$.  
\end{theorem}

\begin{theorem}
\textbf{Convergence of PROTEAN.} With $\eta$ in Equation~\ref{eq:learning_rate} set as:
\begin{equation}\label{eq:learning_rate}
\small
\begin{split}
&\eta \leq \frac{\kappa-\tau}{\psi+\kappa L_{1}/2},\\
&\kappa = \sum_{i=1}^{T}\|\nabla_{\omega_{i}\mathcal{L}_{k}}\|^2_2,\quad \tau = (L_2 + 2\lambda{L_{\phi}}){L_2}T , \quad  \psi = \frac{L_{1}T\sigma^2}{2}
\end{split}
\end{equation}
The convergence of the training process of PROTEAN holds.
\end{theorem}


