\section{Conjectures}\label{Sec: ConjStatement}



From now on, we restrict our attention to the case of $N=3$, and for simplicity, we denote the variables by $x,y,z$. For any Borel-fixed ideal $I=(x^{m_1},y^{m_2},z^{m_3},\text{mixed monomial generators})$, we assume that $m_1\leq m_2 \leq m_3$. We recall that Borel-fixed ideals are among the candidates for obtaining the maximal dimension of the tangent space. First, we introduce a definition.

\begin{definition}[locally-maximal singularity or $m_1$-maximal singularity]\label{def: local-max}  Fix $l={2+k \choose 3}$ and $m_1$.  We say that a Borel-fixed ideal $I$ of colength $l$ has a \textit{locally-maximal singularity} or \textit{$m_1$-maximal singularity} if it has the maximal dimension tangent space among all the Borel-fixed ideals of colength $l={2+k \choose 3}$ and the exponent of $x$ being $m_1$. As mentioned in Notations, we denote such a maximal dimension by $T_{\max,m_1}(l)$.

\end{definition}



To prove Conjecture \ref{necessaryCondition} for tetrahedral numbers and $N=3$, we propose a weaker version:

\begin{conj}\label{Conj:general}
    Fix $l={2+k \choose 3}$. Then, 
    the $T_{\mathrm{max},m_1}(l)-m_1$ diagram is increasing (Figure \ref{Fig: Tmax-m1}). In particular, Conjecture \ref{necessaryCondition} holds for tetrahedral numbers (hence, Conjecture \ref{1978Conj} holds).
\end{conj}

More precisely, we propose the following conjectural statement.
\begin{conj}\label{Conj:explicit}
     Fix $l={2+k \choose 3}$ and $2\leq m_1\leq k$. The following Borel-fixed ideal with $1+m_1(k-m_1+2)+{m_1 \choose 2}$ (minimal) number of generators has a locally-maximal singularity.
     \begin{align*}
I=&(x^{m_1},y^k,z^{m_3},\\ &\text{all degree $k$ mixed generators $x^{\alpha}y^{\beta}z^{\gamma}$ with $0\leq \alpha \leq m_1-1$ and $0\leq \beta \leq k-1$ , $0\leq \gamma \leq m_1$},\\&\text{all degree $k+1$ mixed generators $x^{\alpha}y^{\beta}z^{\gamma}$ with $0\leq \alpha \leq m_1-1$ and  $\gamma =m_1+2<m_3$},\\&\text{all  degree $k+2$ mixed generators $x^{\alpha}y^{\beta}z^{\gamma}$ with $0\leq \alpha \leq m_1-1$  and  $\gamma =m_1+4<m_3$},\\&\ldots,\\&\text{all  degree $k+h$ mixed generators $x^{\alpha}y^{\beta}z^{\gamma}$ with $0\leq \alpha \leq m_1-1$  and  $\gamma =m_1+2h<m_3$},\\&\ldots,\\&xz^{m_1+2(k-m_1-1)},yz^{m_1+2(k-m_1-1)}),
     \end{align*}
    where
     \begin{align}\label{m3first}m_3=
 l-\Big(m_1\big({m_1+1 \choose 2}+\sum_{i=1}^{k-2m_1+1}(m_1+2i)\big)+\sum_{j=1}^{m_1-2}(m_1-j)(m_1+2(k-2m_1+j+1))\Big),  \end{align}
 if $k\geq 2m_1-1$, and 
 \begin{align}\label{m3second}
     m_3=l-\Big(m_1{m_1+1 \choose 2}-{f \choose 2}m_1+{f \choose 3}+\sum_{i=0}^{k-m_1-2}(k-m_1-i)(m_1+2+2i)\Big),
 \end{align}
 if $k\geq m_1 \geq k- \floor*{\frac{k}{2}}$, where we define $f:=2m_1-k$, for $0\leq f \leq 2m_1$. 


 In the former case, the dimension of the tangent space to $\mathrm{Hilb}^l(\mathbb{A}^3)$ at $I$ is given by
 \begin{align*}
     T_{\max,m_1}(l)=3l+2{m_1 \choose 2}\Big(2(k-m_1+1)^2+{m_1 \choose 2}-1\Big),
 \end{align*}
and in the latter case, if we define $g:=k-m_1$, for $0\leq g\leq \floor*{\frac{k}{2}}$, the dimension of the tangent space to $\mathrm{Hilb}^l(\mathbb{A}^3)$ at $I$ is given by
   \begin{align*}
     T_{\max,m_1}(l)={k+1 \choose 2}{k+2 \choose 2}-{g+1 \choose 2}(k-g)(k+g+3).
 \end{align*}
\end{conj}

\begin{remark}
    Note that if $k=2m_1$ or $k=2m_1-1$, the two cases in Conjecture \ref{Conj:explicit} coincide.
\end{remark}

\begin{remark} Let $l={2+k \choose 3}$. For simplicity and to avoid separating into two cases, we assume $k$ is large enough, and we have the following graph that illustrates both of the conjectures above.

