\subsection{Loss Functions}
For joint learning, we adopted a loss function composed of three parts: an offset prediction loss, a blur mask prediction loss, and a reconstruction loss to form the final loss:
\begin{equation}
	\mathcal{L}=\mathcal{L}_{recon} + \lambda \mathcal{L}_{mask}+\mathcal{L}_{offset}.
\end{equation} 
\subsubsection{Reconstruction Loss}
\begin{equation}
	\mathcal{L}_{recon}=\mathtt{L}_{1}({\bm{y}}, \bm{y}^{gt}) + \mathtt{SSIM}({\bm{y}}, \bm{y}^{gt}) +  \gamma \mathtt{FFT}({\bm{y}}, \bm{y}^{gt}),
\end{equation}
where $\bm{y}$ is the output of our network and $\bm{y}^{gt}$ denotes the sharp ground-truth.
Following the setting in~\cite{li2023real, li2024adaptive}, we also utilize $\mathtt{L}_{1}$ loss, SSIM loss $\mathtt{SSIM}$, and frequency reconstruction loss $\mathtt{FFT}$ as our reconstruction loss. And we set $\lambda=0.01$ and $\gamma=0.1$ according to~\cite{li2023real, li2024adaptive}.

\subsubsection{Mask Prediction Loss}
\begin{equation}
	\mathcal{L}_{mask}=\sum^{S}_{i=1}\mathtt{Cross\text{-}Entropy}({{\bm{m}_i}}, \bm{m}^{gt}_i),  
\end{equation} 
where $S$ is the number of scales in the network, and $\bm{m}^{gt}_i$ represents the ground-truth mask in the $i$-th scale.
\subsubsection{Offset Prediction Loss}
\begin{equation}
    \mathcal{L}_{offset}=\sum^{S}_{i=1}(\mathtt{Reblur}({\{\bm{o}^{(t_n)}_i\}_{n=0}^{N-1}}, \bm{x}_i, \bm{y}^{gt}_i) + \alpha\sum^{N-1}_{n=0}\mathtt{TV}(\bm{o}^{(t_n)}_i)),  
\end{equation}
where $\bm{x}_i$ is the blurred image downsampled to match the resolution of the $i$-th scale. $\mathtt{TV}$ is the total variation loss to ensure smooth pixel displacement maps.
%
\begin{equation}
% \begin{aligned}
\mathtt{Reblur}({\{\bm{o}^{(t_n)}_i\}_{n=0}^{N-1}}, \bm{x}_i, \bm{y}^{gt}_i)= \mathtt{MSE}(\sum^{N-1}_{n=0}\mathtt{Warp}(\bm{y}^{gt}_i, \bm{o}^{(t_n)}_i), \bm{x}_i)
% \end{aligned}  
\end{equation}  %\odot \bm{m}^{gt}_i
where $N=N_2$ is only used to constrain $\bm{o}^{(t_0)}$ and $\bm{o}^{(t_{N-1})}$ in training.
Since $\bm{y}^{gt}_i$ typically represents the sharp frame at the midpoint of the exposure time, we can generate potential sharp frames for other instants based on the pixel displacements from the midpoint to other times $\bm{o}^{(t_n)}_i$ within the exposure period. By utilizing a forward warping operation in \cite{niklaus2020softmax}, we can synthesize the blurred frame through signal accumulation of these warped sharp frames and constrain it with the input blurred frames to achieve supervision of the pixel displacements.
