\begin{theorem} \label{thm:main result}
Suppose parameters in Algorithm \ref{algorithm: SGD with Alternating Sampling} are set as $\eta = \frac{c_\eta}{\sqrt{T}}$, $\gamma =c_\gamma \cdot \eta$, and $\alpha_t =  \frac{1}{\lambda_{\min}^+(\hat{\Sigma}_Q) } \cdot\frac{1}{ t+2\kappa_Q}$ for some $c_\eta$ and $c_\gamma$. Then, with probability $1-5\tau$ over $S_P, S_Q$ and the randomness in the procedure, the following holds for $c_\eta$ sufficiently small as a function of $(\hat G_\theta, \hat G_\lambda, \lambda^*, \rho)$, and $c_\gamma \geq \hat G_\theta^2$. The returned solution satisfies 
\begin{align*}
 \mathcal{E}_Q (\hat{\theta}_{PQ}) \lesssim \min\cbr{\epsilon_Q,\lambda_{\max}\pare{ {\Sigma}_P^{-1}  {\Sigma}_Q }  \cdot \epsilon_P + \mathcal{E}_{Q}(\theta_P^*) },
\end{align*}
for $ \epsilon_P= c_0 \frac{\sigma^2_{y}(d+\log(1/\tau))}{n_P}, \epsilon_Q = c_0\frac{\sigma^2_{y}(d+\log(1/\tau))}{n_Q}$ for some unversal constant $c_0> 0$, 
provided a number of iterations 
\begin{align*}
    T &\gtrsim  \pare{\hat G_{\theta}  +  { \hat G_{\lambda}  \sqrt{\log\frac{1}{\tau}}}   }^2  \cdot\pare{ \frac{  \frac{\hat G_{\theta}^2}{c_\eta}   +   \hat{G}_\theta \hat G_{\lambda}   \sqrt{\log \frac{1}{\tau}}       }{ \lambda_{\min}^+(\hat{\Sigma}_Q) \epsilon_Q \epsilon_P      }  + \frac{\lambda^*\hat G_{\lambda}  \sqrt{\log \frac{1}{\tau}} +    \frac{\rho^2}{c_{\eta}} }{\epsilon_P} }^2.
\end{align*}
\end{theorem}

