\subsection{Generalization Analysis}\label{sec:gen}
The following result establishes the generalization guarantee of our algorithm.
\begin{theorem}\label{thm:statsRates}
    Suppose $\hat\theta_{PQ}$ satisfies $\hat R_P(\hat\theta_{PQ}) - \hat R_P( \tilde{\theta}_{PQ})  \leq \epsilon_P.$ Then with probability at least $1-4\tau$ over   $S_P$ and $S_Q$,  the excess risk of $\hat{\theta}_{PQ}$ on $Q$ satisfies:
 \begin{align*}
        &\mathcal{E}_Q (\hat{\theta}_{PQ}) \leq 26 \min\cbr{\epsilon_Q,\lambda_{\max}\pare{ {\Sigma}_P^{-1}  {\Sigma}_Q }  \epsilon_P + \mathcal{E}_{Q}(\theta_P^*) }.
    \end{align*} 
\end{theorem}


To prove Theorem~\ref{thm:statsRates}, we first introduce some technical lemmas. The following lemma gives two information: (i) any $\theta$ in the constraint set of \eqref{eq:obj} will have a small $Q$ risk, and (ii) any $\theta$ that has a small $Q$ risk is covered by our constraint set with high probability.
\begin{lemma}\label{lemma:confidence set}
With probability at least $1-2\tau$,   the following holds: for any $\theta \in \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, we have $\mathcal{E}_{Q}(\theta) \leq 26\epsilon_Q$.   For any $\theta$ such that $\mathcal{E}_{Q}(\theta)\leq  \epsilon_Q$, it is in $\{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$.
\end{lemma}


The next lemma shows that, if $\theta_P^*$ is in the constraint set of \eqref{eq:obj}, any $\theta$ in the constraint set with a small empirical risk on $P$,  then it should also have a small population risk on $P$.
\begin{lemma}\label{lemma:P risk}
 If $ \theta_P^*  \in \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, then for any $\theta\in \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, with probability at least $1-2\tau$ we have $
    \mathcal{E}_P(\theta) \leq 4(\hat{R}_P(\theta) - \hat{R}_P(\tilde{\theta}_{PQ})) +16\epsilon_P.$
\end{lemma}


The next Lemma considers the situation where $\theta_P^*$ is not in the constraint set of \eqref{eq:obj}. Due to the inclusive property of our constraint set (Lemma~\ref{lemma:confidence set}), we can claim that any $\theta$ in the constraint set has a smaller $Q$ excess risk than  $\theta_P^*$ up tp some multiplicative universal constant.

\begin{lemma}\label{lemma:not in confidence set}
 If $ \theta_P^*  \notin \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, then for any $\theta \in \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, with probability at least $1-2\tau$ we have $ \mathcal{E}_Q(\theta) \leq 26\mathcal{E}_Q(\theta_P^*).$
\end{lemma}




%\paragraph{Proof of Theorem~\ref{thm:statsRates}:}
\begin{proof}[\bf Proof of Theorem~\ref{thm:statsRates}]
First, if $ \theta_P^*  \in \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, then  since  $  \hat{R}_P(\hat{\theta}_{PQ}) - \hat{R}_P(\tilde{\theta}_{PQ})  \leq \epsilon_P$, from Lemma~\ref{lemma:P risk} we know with probability at least $1-2\tau$, $
        \mathcal{E}_P(\hat{\theta}_{PQ}) \leq 4\epsilon_P +16\epsilon_P = 20\epsilon_P .$
    Hence $ \mathcal{E}_Q(\hat{\theta}_{PQ})  = \|\hat{\theta}_{PQ} - {\theta}^*_Q\|^2_{\Sigma_Q}   \leq \lambda_{\max}\pare{\Sigma_P^{-1}\Sigma_Q} \cdot 20 \epsilon_P + \mathcal{E}_{Q}(\theta^*_P).$
    If $ \theta_P^*  \notin \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, from Lemma~\ref{lemma:not in confidence set} we know $
        \mathcal{E}_Q(\hat{\theta}_{PQ}) \leq 26 \mathcal{E}_{Q}(\theta^*_P).$
    Hence we know with probability at least $1-2\tau$,  
    \begin{align*}
        \mathcal{E}_Q(\hat{\theta}_{PQ}) \leq 26 \pare{ \lambda_{\max}\pare{\Sigma_P^{-1}\Sigma_Q} \cdot   \epsilon_P + \mathcal{E}_{Q}(\theta^*_P) } .
    \end{align*} 

    On the other hand, since $\hat{\theta}_{PQ}  \in \{\theta: \|\theta-\hat\theta_Q\|^2_{\hat\Sigma_Q}\leq 6\epsilon_Q\}$, from Lemma~\ref{lemma:confidence set} we know $ \mathcal{E}_Q(\hat{\theta}_{PQ}) \leq 26\epsilon_Q.$
    Putting piece together we have with probability at least $1-4\tau$, it holds that
    \begin{align*}
            \mathcal{E}_Q(\hat{\theta}_{PQ}) \leq 26 \min\cbr{ \epsilon_Q,   \lambda_{\max}\pare{\Sigma_P^{-1}\Sigma_Q} \cdot   \epsilon_P + \mathcal{E}_{Q}(\theta^*_P)  }.
    \end{align*} 
\end{proof}
\vspace{-5mm}
\begin{proof}[\bf Proof of Theorem~\ref{thm:main result}]
   In Theorem~\ref{thm:optRates},  choosing $T$ such that $\hat{R}_P(\hat \theta_{PQ}) - \hat{R}_P(\tilde{\theta}_{PQ})\leq \epsilon_P$, together with Theorem~\ref{thm:statsRates} will conclude the proof.
 \end{proof}


\section{Experiments}
In this section, we present the experimental results of our algorithm and the baseline algorithms on both synthetic and real-world datasets. We implement our algorithm using Python on an
Intel i7-8700 CPU. We use the CVXPY~\cite{diamond2016cvxpy} package to implement the projection step in Algorithm~\ref{algorithm: SGD with Alternating Sampling}. The baseline algorithms we consider are source ERM, target ERM, projected SGD (PSGD) (widely used for solving constrained problems) and Hypothesis Transfer Learning (HTL). For HTL, we use 5-fold cross-validation on the target training data to select the best bias parameter. For PSGD, we also employ CVXPY to implement the projection steps. Throughout the figures in this section, we use $\hat{\theta}_{PSGD}$  and $\hat{\theta}_{HTL}$ to denote the model obtained by PSGD and HTL respectively. Due to page limit, we only present part of the results and defer additional ones to the appendix.



