\title[DISTORTION FROM SPHERES INTO EUCLIDEAN SPACE]{DISTORTION FROM SPHERES INTO EUCLIDEAN SPACE}

\author[JAMES DIBBLE]{JAMES DIBBLE}
\address{Department of Mathematics and Statistics, University of Southern Maine, 66 Falmouth Street, Portland, ME 04103}
\email{james.dibble@maine.edu}

\subjclass[2020]{Primary 51F99 and 54H25}

\date{}

\begin{abstract}
Any function from a round $n$-dimensional sphere of radius $r$ into $n$-dimensional Euclidean space must distort the metric additively by at least $\frac{2\pi r}{2 + \sqrt{3-2/n}}$. This is proved using a fixed-point theorem of Granas that generalizes the classical theorem of Borsuk--Ulam to set-valued functions.
\end{abstract}

\maketitle

\section{Introduction}

Let $X$ and $Y$ be metric spaces. The \textbf{distortion} of a nonempty relation $R$ from $X$ to $Y$ (that is, a subset of $X \times Y$) is
\[
    \mathrm{dist}(R) = \sup \big\{ |d_Y(y_1,y_2) - d_X(x_1,x_2)| \st (x_1,y_1),(x_2,y_2) \in R \big\}\textrm{,}
\]
which takes values in $[0,\infty]$. In particular, if $f : X \to Y$ is a function, then
\[
    \mathrm{dist}(f) = \sup_{x_1,x_2 \in X} |d_Y(f(x_1),f(x_2)) - d_X(x_1,x_2)|\textrm{.}
\]
The idea of distortion appears in a number of places in geometry and analysis. For example, the Gromov--Hausdorff distance between two compact metric spaces is realized as half the infimum of the distortion of correspondences between them \cite{BuragoBuragoIvanov2001}.

Denote by $S^n_r$ the round $n$-dimensional sphere of radius $r$ in $\real^{n+1}$. That is,
\[
	S^n_r = \{ (x_1,\ldots,x_{n+1}) \in \real^{n+1} \st x_1^2 + \cdots + x_n^2 = r^2 \}\textrm{.}
\]
The classical theorem of Borsuk--Ulam \cite{Borsuk1933} states that any continuous function from $S^n_r$ to $\real^n$ takes a pair of antipodal points to the same point and, consequently, has distortion at least $\pi r$. Since projection onto any hyperplane distorts by exactly that much, that is the minimum distortion over the set of continuous functions. The main result of this paper is a more general lower bound that holds over the set of all functions.

\begin{theorem}\label{main theorem}
    If $f : S^n_r \to \real^n$ is any function, then $\mathrm{dist} \,f \geq \displaystyle \frac{2\pi r}{2 + \sqrt{3-2/n}}$.
\end{theorem}

\noindent One immediately obtains a universal lower bound for the distortion of functions from spheres into Euclidean spaces of no higher dimension.

\begin{corollary}
	If $f : S^n_r \to \real^m$ is any function and $m \leq n$, then $\mathrm{dist}(f) > \displaystyle \frac{2\pi r}{2 + \sqrt{3}}$.
\end{corollary}

\noindent The one-dimensional case of Theorem \ref{main theorem} was proved by the author and Elizabeth Kupin using a combinatorial argument. The general case is an application of a fixed-point theorem of Granas, which generalizes to upper semi-continuous set-valued functions the theorem of Borsuk--Ulam.\\

\noindent \textit{Organization of the paper.} Section 2 contains an elementary combinatorial proof of the one-dimensional case of the main theorem. Section 3 contains background information about fixed-point theory for set-valued functions, including an elementary proof of a theorem of Granas that generalizes the theorem of Borsuk--Ulam to set-valued functions. Section 4 contains a handful of necessary results about the geometry of simplices in Euclidean space. Section 5 contains the proof of the main theorem.

\section{The one-dimensional case}

Before proving the general case of Theorem \ref{main theorem}, it may help to give an elementary combinatorial proof for functions on $S^1_r$. This was developed jointly with Elizabeth Kupin. The quotient space $[0,2\pi] / \sim$, where $\sim$ identifies the endpoints, is homeomorphic to the circle $S^1_r$ by the map $C(\theta) = (r\cos \theta, r\sin \theta)$. Under this identification, consider the $m$ equally spaced points $x_k = C(2\pi k/m)$ on $S^1_r$, with their indices being taken modulo $m$. To simplify the exposition, $m$ will always be assumed to be odd.

\begin{lemma}\label{one-dimensional lemma}
	Let $f : S^1_r \to \real$ be any function. Suppose, for some $k$, that one of the following holds:\\
	\indent (1) $f(x_k) \leq f(x_{k + \frac{m+1}{2}}) \leq f(x_{k+1})$\\
	\indent (2) $f(x_{k+1}) \leq f(x_{k+\frac{m+1}{2}}) \leq f(x_k)$\\
	Then, $\dist(f) \geq \frac{2\pi r(m-2)}{3m}$.
\end{lemma}

\begin{proof}
	As neighbors on $S^1_r$, $x_k$ and $x_{k+1}$ are at a distance of $\frac{2\pi r}{m}$ from each other. At the same time, $x_k$ and $x_{k + \frac{m+1}{2}}$ are almost antipodal; the distance between them is $\frac{\pi r(m-1)}{m}$, which is also the distance between $x_{k+1}$ and $x_{k + \frac{m+1}{2}}$. Therefore,
	\begin{align*}
		\frac{2\pi r}{m} + \mathrm{dist}(f) &\geq d \big( f(x_k), f(x_{k+1}) \big)\\
		&= d \big(  f(x_k), f(x_{k + \frac{m+1}{2}}) \big) + d \big( f(x_{k+\frac{m+1}{2}}), f(x_{k+1}) \big)\\
		&\geq 2 \Big( \frac{\pi r(m-1)}{m} - \mathrm{dist}(f) \Big)\textrm{.}
	\end{align*}
	The result follows immediately.
\end{proof}

\begin{theorem}
	If $f : S^1_r \to \real$ is any function, then $\dist(f) \geq 2\pi r/3$.
\end{theorem}

\begin{proof}
	Let $m \geq 3$ be an odd integer, and let $x_k$ be the $m$ points in $S^1_r$ described above. Construct a graph on $\{ x_k \}$ by assigning an edge between $x_i$ and $x_j$ whenever $x_i$ and $x_j$ are almost antipodal, i.e., the distance between them is $\frac{\pi r(m-1)}{m}$. Since $m$ is odd, this graph is $2$-regular (i.e., each vertex is connected to exactly two others) and its edges form a cycle of length $m$. If, for some $m$, two almost antipodal points map to the same point under $f$, then the distortion of $f$ is at least $\frac{\pi r(m-1)}{m}$, and the result holds. If that never happens, then one may always make this a directed graph by orienting each edge to point from $x_i$ to $x_j$ exactly when $f(x_i) < f(x_j)$. Since $m$ is odd, the edge cycle must contain a directed path of length at least two, which produces one of the two configurations in the hypothesis of Lemma \ref{one-dimensional lemma}. Therefore, $\dist(f) \geq \frac{2\pi r(m-2)}{3m}$. The result follows by letting $m \to \infty$.
\end{proof}

\noindent It's not difficult to show that the distortion bound is sharp in this case.

\begin{example}
Under the identification of $S^1_r$ with $[0,2\pi] / \sim$, define a map $f : S^1_r \to [0,2\pi r/3)$ by $f(\theta) = r\theta/3$ for all $\theta \in [0,2\pi)$. Then, $\mathrm{dist}(f) = 2\pi r/3$.
\end{example}

\section{Fixed-point theory for set-valued functions}

Let $X$ be a set, and denote by $\mathscr{P}(X)$ the power set of $X$. If $F : X \to \mathscr{P}(X)$ is a set-valued function, then $x \in X$ is a \textbf{fixed point} of $F$ whenever $x \in F(x)$. If $X$ and $E$ are topological spaces, then $F : X \to \mathscr{P}(E)$ is \textbf{upper semi-continuous} if, whenever $x_k \to x$, $y_k \in F(x_k)$, and $y_k \to y$, it follows that $y \in F(x)$. When $E$ is a normed vector space, each $F(x)$ is closed, and $F(X) = \cup_{x \in X} F(x)$ has compact closure, this is equivalent to the condition that the set $\{ x \in X \st F(x) \subset W \}$ is open whenever $W \subseteq X$ is open \cite{GranasDugundji2003}.

The first major result in this area was the celebrated fixed-point theorem of Kakatani \cite{Kakutani1941}.  If $E$ has an affine structure, denote by $CC(E)$ the set of non-empty, closed, and convex subsets of $E$.

\begin{theorem}[Kakutani]
	Let $X \subset \real^n$ be compact and convex. If $F : X \to CC(X)$ is upper semi-continuous, then $F$ has a fixed point.
\end{theorem}

\noindent The proof of Theorem \ref{main theorem} depends on a result of Granas that generalizes the theorem of Borsuk--Ulam \cite{Borsuk1933} to set-valued functions in the same way that Kakutani's theorem generalizes Brouwer's fixed point theorem \cite{Brouwer1911}. This is essentially proved in \cite{Granas1959}.

\begin{theorem}[Granas]\label{granas theorem}
	Let $F : S^n \to CC(\real^n)$ be an upper semi-continuous function such that $F(X)$ has compact closure. Then, there exist antipodal $x,\tilde{x} \in S^n$ such that $F(x) \cap F(\tilde{x}) \neq \emptyset$.
\end{theorem}

\noindent For the sake of completeness, the rest of this section is devoted to an elementary proof of Theorem \ref{granas theorem}.

When $E$ is a vector space and $Y \subseteq E$, denote by $\mathrm{conv}(Y)$ the convex hull of $Y$ and by $\overline{\mathrm{conv}}(Y)$ the closure of $\mathrm{conv}(Y)$. The following approximation result is essentially due to Cellina \cite{Cellina1969} (see also Lemma 8.3 of \cite{GranasDugundji2003}). The proof here uses the non-trivial theorem, due to Stone \cite{Stone1948}, that every metric space $X$ is paracompact. Since metric spaces are Hausdorff, it follows that every open cover $\{ U_\alpha \}$ of $X$ admits a \textbf{barycentric refinement}, i.e., a refinement $\{ V_\beta \}$ such that, for each $x \in X$, all of the $V_\beta$ containing $x$ are contained in some $U_\alpha$. For more details on this topological background material, the reader is referred to \cite{Willard1970}.

\begin{lemma}\label{function lemma}
	Let $X$ be a metric space and $E$ a normed vector space. If $F : X \to CC(E)$ is upper semi-continuous and $F(X)$ has compact closure, then, for each $\varepsilon > 0$, there exists a continuous $f_\varepsilon : X \to\mathrm{conv}(F(X))$ with the following property: For each $x \in X$, there exists $\hat{x} \in B(x,\varepsilon)$ such that $d(f_\varepsilon(x),F(\hat{x})) < \varepsilon$.
\end{lemma}

\begin{proof}
	Let $\varepsilon > 0$. For each $x \in X$, define $U(x) = \{ y \in X \st F(y) \subset B(F(x),\varepsilon) \}$. By upper semi-continuity, each $U(x)$ is open. The collection $\{ U(x) \cap B(x,\varepsilon) \st x \in X \}$ is an open cover of $X$; it admits a barycentric neighborhood-finite refinement $\{ V_\alpha \}$. Let $\phi_\alpha$ be a partition of unity subordinate to $\{ V_\alpha \}$. For each $\alpha$, choose $z_\alpha \in F(V_\alpha)$, and define $f_\varepsilon : X \to \mathrm{conv}(F(X))$ by $f_\varepsilon(x) = \sum_\alpha \phi_\alpha(x) z_\alpha$. Since that is locally a finite sum, $f_\varepsilon$ is continuous.

	Fix $x \in X$, and enumerate by $V_{\alpha_1},\ldots,V_{\alpha_k}$ all the sets in $\{ V_\alpha \}$ containing $x$. Since $\{ V_\alpha \}$ is a barycentric refinement of $\{ U_\alpha \}$, there exists $\hat{x} \in X$ such that $\cup_{i=1}^k V_{\alpha_i} \subseteq U(\hat{x}) \cap B(\hat{x},\varepsilon)$. In particular, $x \in B(\hat{x},\varepsilon)$ and $\cup_{i=1}^k V_{\alpha_i} \subset U(\hat{x})$. Since $z_{\alpha_i} \in F(V_{\alpha_i}) \subset B(F(\hat{x}), \varepsilon)$ and $B(F(\hat{x}),\varepsilon)$ is convex, $f_\varepsilon(x) \in B(F(\hat{x}), \varepsilon)$. Thus, $d(f_\varepsilon(x), F(\hat{x})) <\varepsilon$.
\end{proof}

\begin{lemma}\label{epsilon lemma}
	Let $F : S^n \to CC(\real^n)$ be an upper semi-continuous function such that $F(S^n)$ has compact closure and, for every pair of antipodal points $x,\tilde{x} \in S^n$, $F(x) \cap F(\tilde{x}) = \emptyset$. Then, there exists $\varepsilon > 0$ such that, for every such antipodal pair,
\[
	B \big( F(B(x,\varepsilon)),\varepsilon \big) \cap B \big( F(B(\tilde{x},\varepsilon)),\varepsilon \big) = \emptyset\textrm{.}
\]
\end{lemma}

\begin{proof}
	Fix antipodal $x,\tilde{x} \in S^n$, and assume that, for every $\varepsilon > 0$, the given intersection at $x$ and $\tilde{x}$ is nonempty. Then, there exist sequences $y_k,\hat{y}_k \in S^n$ and $w_k \in \real^n$ such that $y_k \to x$, $\hat{y}_k \to \tilde{x}$, and $w_k \in B(F(y_k),1/k) \cap B(F(\hat{y}_k),1/k)$. Since $F(S^n)$ has compact closure, one may, by passing to a subsequence, assume without loss of generality that $w_k \to w \in \real^n$. By upper semi-continuity, it follows that $w \in F(x) \cap F(\tilde{x})$. This is a contradiction. The claim now follows from the Lebesgue number lemma.
\end{proof}

\begin{proof}[Proof of Theorem \ref{granas theorem}]
	Assume the result is false. Fix $\varepsilon > 0$ as in the conclusion of Lemma \ref{epsilon lemma}, and let $f_\varepsilon : S^n \to \real^n$ be the single-valued approximation of $F$ guaranteed by Lemma \ref{function lemma}. If $x,\tilde{x} \in S^n$ are antipodal, then there exist $y \in B(x,\varepsilon)$ and $z \in B(\tilde{x},\varepsilon)$ such that $d(f_\varepsilon(x), F(y)) < \varepsilon$ and $d(f_\varepsilon(\tilde{x},F(z)) < \varepsilon$, i.e., $f_\varepsilon(x) \in B \big( F(B(x,\varepsilon)), \varepsilon \big)$ and $f_\varepsilon(\tilde{x}) \in B \big( F(B(\tilde{x},\varepsilon)), \varepsilon \big)$. By the choice of $\varepsilon$, this means $f_\varepsilon(x) \neq f_\varepsilon(\tilde{x})$. This contradicts the theorem of Borsuk--Ulam.
\end{proof}

\section{Simplicial geometry}

A handful of elementary facts about the geometry of simplices in $\real^n$ will be needed. An \textbf{$m$-dimensional simplex} in $\real^n$ is the convex hull of $m+1$ affinely independent points, i.e., $v_1,\ldots,v_{m+1} \in \real^n$ such that the set $\{ v_1 - v_{m+1}, \ldots, v_m - v_{m+1} \}$ is linearly independent. As a set,
\[
	\Delta(v_1,\ldots,v_{m+1}) = \Big\{ \sum_{i=1}^{m+1} t_i v_i \st t_1,\ldots,t_{m+1} \geq 0 \textrm{ and } \sum_{i=1}^{m+1} t_i = 1 \Big\}\textrm{.}
\]
A \textbf{$k$-dimensional face} of $\Delta(v_1,\ldots,v_{m+1})$ is a $k$-dimensional simplex obtained as the convex hull of exactly $k$ of the $v_i$. The \textbf{vertices} of $\Delta(v_1,\ldots,v_{m+1})$ are its $0$-faces, and its \textbf{edges} are its $1$-faces. That is, its vertices are the $v_i$, and its edges are the line segments connecting the $v_i$. A simplex is \textbf{regular} if its edges all have the same length, in which case all of its faces are also regular. The \textbf{barycenter} of $\Delta(v_1,\ldots,v_{m+1})$ is $\sum_{i=1}^{m+1} v_i/(m+1)$.

\begin{lemma}\label{regular simplicial geometry}
	Let $\Delta \subset \real^{n+1}$ be a regular $n$-simplex with sides of length $L$ and vertices $v_1,\ldots,v_{n+1}$. Then, the following hold:\\
	\indent (a) The distance from each $v_i$ to the barycenter $b$ of $\Delta$ is $L\sqrt{\frac{n}{2(n+1)}}$.\\
	\indent (b) For any $R > L\sqrt{\frac{n}{2(n+1)}}$, the set $\cup_{i=1}^{n+1} B(v_i, R)$ covers $\Delta$, and the set $\cap_{i=1}^{n+1} \partial B(v_i,R)$ consists of two points, $p$ and $q$.\\
	\indent (c) The segment connecting $p$ and $q$ intersects $\Delta$ orthogonally at $b$ and has length $2\sqrt{R^2 - L^2[\frac{n}{2(n+1)}]}$.\\
	\indent (d) Any segment that intersects $\Delta$ and whose endpoints lie outside of $\cup_{i=1}^{n+1} B(v_i, R)$ is at least as long as the segment from $p$ to $q$. 
\end{lemma}

\begin{proof}
	After applying a rigid motion, one may suppose that $v_i = (L/\sqrt{2}) e_i$, where $e_i$ is the $i$-th standard basis vector of $\real^{n+1}$. Then,
\[
	b = \Big( \frac{L}{(n+1)\sqrt{2}},\ldots,\frac{L}{(n+1)\sqrt{2}} \Big)\textrm{,}
\]
and the distance from each vertex to $b$ is $L\sqrt{\frac{n}{2(n+1)}}$ by the Pythagorean theorem. This proves (a). Suppose that $R > L\sqrt{\frac{n}{2(n+1)}}$. Let $x = \sum_{i=1}^{n+1} t_i v_i$, where $t_1,\ldots,t_{n+1} \geq 0$ and $\sum_{i=1}^{n+1} t_i = 1$, be an arbitrary point of $\Delta$. Suppose $v_j$ is a vertex of $\Delta$ closest to $x$, or, equivalently, that $t_j \geq t_i$ for all $i$. Then, $t_j \geq \frac{1}{n+1}$, $t_i \leq \frac{1 - t_j}{n}$ for all $i \neq j$, and
\begin{align*}
	d(v_j,x) &= \sqrt{ \Big( \frac{t_1 L}{\sqrt{2}} \Big)^2 + \cdots + \Big( \frac{t_j L}{\sqrt{2}} - \frac{L}{\sqrt{2}} \Big)^2 + \cdots + \Big( \frac{t_{n+1} L}{\sqrt{2}} \Big)^2 }\\
	&= \frac{L}{\sqrt{2}} \sqrt{t_1^2 + \cdots + (1-t_j)^2 + \cdots + t_{n+1}^2}\\
	&\leq \frac{L}{\sqrt{2}} \sqrt{n \Big( \frac{1-t_j}{n} \Big)^2 + (1 - t_j)^2} = \frac{L}{\sqrt{2}} \sqrt{\Big( \frac{n+1}{n} \Big) (1-t_j)^2}\\
	&\leq \frac{L}{\sqrt{2}} \sqrt{ \Big( \frac{n+1}{n} \Big) \Big( 1 - \frac{1}{n+1} \Big)^2} = L \sqrt{\frac{n}{2(n+1)}} < R\textrm{.}
\end{align*}
So, $\cup_{i=1}^{n+1} B(v_i, R)$ covers $\Delta$. To see that $\cap_{i=1}^{n+1} \partial B(v_i,R)$ contains exactly two points, suppose $p$ is such a point of intersection and consider the orthogonal projection $\pi(p)$ onto the hyperplane containing $\Delta$. The Pythagorean theorem implies that $\pi(p)$ is equidistant from each $v_i$, and, by writing $\pi(p) = v_{n+1} + \sum_{i=1}^n c_i(v_i - v_{n+1})$ and solving for the $c_i$, one finds that $\pi(p) = b$. Since $b$ is interior to each $B(v_i,R)$, the line that intersects $\Delta$ orthogonally at $b$ intersects $\partial B(v_i,R)$ in exactly two points. This shows that $\cap_{i=1}^{n+1} \partial B(v_i,R)$ contains at most two points. By the Pythagorean theorem, the two points at a distance of $\sqrt{R^2 - L^2[\frac{n}{2(n+1)}]}$ from $b$ along that line are at a distance of $R$ from each $v_i$, and clearly the length of the segment connecting them is $2\sqrt{R^2 - L^2[\frac{n}{2(n+1)}]}$, completing the proof of (b) and (c).

Consider any segment $\ell$ through $\Delta$ with endpoints that lie outside $\cup_{i=1}^{n+1} B(v_i,R)$. Suppose $\ell$ intersects $\Delta$ at a point $x$, and let $v_j$ be a vertex of $\Delta$ closest to $x$. As shown above, $x \in B(v_j, R)$, so $\ell$ intersects $\partial B(v_j,R)$ exactly twice. Let $y$ and $z$ be those points of intersection, and denote by $m$ the midpoint of the segment connecting $y$ to $z$. Then, the segment from $v_j$ to $m$ intersects $\ell$ orthogonally at $m$. By the Pythagorean theorem, $d(v_j,x) \geq d(v_j,m)$. Let $\ell'$ be the segment that intersects $\Delta$ orthogonally at $x$ with endpoints $y'$ and $z'$ on $\partial B(v_j,R)$. Then, $d(a,m) \geq d(y',x)$; at the same time, $d(y,m) = d(m,z)$ and $d(y',x) = d(x,z')$. Thus,
\[
	|\ell| \geq d(y,m) + d(m,z) \geq d(y',x) + d(x,z') = |\ell'|\textrm{.}
\]
Since $d(x,v_j) \leq L\sqrt{\frac{n}{2(n+1)}}$, $|\ell'| \geq 2\sqrt{R^2 - L^2[\frac{n}{2(n+1)}]}$. This proves (d).
\end{proof}

\noindent The following generalizes Lemma \ref{regular simplicial geometry} to irregular simplices.

\begin{lemma}\label{simplicial geometry}
	For $m \geq n+1$, let $\Delta \subset \real^m$ be an $n$-simplex with sides of length no greater than $L$ and vertices $v_1,\ldots,v_{n+1}$. For any $R > L\sqrt{\frac{n}{2(n+1)}}$, the set $\cup_{i=1}^{n+1} B(v_i,R)$ covers $\Delta$. Furthermore, any segment that intersects $\Delta$ and whose endpoints lie outside $\cup_{i=1}^{n+1} B(v_i,R)$ has length at least $2\sqrt{R^2 - L^2[\frac{n}{2(n+1)}]}$.
\end{lemma}

\begin{proof}
	The same argument as in the proof of Lemma \ref{regular simplicial geometry} shows that  $\cup_{i=1}^{n+1} B(v_i,R)$ covers $\Delta$. Let $\ell$ be any segment that intersects $\Delta$, say at a point $x$, and whose endpoints lie outside of $\cup_{i=1}^{n+1} B(v_i,R)$. For a vertex $v_j$ closest to $x$, the segment $\ell'$ orthogonal to $\Delta$ with endpoints on $\partial B(v_i,R)$ satisfies $|\ell| \geq |\ell'|$.  Since $d(v_j,x) \leq d(v_i,x)$ for all $i$, it follows that the endpoints of $\ell'$ lie outside  $\cup_{i=1}^{n+1} B(v_i,R)$. Since $d(v_j,x) \leq \frac{n}{2(n+1)}$, the Pythagorean theorem implies that $|\ell'| \geq 2\sqrt{R^2 - L^2 [\frac{n}{2(n+1)}]}$.
\end{proof}

\noindent A result about the manner in which simplicies intersect will also be needed.

\begin{lemma}\label{simplicial intersection}
	Let $\Delta_1$ and $\Delta_2$ be simplices of positive dimension in $\real^n$ such that $\Delta_1 \cap \Delta_2 \neq \emptyset$. Then, an edge in $\Delta_1$ intersects $\Delta_2$ or an edge in $\Delta_2$ intersects $\Delta_1$.
\end{lemma}

\begin{proof}
	Let $\Delta'$ be a face of smallest dimension in $\Delta_1$ or $\Delta_2$ that intersects $\Delta_1 \cap \Delta_2$. Without loss of generality, suppose that $\Delta'$ is a face in $\Delta_1$. Assume, for the sake of contradiction, that $\Delta'$ is at least two-dimensional. Let $\Delta''$ be a face of smallest dimension in $\Delta_2$ that intersects $\Delta'$. Then, $\Delta''$ is also at least two-dimensional. Let $P_1$ and $P_2$ be the smallest affine subspaces of $\real^n$ containing $\Delta'$ and $\Delta''$, respectively. Since $P_1 \cap P_2$ is at least one-dimensional, it must contain a line $\ell \subseteq P_1 \cap P_2$. By assumption, $p$ is interior to $\Delta' \cap \Delta'' \cap \ell$, which must therefore be a line segment whose endpoints lie on $\partial \Delta' \cup \partial \Delta''$. But, $\partial \Delta'$ and $\partial \Delta''$ have smaller dimensions than $\Delta'$ and $\Delta''$, respectively, which is a contradiction.
\end{proof}

\section{Proof of the main theorem}

Let $f : X \to E$ be any function from a metric space $X$ into a normed vector space $E$. Define a set-valued function $F : X \to CC(E)$ by
\[
	F(x) = \cap_{\varepsilon > 0} \overline{\mathrm{conv}}\big( f(B(x,\varepsilon)) \big)\textrm{.}
\]
This function captures the ``convex essence'' of $f$ at each point. Since $f(x) \in f(B(x,\varepsilon))$ for all $\varepsilon > 0$, $F(x) \neq \emptyset$. As the intersection of closed and convex sets, each $F(x)$ is, in fact, closed and convex.

\begin{lemma}\label{upper semi-continuous}
	For any $f : X \to E$, the function $F$ defined above is upper semi-continuous.
\end{lemma}

\begin{proof}
	Suppose $x_k \in X$, $y_k \in F(x_k)$, $x_k \to x$, and $y_k \to y$. Let $\varepsilon > 0$, and fix $K \in \nat$ such that $x_k \in B(x,\varepsilon)$ for all $k \geq K$. For such $k$,
\[
	y_k \in \overline{\mathrm{conv}} \big( f(B(x_k, \varepsilon - d(x_k,x))) \big)\textrm{,}
\]
which means that $y_k \in \overline{\mathrm{conv}} \big( f(B(x,\varepsilon)) \big)$ and, consequently, $y \in \overline{\mathrm{conv}} \big( f(B(x,\varepsilon)) \big)$. Since the choice of $\varepsilon > 0$ was arbitrary, $y \in F(x)$.
\end{proof}

\begin{lemma}\label{rewrite F}
	If $f : X \to \real^n$ is locally bounded, then $F(x) = \mathrm{conv} \big( \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))} \big)$.
\end{lemma}

\begin{proof}
	Suppose $y \in \mathrm{conv} \big( \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))} \big)$. By Carath\'{e}odory's theorem \cite{Steinitz1913}, there exist $v_1,\ldots,v_{n+1} \in \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))}$ such that $y \in \mathrm{conv} \{ v_1,\ldots,v_{n+1} \}$. For each $\varepsilon > 0$, $v_i \in \overline{\mathrm{conv}} \big( f(B(x,\varepsilon)) \big)$, so $\mathrm{conv} \{ v_1,\ldots,v_{n+1} \} \subseteq \overline{\mathrm{conv}} \big( f(B(x,\varepsilon)) \big)$. Since the choice of $\varepsilon > 0$ was arbitrary, $\mathrm{conv} \{ v_1,\ldots,v_{n+1} \} \subseteq F(x)$. So, $y \in F(x)$.

	Conversely, suppose $y \in F(x)$. Then, $y \in \overline{\mathrm{conv}} \big( f(B(x,1/m)) \big)$ for each $m \in \nat$. For each $k,m \in \nat$, choose $y_k^m \in \mathrm{conv} \big( f(B(x,1/m)) \big)$ such that $d(y_k^m,y) < \frac{1}{k+m}$. By Carath\'{e}odory's theorem, there exist $v_{k,1}^m,\ldots,v_{k,n+1}^m \in f(B(x,1/m))$ such that $y_k^m \in \mathrm{conv} \{ v_{k,1}^m,\ldots,v_{k,n+1}^m \}$. Since $f$ is locally bounded, one may, by passing to a subsequence, suppose without loss of generality that $v_{k,i}^m \to v_{k,i}$ as $m \to \infty$. Let $\varepsilon > 0$. Since $f(B(x,1/m))$ form a decreasing sequence of sets, $v_{k,i}^m \in f(B(x,\varepsilon))$ for all sufficiently large $m$. Thus, $v_{k,i} \in \overline{f(B(x,\varepsilon))}$. Since the choice of $\varepsilon > 0$ was arbitrary, $v_{k,i} \in \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))}$. Thus, for each $k$,
\begin{align*}
	\big\{ \lim_{m \to \infty} z_m \st z_m \in \mathrm{conv} \{ v_{k,1}^m,\ldots,v_{k,n+1}^m \} \big\} &= \mathrm{conv} \{ v_{k,1}, \ldots, v_{k,n+1} \}\\
&\subseteq \mathrm{conv} \big( \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))} \big)\textrm{.}
\end{align*}
Since $y_k^m \in \mathrm{conv} \{ v_{k,1}^m,\ldots,v_{k,n+1}^m \}$ for each $m$,
\[
	y = \lim_{k \to \infty} y_k^m \in \overline{\mathrm{conv}} \big( \cap_{\varepsilon >0} \overline{f(B(x,\varepsilon))} \big) = \mathrm{conv} \big( \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))} \big)\textrm{,}
\]
where the last equality follows from the fact that, since $f$ is locally bounded, $\mathrm{conv} \big( \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))} \big)$ is compact.
\end{proof}

\noindent It is now possible to prove the main theorem.

\begin{proof}[Proof of Theorem \ref{main theorem}]
	Let $f : S^n_r \to \real^n$ be any function. If $f(S^n_r)$ does not have compact closure, then $f$ is unbounded. In this case, $\mathrm{dist}(f) = \infty$, and the result holds. If $f(S^n_r)$ has compact closure, then, by Lemma \ref{rewrite F},
\[
	F(x) =  \mathrm{conv} \big( \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))} \big)\textrm{.}
\]
By Lemma \ref{upper semi-continuous}, $F$ is upper semi-continuous, so, by Theorem \ref{granas theorem}, there exist antipodal $x,\tilde{x} \in S_k^n$ such that $F(x) \cap F(\tilde{x}) \neq \emptyset$. By Carath\'{e}odory's theorem, there exist $v_1,\ldots,v_k \in \cap_{\varepsilon > 0} \overline{f(B(x,\varepsilon))}$ and $\hat{v}_1,\ldots,\hat{v}_m \in \cap_{\varepsilon > 0} \overline{f(B(\tilde{x},\varepsilon))}$ such that $\mathrm{conv} \{ v_1,\ldots,v_k \} \cap \mathrm{conv} \{ \hat{v}_1,\ldots,\hat{v}_m \} \neq \emptyset$, where $k,m \leq n+1$. By Lemma \ref{simplicial intersection}, one may suppose, without loss of generality, that the segment connecting $v_1$ to $v_2$ intersects $\mathrm{conv} \{ \hat{v}_1,\ldots,\hat{v}_m \}$. Since the desired distortion bound holds if one of $v_1$ or $v_2$ lies interior to $\mathrm{conv} \{ \hat{v}_1,\ldots,\hat{v}_m \}$, one may further suppose, again without loss of generality, that the segment connecting $v_1$ to $v_2$ intersects $\mathrm{conv} \{ \hat{v}_1,\ldots,\hat{v}_{m-1} \}$.

For each $\varepsilon > 0$, one has that $d(v_1,v_2) < \mathrm{dist}(f) + 2\varepsilon$, $d(\hat{v}_i,\hat{v}_j) < \mathrm{dist}(f) + 2\varepsilon$, and $d(v_i,\hat{v}_j) > \pi r - \mathrm{dist}(f) - 2\varepsilon$. Thus, $d(v_1,v_2) \leq \mathrm{dist}(f)$, $d(\hat{v}_i, \hat{v}_j) \leq \mathrm{dist}(f)$, and $d(v_i,\hat{v}_j) \geq \pi r - \mathrm{dist}(f)$. By Lemma \ref{simplicial geometry},
\[
	2\sqrt{ \pi^2 r^2 - [\mathrm{dist}(f)]^2 \big( \frac{n-1}{2n} \big) } \leq d(v_1,v_2) \leq \mathrm{dist}(f)\textrm{.}
\]
The result follows by solving for $\mathrm{dist}(f)$.
\end{proof}

