\section{Background on elliptic curves}
    \label{sec:Background}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%=======================================================

\subsection{Notation}
We write $[k]$ for $\aset{1,2, \dots, k}$; 
$\card X$ for cardinality of a set; 
$X \cup i$ for $X \cup \aset{i}$; 
SES for Short Exact Sequence;
$\CoCo X$ for connected components of $X$.


\subsection{Elliptic curves with complex multiplication}
    \label{sub:EllipticCurvesWithComplexMultiplication}
%=======================================================
Let $\EC$ be a smooth complex Riemann surface of genus one. 
All such $\EC$ are isomorphic to $\faktor \CC  \Lambda$, 
with $\Lambda$ a lattice generated by $1$ and $\tau \in \CC \setminus \RR$,
and group structure induced by $(\CC, +)$.
If $\End \EC \ne \ZZ$ we say that  $\EC$ has complex multiplication type.
We recall some properties of $\End \EC$ and $\Lambda$;
for details and introductory references, see \cite{Silverman09} or \cite{st15}. 

%=======================================================
\subsubsection{The endomorphism ring}
    \label{sub:EndomorphismRing}
%=======================================================
We describe a ring $R_\EC$ isomorphic to $\End \EC$.
Denote by $A_\alpha$ the linear map given by multiplication by $\alpha$, i.e.~$z \mapsto \alpha z$.

%-------------------------------------------------------
\begin{lm} 
    \label{lm:EndoRingAsR}
%------------------------------------------------------- 
    For an elliptic curve $\EC = \CC / \Lambda$, the ring $\End \EC$ is isomorphic to \[R_\EC = \aset{\alpha \in \Lambda \suchthat \alpha \Lambda \subset \Lambda}\]
    via the map $R_\EC \to \End \EC$ defined by $\alpha \mapsto A_\alpha$.
\end{lm}

\begin{proof}[Sketch of proof]
    One shows that if $f \colon \faktor \CC  \Lambda \to \faktor \CC  \Lambda$ is an endomorphism,
    then an analytic continuation $\hat f \colon \CC \to \CC$ of $f$ around 0 is of the form $\hat f(z) = \alpha z$. 
    Moreover, $\alpha$ must have the property that $\alpha \Lambda \subset \Lambda $ for $f$ being well defined when descending to $\faktor \CC  \Lambda$. 
    See Proposition~6.17 of \cite{st15} for details.
\end{proof}

We write $R$ instead of $R_\EC$ when $\EC$ is clear from the context.

%=======================================================
\subsubsection{A quadratic relation for \texorpdfstring{$\tau$}{tau}}
    \label{sub:AQuadraticRelationForTau}
%=======================================================
    Assume that $\End \EC \not \isom \ZZ$ and consider $\alpha$ in $R$.
    By \Cref{lm:EndoRingAsR} we have $\alpha \Lambda \subset \Lambda$.
    Equivalently, $\alpha \cdot 1 \in \Lambda$ and  $\alpha \cdot \tau \in \Lambda$.
    Having $\alpha \cdot 1 \in \Lambda$ gives $R \subset \Lambda$,
    so we can write $\alpha = x + y\tau$ with $x, y \in \ZZ$.
    Thus, $\alpha \cdot \tau = x\tau + y\tau^2$.
    Hence, the second condition $\alpha \cdot \tau \in \Lambda$ is true if and only if 
    $y\tau^2$ is in $\Lambda$.
    That is, for some $h, k \in \ZZ$ we have 
    %-------------------------------------------------------
    \begin{align} 
        \label{eq:tauisquadratic}
    %-------------------------------------------------------
      y\tau^2 = h\tau + k.
    \end{align}
    %From $ y\tau^2 - h'\tau - k' = 0$  we get the following.
    %    %We frame the next lemma in the language of algebraic number theory.
    %Recall that a degree-$d$ number field is a field extension $K$ of $\QQ$ with $[K : Q] = d$, 
    %and an order in $K$ is a subring whose additive group is finitely generated of rank~$d$.
    %-------------------------------------------------------
    \begin{lm} 
        \label{lm:RIsAnOrder}
    %-------------------------------------------------------
        If $\EC = \CC / \langle 1, \tau \rangle$ has $\End \EC \not \isom \ZZ$, then $\QQ[\tau]$ is a quadratic imaginary number field and $R_\EC$ is an order, i.e.\ a subring of the ring of integers $\calO_{\QQ[\tau]}$ of rank two.
    \end{lm}

    %-------------------------------------------------------
    \begin{proof} 
%        \label{proof:}
    %-------------------------------------------------------     
        If $y=0$ in Equation~\eqref{eq:tauisquadratic}, then $\alpha = x$ is an integer. 
        So $\End \EC \not \isom \ZZ$ is equivalent to the existence of a non-zero choice for $y$, which gives the quadratic relation $y\tau^2 - h\tau - k = 0$ for $\tau$.
        Moreover, $\tau$ is non-real because otherwise $\Span_\ZZ \aset{1, \tau}$ would not be a lattice in $\CC$.
        This proves the statement about $\QQ[\tau]$.

        Recall that the ring of integers $\calO$ is the subring of algebraic numbers $\alpha \in \QQ[\tau]$ whose minimal polynomial $f_\alpha$ over $\ZZ$ is monic.
        To see that $\alpha \in R_\EC$ is an algebraic integer,
        multiply Equation~\eqref{eq:tauisquadratic} by $y$ to get the monic relation $(y\tau)^2 -h(y\tau) - yk = 0$, thus $y\tau \in \calO$.
        Since $x \in \ZZ$, we have that $\alpha = x + y\tau$ is in $\calO$ as desired.
    \end{proof}

%=======================================================
\subsubsection{Quadratic number fields}
    \label{sub:QuadraticNumberFields}
%=======================================================
In view of \Cref{lm:RIsAnOrder}, we recall that
every imaginary quadratic number field can be obtained via a unique choice of a square-free positive integer $m$:
let $K_m = \QQ(\sqrt{-m})$ be the field containing $\tau$. 
Consider
\begin{align}
  \label{eq:CasesOmega}
\omega =
\begin{cases}
  \frac{1 + \sqrt{-m}}{2} & \text{ if } m \equiv 3 \mod 4,\\
  \sqrt{-m} & \text{ otherwise,}
\end{cases}
\end{align}
and recall that $\calO_m = \ZZ[\omega]$ is the ring of integers of $K_m$.
In the first case we have the minimal polynomial $f^\ZZ_\omega(\omega) = \omega^2-\omega+m'= 0$ 
where $4m'-1 = m$, and in the second case $f^\ZZ_\omega(\omega) = \omega^2 +m = 0$.  
Since $\tau$ is in  $K_m$, we can choose integers $a,b,c$ with $\gcd(a,b,c) = 1$ such that $\tau = \frac{a+b\omega}{c} \in K_m$.
Calculate
\begin{align}
    \trace A_\tau &= \begin{cases}
    (2a+b)/c & \text{ if } m \equiv 3 \mod 4,\\
  2a/c & \text{ else,}
\end{cases}\\
        \det A_\tau &=\begin{cases}
  (a^2 + ab +b^2m')/c^2 & \text{ if } m \equiv 3 \mod 4,\\
  (a^2 + b^2m)/c^2 & \text{ else;}
\end{cases}
\end{align}
where $\trace A_\tau$ and $\det A_\tau$ are the trace and determinant of the linear map $z \mapsto \tau z$ .
Thus, the minimal polynomial over $\QQ$ of $\tau$ is the characteristic polynomial of $A_\tau$:
%-------------------------------------------------------
\begin{align} 
    \label{eq:MinPolyTau}
%-------------------------------------------------------
    f^\QQ_\tau(\tau) = \tau^2 - \trace A_\tau \tau + \det A_\tau.
    %= \tau^2 - \frac \normTr c + \frac \normDet {c^2} =  0;
\end{align}
%we have written $\normTr = c \trace A_\tau \in \ZZ$ and $\normDet = c^2 \det A_\tau \in \ZZ$ for convenience.


%=======================================================
\subsubsection{Generators for \texorpdfstring{$R_\EC$}{R}}
    \label{sub:GeneratorsForRE}
%=======================================================
    Consider the isomorphism $(x, y) \mapsto x \cdot 1 + y \cdot \tau$ between $\ZZ^2$ and $\Lambda$. 
    Since $R$ is a subgroup of $\Lambda \isom \ZZ^2$ with $1 \in R$, 
    we conclude that $R$ is equal to $\langle 1, N \tau \rangle$ for some non-zero integer~$N$.
    As a consequence of Equation~\eqref{eq:MinPolyTau} and the fact that $N\tau^2$ must have integral coordinates in the basis  $\aset{1, \tau}$ we get that:
%-------------------------------------------------------
\begin{lm} 
    %\label{lm:GeneratorsForR}
    \label{lm:MinimalPolynomialTau}
%-------------------------------------------------------
    We have that $R = \langle 1, N \tau \rangle$ 
    if and only if 
    $N f^\QQ_\tau$ equals the primitive minimal polynomial  $f^\ZZ_\tau$ of $\tau$ over $\ZZ$.
\end{lm}

%-------------------------------------------------------
%\begin{proof} 
%-------------------------------------------------------

%\end{proof}

We assume that $N$ is positive, and calculate:
%In fact, we can calculate:

%-------------------------------------------------------
\begin{lm} 
    \label{lm:FormulaForN}
%-------------------------------------------------------
We have that  
\[
   N = c^2/\gcd(c, c^2\det A_\tau).
\]
\end{lm}

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    This follows from clearing up denominators from $\trace A_\tau$ and  $\det A_\tau$ in Equation~\eqref{eq:MinPolyTau}. 
    The equalities
    \begin{align*}
        \gcd(c^2, (2a+b)c, a^2+ab+b^2m') &= \gcd(c, a^2+ab+b^2m') & & \text{ if } m\equiv 3 \mod 4, \\
        \gcd(c^2, 2ac, a^2+b^2m) &= \gcd(c, a^2+b^2m) && \text{ otherwise};
    \end{align*}
    hold by the hypothesis $\gcd(a,b,c)=1$ and the claimed result follows.
%$\gcd(c/\gcd(\trace ), c^2)$ 
\end{proof}

%-------------------------------------------------------
\begin{re} 
    \label{re:OrdersOfNumberRings}
%-------------------------------------------------------
    An order in a number field $K$ is a subring whose additive group is finitely generated of rank equal to $[K:\mathbb Q]$.
    Thus, $R_\EC$ is an order in $K_m$.

%    This can be obtained already from the fact that $R_\EC$ is a subring of $\calO_m$, but we need the explicit generators for further calculations.
    %see https://math.stackexchange.com/questions/3090454/subrings-of-quadratic-integer-ring
\end{re}


%=======================================================
\section{Arrangements}
    \label{sec:Arrangements}
%======================================================= 
    A central \textit{abelian arrangement} $\Arrangement$ is a collection of codi\-men\-sion-1 Lie subgroups
    $H_1, \dots, H_k$ in $G^n$ where $G$ is an abelian Lie group. 
    The subgroups $H_i$ are of the form $\ker \phi_i$ for some $\phi_i \in \Hom (G^n,G)$.
    %We are interested in the central case, i.e.~$H_i = \ker \phi_i$ for a morphism $\phi_i$ from  $G^n$ to some group~$G$.
    Let $\CM(\Arrangement) = G^n \setminus \bigcup_{i \in [k]} H_i $ be the complement;
    the study of the topology of $\CM(\Arrangement)$ is one of the motivations to study $\Arrangement$.
    We recall the affine and toric cases, 
    to motivate our elliptic setting.

\subsection{Abelian arrangements}
%-------------------------------------------------------
\subsubsection{Hyperplane arrangements}
    \label{subsub:HyperplaneArrangements}
%------------------------------------------------------- 
    Here $G = (K,+)$ for some field $K$ and $\phi_i$ is some functional in $\Hom(K^n, K)$, thus $H_i$ is a hyperplane.
A result by Orlik and Solomon establishes that an important combinatorial invariant of $\Arrangement$ is the \emph{lattice of intersections} $\calL(\Arrangement)$, 
i.e.~affine spaces $\aset{\bigcap_{i \in S} H_i \suchthat S \subset [k]}$ partially ordered by reverse inclusion.  
From $\calL(\Arrangement)$ one can reconstruct some topological data of the complement $\CM(\Arrangement)$: 
cohomology when $K = \mathbb C$, 
number of connected components when $K = \RR$,
number of points when $K$ is a finite field $\FF_q$.
See \cite[Theorem~3.5]{dim17} for an introduction.

It turns out that $\calL(\Arrangement)$ as a lattice is semimodular and atomic, thus cryptomorphically is a matroid, realizable over $K$, on the groundset $[k]$; see \cite[Section~1.7]{oxl06}.
Our philosophy is to generalize the matroid approach.

%-------------------------------------------------------
\subsubsection{Toric arrangements}
    \label{subsub:ToricArrangements}
%------------------------------------------------------- 
 Here $G = (\CC^*,*)$ is the multiplicative group and $\phi_i$ is some character in $\Hom((\CC^*)^n, \CC^*)\simeq \ZZ^n$, 
so $H_i$ is a union of subtori of codi\-men\-sion~1. 
We will not consider here the case of subtori of arbitrary codimension, 
which has been studied in \cite{mp22}. 
Write $\Arrangement_S$ for the intersection $\bigcap_{i \in S} H_i$ for some $S \subset [k]$.
In the toric and elliptic cases $\Arrangement_S$ is generally not connected.
We call an element of $\CoCo{\Arrangement_S}$ a \emph{layer}, 
i.e. a connected component of $\Arrangement_S$.
All layers of $\CoCo{\Arrangement_S}$ have the same dimension. 
If $\ell_1$ and $\ell_2$ are layers such that $\card \CoCo{\ell_1 \cap \ell_2} \ge 2$,
there is no unique minimal upper bound of $\ell_1$ and $\ell_2$
in the poset $\aset{\bigcap_{i \in S} H_i \suchthat S \subset [k]}$,
so we do not have a lattice. 
Thus, we call $\calC(\Arrangement)$ the \emph{poset of layers}.

This also means that $\calC(\Arrangement)$ cannot correspond to a matroid. 
This is partially fixed in \cite{moc12a} by considering the triple $([k], \rk, m)$
of the functions $\rk S = \codim A_S$ and $m(S) = \card \CoCo{\Arrangement_S}$.
These satisfy some axioms that are christened an \emph{arithmetic matroid} in \cite{dm13, bm14}.
The arithmetic matroid contains enough information to define an arithmetic Tutte polynomial that,
like in the hyperplane case, yields important invariants as evaluations \cite{moc12a}.
For example:
the Poincare polynomial, whose coefficients encode the Betti numbers of the complement $\CM(\Arrangement)$; 
the characteristic polynomial of $\calC(\Arrangement)$, associated with any poset and containing homological information of its order complex. 

%-------------------------------------------------------
\subsubsection{Elliptic arrangements}
    \label{subsub:EllipticArrangements}
%------------------------------------------------------- 
    Here $G = \EC$ for some elliptic curve $\EC = \CC / \Lambda$ and $\phi_i$ is in $\Hom(\EC^n, \EC)$.
    By \Cref{sub:EllipticCurvesWithComplexMultiplication} we regard $\phi_i$ as a scalar product $\phi_i(p) = \langle \alpha_i, p \rangle$ with $\alpha_i = (\alpha_{i1}, \dots, \alpha_{in}) \in R^n$.
    Let $A$ be the matrix $(\alpha_{ij})$.
    It gives rise to maps $\AR \colon  R^n \to R^k$, $\AL \colon \Lambda^n \to \Lambda^k$, $\ACC \colon \CC^n \to \CC^k$ and $\AEC \colon \EC^n \to \EC^k$, 
    and for convenience if we omit the subscript then we mean $\AL$.

Like in the toric case, we are interested in the number of layers in $\Arrangement_S$ for $S \subset [k]$.
%To describe $\Arrangement_S$ let $A_S$ be the submatrix of $A$ of those rows indexed by $i \in S$. 
%Likewise write $A^R_S$, $A^\Lambda_S$, etc.~for the maps as before.
Note that $\ker \alpha_i = \ker \res i  \AEC$ is the $i$-th subvariety in $\Arrangement$.
Thus, $\Arrangement_S = \bigcap_{i \in S} H_i = \ker \res S \AEC$.
We claim the following identity:

%-------------------------------------------------------
\begin{lm} 
    \label{lm:NumberOfLayers}
%-------------------------------------------------------
    Let $\Arrangement$ be an elliptic arrangement in $\EC^n$. % where $\EC$ is an elliptic curve with complex multiplication.
    For all $S \subset [k]$ the number of layers in $\Arrangement_S$ is:
 \[
     m(S) := \card \CoCo{\Arrangement_S} = \card \tor{\coker \res S \AL}.
 \] 
\end{lm}

For the proof, we find a short exact sequence with the middle term $\Arrangement_S$ such that the sequence splits, giving us a decomposition of $\Arrangement_S$ from which we derive the result. 
Consider the following diagram, where the second and third rows describe the elliptic arrangement
and the first and fourth make an exact sequence, with $\partial$ the map obtained via the snake lemma:    %-------------------------------------------------------
