To simplify notation, for the remainder of this subsection we write $A$ instead of $\res S A$.

We write $\rad \im A = \Lambda^S \cap \im A $ for the \emph{radical} of $\im A$, 
i.e.~the elements in $\Lambda^S$ such that they have a non-zero multiple in $\im A$.
We obtain our desired short exact sequence:
%-------------------------------------------------------
\begin{lm} 
    \label{lm:SESNumberLayers}
%-------------------------------------------------------
    Let $\Arrangement$ be an elliptic arrangement in $\EC^n$. % where $\EC$ is an elliptic curve with complex multiplication.
    For all $S \subset [k]$ we have the following SES:
%-------------------------------------------------------
 \begin{equation}
          0 \rightarrow \faktor{\ker \ACC}{\ker \AL} \rightarrow \Arrangement_S \rightarrow \im \partial \rightarrow 0.
			\label{SES:NumberOfComponents}
 \end{equation}
Moreover, this sequence splits as $\ZZ$-modules.
\end{lm}

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    From the first and fourth row of Diagram~\ref{dia:SnakeLemma} and the snake lemma we readily get the SES~\eqref{SES:NumberOfComponents}.
Note that $\faktor{\ker \ACC}{\ker \AL}$ is a divisible abelian group, 
thus as a $\ZZ$-module it is injective and the sequence splits as $\ZZ$-modules.
\end{proof}

%-------------------------------------------------------
\begin{proof}[Proof of \Cref{lm:NumberOfLayers}] 
%-------------------------------------------------------
The vector space $\ker \ACC \isom \CC^{n-r}$ is connected and so the quotient $\faktor{\ker \ACC}{\ker A}$ is too.
From \Cref{lm:SESNumberLayers} the number of connected components of $\Arrangement_S$ is equal to the one of $\im \partial$.

The result follows from $\rad \im (A_\Lambda)= (\im A_\CC) \cap \Lambda^S$ because 
\[\im \partial = \faktor{(\im A_\CC) \cap \Lambda^S}{\im A_\Lambda} \text{ and } \tor \coker A_\Lambda = \faktor{\rad \im (A_\Lambda)}{\im (A_\Lambda)}.\]
Consider the case of CM elliptic curve, let $K=\operatorname{frac}(R)$ and observe that $K^S \cap \im A_\CC  = \im A_K$, moreover every element in $K$ has a multiple in $\Lambda$, hence $\Lambda^S \cap\im A_K = \rad \im A_\Lambda$.
The proof for non CM elliptic curve is similar and we omit it.

Therefore $\im \partial = \tor{\coker A}$, from which the result follows.
\end{proof}

The behaviour of the SES~\eqref{SES:NumberOfComponents} is more intricate when regarded as $R$-modules.
This is explored in \Cref{sub:ModulesOverR}, including an example where the sequence does not split as $R$-modules.

\subsection{Description of connected components}
Now we focus on the description of the connected component of the identity of $\Arrangement_S$ as an abelian variety.

%-------------------------------------------------------
\begin{de} 
    \label{de:conductor}
%-------------------------------------------------------
 The conductor of $R_\EC$ is $f_\EC  := [\mathcal{O}:R_\EC]= \frac{bc}{\gcd(c,c^2\det A_\tau)}$. 
\end{de}


\begin{lm} Let us fix a complex multiplication elliptic curve $\EC$.
\label{lm:descr_conn_comp}
\begin{enumerate}
    \item Every connected component $\faktor{\ker A_\CC}{\ker A_\Lambda}$ of some elliptic arrangement in $\EC^n$ is a product of elliptic curves $\EC_i$ isogenous to $\EC$ such that $f_{\EC_i} \mid f_\EC$;
    \item Viceversa, every product of elliptic curves $\EC_i$ isogenous to $\EC$ such that $f_{\EC_i} \mid f_\EC$ is a connected component of some elliptic arrangement in $\EC^n$,
\end{enumerate}
\end{lm}
\begin{proof}
\begin{enumerate}
    \item
    Consider a connected component of $A_\EC \colon \EC^n \to \EC^k$, by the previous discussion or by \cite[Theorem 4.4 (c)]{AbVarProdEC} every such morphism arises as a morphism of $R_\EC$-module $A_R^T \colon R^k \to R^n$.
    Choosing a set of generators of $\tor \coker A_R^T$, we construct another morphism $B_\EC \colon \EC^n \to \EC^h$ such that $B_R^T \colon R^h \to R^n$ satisfies $\im B_R^T = \rad \im A_R^T$. This implies $\faktor{\ker A_\CC}{\ker A_\Lambda} = \ker B_\EC$ by \cite[Theorem 4.4 (b)]{AbVarProdEC}.
    The result follows immediately from \cite[Theorem 7.5]{AbVarProdEC} applied to $B_\EC$.
    \item Let $X$ be an abelian variety satisfying the hypothesis, by \cite[Theorem 7.5]{AbVarProdEC} it arises from a torsion-free $R$-module $M$. Choose a free presentation of $M$
    \[ R^k \to R^n \to M \to 0 \]
    by \cite[Theorem 4.4 (b)]{AbVarProdEC} it corresponds to a sequence 
    \[ 0 \to X \to \EC^n \to \EC^k\]
    hence $X$ is a layer of an arrangement of $k$ divisors in $\EC^n$.
\end{enumerate}
\end{proof}

\begin{remark}
    The techniques of \cite{AbVarProdEC,KaniCMelliptic} cannot be applied to the intersection of $\Arrangement _S$ but only to a connected component (layer). Indeed the functor $\SheafHom_R(-,\EC)$ that they consider is not fully faithful on torsion modules.
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Modules over \texorpdfstring{$R_\EC$}{Rℰ}}
    \label{sec:StructureOverEnd(E)}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Our central aim is to describe $\Arrangement_S$.
A good deal of our efforts are dedicated to studying the behaviour of the sequence 
 \[
     \zeta \colon 0 \rightarrow \quotient{\ker \ACC}{\ker A} \rightarrow \Arrangement_S \rightarrow \tor{\coker A} \rightarrow 0
\]
as modules over~$R_\EC$. 
We give some conditions under which $\zeta$ splits, and an example in which it does not.

%=======================================================
\subsection{An example of non-splitting}
    \label{sub:AnExampleOfNonSplitting}
%=======================================================
    If either $\tor{\coker A}$ is projective or $\quotient{\ker \ACC}{\ker A}$ is injective, 
    we get that $\zeta$ splits.
    The former only happens when $\tor{\coker A}$ is trivial, 
    because projective modules are torsion free.
    The latter offers more hope, as $\quotient{\ker \ACC}{\ker A}$ is divisible, 
    so we are done if we regard it over a principal ideal domain, e.g.~as $\ZZ$-module.
    Unfortunately, $R$ is not necessarily a PID,
    and quotients of $\CC^n$ by a lattice are not necessarily injective as $R$-modules;
    we illustrate this now.

%-------------------------------------------------------
\begin{ex} 
    \label{ex:LambdaNotInjective}
%-------------------------------------------------------
    Let $R = \ZZ[\sqrt{-3}]$ and $\Gamma = \left \langle 1, (1 + \sqrt{-3})/2 \right \rangle$.
    We claim that $\quotient \CC  \Gamma$ is not an injective $R$-module. 
    Consider the map $\AR \colon R^2 \to R$ given by $(x,y) \mapsto 2x + (1 + \sqrt{-3})y$.
    The kernel is generated by 
    \[
        \ker \AR = \left \langle 
        v = \begin{psmallmatrix} 2 \\ -1 + \sqrt{-3}  \end{psmallmatrix},  
        w = \begin{psmallmatrix} 1 + \sqrt{-3} \\ -2\end{psmallmatrix}  \right \rangle.
    \]
    Note that $w = (1 + \sqrt{-3})/2v$, 
    so the map $v \mapsto 1$ shows that $\ker \AR$ is isomorphic to $\Gamma$, 
    thus $\quotient \CC \Gamma$ is isomorphic to $\ker \ACC / \ker \AR$.

    Let $\iota \colon \im \AR \to R$ and $\pi \colon \CC \to \quotient{\CC}{\Gamma}$ be the canonical injection and surjection, respectively.
    We construct an $f \in \Hom_R(\im \AR, \quotient{\CC}{\Gamma})$ that cannot be extended to $R \to \quotient{\CC}{\Gamma} $.
    By the first isomorphism theorem, 
    a map $f$ in $\Hom_R(\im \AR, \quotient{\CC}{\Gamma})$ is induced by 
    a map $R^2 \to \quotient \CC \Gamma$ that vanishes on $\ker \AR$. 
    This gives the following conditions:
    %-------------------------------------------------------
    \begin{equation}
    \begin{split} 
        \label{eq:sizygies}
    %-------------------------------------------------------
        2 f(2) &\equiv (1 - \sqrt{-3}) f(1+\sqrt{-3})  \mod \Gamma, \\
        (1 + \sqrt{-3}) f(2) &\equiv 2 f(1+ \sqrt{-3})  \mod \Gamma.
    \end{split}       
    \end{equation}
    We take the following values:
    %-------------------------------------------------------
    \begin{align*} 
    %-------------------------------------------------------
      f(2) &= 0 &
      f(1 + \sqrt{-3}) &= \dfrac{1}{ 1 - \sqrt{-3}}.
    \end{align*}
    Suppose $g \colon R \to \quotient \CC \Gamma$ lifts $f$. 
    For some $\gamma \in \Gamma$ we have that
    \[(1 + \sqrt{-3})g(1) =  g(1 + \sqrt{-3}) = f(1 + \sqrt{-3}) = \frac{1}{ 1 - \sqrt{-3}} + \gamma. \]
    Thus, 
    \[
        2g(1) = 2 \left( \frac{1}{ (1+\sqrt{-3}) (1 - \sqrt{-3})} + \frac{\gamma}  {1 + \sqrt{-3}} \right)  = \frac 1 2 + \frac{2\gamma}{1+\sqrt{-3}}.
    \]
    Finally, a quick calculation on the generators verifies that
    $\frac{2}  {1 + \sqrt{-3}} \Gamma = \Gamma$, hence $g(2) \equiv 1/2 \mod \Gamma$, a contradiction.
    Therefore $\quotient \CC  \Gamma \isom \quotient {\ker \ACC}{\ker \AR}$ is not injective.
\end{ex}

The failure of injectivity of $\quotient{\ker A_\CC}{\ker A}$ sets the stage for the failure of the sequence to split, 
which we verify by considering $A$ in the ambient space $(\quotient{\CC}{\ZZ[\sqrt{-3}]})^2$.

%-------------------------------------------------------
\begin{ex} 
    \label{ex:SequenceNotSplits}
%-------------------------------------------------------
    Let $A$ be the matrix from \Cref{ex:LambdaNotInjective}. 
    We study the arrangement defined by $A$ in the ambient space $(\CC / \Lambda)^2$ with $\Lambda = \ZZ[\sqrt{-3}]$.
    That is, the parameters are $m=3$ and $\tau= \sqrt{-3}$.
    Set $S = \aset{1, 2}$, so $\Arrangement_S = \ker \AEC = \aset{z \in \CC \suchthat \ACC(z) \in \ZZ[\sqrt{-3}]  } / (\ZZ[\sqrt{-3}])^2$.
    By \Cref{lm:FormulaForN} we have $N = 1$, so $R$ equals $\ZZ[\sqrt{-3}]$ as well. 
    Thus, $\ker A = \ker A_R$ and \Cref{ex:LambdaNotInjective} tells us that $\quotient{\ker A_\CC}{\ker A}$ is not injective, so there is a chance that $\zeta$ does not split.
    Over $\ZZ$ we have
    \begin{align}   
        \label{eq:NonRealizableAsToric}
        \AZZ = 
      \begin{pmatrix} 2 & 0 & 1 & -3 \\ 
            0 & 2 & 1 & 1 
          \end{pmatrix}.
    \end{align} 
    Hence, $\card{\tor{\coker A}} = \gcd(2 \times 2\text{ minors of } A) = 2$ and so $\tor \coker A \isom \quotient \ZZ {2\ZZ}$.
    This suggests to take $\zeta$ and look at elements of order~2 in each of the modules.
    Given a group $X$, write $X[2]$ for its 2-torsion, i.e.~elements $x$ such that $2x = 0$.
    First, we have $(\tor \coker A)[2] = \tor \coker A \simeq R/I$ where $I=(2,1+\sqrt{-3})$.
    Since the short exact sequence $\zeta$ splits as $\ZZ$-module, we have
    \[
      \zeta[2] \colon 0 \to \quotient{\ker \ACC}{\ker A}[2] \to \Arrangement_S[2] \to \tor \coker A[2] \to 0
    \] 
    as $R$-modules.
    Since $\quotient{\ker \ACC}{\ker A}$ is an elliptic curve, its order-2 points are generated by $v/2$ and $w/2$, with $v$ and $w$ as in \Cref{ex:LambdaNotInjective}.
    Namely,
   \[  (\quotient{\ker \ACC}{\ker A})[2] = \aset{
        \begin{psmallmatrix} 0 \\   0 \end{psmallmatrix},  
        \begin{psmallmatrix} 1 \\   (-1 + \sqrt{-3})/2  \end{psmallmatrix},  
        \begin{psmallmatrix} (1 + \sqrt{-3})/2 \\ -1\end{psmallmatrix}  
        \begin{psmallmatrix} (3 + \sqrt{-3})/2 \\ (-3 + \sqrt{-3})/2  \end{psmallmatrix}  }
        \simeq \left( \faktor{R}{I} \right) ^2. \]
    We have that $\card \Arrangement_S[2] = (\card \quotient{\ker \ACC}{\ker A}[2]) \cdot (\card \tor \coker A[2]) = 8$ since $\zeta[2]$ is an exact sequence over $\ZZ$.
    We already have four elements coming from the injection of $\quotient{\ker \ACC}{\ker A}$, plus the element $(1/2, 0)$ we had found before, so we compute:
    %-------------------------------------------------------
    \begin{align*} 
    %------------------------------------------------------- 
        (\Arrangement_S)[2] = & \left \{ 
        \begin{psmallmatrix} 0 \\   0 \end{psmallmatrix},  
        \begin{psmallmatrix} 0 \\   (-1 + \sqrt{-3})/2  \end{psmallmatrix},  
        \begin{psmallmatrix} (1 + \sqrt{-3})/2 \\ 0\end{psmallmatrix}  
        \begin{psmallmatrix} (1 + \sqrt{-3})/2 \\ (-1 + \sqrt{-3})/2  \end{psmallmatrix} \right. ,   \\
         & \left.  \phantom{\{} \begin{psmallmatrix} 1/2 \\   0 \end{psmallmatrix},  
        \begin{psmallmatrix} 1/2 \\   (-1 + \sqrt{-3})/2  \end{psmallmatrix},  \begin{psmallmatrix} \sqrt{-3}/2 \\ 0\end{psmallmatrix}, \begin{psmallmatrix} \sqrt{-3}/2 \\ (-1+\sqrt{-3})/2  \end{psmallmatrix} \right \} \simeq \faktor{R}{I} \times \faktor{R}{(2)}.
    \end{align*}
    In particular, $\zeta[2]$ does not split.
    Therefore $\zeta$ does not split, as a splitting of $\zeta$ would give a splitting of $\zeta[2]$.
\end{ex}

%=======================================================
\subsection{Splitting of \texorpdfstring{$\Arrangement_S$}{A sub S} }
    \label{sub:DoesTheSESSplit}
%=======================================================
    Choose $S \subseteq [k]$ and for brevity write $A$ instead of $A_S$.
    We now relate the splitting of the sequence 
 \[
     \zeta \colon 0 \rightarrow \faktor{\ker \ACC}{\ker A} \rightarrow \Arrangement_S \rightarrow \tor{\coker A} \rightarrow 0
\]
    with the splitting of the sequence
 \[
	 \eta \colon 0 \rightarrow \ker A \rightarrow \Lambda^n \rightarrow \im A \rightarrow 0.
\]
    The left term of $\zeta$ is described by the sequence
 \[
     \mu \colon 0 \rightarrow \ker A \rightarrow \ker \ACC \rightarrow  \faktor{\ker \ACC}{\ker A}  \rightarrow 0,
\]
    and the right one by 
 \[
	 \nu \colon 0 \rightarrow \im A \rightarrow \rad \im A \rightarrow  \tor \coker A   \rightarrow 0.
\]
Recall that $\zeta$ and $\eta$ correspond to classes in the ext groups $\Exti 1 {\tor \coker A} {\quotient{\ker \ACC}{\ker A} }$ and $\Exti 1 {\ker A} {\im A}$, respectively. 
We relate these two groups:

%-------------------------------------------------------
\begin{lm} 
    \label{lm:Diagramone}
%-------------------------------------------------------
    The Diagram~\ref{dia:BigDiagram} of exact sequences commutes.

%-------------------------------------------------------
\begin{figure}[ht!]
%-------------------------------------------------------
 \center
\begin{tikzcd}[scale=0.9,column sep=tiny]
& 0 \arrow[d]                                                                  & {\Hom(\im A, \ker A)} \arrow[d]                      &   \\
0 \arrow[d] \arrow[r]                              & {\Hom(\tor{\coker A}, \quotient {\ker \ACC}{\ker A})} \arrow[d] \arrow[r]   & \Exti 1 {\tor{\coker A}}{\ker A} \arrow[d] \arrow[r] & 0 \\
{\Hom(\rad \im A, \ker \ACC)} \arrow[r] \arrow[d] & {\Hom(\rad \im A, \quotient {\ker \ACC}{\ker A})} \arrow[r] \arrow[d]       & \Exti 1 {\rad \im A}{\ker A} \arrow[d] \arrow[r]     & 0 \\
{\Hom(\im A, \ker \ACC)} \arrow[r] \arrow[d]      & {\Hom(\im A, \quotient {\ker \ACC}{\ker A})} \arrow[r] \arrow[d]            & \Exti 1 {\im A}{\ker A} \arrow[d] \arrow[r]          & 0 \\
0 \arrow[r]                                        & \Exti 1 {\tor{\coker A}}{\quotient {\ker \ACC}{\ker A}} \arrow[r] \arrow[d] & \Exti 2 {\tor{\coker A}}{\ker A} \arrow[d]    \arrow[r]       &  0 \\
& \Exti 1 {\rad \im A }{\quotient {\ker \ACC}{\ker A}} \arrow[r]               & \Exti 2 {\rad \im A}{\ker A}                         &  
\end{tikzcd}
            \renewcommand{\figurename}{Diagram}
            \caption{}
			\label{dia:BigDiagram}
            \renewcommand{\figurename}{Figure}
\end{figure}
\end{lm}
%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------  
    Combine $\mu$ and $\nu$ using the bifunctoriality of $\Hom(-, -)$.
    Most of the zeros follow from the fact that $\ker \ACC$ is a $\CC$-vector space, 
    thus is an injective $R$-module,
    hence $\Exti 1 - {\ker \ACC}$ is zero.
    Moreover, $\Hom(\tor \coker A, \ker \ACC)$ is zero because $\ker \ACC$ being a $\CC$-vector space has trivial torsion.
\end{proof}
    Looking at the middle term of the 4th row of Diagram~\ref{dia:BigDiagram},
    if there were an $f \in \Hom(\im A, \quotient{\ker \ACC}{\ker A} )$ that lifts both $\zeta$ and $\eta$, 
    we could perform diagram chasing to relate $\zeta$ and $\eta$.
    Since $\ACC$ is a map of vector spaces, there exists a section $s \colon \im \ACC \to \CC^n$ with $\ACC \circ s = \id_{\im \ACC}$.
    Consider $f \colon \im A \to \quotient{\ker \ACC}{\ker A}$ given by
\[
  A\lambda \mapsto s(A\lambda) - \lambda.
\]
    This is well defined because for another $\lambda'$ such that $A\lambda = A\lambda'$ 
    we have that $A(\lambda - \lambda') = 0$, so $\lambda - \lambda'$ is in $\ker A$ and $(s(A\lambda) - \lambda) - (s(A\lambda') - \lambda') \equiv 0 \mod \ker A.$ 
We show that $f$ is mapped on the one hand to $[\zeta]$, and on the other to~$-[\eta]$.

%-------------------------------------------------------
\begin{lm} 
    \label{lm:fMapsToZeta}
%-------------------------------------------------------
In Diagram~\ref{dia:BigDiagram} we have that $f \mapsto [\zeta]$. 
\end{lm}

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    Let $Y$ be the pushout of $f \colon \im A \rightarrow \quotient{\ker \ACC}{\ker A}$ and $\iota \colon \im A \rightarrow \rad \im A$.
    By \cite[Lemma~7.28]{rot08} the following diagram commutes
%-------------------------------------------------------
\begin{figure}[ht!] \center
%-------------------------------------------------------
\adjustbox{scale=1}{%
\begin{tikzcd}
0 \arrow[r] & \im A \arrow[r, "\iota"] \arrow[d, "f"]               & \rad \im A \arrow[r] \arrow[d] & \tor \coker A \arrow[r] \arrow[d, equal] & 0 \\
0 \arrow[r] & \quotient{\ker \ACC}{\ker A} \arrow[r] & Y \arrow[r]                    & \tor \coker A \arrow[r]           & 0.
\end{tikzcd}
}
            \renewcommand{\figurename}{Diagram}
            \caption{}
			\label{dia:fMapsToZeta}
            \renewcommand{\figurename}{Figure}
\end{figure}
Applying the functor $\Hom(-, \quotient{\ker \ACC}{\ker A})$ gives that $f$ maps to the class of the bottom row in the corresponding ext group.
Thus, we are done if the bottom row is equivalent to $\zeta$. 
    We deal first with the square on the left. 
    Consider the diagram:
%-------------------------------------------------------
\begin{center}
%-------------------------------------------------------
\begin{tikzcd}[column sep = tiny, row sep = small]
\im A \arrow[r] \arrow[d]                                                 & \rad \im A \arrow[d] \arrow[rdd, "s", bend left] &                  \\
\quotient{\ker \ACC}{\ker A} \arrow[r] \arrow[rrd, "\iota"', bend right] & Y \arrow[rd, "g"]                                     &                  \\
   &              & \Arrangement_S
\end{tikzcd}
\end{center}
    The diagram commutes:
    take an arbitrary element $A\lambda$ in $\im A$. 
    Going right and then down we have $A \lambda \mapsto s(A\lambda)$; down and right gives $A \lambda \mapsto s(A \lambda) - \lambda$.
    The difference of both images is $s(A \lambda) - (s(A \lambda) - \lambda) = \lambda \equiv 0 \mod \Arrangement_S \subset \CC^n/\Lambda^n$.
    Thus, the outer square commutes and by the universal property of the pushout the map $g\colon Y \mapsto \Arrangement_S$ exists.
    We argue that $g$ is an isomorphism.

    Recall that $Y$ can be taken equal to $\quotient{\ker \ACC}{\ker A} \oplus \rad \im A$ 
    quotiented by the submodule $\langle (-f(\lambda), \lambda) \mid \lambda \in \im A \rangle$.
    In this presentation $g$ is given by $(z, \lambda) \mapsto z + s(\lambda)$.

    Surjectivity of $g$: take an element in $\Arrangement_S$ with representative $z \in \CC^n$. 
    Thus, $\ACC(z) \in \Lambda^S$ and $\lambda := \ACC(z) \in \rad \im A = \Lambda^S \cap \im A_\CC$.
    In particular, $z-s(A_\CC(z)) \in \ker A_\CC$ and 
    \[ g((z-s(A_\CC(z)), A_\CC(z)))= z-s(A_\CC(z)) + s(A_\CC(z)) = z.\]

    Injectivity of $g$: 
    take $z \in \ker \ACC$ and $\lambda \in \rad \im A$ and
    suppose that $(z, \lambda) \in \ker g$, i.e.~$z + s(\lambda) = \mu$ for some $\mu$ in $\Lambda^n$.
    %Applying $\ACC$, 
    Since $z \in \ker \ACC$, we have $\lambda = \ACC \circ s (\lambda) = A(\mu)$.
    So $\lambda$ is in $\im A$; also $f(\lambda) = s(\lambda) - \mu = -z$.
    Thus, $(z, \lambda) = (-f(\lambda), \lambda) \equiv 0$ in $Y$, as desired.

    To prove the equivalence it remains to show that $Y \rightarrow \tor \coker A$ equals $\partial \circ g$.
    Given $(z, \lambda)$ as before, the former map sends it to $\lambda$ in $\tor \coker A$.
    The latter map first sends it to $z +s(\lambda)$, 
    and then $\partial$ sends it to $\ACC(z + s(\lambda))$, which equals $\lambda$.
\end{proof}
The above lemma implies that the short exact sequence $\pi^*\zeta$ always splits, where $\pi \colon \rad \im A \to \tor \coker A$. However, we already know this fact because it is equivalent to the existence of the section $s$.

%-------------------------------------------------------
\begin{lm} 
    \label{lm:fMapsToEta}
%-------------------------------------------------------
    In Diagram~\ref{dia:BigDiagram} we have that $f \mapsto -[\eta]$. 
\end{lm}

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    Let $X$ be the pullback of $-f : \im A \rightarrow \quotient{\ker \ACC}{\ker A}$ and $\iota : \ker A \rightarrow \ker \ACC$.
    By \cite[Lemma 7.29]{rot08} the following diagram commutes: 
%-------------------------------------------------------
\begin{figure}[ht!]
%-------------------------------------------------------
 \center
\begin{tikzcd}
0 \arrow[r] & \ker A \arrow[r] \arrow[d, equal] & X \arrow[r] \arrow[d] & \im A \arrow[r] \arrow[d, "-f"]               & 0 \\
0 \arrow[r] & \ker A \arrow[r]           & \ker \ACC \arrow[r]  & \quotient{\ker \ACC}{\ker A} \arrow[r] & 0

\end{tikzcd}
    \renewcommand{\figurename}{Diagram}
    \caption{}
	\label{dia:fMapsToEta}
    \renewcommand{\figurename}{Figure}
\end{figure}

    The functor $\Hom(\im A, -)$ maps $-f$ to the class of the bottom row in the corresponding $\Ext^1$.
    Thus, we are done if the top row is equivalent to $\eta$. 
    We deal first with the square on the right. 
    Consider the diagram: 
%-------------------------------------------------------
\begin{center}
%-------------------------------------------------------
\begin{tikzcd}[column sep = tiny, row sep = small]
& \ker \ACC \arrow[r]  & \quotient{\ker \ACC}{\ker A} \\
\hat f                                                                    & X \arrow[r] \arrow[u] & \im A \arrow[u, "-f"]               \\
\Lambda^n \arrow[ru, "h"] \arrow[ruu, bend left] \arrow[rru, "A"', bend right] &                       &                              
\end{tikzcd}
\end{center}
where $\hat f$ sends $\lambda \in \Lambda^n$ to $\lambda - s(A\lambda)$;
this $\hat f$ makes the diagram commute.
Thus, by the universal property of the pullback we have a map $h : \Lambda^n \mapsto X$.

Recall that $X$ can be taken to be the sub-module of $\ker \ACC \oplus \im A$ of pairs $(z, A\lambda)$ such that $z \equiv -f(\lambda) \mod \ker A$, and so $h$ maps $\lambda$ to $(\hat f(\lambda), A\lambda)$.
Suppose the latter pair is $(0,0)$ in $X$, so $A\lambda = 0$, and $0 = \hat f(\lambda) = \lambda - s(A\lambda)  = \lambda$,
which proves injectivity.
On the other hand, given an arbitrary element $(z, A\lambda)$ of $X$, we have  $z \equiv -f(\lambda) \mod \ker A$ and $z = \lambda - s(A\lambda) + \mu$ for some $\mu \in \ker A$.
Therefore $\hat f(\lambda + \mu) = \lambda + \mu - f(A(\lambda + \mu)) = \lambda - s(A\lambda) + \mu = z$, thus $\lambda - \mu$ maps to $(z, A \lambda)$, proving surjectivity.

Lastly, $\lambda \in \ker A$ gets mapped to $(\hat f(z), A\lambda) = (\lambda, 0)$ in $X$, showing that the bottom row is equivalent to  $\eta$, so $-f$ maps to $[\eta]$.
Since $\Ext^1$ is a group, we conclude that $f$ maps to $-[\eta]$.
\end{proof}

    In the following write $\pi \colon \ker \ACC \to \quotient{\ker \ACC}{\ker A}$ and $\iota \colon \im A \to \rad \im A$ for the canonical projection and immersion, respectively.
    The previous three results give:

%-------------------------------------------------------
\begin{prop} 
    \label{prop:DiagramChasing}
%-------------------------------------------------------
    The element $[\eta]$ is in $\im \Exti 1 {\iota} {\ker A}$ if and only if the sequence $\zeta$ splits.
\end{prop}

%-------------------------------------------------------
\begin{proof} 
Notice that by \Cref{lm:fMapsToZeta} and \Cref{lm:fMapsToEta} the image of $[\eta]$ and the one of $[\zeta]$ in $\Ext^2(\tor \coker A, \ker A)$ coincide.
The sequence $\zeta$ splits if and only if the image of $[\zeta]$ in $\Ext^2(\tor \coker A, \ker A)$ is zero.
The latter is equivalent to $\eta \in \im \Exti 1 {\iota} {\ker A}$.
\end{proof}

As a corollary we get sufficient easy conditions for the splitting of $\zeta$.

 %-------------------------------------------------------
\begin{cor} 
    \label{cor:RDedekindZetaSplits}
%-------------------------------------------------------
    If $R$ is Dedekind, then the sequence $\zeta$ splits.
\end{cor}
%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    If $R$ is Dedekind, all $\Ext^2$ groups vanish, so 
    $\Ext^1(\iota, \ker A)$ is surjective, thus $[\eta]$ lifts.
    Alternatively, if we regard the fifth row of Diagram~\ref{dia:BigDiagram} we see that $\Ext^1(\tor \coker A, \quotient{\ker \ACC}{\ker A})$ vanishes when $\Ext^2$ vanishes.
\end{proof}
If the map $A_S \colon \Lambda^n \to \im A_S$ has a section then the extension $\zeta$ is trivial, indeed:
 %-------------------------------------------------------
\begin{cor} 
    \label{cor:EtaSplitsZetaSplits}
%-------------------------------------------------------
    If $\eta$ splits, then the sequence $\zeta$ splits.
\end{cor} 

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    If $\eta$ splits then $[\eta] = 0$ in $\Ext^1(\im A, \ker A)$ and the zero class always lifts.
\end{proof}


%=======================================================
    \subsection{The lattice \texorpdfstring{$\Lambda$}{Λ}}
    \label{sub:ModulesOverR}
%=======================================================
As $\ZZ$-module we have that $\Lambda \isom \ZZ^2$, thus it is free.
As $R$-module we have that $\Lambda$ is not free because $R \isom \ZZ^2 \isom \Lambda$ as $\ZZ$-modules, 
$\Lambda \isom R$ would be the only option for freeness as $R$-module, 
but evidently this is not the case. 
Clearly $\Lambda$ is not injective either, since it is not divisible.
We show that $\Lambda$ is projective.

%-------------------------------------------------------
\begin{lm} 
    \label{lm:LambdaIsProjective}
%-------------------------------------------------------
   The lattice $\Lambda$ is a projective $R$-module.
\end{lm}

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------

    Recall that $R = \ZZ \oplus N\tau \ZZ$ and that $\Lambda = \ZZ \oplus \tau \ZZ$. 
    Since $\Lambda$ is closed under sums and $R \Lambda \subset \Lambda$, it is an $R$-module in $\Quot R$, 
    i.e.~a fractional $R$-ideal.
    Thus,  $\Lambda$ is projective if and only if it is invertible; see e.g.~\cite[Proposition~4.21]{rot08}. 
    We claim that $N \cdot \Lambda \cdot \sigma(\Lambda) = R$, where $\sigma$ is the automorphism of $\QQ[\sqrt{-m}]$ that sends $\sqrt{-m} \mapsto -\sqrt{-m}$. 
    Indeed, 
    \[
        I = N \cdot \Lambda \cdot \sigma(\Lambda) = N \cdot \langle 1, \tau \rangle \cdot \langle 1,  \bar \tau \rangle 
        = N \cdot \langle 1, \tau, \tau + \bar \tau, \tau \bar \tau \rangle.
    \]
    From the expression on the right, we see that $I \subset R$. 
    Moreover, $I$ contains $N(\tau + \bar \tau) = N \trace A_\tau $, also $N \tau \bar \tau = N \det A_\tau$, and $N$.
    By \Cref{lm:FormulaForN} these are the coefficients of the minimal polynomial of $\tau$ over $\ZZ$, so $\gcd(N \trace A_\tau, N \det A_\tau, N) = 1$, which means $1 \in I$ as desired.
\end{proof}

%=======================================================
\subsection{Multiplication by \texorpdfstring{$\alpha \in R$}{α ∈ R}}
    \label{sub:MultiplicationByAlpha}
%=======================================================
    Let $A \in \Mat_{k \times n}(R_\EC)$ encode an elliptic arrangement in $\EC^n$.
    Consider the induced maps $\AR \colon R^n \to R^k$ and $\AL \colon \Lambda^n \to \Lambda^k$. 
    As in \Cref{sub:EndomorphismRing}, we have $\tau = (a+b\omega)/c$ with $\gcd(a,b,c) = 1$.
    We will show that $R^k/\im A_R$ and $\Lambda^k/\im A_\Lambda$ are isomorphic as abelian groups.
    First, a motivating example that corresponds to smallest non-trivial case. 

%-------------------------------------------------------
\begin{ex}
    \label{ex:LambdaAlphaRAlpha}
%-------------------------------------------------------
When $n=k=1$ we have a map of the form $A_\alpha$ for some $\alpha = x + yN\tau \in R$. 
We claim that
\[
  \Lambda / \alpha \Lambda \isom R / \alpha R
\]
as $\ZZ$-modules.
For this we write $A_\alpha$ as a matrix $A$ in the basis $\aset{1, \tau}$ of $\Lambda$,  
and as a matrix $\tA$ in the basis $\aset{1, N\tau}$, and we compare their Smith normal form. 
Consider the integers $\normTr= c \trace A_\tau$, $\normDet = c^2 \det A_\tau$, $g= \gcd(c, \normDet)$, $c = gc'$ and $\normDet=g\normDet'$.
So  that $N = c^2/g = g(c')^2$, we get
\[
    A = \begin{pmatrix} x & -y \normDet'\\ 
      y g(c')^2 & x + y \normTr c' 
  \end{pmatrix}
  \quad \quad \quad
      \tA = \begin{pmatrix} x & -y \normDet'g(c')^2 \\ 
      y & x + y \normTr c'
  \end{pmatrix}
\]
Clearly $\det A = \det \tA$. We are done if we prove that the g.c.d. of the entries of $A$ and of $\tA$ coincide.  
By Euclidean algorithm this is equivalent to:
\[
  \gcd\left(x, 
  y\gcd\left(
    g(c')^2,
    \normDet',
    \normTr c'
\right) \right)  = 
\gcd\left(x, 
  y\gcd\left(
    1,
    \normDet'g(c')^2,
    \normTr c'
\right) \right) ,
\]
which is true if 
%-------------------------------------------------------
\begin{align} 
%-------------------------------------------------------
 \gcd\left(
    g(c')^2,
    \normDet',
    \normTr c'
\right)  = 1. 
\end{align}
By \Cref{lm:MinimalPolynomialTau} and \Cref{lm:FormulaForN}, 
these three numbers are the coefficients of the minimal polynomial $f_\tau^\ZZ$ of $\tau$ over the integers,
which implies the coprimality.
\end{ex}

Now we consider the general case. 
Consider the basis $\aset{1, \tau}$ of $\Lambda$, each entry of $\AL$ expands into a  $2\times2$ matrix, as in \Cref{ex:LambdaAlphaRAlpha}, to get a matrix in $\Mat_\ZZ(2k,2n)$ representing $\AL$. 
Likewise, the basis $\aset{1, N\tau}$ gives a matrix in $\Mat_\ZZ(2k,2n)$ representing $\AR$.
By reordering the bases, we can write:
\[
    \AL = \begin{pmatrix} X & -Y \normDet'\\ 
      Y N & X + Y \normTr c' 
  \end{pmatrix}
  \quad \quad \quad
      \AR = \begin{pmatrix} X & -Y \normDet'N \\ 
      Y & X + Y \normTr c'
  \end{pmatrix},
\]
with $X, Y \in \Mat_\ZZ(k,n)$. 
We claim that the cokernels of both matrices are isomorphic: 

%-------------------------------------------------------
\begin{lm} 
    \label{lm:CokernelsCoincide}
%-------------------------------------------------------
   Given $\AR \colon R^n \to R^k$ and $\AL \colon \Lambda^n \to \Lambda^k$ we have that
\[
  \Lambda^k / \AL(\Lambda^n) \isom R^k / \AR( R^n)
\]
as additive groups.
\end{lm}
%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    We regard $R$ and $\Lambda$ as $\ZZ$-modules and we write $A$ for $\AL$ and $\tA$ for $\AR$.
    By the structure theorem for finitely generated modules over PID, it is enough to prove that for all primes $p \in \ZZ$ the localizations 
    $A_{(p)} \colon (\ZZ_{(p)})^{2n} \to (\ZZ_{(p)})^{2k}$ and $\tA_{(p)} \colon (\ZZ_{(p)})^{2n} \to (\ZZ_{(p)})^{2k}$ 
    have isomorphic cokernels.
    This property is preserved by applying elementary row and columns operations.
    We distinguish three cases:
    \begin{description}
        \item [$p \nmid N$] since $N$ is invertible in $\ZZ_{(p)}$ we can multiply the second column of $\tilde{A}_{(p)}$ by $N^{-1}$ and the second row by $N$ and obtain the matrix $A_{(p)}$.
        \item [$p \nmid \delta'$] since $\normDet'$ is invertible in $\ZZ_{(p)}$ we can multiply the second column of $\tilde{A}_{(p)}$ by $-\normDet^{\prime -1}$ and the second row by $-\normDet'$ and obtain the matrix 
        \[ \begin{pmatrix} X & YN \\ 
      -Y \normDet' & X + Y \normTr c' 
  \end{pmatrix} 
  \sim %\extoverset[6pt]{$c_2 := c_2+\frac{\normTr c'}{\normDet'} c_1$}{\sim}
  \begin{pmatrix} X & YN+\frac{\normTr c'}{\normDet'} X \\ 
      -Y \normDet' & X
  \end{pmatrix} \sim \begin{pmatrix} X + Y \normTr c'  & YN \\ 
      -Y \normDet' & X
  \end{pmatrix}.
  \] 
        where firstly we added to the second column $\frac{\normTr c'}{\normDet'}$ times the first one and then to the first row $\frac{\normTr c'}{\normDet'}$ times the second one.
        Finally, by exchanging both rows and columns we obtain the matrix $A_{(p)}$.
        \item [$ p \mid N$ and $p \mid \delta'$]
    Let $I_k$ be the $k \times k$ identity, and $I_n$ the $n\times n$ identity. 
    We modify $A$ and $\tA$ so that the integer $N$ is replaced by another integer $N(s)$ coprime with $p$ and then the result follows from the first case.
    We have for some $s \in \ZZ$:
\begin{align*}
  A_{(p)}  & \sim
    \begin{pmatrix} I_k & 0\\ 
      -s I_k & I_k \end{pmatrix}
    \begin{pmatrix} X & -Y \normDet' \\ 
      YN & X + Y \normTr c'\end{pmatrix}
    \begin{pmatrix} I_n & 0\\ 
      s I_n & I_n \end{pmatrix} \\
      &= \begin{pmatrix} X - Ys\normDet'    & -Y \normDet' \\ 
      Y(N+ s \normTr c'+ s^2 \normDet') & X + Y(\normTr c'+s\normDet' )\end{pmatrix}  \\
  \tA_{(p)}  & \sim
    \begin{pmatrix} I_k & -\normDet' s I_k\\ 
      0 & I_k \end{pmatrix}
    \begin{pmatrix} X & -Y \normDet'N \\ 
      Y & X + Y \normTr c'\end{pmatrix}
    \begin{pmatrix} I_n & \normDet' sI_n\\ 
      0 & I_n \end{pmatrix} \\
      &= \begin{pmatrix} X - Ys\normDet'    & -Y \normDet' (N+s\normTr c'+ s^2\normDet')\\ 
      Y & X + Y(\normTr c'+s\normDet')\end{pmatrix} 
\end{align*}
Write $N(s)$ for $N+s\normTr c'+ s^2\normDet' $.   
We are done if there is a choice of $s$ such that $p \nmid N(s)$.
As in \Cref{ex:LambdaAlphaRAlpha}, we have $\gcd(\normDet', \normTr c', N) = 1$, so $p \nmid \normTr c'$, and we can choose any $s \not \equiv 0 \mod p$.
\qedhere
    \end{description}
\end{proof}

%-------------------------------------------------------
\begin{re} 
    \label{re:}
%-------------------------------------------------------
    \Cref{lm:CokernelsCoincide} is used implicitly in the proof of Theorem~6.1 and Theorem~6.2 of \cite{bm19}. 
    They only provide the justification for the 1-dimensional case, which corresponds to our \Cref{ex:LambdaAlphaRAlpha}.
\end{re}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Arithmetic matroid structure}
    \label{sec:ComatroidsOverRings}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%=======================================================
\subsection{Arithmetic matroids}
    \label{sub:ArithmeticMatroids}
%=======================================================
    Let $E$ be a finite set. 
    A \textit{matroid} on $E$ is given by a function $\rk \colon \powerset E \to \NN$ that satisfies:
    %-------------------------------------------------------
    \begin{enumerate}[label=(r\arabic*)]
    %-------------------------------------------------------
        \item \label{item:rk_normalized} $ \rk{\varnothing} =  0$,
        \item \label{item:rk_increasing} $\rk X \le \rk(X \cup i) \le \rk X + 1$ for every $X \subset E$ and $i \in E$,
        \item \label{item:rk_submodular} $\rk(X \cup Y) + \rk(X \cap Y) \le \rk X + \rk Y$ for every $X, Y \subset E$.
    \end{enumerate}
    These axioms are an abstraction of the following example, called the \emph{realizable case}:
    given a list $(v_e)_{e \in E}$ of vectors (indexed by $E$) in some finite dimensional vector space  $V$ over some field $K$, 
    set $\rk S = \dim_K \langle v_e \suchthat e \in S \rangle$ for every subset $S \subset E$. The vectors $(v_e)_{e \in E}$ define an arrangement of hyperplanes on the dual vector space $V^*$; the cohomology of the complement of this arrangement can be described explicitly in terms of the matroid. 

    On the other hand, the cohomology of the complement of a \textit{toric arrangement} is not determined by the matroid. Let us recall that a toric arrangement is a family of hypersurfaces in a complex torus $T=(\mathbb C^*)^n$, each hypersurface being  defined by a character $\chi\in Hom(T, \mathbb C^*)\simeq \mathbb Z^n$.
    We set $\rk S$ to be the rank of the submodule $\langle \chi_e \suchthat e \in S \rangle_\ZZ$.
    This satisfies axioms~\ref{item:rk_normalized},~\ref{item:rk_increasing}, and~\ref{item:rk_submodular}. 
    Consider also the number $m(S)$ of connected components in the intersection $\bigcap_{i \in S} H_i$.
    The question of axiomatizing $m(S)$ and studying its properties was addressed in \cite{dm13, bm14, dm18}; we now recall some basic facts.

    Denote by $[X,Y]$ the interval $\aset{S \subset E : X \subseteq S \subseteq Y}$ in $(\powerset E, \subseteq)$.
    We say that $[X,Y]$ is a \emph{molecule} if we can write $Y$ as a disjoint union $Y = X \sqcup F \sqcup T$ such that for each $S \in [X,Y]$ we have
    \[      \rk(S) = \rk(X) + \card{(X \cap F)}.    
    \]
    This amounts to saying that, after contracting the elements of $X$, the elements of $T$ become loops and the elements of $F$ become coloops.
    Now, an \emph{arithmetic matroid} is a matroid $(E, \rk)$ endowed with a \textit{multiplicity function} $m \colon \powerset E \to \NN$ such that the following axioms are satisfied:
    %-----------------------------------------------------
    \begin{enumerate}[label=(A\arabic*)]
    %-----------------------------------------------------
     \item \label{item:axiomA1} For all $S \subset E$ and $i \in E $: if $\rk(S \cup i) = \rk(S)$, 
       then $m(S \cup i)$ divides $m(S)$; 
       otherwise $m(S)$ divides $m(S \cup i)$.
      \item \label{item:axiomA2} If $[X,Y]$ is a molecule then
        \[ m(X) m(Y) = m(X \cup F) m(X \cup T).\]        
    \end{enumerate}
    %-----------------------------------------------------
    \begin{enumerate}[label=(P)]
    %-----------------------------------------------------
      \item \label{item:axiomP}  If $[X,Y]$ is a molecule, $Y = X \sqcup F \sqcup T$, then the number $ \rho(X,Y) $  given by
        \[
        \rho(X,Y) = (-1)^{|T|} \sum_{S \in [X,Y]} (-1)^{|Y|-|S|}m(S)
        \]
        is greater or equal than~0.
   \end{enumerate}
   In the realizable case, Axioms~\ref{item:axiomA1} and~\ref{item:axiomA2} hold by basic algebraic facts on injections, surjections and sums of modules, while Axiom~\ref{item:axiomP} expresses a count of connected components in a toric arrangement, through inclusion-exclusion.

%=======================================================
\subsection{The arithmetic matroid of an elliptic 
 arrangement}
    \label{sub:TheArithmeticMatroidAssociatedToAnArrangement}
%=======================================================
We now show that to an elliptic arrangement one can naturally associate an arithmetic matroid.

   %-------------------------------------------------------
   \begin{cons} 
       \label{cons:ArithmeticMatroidArrangement}
       %\label{lm:ArithmeticMatroidArrangement}
   %-------------------------------------------------------
       Let $\EC$ be an elliptic curve and let $A \in \Mat_{k \times n}(R_\EC)$ encode an elliptic arrangement in $\EC^n$.
       Given a subset $S \subset [k]$ define:
       %-------------------------------------------------------
       \begin{align*} 
       %-------------------------------------------------------
           \rk_\Arrangement(S) &= \codim \Arrangement_S    \\
           m_\Arrangement(S) &= \card \CoCo{\Arrangement_S}
       \end{align*}
   \end{cons}   
      Our aim is to show that the triple $([k], \rk_\Arrangement, m_\Arrangement)$ of Construction~\ref{cons:ArithmeticMatroidArrangement} is an arithmetic matroid, by proving that axioms~\ref{item:axiomA1},~\ref{item:axiomA2} and~\ref{item:axiomP} hold in this case.

      First, by \Cref{lm:NumberOfLayers} the multiplicity $m(S)$ equals $\tor{\coker A_S}$.
   For convenience, let us write $G_S$ for $\tor \coker A_S$.
   Note that if $X \subset Y$, then the natural projection $\pi \colon \Lambda^Y \to \Lambda^X$ induces a map $\barpi \colon G_Y \to G_X$ with the following properties.

    %-------------------------------------------------------
   \begin{lm} 
       \label{lm:ProjectionGS}
   %-------------------------------------------------------
       Let
       $S \subseteq [k]$ a set and $i \in [k] \setminus S$ an element. 
       Consider the map $\barpi \colon G_{S \cup i} \to G_S$.
       %-------------------------------------------------------
       \begin{enumerate} 
       %-------------------------------------------------------
         \item If $\rk(S \cup i) = \rk(S)$, then $\barpi$ is injective. 
         \item If $\rk(S \cup i) \ne \rk(S)$, then $\barpi$ is surjective. 
       \end{enumerate} 
   \end{lm}

   %-------------------------------------------------------
   \begin{proof} 
   %-------------------------------------------------------

           Let $e_i$ be the standard basis vector with $1$ in the $i$-th coordinate and zeros everywhere else.
           We observe that there exists a nonzero integer $k$ with $k e_i \in \im A_{S \cup i}$ if and only if $\rk(S \cup i) > \rk(S)$. 
           This is because $\rk(S \cup i) = \rk(S)$ if and only if 
           the $i$-th coordinate is linearly dependent on those indexed by $S$.
\begin{enumerate}
    \item
        let $\barv \in G_{S \cup i}$ be nonzero, and $v \in \Lambda^{S \cup i}$ a representative.
           So $mv \in \im A_{S \cup i}$ for a non-zero $m$.
           If $\barv \in \ker \barpi$, there is $x \in \Lambda^n$ such that $\pi(v) = A_S(x)$.
	   Thus, $v + \lambda e_i \in \im A_{S \cup i}$
           for $\lambda = A_{S \cup i}(x)_i - v_i$;
           also $m \lambda e_i = m(v + \lambda e_i) - mv$ is in $\im A_{S \cup i}$. 
           By the observation $m\lambda = 0$, so $\lambda = 0$ and $\ker \barpi$ is trivial.
    \item Let $\barv \in G_S$, and $v \in \Lambda^{S}$ a representative.
           So $mv \in \im A_{S}$ for a non-zero $m$, 
           thus by a similar argument as before there is $\lambda$ such that 
           $(mv, 0) + \lambda e_i$ is in $\im A_{S \cup i}$.
           Moreover, by the observation let $k \in \ZZ \setminus 0$ such that $k e_i \in \im A_{S \cup i}$.
           Thus, $km(v,0) = k((mv,0)+\lambda e_i) - \lambda (k e_i)$ is in $\im A_{S \cup i}$, 
           so $\overline{(v,0)}$ is a torsion element in $G_{S \cup i}$ and also a lift of $\overline v$,
           proving that $\overline \pi$ is surjective. \qedhere
\end{enumerate}            
   \end{proof}

   %-------------------------------------------------------
   \begin{cor} 
       \label{cor:SatisfiesA1}
   %-------------------------------------------------------
       The triple $([k], \rk_\Arrangement, m_\Arrangement)$ satisfies Axiom~\ref{item:axiomA1}.
   \end{cor}
   \begin{proof}
        For any $ S \subset [k]$ and $i \in [k] \setminus S $, if $\rk_\Arrangement(S \cup i) = \rk_\Arrangement(S)$ then $G_{S \cup i} \hookrightarrow G_S$ by \Cref{lm:ProjectionGS} and so $m_\Arrangement(S \cup i) \mid m(S)$ by \Cref{lm:NumberOfLayers}.
       Otherwise, $\rk_\Arrangement(S \cup i) = \rk_\Arrangement(S)+1$ and the surjection $G_{S \cup i} \twoheadrightarrow G_S$ implies $m_\Arrangement(S) \mid m_\Arrangement(S \cup i)$.
   \end{proof}

Next, if $[X,Y]$ is a molecule with $Y = X \sqcup F \sqcup T$ we can chain the maps from the previous lemma to get a commutative square. 
