%-------------------------------------------------------
   \begin{lm} 
       \label{lm:SatisfiesA2}
   %-------------------------------------------------------
       The triple $([k], \rk_\Arrangement, m_\Arrangement)$ satisfies Axiom~\ref{item:axiomA2}.
       That is, if $[X,Y]$ is a molecule with $Y = X \sqcup F \sqcup T$, we have that
   \[ m_\Arrangement(X) \cdot m_\Arrangement(X \sqcup F \sqcup T) = m_\Arrangement(X \sqcup F) \cdot m_\Arrangement(X \sqcup T). \]
   \end{lm}

   \begin{proof}
We complete Diagram~\ref{dia:Projection} with cokernels and apply the snake lemma to get Diagram~\ref{dia:MultiplicitySnakeLemma}.
