The result follows from the third column if we prove that $\ker \overline \psi$ is trivial, that is $\ker \varphi$ and $\ker \psi$ are isomorphic.
So we show that $\ker \varphi \to \ker \psi$ is surjective.
If $\bary$ is in $\ker \psi$, there is a representative in $\Lambda^{X \sqcup F}$ of the form $(0, v)$, where the zeros are for the coordinates indexed by $X$. 
There is a non-zero $m$ such that $(0, mv) = A_{X \sqcup F}(x)$ for some $x \in \Lambda^n$.
Since $\rk(X \sqcup T) = \rk(X)$, the coordinates indexed by $T$ are dependent on those indexed by $X$.
Thus, $(0, mv) = A_{X \sqcup F}(x)$ implies $(0, mv, 0) = A_{X \sqcup F \sqcup T}(x)$.
Hence $\overline{(0,v,0)}$ is a torsion element in $G_{X \sqcup F \sqcup T}$ and also the desired lift for $\bary$.
\end{proof}

The remaining Axiom~\ref{item:axiomP} is proved in the next subsection by using duality.

%=======================================================
\subsection{Arithmetic matroid duality}
    \label{sub:DualOfAnArithmeticMatroid}
%=======================================================
Given a triple $M = (E, \rk, m)$ we define 
the \emph{dual rank function} $\rk^*(S)$ and the \emph{dual multiplicity} $m^*(S)$ as
%-------------------------------------------------------
\begin{align} 
    \label{eq:DualArithmeticMatroid}
%-------------------------------------------------------
\rk^*(S) = \card S - (\rk E - \rk(E \setminus S))  \quad \quad m^*(S) = m(E \setminus S).
\end{align}
Note that $(M^*)^*$ equals $M$ again. 
By \cite[Lemma 2.2]{dm13}, if $M$ is an arithmetic matroid, then 
so is $M^* = (E, \rk^*, m^*)$ and we call it the \emph{dual arithmetic matroid}.
By \cite[Section~2]{bm14} Axiom~\ref{item:axiomP} is equivalent to Axiom~\ref{item:axiomA2} plus:
    %-------------------------------------------------------
    \begin{enumerate}[label=(P\arabic*)]
    %-------------------------------------------------------
        \item \label{item:axiomP1} For all $X \subset E$, if $Y \in [X, E]$ and $\rk X = \rk Y$, 
	     then $\rho(X,Y) \ge 0$.
         \item \label{item:axiomP2} For all $X \subset E$,  if $Y \in [X, E]$ and $\rk^* X = \rk^* Y$, 
	     then $\rho^*(X,Y) \ge 0$. 
\end{enumerate}
Here $\rho^*$ is the analogous expression for the dual matroid.
Looking at Axiom~\ref{item:axiomP1} in this setting, we must prove for an elliptic arrangement $\calA$ that
\[ 
        \rho(X,Y) = \sum_{S \in [X,Y]} (-1)^{|S|-|X|}m(S)
\]
is non-negative. 
We abuse notation by writing $\CoCo S$ instead of $\CoCo{\Arrangement_S}$, 
i.e.~the set of connected components of $\Arrangement_S = \bigcap_{i \in S} H_i$.
%-------------------------------------------------------
\begin{lm}
    \label{lm:CountingComponents}
%-------------------------------------------------------
Let $\Arrangement$ be an elliptic arrangement, for all $X \subset Y \subseteq [k]$ with $\rk X = \rk Y$, we have
\[ 
  \rho(X,Y) = \card \Big(\CoCo X \setminus \bigcup_{i \in Y \setminus X} \CoCo{X \cup i} \Big).
\]
\end{lm}

%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    The expression on the right considers all the layers $\ell$ such that $\ell$ is in $\Arrangement_X$ and for any $i \in Y \setminus X$ we have that $\ell$ is not a subset of $H_i = \ker A_i$.
    Note that since $\rk X = \rk Y$,
    taking connected components $\CoCo -$ is an inclusion-reversing operation on the interval $[X,Y]$,
    i.e.~for all $S, T \in [X,Y]$ we have that $S \subset T$ implies that $\CoCo T \supset \CoCo S$. 
    For similar reason we have $\CoCo S \cap \CoCo T = \CoCo{S \cup T}$ for all $S, T \in [X,Y]$. 
    Recall that $m(S) = \card \CoCo S$.
    The result follows from a straightforward inclusion-exclusion count.
\end{proof}
%-------------------------------------------------------
   \begin{cor} 
       \label{cor:SatisfiesP1}
%-------------------------------------------------------
       In the context of Construction~\ref{cons:ArithmeticMatroidArrangement}, the triple $([k], \rk_\Arrangement, m_\Arrangement)$ satisfies Axiom~\ref{item:axiomP1}.
    \end{cor} 

%-------------------------------------------------------
    \begin{proof} 
%-------------------------------------------------------
    From \Cref{lm:CountingComponents} follows that $\rho(X,Y)$ is non-negative, as it counts the cardinality of a set.
\end{proof}

Finally, Axiom~\ref{item:axiomP2} would follow from duality if were able to build an elliptic arrangement realizing the dual arithmetic matroid.
We believe this construction to be possible, by developing an analogue of the \textit{generalized toric arrangements} developed
in \cite[Section~4]{dm13},
but we deem it excessively technical for our aims.
Thus, in the next section we approach Axiom~\ref{item:axiomP2} with a weaker construction. 

%=======================================================
\subsection{The dual matroid as a minor}
    \label{sub:RealizableDual}
%=======================================================
We describe an elliptic arrangement that gives an arithmetic matroid $M_{\Omega \cup \Psi}$
with a minor isomorphic to the dual of~$M$.
Thus, $M_{\Omega \cup \Psi}$ satisfies Axiom~\ref{item:axiomP1}.
Since Axiom~\ref{item:axiomP1} is inherited to minors,
$M^*$ satisfies Axiom~\ref{item:axiomP1}, 
and $(M^*)^* = M$ satisfies Axiom~\ref{item:axiomP2} as desired.

The main ingredient is the elliptic analogue of a toric construction from \cite[Section~3.4]{dm13}.
Firstly, let us recall that $k$ elements $\calP = \aset{p_1, \dots, p_k} \subset \ZZ^n$
give an arithmetic matroid $M_\calP$ as follows: 
for $S \subset \calP$ let $G_S = \rad_{\ZZ^n} \langle p \suchthat p \in S \rangle$.
Consider then $\rk_\calP(S) = \rk \langle p \suchthat p \in S \rangle$ and 
\[m_\calP(S) = \# \tor (\ZZ^n/\langle p \suchthat p \in S \rangle) = \# G_S/ \langle p \suchthat p \in S \rangle.\]
The triple $M_\calP = ([k], \rk_\calP, m_\calP)$ is an arithmetic matroid; see \cite[Section~2.4]{dm13}.

Secondly, we recall the contraction of arithmetic matroids $M = (E, \rk, m)$: the contraction $M/T$ by a set $T \subset E$ is an arithmetic matroid on $E \setminus T$ with rank $r_{M/T}(A) = r(A \cup T) - r(T)$ and multiplicity $m_{M/T}(A) = m(A \cup T)$.

Finally, let $\calQ = \aset{q_1, \dots, q_n} \subset \ZZ^k$ be the columns of the $(k \times n)$-matrix $A$ whose $i$-th row is the vector $p_i$ of $\calP$.
Also let $e_i$ be the $i$-th standard vector of $\ZZ^k$ and $\calB = \aset{e_1, \dots, e_k} \subset \ZZ^k$ the collection of standard vectors.
We consider the matroid $M_{\calB \cup \calQ}$ associated to the matrix $\calB \cup \calQ$ with $n + k$ columns: 

%-------------------------------------------------------
\begin{lm}[Theorem~3.8 from \cite{dm13}] 
    \label{lm:DualMatroidToric}
%-------------------------------------------------------
    Let $\calP$ be a list of elements in $\ZZ^n$, the dual $(M_\calP)^*$ is isomorphic to the contraction $M_{\calB \cup \calQ} / \calQ$.
\end{lm}

    We perform a similar construction for elliptic arrangements. Let $\Arrangement$ be an elliptic arrangement defined by a matrix $A \colon \EC^n \to \EC^k$ and consider the dual homomorphism of abelian varieties $A^H \colon (\EC^\vee)^k \to (\EC^\vee)^n$, where $\EC^\vee$ is the dual elliptic curve and $A^H$ is the conjugate transpose of $A$.
    Consider $\mathcal{B}$ the arrangement given by the matrix
    \[ (\EC^\vee)^k \xrightarrow[\begin{pmatrix}
        I_k\\ A^H
    \end{pmatrix}]{} (\EC^\vee)^{k+n}\]
    Let $T= \{ k+1, \dots, n\}$ be the indexes of the rows of $A^H$.
    \begin{lm}
    \label{lm:DualMatroidElliptic}
        Let $\Arrangement$ be an elliptic arrangement, the dual matroid $M_\Arrangement^*$ is isomorphic to the contraction $M_\mathcal{B}/T$ 
    \end{lm}
    Before the proof of \Cref{lm:DualMatroidElliptic} we need a technical result. 
    \begin{lm}
    \label{lm:coker_conjugate_transpose}
        For any matrix $A \in \Mat_{k,n}(R)$ we have $\tor \coker (A \colon \Lambda^n \to \Lambda^k) \simeq \tor \coker (A^H\colon (\Lambda^\vee)^k \to (\Lambda^\vee)^n)$ as abelian groups.
    \end{lm}
    \begin{proof}
        Observe that $\tor \coker A \simeq \tor \coker A^T$ because their elementary divisors coincides.
        It remains to show that $\tor \coker A \simeq \tor \coker \overline{A}$ where $\overline{A}$ is the complex conjugate of the matrix $A$.
        As in \Cref{sub:MultiplicationByAlpha}, consider $\ZZ$-bases of $\Lambda^n$ and $\Lambda^k$ given by $\{e_i, \tau e_i\}_i$ for $i\leq n$, respectively $i\leq k$.
        The matrices that represent $A$ and $\overline{A}$ in the $\ZZ$-basis are of the form
        \[ A_\ZZ = \begin{pmatrix}
            X & -Y\normDet' \\
            YN & X +Y \normTr c'
        \end{pmatrix}
        \text{ and }
        \overline{A}_\ZZ = \begin{pmatrix}
            X +Y \normTr c' & Y\normDet' \\
            -YN & X
        \end{pmatrix}
        \]
        We show that they have the same Smith normal form, indeed by exchanging rows and columns 
        \[ A_\ZZ \sim \begin{pmatrix}
            X +Y \normTr c' & YN \\
            -Y\normDet' & X
            \end{pmatrix} \sim  
            \begin{pmatrix}
            X +Y \normTr c' & Y \\
            -Y\normDet'N & X
            \end{pmatrix}
            \sim  
            \begin{pmatrix}
            X +Y \normTr c' & -Y\normDet' \\
            YN & X
            \end{pmatrix}
            \sim \overline{A}_\ZZ,
        \]
        where the two middle steps follows from the proof of \Cref{lm:CokernelsCoincide}.
    \end{proof}

    \begin{proof}[Proof of \Cref{lm:DualMatroidElliptic}]
        The statement about underlying matroid is classical, we check only that the two multiplicity functions coincide.
        Let $S \subseteq [k]$, we want to compute 
        \[m_{\mathcal{B}/T}(S) = m_\mathcal{B}(S \cup T) = \# \tor \coker \begin{pmatrix}
        (I_k)_S\\ A^H
    \end{pmatrix}\]
    Using row operation we simplify the matrix  and obtain
    \[ \# \tor \coker \begin{pmatrix}
        (I_k)_S\\ A^H
    \end{pmatrix} =  \# \tor \coker \begin{pmatrix}
        I_s & 0\\ 0 & (A_{[k] \setminus S})^H
    \end{pmatrix}
    =  \# \tor \coker \begin{pmatrix}
         (A_{[k] \setminus S})^H
    \end{pmatrix}\]
    where for simplicity in the middle step we have assumed that $S$ are the first $s$ indices.
    Finally, \Cref{lm:coker_conjugate_transpose} implies $m_{\mathcal{B}/T}(S)= m_\Arrangement ([k] \setminus S)$ and this complete the proof.
    \end{proof}

%-------------------------------------------------------
   \begin{cor} 
       \label{cor:SatisfiesP2}
%-------------------------------------------------------
       In the context of Construction~\ref{cons:ArithmeticMatroidArrangement}, the triple $([k], \rk_\Arrangement, m_\Arrangement)$ satisfies Axiom~\ref{item:axiomP2}.
    \end{cor} 

%-------------------------------------------------------
    \begin{proof} 
%-------------------------------------------------------
        By \Cref{cor:SatisfiesA1} the triple $M_{\mathcal{B}} = ([k+n], \rk_\mathcal{B}, m_\mathcal{B})$ satisfies Axiom~\ref{item:axiomP1}.
        This implies that the minor $M_{\mathcal{B}} / T$ satisfies Axiom~\ref{item:axiomP1}.
        To prove the relevant equality, 
        given a molecule $[X, Y]$ in $M_{\mathcal{B}} / T$
        just consider the molecule $[X \cup T, Y \cup T]$ in $M_{\mathcal{B}}$. 
        Now by \Cref{lm:DualMatroidElliptic}, 
        Axiom~\ref{item:axiomP1} holds for $M_\Arrangement^*$, 
        which as observed before proves Axiom~\ref{item:axiomP2} for $M_\Arrangement$ by duality.
\end{proof}

%-------------------------------------------------------
\begin{thm}
    \label{thm:4EllipticArr-AritMat}
%-------------------------------------------------------
    The data of ground set $[k]$, of rank function $\rk_\Arrangement$, 
    and of number of connected components 
    $m_\Arrangement(S) = \card \tor{\coker A_S }$ gives rise to an arithmetic matroid.
\end{thm}   



%-------------------------------------------------------
\begin{proof}
%-------------------------------------------------------
       Note that $ \codim \Arrangement_S = \rk A_S$, which implies that $([k], \rk_\Arrangement)$ is an underlying matroid. 
       We are left with: \Cref{cor:SatisfiesA1} proving Axiom~\ref{item:axiomA1}; \Cref{lm:SatisfiesA2} proving Axiom~\ref{item:axiomA2};
       Corollaries~\ref{cor:SatisfiesP1}
       and~\ref{cor:SatisfiesP2} proving Axiom~\ref{item:axiomP}.
\end{proof}

\begin{remark}
    Another proof of \Cref{thm:4EllipticArr-AritMat} is suggested by Emanuele Delucchi.
    It consists in checking that the action of $\Lambda^n$ on the periodic hyperplane arrangement $\Arrangement^\upharpoonright$ in $\CC^n$ by translations is \textit{arithmetic}, in the sense of \cite[Definition 3.15]{dr18}.
    Then \Cref{thm:4EllipticArr-AritMat} follows from \cite[Theorem C]{dr18}.
\end{remark}

%=======================================================
\subsection{Examples}
%=======================================================
We provide two interesting examples:
the first is an arithmetic matroid realizable via elliptic arrangements, but not via toric arrangements.
The second is a variation in which we change the elliptic curve, but the defining matrix is the same. This second arrangement defines an arithmetic matroid realizable as toric arrangement.

   Recall from \cite[Section~3]{dm13} that all arithmetic matroids realizable in the usual sense (that is, via toric arrangements) have the so-called \textit{GCD property}, i.e.~the multiplicity function is defined by the values on the independent sets:
   \[
     m(A) = \gcd(\aset{m(I) \suchthat I \subseteq A \text{ and } |I| = \rk(I) = \rk(A) }).
   \]
   The other implication and the realizability space were studied in \cite{PagariaPaolini}.
   We now show a generalized elliptic arrangement whose arithmetic matroid do not satisfy the GCD property.

%-------------------------------------------------------
\begin{ex} 
    \label{ex:NewRealization}
%-------------------------------------------------------
   Let $\Lambda=\ZZ [\sqrt{-3]}$, $\EC = \CC / \Lambda$, so $\End \EC \isom  \ZZ[\sqrt{-3}]$ as in \Cref{sub:ModulesOverR}. 
   Consider the arrangement $\Arrangement$ associated with the matrix
   \[A= \begin{pmatrix}
       2 \\
       1+\sqrt{-3}
   \end{pmatrix}.\]
   We get:
     \begin{align*}
         m_\Arrangement(1,2) &= \card \ZZ[\sqrt{-3}] / (2, 1 + \sqrt{-3}) = 2, \\
         m_\Arrangement(1) = \card \ZZ[\sqrt {-3}] / 2R = 4, \quad\quad & \quad \quad 
      m_\Arrangement(2) = \card \ZZ[\sqrt{-3}]/(1+\sqrt {-3}) = 4, \\ 
         m_\Arrangement(\varnothing) &= 1. 
    \end{align*}
    This arithmetic matroid does not satisfy the GCD property, since $m(1,2) \ne 4$.

    On the other hand, if we consider $\Gamma=\ZZ[\omega]$ where $\omega$ is a third root of unity, the arrangement $\mathcal{B}$ in $\CC / \Gamma$ defined by the matrix
    \[
    B=\begin{pmatrix}
       2 \\
       1+\sqrt{-3}
   \end{pmatrix}.
    \]
    has multiplicities $m_\mathcal{B}(\varnothing) = 1$ and $m_\mathcal{B}(1) = m_\mathcal{B}(2) = m_\mathcal{B}(1,2) = 4$, 
    which is realizable via a toric arrangement associated to the matrix $B' = \begin{pmatrix}
        4 \\
        4
    \end{pmatrix}$. 
\end{ex}

%=======================================================
\subsection{The GCD property}
    \label{sub:TheGCDProperty}
%=======================================================
    The proof of the GCD property for toric arrangements
    uses the fact that over a PID every matrix has a Smith normal form.
    This is no longer necessarily true for matrices over $R$.
    Recall that if $R$ is Dedekind, all localizations $R_\frakp$ over all maximal ideals $\frakp \subset R$ are discrete valuation rings, therefore PID. 
    This fact, together with a local-global principle argument, allows us to prove:
%-------------------------------------------------------
\begin{lm} 
    \label{lm:GCDpropertyForRDedekind}
%------------------------------------------------------- 
    Let $\Arrangement$ be an elliptic arrangement in $\EC^n$.
    If $R=\End \EC$ is Dedekind, then the arithmetic matroid $M_\Arrangement$ satisfies the GCD property.
\end{lm}
%-------------------------------------------------------
\begin{proof} 
%-------------------------------------------------------
    Let $\frakp \subset R$ be a maximal prime.
    As usual, denote by $R_\frakp = \inv{(R \setminus \frakp)} R $ the localization of $R$ and $M_\frakp$ the $R_\frakp$-module obtained by localizing $M$.
    We use the following facts about the localization of $R$ over a maximal prime ideal $\frakp \subset R$:
    %-------------------------------------------------------
    \begin{itemize} 
    %-------------------------------------------------------
        \item $\tor M_\frakp = (\tor M)_\frakp$, see e.g.\ \cite[Proposition 3.3]{fm16};
        \item $\coker A_\frakp = (\coker A)_\frakp$, because localization is an exact functor.
        \item If $M$ is a finitely generated torsion module over $R$, then
            $M \simeq \bigoplus_{\frakp} M_\frakp$. 
            The isomorphism follows by the structure theorem for modules over Dedekind domain \cite[Chapter 16, Theorem 22]{DummitFoote} and by the isomorphism $R/\frakp^e \simeq R_\frakp/\frakp^e R_\frakp $.
    \end{itemize}
    Applying these facts we get
    %-------------------------------------------------------
    \begin{align}
        \label{eq:GCDpropertyinlocalizations} 
    %-------------------------------------------------------
        m_\Arrangement (S) &= \card ( \tor \coker A_S )  \\
        \nonumber        &= \card \left(  \bigoplus _\frakp  \left( \tor \coker A_S \right)_\frakp \right) = \prod_\frakp \card\tor \coker\left( A_S \right)_\frakp 
    \end{align}
    Recall that $R$ is Dedekind if and only if $R$ is Noetherian and all localizations $R_\frakp$ at maximal primes are discrete valuation rings.
    Thus, $m_\frakp(S) = \card \tor \coker\left( A_S \right)_\frakp$
    satisfies the GCD property.
    Since Equation~\eqref{eq:GCDpropertyinlocalizations} expresses $m_\Arrangement$ as the product of $m_\frakp$ over all maximal primes $\frakp \subset R$, we have that $m_\Arrangement$ satisfies the GCD property. 
\end{proof}

\subsection{Matroids over rings}
\label{subsec:matroids_over_rings}
Elliptic arrangements with complex multiplication define naturally matroids over a ring, see \cite{fm16, fm19a} for the definition.

Let $\Arrangement$ be the arrangement defined by a matrix $A \in \Mat_{k,n}(R)$.
Consider the $R$-module $(\Lambda^\vee)^n$ and the submodules 
\[ \im \left(A_S^H \colon (\Lambda^\vee)^S \to (\Lambda^\vee)^n \right) \]
for each $S\subseteq [k]$. This data defines a \textit{realizable polymatroid over} $R$ with the desirable properties
\begin{align*}
    &\codim \Arrangement_S = \rk_R (\coker(A_S^H)), \\
    & \# CC(\Arrangement_S) = \# \tor (\coker(A_S^H)).
\end{align*}
These properties follow from Lemmas~\ref{lm:NumberOfLayers} and~\ref{lm:coker_conjugate_transpose}.
This is not a matroid over $R$ because $\Lambda$ could be a non-free $R$-module: take $k=n=1$ and $A= \begin{pmatrix}
    1
\end{pmatrix}$, the surjection $\Lambda^\vee \to 0$ does not have a $R$-cyclic kernel. 

The construction presented above is the most natural one; however  -- if one is more comfortable working with matroids instead polymatroids -- an alternative construction is available.
Consider the module $R^n$ and the elements $A_R^H e_i$ for each $i \in [k]$, where $e_i$ is the standard base element of $R^k$.
This data defines a \textit{realizable matroid over }$R$ with the properties
\begin{align*}
    &\codim \Arrangement_S = \rk_R (R^n/\langle A_R^H e_i \mid i \in S\rangle ), \\
    & \# CC(\Arrangement_S) = \# \tor (R^n/\langle A_R^H e_i \mid i \in S\rangle ).
\end{align*}
The equalities follow from Lemmas~\ref{lm:NumberOfLayers},~\ref{lm:coker_conjugate_transpose} and~\ref{lm:CokernelsCoincide}.

%=======================================================
\subsection{Calculating the Euler characteristic}
    \label{sub:CalculatingTheEulerCharacteristic}
%=======================================================
    The work of \cite{bib15} computes the Euler characteristic of the complement $\CM(\Arrangement)$ for abelian arrangements $\Arrangement$ that are defined by a $(k \times n)$-matrix $A$ with integer coefficients.
    That work can be adapted to our setting where $A$ has coefficients in~$R$.
    We do not do a full recap here, but rather indicate the main signposts and the points at which one needs a different argument to prove the result.

    Let $\calX = \EC^n$ and $j \colon \CM(\Arrangement) \hookrightarrow \calX$ the natural embedding.
    We consider the constant sheaf $\underline{\QQ}$ and its higher direct image $R^{\bullet} j_* \underline{\QQ}$, which we aim to relate via the Leray spectral sequence.
    At the second page of such a spectral sequence, we get:
    \[
      E^{p,q}_2 = H^p(X, R^q j_* \underline{\QQ}) \Longrightarrow H^{p,q}(\CM(\Arrangement)).
    \]
    Since elliptic arrangement are locally isomorphic to hyperplane arrangements, for any $x \in \calX$ we have
    %-------------------------------------------------------
    \begin{align*} 
    %-------------------------------------------------------
        (R^q j_* \underline{\QQ})_x &= \lim_{x \in U} H^q(\inv j(U), \underline{\QQ}) 
        &\simeq \bigoplus_{\substack{W \in \calL_q(\Arrangement)\\ x \in W}} H^{\text{top}}(M(A^{\upharpoonright}_W)) %\otimes \underline{\QQ}_W.
    \end{align*}
    Thus $$R^q j_* \underline{\QQ} = \bigoplus_{W \in \calL(\Arrangement)} H^{\text{top}}(M(A^{\upharpoonright}_W)) \otimes \underline{\QQ}_W.$$
    In particular,
    \begin{equation}
    \label{eq:Leray_SS}
                E^{p,q}_2 = H^p(R^q j_* \underline{\QQ}) = \bigoplus_{W \in \calL_q(\Arrangement)} H^{\text{top}}(M(A^\upharpoonright _W)) \otimes H^p(W, \underline{\QQ}).
    \end{equation}
    Using the mixed Hodge structure, we get that the spectral sequence degenerates at the third page $E_3$. Hence $H^\bullet(\CM(\Arrangement), \QQ) = H^\bullet(E^{\bullet, \bullet}_2, d_2)$, both as algebras and as mixed Hodge structures.

    Recall that the arithmetic Tutte polynomial of the arithmetic matroid is 
    \[T_{M}(x,y)= \sum_{S \subseteq [n]} m(A)(x-1)^{\rk[n] -\rk S} (y-1)^{\lvert S \rvert - \rk S}\]
    and the characteristic polynomial of the lattice is
    \[\chi_\calL (t) = \sum_{W \in \calL} \mu_{\calL}(\hat{0}, W) t^{n-\rk W}.\]
    We get the following result.

    %-------------------------------------------------------
    \begin{thm}

        \label{pr:EulerCharacteristic}
    %-------------------------------------------------------
    Let $\Arrangement$ be an elliptic arrangement of rank $n$. The Euler characteristic of the complement is 
     \[
e_{\CM(\Arrangement)} = (-1)^n T_{M_\Arrangement}\left( 1,0 \right) = \chi_{\calL(\Arrangement)} \left(0 \right) = (-1)^n \sum_{P \in \calL_n(\Arrangement)} \operatorname{nbc} (P).
     \]
where $\operatorname{nbc} (P)$ is the number of no broken circuits contained in the flat $P$.
\end{thm}

    %-------------------------------------------------------
    \begin{proof} 
    %-------------------------------------------------------
        The proof goes exactly as the one in \cite{bib15}, which uses a theorem of \cite{moc12a}. We provide a sketch of the proof in our case.
        Let us start by considering the bigraded Poincaré polynomial of $E_2^{\bullet,\bullet}$, described in Equation~\eqref{eq:Leray_SS}:
        \[
         P_{E_2}(t,s) = \sum_{p,q} \dim (E_2^{p,q}) t^p s^q =  \sum_{W \in \calL(\Arrangement)} (-1)^{\rk W} \mu_{\calL (\Arrangement)}(\hat{0}, W) (1+t)^{2(n-\rk W)} s^{\rk W} 
     \]
     where in the second equality we used that the cohomology of an hyperplane arrangement has rank equal to the number of no-broken circuits that is equal to $(-1)^{\rk W} \mu_{\calL (\Arrangement)}(\hat{0}, W)$.
     Recall from \cite[Theorem 5.6]{moc12a} that
     \[ \chi_{\calL(\Arrangement)} (t) = (-1)^n T_{M(\Arrangement)} (1-t,0).\]
     Therefore, 
     \[P_{E_2}(t,s)=(-s)^n\chi_{\calL(\Arrangement)} \left(\frac{(1+t)^2}{-s} \right) = s^n T_{M_\Arrangement}\left( 1+ \frac{(1+t)^2}{s},0 \right) \]
     Evaluating at $s=-t^2$ we obtain 
     \begin{align*}
         P_{\CM(\Arrangement)}(t,-t^2) &=P_{E_2}(t,-t^2) =t^{2n}\chi_{\calL(\Arrangement)} \left(\frac{(1+t)^2}{t^2} \right) \\
         &= (-t^2)^n T_{M_\Arrangement}\left( 1- \frac{(1+t)^2}{t^2},0 \right)
     \end{align*}
     Finally, setting $t=-1$ we have
     \[ e_{\CM(\Arrangement)} = (-1)^n T_{M_\Arrangement}\left( 1,0 \right) = \chi_{\calL(\Arrangement)} \left(0 \right) = (-1)^n \sum_{P \in \calL_n(\Arrangement)} \operatorname{nbc} (P). \]
     This completes the proof.
    \end{proof}

